The remaining sections present the proof of Theorem \ref{thm:viscosity}. The main approach is based on the stochastic Perron's method; see \cite{bayraktar2013stochastic, bayraktar2015stochastic}. The proof proceeds in three steps: 
\begin{enumerate}[label={(\arabic*)}]	
	\item In Section \ref{sec:sto_sup}, we introduce a family of stochastic supersolutions which bound the value function from above. The infimum of this family is called the upper stochastic envelope and is shown to be a viscosity subsolution. 

	\item In Section \ref{sec:sto_sub}, we introduce a family of stochastic subsolutions which bound the value function from below. The supremum of this family is called the lower stochastic envelope and is shown to be a viscosity supersolution. 

	\item Finally, a comparison argument in Section \ref{sec:compare} completes the proof. 
\end{enumerate}

The stochastic Perron's method bypasses the need to first establish the dynamic programming principle (DPP), instead deriving it after proving that the value function is a viscosity solution. This approach circumvents the complicated and sometimes incomplete proofs of the DPP.

Before presenting the details, we outline the main technical challenges and the techniques used to address them:
\begin{enumerate}[label={(\arabic*)}]	
	\item The value function loses one state variable $x_k$ after the deadline of goal $k$. Then we need to define stochastic supersolutions and subsolutions properly in Definition \ref{def:sto_super} and \ref{def:sto_sub}, respectively. The boundary condition in equation \eqref{Tk_bc} at the deadline $T_k$ links the value function $V_k(T_k, x_{k:K+1}, y)$ to $V_{k+1}(T_k, x_{k+1:K+1}, y)$, which is a novel problem. The stochastic Perron's method is adapted to prove the viscosity solution property at $T_k$, as detailed in Step 3 of the proof of Propositions \ref{prop:vissub} and \ref{prop:vissuper}.
	\item Another technical challenge is the state constraint that the wealth processes are nonnegative. Similar to \citet[Equation (4.3)]{bentahar2007} and \citet[Theorem 1.2]{rokhlin2014}, Lemma \ref{lem:boundary} shows that the upper stochastic envelope $v_+$ also provides information about the value function on the boundary $\overline{\cS}^o_{k} \backslash \cS_k$. Together with Lemma \ref{lem:conti}, we can relax the continuity assumption imposed in the \citet[Theorem 7.9]{crandall1992user} when proving the comparison principle. The similar idea is also used in \citet[Lemma 4.1]{bentahar2007}. 
	\item The mental accounting formulation leads to gradient constraints from two sides as follows:
	\begin{equation*}
		- \theta_{i}  \leq \partial_{K+1} V_k - \partial_{i} V_k \leq \lambda_{i}, \quad i = k, \ldots, K.
	\end{equation*}
	This requires a modified approach to proving the comparison principle, similar to the technique in \citet[Proposition 2.2]{hynd2012eigenvalue}. The gradient constraints also complicate the construction of a strict classical subsolution as in Lemma \ref{lem:strict_l}. In fact, if we extend the domain of $x_{1:K+1}$ from $[0, \infty)^{K+1}$ to $\R^{K+1}$ and try to avoid the difficulty from state constraints like \cite{capponi2024}, then we could not find a strict classical subsolution on $\R^{K+1}$. Therefore, this paper follows the techniques mentioned in item (2) instead.
\end{enumerate}


\section{Stochastic supersolution}\label{sec:sto_sup}

For $k=1, \ldots, K+1$, a tuple $(\tau, \xi_{k:K+1}, \xi_y)$ is called a {\it random initial condition} for the state process \eqref{Y}, \eqref{Xlast}, and \eqref{Xk}, if $\tau \in [T_{k-1}, T]$ is an $\mathbb{F}$-stopping time and $(\xi_{k:K+1}, \xi_y)$ is an $\cF_{\tau}$-measurable random vector with $\p((\xi_{k:K+1}, \xi_y) \in \overline{\cS}_k) = 1$. It is possible that some elements in $\xi_{k:K+1}$ may be unnecessary. For example, if $\p( \tau > T_k) = 1$, then the random initial value $\xi_k$ is not needed since the portfolio $X_k$ terminates after the deadline $T_k$. However, we keep the redundant $\xi_k$ for notational convenience.

Denote $\{(X_{k:K+1}, Y)(t; \tau, \xi_{k:K+1}, \xi_y, U) \}_{t \in [\tau, T]}$ as the solution of the state process \eqref{Y}, \eqref{Xlast}, and \eqref{Xk}, with a control $U$ and random initial condition $(\tau, \xi_{k:K+1}, \xi_y)$ in the sense that
\begin{equation*}
	(X_{k:K+1}, Y)(\tau-; \tau, \xi_{k:K+1}, \xi_y) = (\xi_{k:K+1}, \xi_y).
\end{equation*}
Here, $U:=(\alpha_{k:K+1}, L_{k:K}, M_{k:K})$ is called $(\tau, \xi_{k:K+1}, \xi_y)$-admissible if 
\begin{equation*}
\p((X_{k:K+1}, Y)(t; \tau, \xi_{k:K+1}, \xi_y, U) \in \overline{\cS}_k, \; \tau \leq t \leq T ) = 1.
\end{equation*}
We adopt the convention that $X_k(t) = X_k(T_k)$ for $t > T_k$, i.e., the state ceases at the deadline $T_k$. Similarly, some elements in $X_{k:K+1}$ and $U$ may be redundant if $\p(\tau > T_k) = 1$.

Like \citet[Lemma 2.2]{bayraktar2015stochastic}, we have the following result on the concatenation of admissible controls. The proof is also similar to that of \citet[Lemma 2.2]{bayraktar2015stochastic} and we omit the details for brevity.
\begin{lemma}\label{lem:glue}
	For $k=1, \ldots, K+1$, consider a random initial condition $(\tau, \xi_{k:K+1}, \xi_y)$ with $\tau \in [T_{k-1}, T_k]$.
	\begin{enumerate}
		\item If $(\alpha^1_{k:K+1}, L^1_{k:K}, M^1_{k:K})$ and $(\alpha^2_{k:K+1}, L^2_{k:K}, M^2_{k:K})$ are $(\tau, \xi_{k:K+1}, \xi_y)$-admissible and $A$ is an $\cF_\tau$-measurable set, then
		\begin{align*}
			&(\alpha_{k:K+1}(t), L_{k:K}(t), M_{k:K}(t)) \\
			& := \one_{ \{ \tau \leq t \} \cap A} (\alpha^1_{k:K+1}(t), L^1_{k:K}(t) - L^1_{k:K}(\tau-), M^1_{k:K}(t) - M^1_{k:K}(\tau-)) \\
			& \qquad + \one_{ \{ \tau \leq t \} \cap A^c} (\alpha^2_{k:K+1}(t), L^2_{k:K}(t) - L^2_{k:K}(\tau-), M^2_{k:K}(t) - M^2_{k:K}(\tau-))
		\end{align*}
		is also $(\tau, \xi_{k:K+1}, \xi_y)$-admissible.
		\item Let $U^1 := (\alpha^1_{k:K+1}, L^1_{k:K}, M^1_{k:K})$ be a $(\tau, \xi_{k:K+1}, \xi_y)$-admissible control, $\rho \in [\tau, T]$ be an $\mathbb{F}$-stopping time, and $(\xi^1_{k:K+1}, \xi^1_y) := (X_{k:K+1}, Y)(\rho; \tau, \xi_{k:K+1}, \xi_y, U^1)$. Then $(\rho, \xi^1_{k:K+1}, \xi^1_y)$ is a random initial condition. If $U^2 := (\alpha^2_{k:K+1}, L^2_{k:K}, M^2_{k:K})$ is $(\rho, \xi^1_{k:K+1}, \xi^1_y)$-admissible, then
		\begin{align*}
			&(\alpha_{k:K+1}(t), L_{k:K}(t), M_{k:K}(t)) \\
			& := \one_{\{\tau \leq  t < \rho \}} (\alpha^1_{k:K+1}(t), L^1_{k:K}(t), M^1_{k:K}(t)) \\
			& \qquad + \one_{ \{ \rho \leq t \leq T\}} (\alpha^2_{k:K+1}(t), L^2_{k:K}(t) - L^2_{k:K}(\rho-) + L^1_{k:K}(\rho), \\
			& \hspace{3.0cm} M^2_{k:K}(t) - M^2_{k:K}(\rho-) + M^1(\rho))
		\end{align*}
		is $(\tau, \xi_{k:K+1}, \xi_y)$-admissible.
	\end{enumerate}
\end{lemma}
Here, if the stopping time $\rho$ is after the deadline of goal $i$ with $i \geq k$, i.e., $\p(\rho > T_i) = 1$, then the initial conditions $\xi^1_{k:i}$ become redundant. Again, we include $\xi^1_{k:i}$ for notational convenience.


\begin{definition}[Stochastic supersolution]\label{def:sto_super}
	Denote an array of functions as
	\begin{equation}\label{sto_super}
		(\{ v_1(t, x_{1:K+1}, y) \}_{t \in [0, T_1]}, \ldots, \{ v_k(t, x_{k:K+1}, y) \}_{t \in [T_{k-1}, T_{k}]}, \ldots, \{ v_{K+1}(t, x_{K+1}, y) \}_{t \in [T_K, T]} ),
	\end{equation}
	where $v_k(t, x_{k:K+1}, y): [T_{k-1}, T_k] \times \overline{\cS}_k \rightarrow \R, k=1,\ldots, K+1$ is bounded and USC. The array \eqref{sto_super} is a stochastic supersolution of the HJB equation system if
	\begin{enumerate}[label={(\arabic*)}]	
		\item for each $k=1, \ldots K+1$, consider any random initial condition $(\tau, \xi_{k:K+1}, \xi_y)$ with $\tau \in [T_{k-1}, T_k]$, $(\xi_{k:K+1}, \xi_y) \in \cF_\tau$ and $\p((\xi_{k:K+1}, \xi_y) \in \cS_k) = 1$. There exists an admissible control $U:= (\alpha_{k:K+1}, L_{k, K}, M_{k, K}) \in \cU(\tau, \xi_{k:K+1}, \xi_y)$, such that
		\begin{equation*}
			\p((X_{k:K+1}, Y)(t; \tau, \xi_{k:K+1}, \xi_y, U) \in \cS_k, \; \tau \leq t \leq T) = 1,
		\end{equation*}
		and for any stopping time $\rho \in [\tau, T]$,
		\begin{equation}
			v_k(\tau, \xi_{k:K+1}, \xi_y) \geq \E \big[ \cM \big([\tau, \rho], v_{k:K+1}, (X_{k:K+1}, Y)(\cdot; \tau, \xi_{k:K+1}, \xi_y, U) \big) \big| \cF_\tau \big],
		\end{equation}
		where
		\begin{align}
			& \cM \big([\tau, \rho], v_{k:K+1}, (X_{k:K+1}, Y)(\cdot; \tau, \xi_{k:K+1}, \xi_y, U) \big) \label{M} \\
			& \quad := \Big\{ e^{-\beta(\rho - \tau)} v_{k}(\rho, (X_{k:K+1}, Y)(\rho; \tau, \xi_{k:K+1}, \xi_y, U)) \nonumber \\
			& \quad \qquad + \lambda_k \int^{\rho}_\tau e^{-\beta(s-\tau)} d L_k(s) + \theta_k \int^{\rho}_\tau e^{-\beta (s - \tau)} d M_k(s) \Big \} \one_{\{\tau \leq \rho < T_k\}} \nonumber \\		
			& \qquad + \sum^{K-1}_{l=k} \Big\{ e^{-\beta(\rho - \tau)} v_{l+1}(\rho, (X_{l+1:K+1}, Y)(\rho; \tau, \xi_{k:K+1}, \xi_y, U)) \nonumber \\
			&\quad \qquad \qquad +  \sum^{l}_{i = k} w_i e^{-\beta (T_i - \tau)} (G_i - X_i(T_i; \tau, \xi_{k:K+1}, \xi_y, U))^+  \nonumber \\
			& \quad \qquad \qquad + \sum^{l+1}_{i=k} \lambda_i \int^{\rho \wedge T_i}_\tau e^{-\beta(s-\tau)} d L_i(s) + \sum^{l+1}_{i=k} \theta_i \int^{\rho \wedge T_i}_\tau e^{-\beta (s - \tau)} d M_i(s) \Big \} \one_{\{T_l \leq \rho < T_{l+1} \}} \nonumber \\
			&\qquad + \Big\{ e^{-\beta(\rho - \tau)} v_{K+1}(\rho, (X_{K+1}, Y)(\rho; \tau, \xi_{k:K+1}, \xi_y, U)) \nonumber \\
			&\qquad \qquad +  \sum^{K}_{i = k} w_i e^{-\beta (T_i - \tau)} (G_i - X_i(T_i; \tau, \xi_{k:K+1}, \xi_y, U))^+  \nonumber \\
			& \qquad \qquad + \sum^{K}_{i=k} \lambda_i \int^{T_i}_\tau e^{-\beta(s-\tau)} d L_i(s) + \sum^{K}_{i=k} \theta_i \int^{T_i}_\tau e^{-\beta (s - \tau)} d M_i(s) \Big \} \one_{\{T_K \leq \rho \leq T\}}. \nonumber
		\end{align}	 
		The sum over $i = k, \ldots, K$ is interpreted as zero if $k = K+1$. We refer to $U$ as a {\bf suitable} control for $v_{k}$ (and $v_{k+1}, \ldots, v_{K+1}$ in  \eqref{sto_super}) with the random initial condition $(\tau, \xi_{k:K+1}, \xi_y)$.  
	\item  
	\begin{align}
		v_k(t, 0, y) & \geq \sum^{K+1}_{i = k} w_i e^{-\beta (T_i-t)} G_i, \quad \forall\;  t \in [0, T], y \in \R^m, k = 1, \ldots, K+1,\\
		v_{K+1}(T, x_{K+1}, y) & \geq (G_{K+1} - x_{K+1})^+, \quad \forall \; (x_{K+1}, y) \in \cS_{K+1}.
	\end{align}
	\end{enumerate}
	Denote the set of stochastic supersolutions as $\cV^+$. 
\end{definition}
\begin{remark}
  The first argument $[\tau, \rho]$ in $\cM$ represents the interval of integration. The second $\tau$ is in the random initial condition of state processes. In general, the random initial condition can be earlier than the lower limit of the integral. Then two different stopping times can appear in these two places. See \eqref{Q1M} for an example.
\end{remark}

Following a similar argument as in \citet[Remark 3.2]{bayraktar2015stochastic}, for $k=1, \ldots, K+1$, any stochastic supersolution in $\cV^+$ dominates the value function in the following sense:
\begin{align}
	V_{k}(t, x_{k:K+1}, y)  & \leq v_{k}(t, x_{k:K+1}, y) \quad \text{ on } \quad [T_{k-1}, T_k] \times (\cS_k \cup (\{ 0 \} \times \R^m)).
\end{align}

Lemma \ref{lem:two_stochsup} below shows that the family $\cV^+$ of stochastic supersolutions is stable under minimum. The proof of Lemma \ref{lem:two_stochsup} is similar to \citet[Lemma 3.2]{bayraktar2015stochastic} and omitted here.
\begin{lemma}\label{lem:two_stochsup}
	If $ (v^1_1, \ldots, v^1_k, \ldots, v^1_{K+1})$ and $ (v^2_1, \ldots, v^2_k, \ldots, v^2_{K+1})$ are stochastic supersolutions, then $(v^1_1 \wedge v^2_1, \ldots, v^1_k \wedge v^2_k, \ldots, v^1_{K+1} \wedge v^2_{K+1})$ is also a stochastic supersolution.
\end{lemma}

Given $k = 1, \ldots, K+1$ and $(t, x_{k:K+1}, y) \in [T_{k-1}, T_k] \times \overline{\cS}_k$, define
\begin{align}
	&v_{k, +}(t, x_{k:K+1}, y) := \inf \big\{ v_k(t, x_{k:K+1}, y) |\; v_k \text{ is the $k$-th element of some } v \in \cV^+ \big\}.  \label{v+}
\end{align}
Here, $v \in \cV^+$ means that $v := (v_1, \ldots, v_k, \ldots, v_{K+1})$ is a stochastic supersolution. Importantly, the infimum in $v_{k, +}$ only considers $v_k$ when it can construct a stochastic supersolution $v$ with some $(v_1, \ldots, v_{k-1}, v_{k+1}, \ldots, v_{K+1})$. We write the upper stochastic envelope as $v_+ := (v_{1, +}, \ldots, v_{k, +}, \ldots, $ $v_{K+1, +})$.
\begin{proposition}\label{prop:vissub}
	The upper stochastic envelope $v_+$ is a viscosity subsolution of the HJB equation under Definition \ref{def:vis_sub}.
\end{proposition}
The proof of Proposition \ref{prop:vissub} is given in the Appendix \ref{sec:proof_stosuper}.

Lemma \ref{lem:boundary} below shows that the upper stochastic envelope $v_+$ also provides information about the value function on the boundary $\overline{\cS}^o_{k} \backslash \cS_k$. A similar claim can be found in \citet[Equation (4.3)]{bentahar2007} and \citet[Theorem 1.2]{rokhlin2014}. We do not have to consider the case with $k = K+1$, since the set $\overline{\cS}^o_{K+1} \backslash \cS_{K+1}$ is empty.

\begin{lemma}\label{lem:boundary}
	For each $k=1, \ldots, K$, consider $t \in [T_{k-1}, T_k]$ and $(x^o_{k:K+1}, y) \in \overline{\cS}^o_{k} \backslash \cS_k$. $v_{k, +}$ in the upper stochastic envelope $v_+$ has the following property:
	\begin{align}\label{ineq:uscbd}
		V_k(t, x^o_{k:K+1}, y) \leq \limsup_{\substack{ x'_{k:K+1} \rightarrow x^o_{k:K+1} \\ x'_j > 0, \, j = k,\ldots,K+1}} v_{k, +}(t, x'_{k:K+1}, y),
	\end{align}
	where $V_k$ is the value function.
\end{lemma}
We introduce some notations used in the proofs of Lemma \ref{lem:boundary} and also Lemma \ref{lem:conti}. Given some $k=1, \ldots, K$, for any $(x_{k:K+1}, y) \in \overline{\cS}^o_{k}$, there exists at least one index $i \in \{k, \ldots, K+1\}$ such that $x_i > 0$. Without loss of generality, consider the smallest index $i$ with $x_i > 0$. Suppose $N$ elements in $x_{k:K+1}$ are zero. If $(x_{k:K+1}, y) \in \overline{\cS}^o_{k}\backslash \cS_k$, then $N > 0$. Instead, if $(x_{k:K+1}, y) \in \cS_k$, then $N=0$ and no transfer is needed. We introduce a small constant $\zeta > 0$. Define a new wealth state $Z_{k:K+1}(x_{k:K+1}, \zeta)$:
\begin{equation}\label{z}
	Z_i(x_{k:K+1}, \zeta) = x_i - N \zeta \text{ and for } j \neq i, \; 
	Z_j(x_{k:K+1}, \zeta) = \left\{ 
	\begin{array}{ c l }
		\zeta, & \text{ if } x_j = 0, \\
		x_j , & \text{ if } x_j > 0.
	\end{array}
	\right.
\end{equation}
From the state $x_{k:K+1}$ on the boundary to the state $Z_{k:K+1}(x_{k:K+1}, \zeta)$ in the interior, we reallocate $\zeta$ dollars from $x_i$ to each portfolio $j$ with $x_j = 0$. In general, the index $i$ may not be the fundamental portfolio $K+1$. Hence, the transfer is achieved via the route $x_i \rightarrow x_{K+1} \rightarrow x_j$. Evidently, there exists a unique transfer plan $(\zeta \Delta L_{k:K}(x_{k:K+1}), \zeta \Delta M_{k:K}(x_{k:K+1}))$ such that
\begin{equation}\label{transfer}
	\begin{aligned}
		& x_{K+1} - \sum_{j=k}^{K} \zeta \Delta L_j (x_{k:K+1}) +  \sum_{j=k}^{K} \zeta \Delta M_j(x_{k:K+1})  = Z_{K+1}(x_{k:K+1}, \zeta), \\
		& x_j + \zeta \Delta L_j(x_{k:K+1}) - \zeta \Delta M_j(x_{k:K+1}) = Z_j(x_{k:K+1}, \zeta), \text{ for } j = k, \ldots, K.
	\end{aligned}
\end{equation}
Elements of $\Delta L_{k:K}(x_{k:K+1})$ and $\Delta M_{k:K}(x_{k:K+1})$ are nonnegative integers. For each $j=1, \ldots, K$, $\Delta L_j(x_{k:K+1})$ and $\Delta M_j(x_{k:K+1})$ are not positive at the same time.

The proof of Lemma \ref{lem:boundary} is given in the Appendix \ref{sec:proof_stosuper}. Thanks to Lemma \ref{lem:boundary}, we can modify $v_+$ as follows. When $k=1, \ldots, K$ and $t \in [T_{k-1}, T_k]$, set
\begin{equation}\label{eq:modified}
	 \tilde{v}_{k, +} (t, x_{k:K+1}, y) = \left\{ 
	\begin{array}{ c l }
		\limsup_{\substack{ x'_{k:K+1} \rightarrow x_{k:K+1} \\ x'_j > 0, \, j = k,\ldots,K+1}} v_{k, +}(t, x'_{k:K+1}, y), & \text{ if } (x_{k:K+1}, y) \in \overline{\cS}^o_{k} \backslash \cS_k, \\
		v_{k, +} (t, x_{k:K+1}, y), & \text{ otherwise}.
	\end{array}
	\right.
\end{equation}
This modification is unnecessary for $v_{K+1, +}$. Additionally, we note that $\tilde{v}_+ := (\tilde{v}_{1, +}, \ldots, \tilde{v}_{k, +}, \ldots, $ $\tilde{v}_{K, +}, v_{K+1, +})$ is a viscosity subsolution of the HJB equation system. In Section \ref{sec:compare}, it will be used to validate the condition \eqref{modi_bd_u} in the comparison principle.


\section{Stochastic subsolution}\label{sec:sto_sub}

\begin{definition}[Stochastic subsolution]\label{def:sto_sub}
	Denote an array of functions as
	\begin{equation}\label{sto_sub}
		(\{ v_1(t, x_{1:K+1}, y) \}_{t \in [0, T_1]}, \ldots, \{ v_k(t, x_{k:K+1}, y) \}_{t \in [T_{k-1}, T_{k}]}, \ldots, \{ v_{K+1}(t, x_{K+1}, y) \}_{t \in [T_K, T]} ),
	\end{equation}
	where $v_k(t, x_{k:K+1}, y): [T_{k-1}, T_k] \times \overline{\cS}_k \rightarrow \R, k=1,\ldots, K+1$ is bounded and LSC. The array \eqref{sto_sub} is a stochastic subsolution of the HJB equation system if
	\begin{enumerate}[label={(\arabic*)}]	
		\item for each $k=1, \ldots K+1$, consider any random initial condition $(\tau, \xi_{k:K+1}, \xi_y)$ with $\tau \in [T_{k-1}, T_k]$, $(\xi_{k:K+1}, \xi_y) \in \cF_\tau$ and $\p((\xi_{k:K+1}, \xi_y) \in \overline{\cS}^o_k) = 1$. For any admissible control $U:= (\alpha_{k:K+1}, L_{k, K}, M_{k, K}) \in \cU(\tau, \xi_{k:K+1}, \xi_y)$ and any stopping time $\rho \in [\tau, T]$,
		\begin{equation}
			v_k(\tau, \xi_{k:K+1}, \xi_y) \leq \E \big[ \cM \big([\tau, \rho], v_{k:K+1}, (X_{k:K+1}, Y)(\cdot; \tau, \xi_{k:K+1}, \xi_y, U) \big) \big|\cF_\tau \big],
		\end{equation}
		where $\cM \big([\tau, \rho], v_{k:K+1}, (X_{k:K+1}, Y)(\cdot; \tau, \xi_{k:K+1}, \xi_y, U) \big)$ is defined in \eqref{M}.
		\item  
		\begin{align}
			v_k(t, 0, y) & \leq \sum^{K+1}_{i = k} w_i e^{-\beta (T_i-t)} G_i, \quad \forall\;  t \in [0, T], y \in \R^m, k = 1, \ldots, K+1,\\
			v_{K+1}(T, x_{K+1}, y) & \leq (G_{K+1} - x_{K+1})^+, \quad \forall \; (x_{K+1}, y) \in \cS_{K+1}.
		\end{align}
	\end{enumerate}
	Denote the set of stochastic subsolutions as $\cV^-$.
\end{definition}

With a similar argument in \citet[Remark 4.2]{bayraktar2015stochastic}, we can demonstrate that any stochastic subsolution in $\cV^-$ is dominated by the value function as follows:
\begin{align}
	v_{k}(t, x_{k:K+1}, y) & \leq V_{k}(t, x_{k:K+1}, y) \quad \text{ on } \quad [T_{k-1}, T_k] \times \overline{\cS}_k, \quad k=1, \ldots, K+1.
\end{align}

Lemma \ref{lem:two_sub} below shows that the family $\cV^-$ of stochastic subsolutions is stable under maximum. We omit the proof, since it follows directly from the definition of stochastic subsolutions and is similar to \citet[Lemma 4.1]{bayraktar2015stochastic}.
\begin{lemma}\label{lem:two_sub}
	If $ (v^1_1, \ldots, v^1_k, \ldots, v^1_{K+1})$ and $ (v^2_1, \ldots, v^2_k, \ldots, v^2_{K+1})$ are stochastic subsolutions, then $(v^1_1 \vee v^2_1, \ldots, v^1_k \vee v^2_k, \ldots, v^1_{K+1} \vee v^2_{K+1})$ is also a stochastic subsolution.
\end{lemma}


To address the boundary conditions of the viscosity supersolution, we consider an important example of stochastic subsolutions: the {\it value} function without mental accounting, i.e., $\lambda_{k} = \theta_k = 0$. In this context, \cite{capponi2024} considered a single portfolio $X$ for all goals. Between two goal deadlines, the single wealth process $X$ satisfies
\begin{equation}\label{eq:no_account}
	\begin{aligned}
		d X(u) &=  r X(u) du + (\mu(Y(u)) - r \mathbf{1})^\top \alpha(u) X(u) du + X(u) \alpha^\top(u) \sigma(Y(u)) dW(u), \\
		X(t) &= x \geq 0,
	\end{aligned}
\end{equation}
where the initial wealth $x$ is one-dimensional. At the goal deadline $T_k$, the agent withdraws $C_k$ to fund goal $k$. Hence, $X(T_k) = X(T_k-) - C_k$.

During time $t \in [T_{k-1}, T_{k}]$ with $k = 1, \ldots, K+1$, the value function without mental accounting is defined as 
\begin{equation}\label{obj:no_acc}
	\begin{aligned}
		J(t, x, y) := \inf_{\substack{ (\alpha, C_{1:K+1} ) \\ \in \cU(t, x, y) } }  \E \Big[& \sum^{K+1}_{i = 1} w_i e^{-\beta (T_i-t)} (G_i - C_i)^+ \one_{\{ T_i > t \}} \Big| X(t) = x, Y(t) = y \Big].
	\end{aligned}
\end{equation}
Importantly, we use $X(t) = x$ instead of $X(t-) = x$ in \eqref{obj:no_acc}. Hence, $J(T_k, x, y)$ is the value function right after funding the goal $k$. Based on $J(t, x, y)$, we introduce
\begin{align*}
	\Gamma_k(t, x_{k:K+1}, y) & := J(t, x_k + \ldots + x_{K+1}, y) \quad \text{ for } t \in [T_{k-1}, T_k), \\
	\Gamma_k(T_k, x_{k:K+1}, y) & := J(T_k- , x_k + \ldots + x_{K+1}, y).
\end{align*}


\begin{lemma}\label{lem:no_mental}
	$\Gamma := (\Gamma_1, \ldots, \Gamma_k, \ldots, \Gamma_{K+1})$ is a stochastic subsolution.
\end{lemma}


Given $k = 1, \ldots, K+1$ and $(t, x_{k:K+1}, y) \in [T_{k-1}, T_k] \times \overline{\cS}_k$, we define
\begin{align}
	&v_{k, -}(t, x_{k:K+1}, y) := \sup \big\{ v_k(t, x_{k:K+1}, y) |\; v_k \text{ is the $k$-th element of some } v \in \cV^- \big\}.  \label{v-}
\end{align}
The lower stochastic envelope is denoted as $v_- := (v_{1, -}, \ldots, v_{k, -}, \ldots, v_{K+1, -})$.

\begin{proposition}\label{prop:vissuper}
	The lower stochastic envelope $v_-$ is a viscosity supersolution of the HJB equation under Definition \ref{def:vis_super}.
\end{proposition}

Proofs of Lemma \ref{lem:no_mental} and Proposition \ref{prop:vissuper} are provided in Appendix \ref{sec:proof_stosub}.




\section{Comparison principle}\label{sec:compare}
In this section, we establish a comparison principle to prove the continuity and uniqueness of viscosity solutions of the HJB equation system. Detailed proofs of all results in this section can be found in Appendix \ref{sec:proof_comp}.

The first step is to construct a strict classical subsolution as follows.
\begin{lemma}\label{lem:strict_l}
	Let constants $c_1, c_2>0$, $a_i > 0, i = k, \ldots, K+1$, $q \in (0, 1)$, $\gamma>0$, and define
	\begin{equation}
		l(t, x_{k:K+1}, y) := - c_1 e^{\gamma(T_k-t)} \Big(1 + \sum^{K+1}_{i=k} a_i x_i \Big)^q - c_2 e^{\gamma(T_k - t)} (1+|y|^2),
	\end{equation}
	with $(t, x_{k:K+1}, y) \in [T_{k-1}, T_k] \times \overline{\cS}_k$. 

	Suppose
	\begin{equation}
		\begin{aligned}
			 - \theta_i < (a_i - a_{K+1}) < \lambda_i, \; i = k, \ldots K, \quad 0 < c_1 q e^{\gamma(T_k - t)} < 1,
		\end{aligned} 
	\end{equation}
	and $\gamma$ is large enough. Then $l$ is a strict classical subsolution of \eqref{F} on $[T_{k-1}, T_k) \times \overline{\cS}_k$.
\end{lemma}

Next, we present the following lemma, which is crucial to relax the continuity assumption imposed in \citet[Theorem 7.9]{crandall1992user}. A similar result can be found in \citet[Lemma 4.1]{bentahar2007}.

For notational simplicity, denote the vector $\zeta g(x_{k:K+1}) := x_{k:K+1} - Z_{k:K+1}(x_{k:K+1}, \zeta)$ with $Z_{k:K+1}(x_{k:K+1}, \zeta)$ defined in \eqref{z}.    
\begin{lemma}\label{lem:conti}
	Let $u \in \text{USC}([T_{k-1}, T_k] \times \overline{\cS}_k)$ satisfying that for $(x^o_{k:K+1}, y) \in \overline{\cS}^o_{k} \backslash \cS_k$,
	\begin{equation}
		u(t, x^o_{k:K+1}, y) = \limsup_{\substack{ x'_{k:K+1} \rightarrow x^o_{k:K+1} \\ x'_j > 0, \, j = k,\ldots,K+1}} u(t, x'_{k:K+1}, y).
	\end{equation}
	Suppose
	\begin{equation}\label{u_sub}
		\begin{aligned}
			\max \Big\{ & - \lambda_{k} + \partial_{K+1} u - \partial_{k} u, \ldots, - \lambda_{K} + \partial_{K+1} u - \partial_{K} u, \\
			& - \theta_{k} - \partial_{K+1} u + \partial_{k} u, \ldots, - \theta_K - \partial_{K+1} u + \partial_K u \Big\} \leq 0
		\end{aligned}
	\end{equation}
	holds on $[T_{k-1}, T_k] \times \cS_k$ in the viscosity sense. Then
	\begin{equation}\label{conti}
		\begin{aligned}
			& \limsup_{\zeta \downarrow 0} u(t, x_{k:K+1} - \zeta g(x_{k:K+1}), y) = \liminf_{\zeta \downarrow 0} u(t, x_{k:K+1} - \zeta g(x_{k:K+1}), y) \\
			& = u(t, x_{k:K+1}, y)
		\end{aligned}
	\end{equation}
	holds for any $t \in [T_{k-1}, T_k]$ and $(x_{k:K+1}, y) \in \overline{\cS}^o_{k}$.
\end{lemma}


In the proof of the comparison principle, one technical difficulty is that the constraints on $\partial_{K+1} v - \partial_{k} v$ are from both the above and below. To address this, we perturb $u - v$ by introducing $\delta u - v$, where the constant $\delta$ is close to $1$. The same idea also appears in \citet[Proposition 2.2]{hynd2012eigenvalue}.
\begin{proposition}[Comparison principle: $t \in [T_{k-1}, T_{k})$]\label{p:comp_btw}
	Given some $k=1, \ldots, K$, suppose
	\begin{enumerate}[label={(\arabic*)}]	
		\item  $u_k \in USC([T_{k-1}, T_k] \times \overline{\cS}_{k})$ is a viscosity subsolution of \eqref{F} on $[T_{k-1}, T_k) \times \cS_k$, that is, the USC function $u_k$ satisfies condition \eqref{F_sub} in Definition \ref{def:vis_sub}. Moreover, for $(x^o_{k:K+1}, y) \in \overline{\cS}^o_{k} \backslash \cS_k$ and $t \in [T_{k-1}, T_k)$,
		\begin{equation}\label{modi_bd_u}
			u_k(t, x^o_{k:K+1}, y) = \limsup_{\substack{ x'_{k:K+1} \rightarrow x^o_{k:K+1} \\ x'_j > 0, \, j = k,\ldots,K+1}} u_k(t, x'_{k:K+1}, y);
		\end{equation}
		\item $v_k \in LSC([T_{k-1}, T_k] \times \overline{\cS}_{k})$ is a viscosity supersolution of \eqref{F} on $[T_{k-1}, T_k) \times \overline{\cS}^o_k$, that is, the LSC function $v_k$ satisfies condition \eqref{F_super} in Definition \ref{def:vis_super};
		\item
		\begin{align}
			u_k(t, 0, y) & \leq v_k(t, 0, y), \quad \forall\;  t \in [T_{k-1}, T_k], \; y \in \R^m,\\
			u_k(T_k, x_{k:K+1}, y) & \leq v_k(T_k, x_{k:K+1}, y), \quad \forall\; (x_{k:K+1}, y) \in \overline{\cS}_{k};
		\end{align}
	\item $u_k$ and $v_k$ are bounded,
	\end{enumerate}
	then $v_k$ dominates $u_k$ in the sense that
	\begin{equation}
		u_k(t, x_{k:K+1}, y) \leq v_k(t, x_{k:K+1}, y), \quad \forall\; (t, x_{k:K+1}, y) \in [T_{k-1}, T_k] \times \overline{\cS}_{k}.
	\end{equation}
\end{proposition}


In Proposition \ref{prop:Tk}, we omit the time variable $T_k$ for simplicity.
\begin{proposition}[Terminal comparison at $T_k$]\label{prop:Tk}
	Given some $k=1, \ldots K$, consider a continuous and bounded function $f: \overline{\cS}_{k+1} \rightarrow \R$ and the PDE for $h: \overline{\cS}_{k} \rightarrow \R$:
		\begin{equation}\label{Tk_f}
		\begin{aligned}
			& F_k (x_{k:K+1}, y, h(x_{k:K+1}, y), \partial_{k:K+1} h(x_{k:K+1}, y)) \\
			& \quad := \max \Big\{ h(x_{k:K+1}, y) - w_k (G_k - x_k)^+ - f(x_{k+1:K+1}, y), \\
			& \quad \qquad \qquad - \lambda_{k} + \partial_{K+1} h - \partial_{k} h, \ldots, - \lambda_{K} + \partial_{K+1} h - \partial_{K} h, \\
			& \quad \qquad \qquad -\theta_{k} - \partial_{K+1} h + \partial_k h, \ldots, - \theta_K - \partial_{K+1} h + \partial_{K} h \Big\} = 0.
		\end{aligned}
	\end{equation}
	Suppose
	\begin{enumerate}[label={(\arabic*)}]	
		\item  $u_k \in USC(\overline{\cS}_{k})$ is a viscosity subsolution of \eqref{Tk_f} on $\cS_k$, i.e.
			\begin{equation*}
				F_k (\bar{x}_{k:K+1}, \bar{y}, u_k(\bar{x}_{k:K+1}, \bar{y}), \partial_{k:K+1} \varphi(\bar{x}_{k:K+1}, \bar{y})) \leq 0
			\end{equation*}
			for all $(\bar{x}_{k:K+1}, \bar{y}) \in \cS_k$ and for all $\varphi \in C^{2}(\cS_k)$ such that $(\bar{x}_{k:K+1}, \bar{y})$ is a maximum point of $u_k - \varphi$. Moreover, for $(x^o_{k:K+1}, y) \in \overline{\cS}^o_{k} \backslash \cS_k$,
			\begin{equation}
				u_k(x^o_{k:K+1}, y) = \limsup_{\substack{ x'_{k:K+1} \rightarrow x^o_{k:K+1} \\ x'_j > 0, \, j = k,\ldots,K+1}} u_k(x'_{k:K+1}, y);
			\end{equation} 
		\item $v_k \in LSC(\overline{\cS}_{k})$ is a viscosity supersolution of \eqref{Tk_f} on $\overline{\cS}^o_k$, i.e.
		\begin{equation*}
			F_k (\bar{x}_{k:K+1}, \bar{y}, v_k(\bar{x}_{k:K+1}, \bar{y}), \partial_{k:K+1} \varphi(\bar{x}_{k:K+1}, \bar{y})) \geq 0
		\end{equation*}
		for all $(\bar{x}_{k:K+1}, \bar{y}) \in \overline{\cS}^o_k$ and for all $\varphi \in C^{2}(\overline{\cS}^o_k)$ such that $(\bar{x}_{k:K+1}, \bar{y})$ is a minimum point of $v_k - \varphi$;
		\item
		\begin{align}
			u_k(0, y) & \leq v_k(0, y), \quad \forall \;  y \in \R^m;
		\end{align}
		\item $u_k$ and $v_k$ are bounded,
	\end{enumerate}
	then
	\begin{equation}
		u_k(x_{k:K+1}, y) \leq v_k(x_{k:K+1}, y), \quad \forall\; (x_{k:K+1}, y) \in \overline{\cS}_{k}.
	\end{equation}
\end{proposition}



The comparison principle when $t \in [T_K, T)$ is classical and much easier, since there are no gradient constraints involved. However, we could not find a precise reference applicable to our case. Therefore, we include the proof in Appendix for readers' convenience. The assumptions in Proposition \ref{prop:comp_last} are not the most general ones. 

\begin{proposition}[Comparison principle: $t \in [T_K, T)$]\label{prop:comp_last}
	Consider the HJB equation \eqref{Vlast} for $V_{K+1}(t, x_{K+1}, y)$. Suppose
	\begin{enumerate}[label={(\arabic*)}]	
	\item  $u_{K+1} \in USC([T_K, T] \times \overline{\cS}_{K+1})$ is a viscosity subsolution of \eqref{Vlast} on $[T_K, T) \times \cS_{K+1}$, that is, the USC function $u_{K+1}$ satisfies condition \eqref{Vlast_sub} in Definition \ref{def:vis_sub};
	\item $v_{K+1} \in LSC([T_K, T] \times \overline{\cS}_{K+1})$ is a viscosity supersolution of \eqref{Vlast} on $[T_K, T) \times \cS_{K+1}$, that is, the LSC function $v_{K+1}$ satisfies condition \eqref{Vlast_super} in Definition \ref{def:vis_super};
	\item
	\begin{align}
		u_{K+1}(t, 0, y) & \leq v_{K+1}(t, 0, y), \quad \forall\;  t \in [T_K, T], \; y \in \R^m,\\
		u_{K+1}(T, x_{K+1}, y) & \leq v_{K+1}(T, x_{K+1}, y), \quad \forall\; (x_{K+1}, y) \in \overline{\cS}_{K+1};
	\end{align}
	\item $u_{K+1}$ and $v_{K+1}$ are bounded,
\end{enumerate}
then
\begin{equation}
	u_{K+1}(t, x_{K+1}, y) \leq v_{K+1}(t, x_{K+1}, y), \quad \forall\; (t, x_{K+1}, y) \in [T_K, T] \times \overline{\cS}_{K+1}.
\end{equation}
\end{proposition}

We now present the proof of Theorem \ref{thm:viscosity}.
\begin{proof}
	First, using a similar argument as in \citet[Remark 3.2 and 4.2]{bayraktar2015stochastic}, we have for $k=1, \ldots, K+1$:
	\begin{align}
		v_{k, -}(t, x_{k:K+1}, y) & \leq V_{k}(t, x_{k:K+1}, y) \quad \text{ on } \quad [T_{k-1}, T_k] \times \overline{\cS}_k, \\
		V_{k}(t, x_{k:K+1}, y)  & \leq v_{k, +}(t, x_{k:K+1}, y) \quad \text{ on } \quad [T_{k-1}, T_k] \times (\cS_k \cup (\{ 0 \} \times \R^m)).
	\end{align}
	Thanks to Lemma \ref{lem:boundary}, the modified function $ \tilde{v}_{k, +} (t, x_{k:K+1}, y)$ defined in \eqref{eq:modified} satisfies
	\begin{align}
		V_{k}(t, x_{k:K+1}, y)  & \leq \tilde{v}_{k, +}(t, x_{k:K+1}, y) \quad \text{ on } \quad [T_{k-1}, T_k] \times \overline{\cS}_k, \quad k = 1, \ldots, K.
	\end{align}

	Moreover, the modified function $\tilde{v}_+ = (\tilde{v}_{1, +}, \ldots, \tilde{v}_{k, +}, \ldots, \tilde{v}_{K, +}, v_{K+1, +})$ is a viscosity subsolution of the HJB equation under Definition \ref{def:vis_sub}. By Proposition \ref{prop:vissuper}, the lower stochastic envelope $v_-$ is a viscosity supersolution of the HJB equation under Definition \ref{def:vis_super}. To obtain the continuity and uniqueness of the viscosity solution, we apply the comparison principle in Propositions \ref{prop:comp_last}, \ref{prop:Tk}, and \ref{p:comp_btw} backwardly: 
	\begin{enumerate}[label={(\arabic*)}]	
		\item By Proposition \ref{prop:vissub} and \ref{prop:vissuper}, $v_{K+1, +}$ is USC and $v_{K+1, -}$ is LSC. Moreover, 
		\begin{align}
			v_{K+1, +}(t, 0, y) & \leq v_{K+1, -}(t, 0, y), \quad \forall\;  t \in [T_K, T], \; y \in \R^m,\\
			v_{K+1, +}(T, x_{K+1}, y) & \leq v_{K+1, -}(T, x_{K+1}, y), \quad \forall\; (x_{K+1}, y) \in \overline{\cS}_{K+1};
		\end{align}
		Then Proposition \ref{prop:comp_last} implies 
		$$v_{K+1, +} (t, x_{K+1}, y) \leq v_{K+1, -} (t, x_{K+1}, y)  \quad \text{on} \quad [T_{K}, T] \times \overline{\cS}_{K+1}.$$ 
		It leads to
		$$v_{K+1, +}(t, x_{K+1}, y) = v_{K+1, -}(t, x_{K+1}, y) = V_{K+1}(t, x_{K+1}, y) \text{ on } [T_{K}, T] \times \overline{\cS}_{K+1}.$$
		Hence, $V_{K+1}$ is continuous and unique;
		\item  At the deadline $T_{K}$, Propositions \ref{prop:vissub} and \ref{prop:vissuper} show that $\tilde{v}_{K, +}(T_K, \cdot, \cdot)$ is USC and $v_{K, -}(T_K, \cdot, \cdot)$ is LSC. Moreover, $\tilde{v}_{K, +}(T_K, 0, y) \leq v_{K, -}(T_K, 0, y)$. By Lemma \ref{lem:boundary}, \ref{lem:conti}, and step (1) above, we can apply Proposition \ref{prop:Tk} and obtain 
		$$\tilde{v}_{K, +}(T_K, x_{K:K+1}, y) = v_{K, -}(T_K, x_{K:K+1}, y) = V_K(T_K, x_{K:K+1}, y) \text{ on } \overline{\cS}_K.$$
		Then $V_K(T_K, \cdot, \cdot)$ is continuous in $(x_{K:K+1}, y)$ and unique;
		\item On $[T_{K-1}, T_K)$, Propositions \ref{prop:vissub} and \ref{prop:vissuper} show that $\tilde{v}_{K, +}$ is USC, $v_{K, -}$ is LSC, and
		\begin{align}
			\tilde{v}_{K, +}(t, 0, y) & \leq v_{K, -}(t, 0, y), \quad \forall\;  t \in [T_{K-1}, T_K], \; y \in \R^m.
		\end{align}
		Step (2) above shows that
		\begin{align}
			\tilde{v}_{K, +}(T_K, x_{K:K+1}, y) & \leq v_{K, -}(T_K, x_{K:K+1}, y), \quad \forall\; (x_{K:K+1}, y) \in \overline{\cS}_{K}.
		\end{align} 

		Hence, by Propositions \ref{prop:vissub} and \ref{prop:vissuper}, together with Lemma \ref{lem:boundary} and \ref{lem:conti}, we can apply Proposition \ref{p:comp_btw} and show that
		$$\tilde{v}_{K, +}(t, x_{K:K+1}, y) = v_{K, -}(t, x_{K:K+1}, y) = V_K(t, x_{K:K+1}, y) \quad \text{ on } \quad [T_{K-1}, T_K] \times \overline{\cS}_{K}. $$
		Then $V_K$ is continuous in $(t, x_{K:K+1}, y)$ and unique;
		\item We repeat the procedures as in step (2) and (3) until $[0, T_1]$. In summary, for each $k = 1, \ldots, K+1$, $V_k(t, x_{k:K+1}, y)$ is continuous and bounded on $[T_{k-1}, T_k] \times \overline{\cS}_k$.
	\end{enumerate}	
\end{proof}






