\section{Proofs of results} 

\subsection{Results of the stochastic supersolution}\label{sec:proof_stosuper}

\begin{proof}[Proof of Proposition \ref{prop:vissub}]
	{\bf Step 1}. The boundary/terminal conditions in Definition \ref{def:vis_sub} (4): Clearly, the array with functions
	\begin{equation}
		v_k(t, x_{k:K+1}, y) := \sum^{K+1}_{i = k} w_i e^{-\beta (T_i-t)} G_i,
	\end{equation} 
	is a stochastic supersolution with the admissible control $U = (0, 0, 0)$ that does not invest in stocks and makes no transfer. Since $v_+$ is the infimum of stochastic supersolutions, $v_+$ satisfies the boundary condition \eqref{vissub_bd0} at $x_{k:K+1} = 0$. By a modification of the proof in \citet[Theorem 3.1]{bayraktar2013stochastic}, it follows that $v_{K+1, +}$ in $v_+$ satisfies the terminal condition \eqref{visub_T} at $T$.

	{\bf Step 2}. The viscosity subsolution property in Definition \ref{def:vis_sub} (3), when $t \in [T_k, T)$: Similarly, it follows from the proof of \citet[Theorem 3.1]{bayraktar2013stochastic}.

	{\bf Step 3}. The viscosity subsolution property in Definition \ref{def:vis_sub} (2), when $t=T_K$: Let $(\bar{x}_{K:K+1}, \bar{y}) \in \cS_K = (0, \infty)^2 \times \R^m$ and $\varphi(x_{K:K+1}, y) \in C^2(\cS_K)$ be a test function such that $v_{K, +}(T_K, \cdot, \cdot) - \varphi(\cdot, \cdot)$ attains a strict local maximum of zero at $(\bar{x}_{K:K+1}, \bar{y})$. We want to prove
	\begin{equation}
		\begin{aligned}
			\max \Big\{ & v_{K, +}(T_K, \bar{x}_{K:K+1}, \bar{y}) - w_K (G_K - \bar{x}_K)^+ - v_{K+1, +}(T_K, \bar{x}_{K+1}, \bar{y}), \\
			& - \lambda_{K} + \partial_{K+1} \varphi(\bar{x}_{K:K+1}, \bar{y}) - \partial_{K} \varphi(\bar{x}_{K:K+1}, \bar{y}), \\
			&- \theta_K - \partial_{K+1} \varphi(\bar{x}_{K:K+1}, \bar{y}) + \partial_{K} \varphi (\bar{x}_{K:K+1}, \bar{y}) \Big\} \leq 0.
		\end{aligned}
	\end{equation}
	Assume on the contrary that the left-hand side is strictly positive. There are three cases to consider: 

	{\bf Step 3: Case (1)}. $ v_{K, +}(T_K, \bar{x}_{K:K+1}, \bar{y}) - w_K (G_K - \bar{x}_K)^+ - v_{K+1, +}(T_K, \bar{x}_{K+1}, \bar{y}) > 0$. 

	As $v_{K+1, +}$ is USC, there exists a small $\varepsilon > 0$ such that
	\begin{equation*}
		v_{K, +}(T_K, \bar{x}_{K:K+1}, \bar{y}) \geq w_K (G_K - x_K)^+ + v_{K+1, +}(T_K, x_{K+1}, y) + \varepsilon
	\end{equation*}
	on the compact set $\overline{B(\bar{x}_{K:K+1}, \bar{y}, \varepsilon)}$, the closure of 
	\begin{equation}\label{Beps}
		B(\bar{x}_{K:K+1}, \bar{y}, \varepsilon) : = \{(x_{K:K+1}, y): |(x_{K:K+1}, y) - (\bar{x}_{K:K+1}, \bar{y})| < \varepsilon \}.
	\end{equation}
	Since $(\bar{x}_{K:K+1}, \bar{y})$ is in the interior $\cS_{K}$ and $\varepsilon$ is small enough, we can choose $\overline{B(\bar{x}_{K:K+1}, \bar{y},\varepsilon)} \subset \cS_K$. By \citet[Proposition 4.1]{bayraktar2012linear}, we obtain a nonincreasing sequence of stochastic supersolutions $v^n_{K+1} \searrow v_{K+1, +}$. Moreover, every $v^n_{K+1}$ has a corresponding stochastic supersolution $v^n = (v^n_1, \ldots, v^n_K, v^n_{K+1})$. Indeed, we can specify the function class $\mathcal{G}$ in \citet[Proposition 4.1]{bayraktar2012linear} to be functions $v_{K+1}$ that can form a stochastic supersolution $v = (v_1, \ldots, v_K, v_{K+1})$ with some $(v_1, \ldots, v_{K})$, which can be different for different $v_{K+1}$. By \citet[Lemma 2.4]{bayraktar2014Dynkin}, for the given compact set $\overline{B(\bar{x}_{K:K+1}, \bar{y},\varepsilon)}$ defined above, there exists a large enough $n_1$ such that $v^{n_1}_{K+1}$ is close enough to $v_{K+1, +}$ and yields 
	\begin{equation}\label{n1}
		v_{K, +}(T_K, \bar{x}_{K:K+1}, \bar{y}) \geq w_K (G_K - x_K)^+ + v^{n_1}_{K+1}(T_K, x_{K+1}, y) + \frac{\varepsilon}{2}
	\end{equation}  
	on $\overline{B(\bar{x}_{K:K+1}, \bar{y},\varepsilon)}$. Besides, $v^{n_1}_{K+1}$ corresponds to a stochastic supersolution $v^{n_1} = (v^{n_1}_1, \ldots$, $ v^{n_1}_K, v^{n_1}_{K+1})$. 

	Define sets
	\begin{align*}
		D(T_K, \bar{x}_{K:K+1}, \bar{y}, \varepsilon) & := (T_K - \varepsilon, T_K] \times B(\bar{x}_{K:K+1}, \bar{y}, \varepsilon), \\
		E(\varepsilon) & := \overline{D(T_K, \bar{x}_{K:K+1}, \bar{y},\varepsilon)} \backslash D(T_K, \bar{x}_{K:K+1}, \bar{y},\varepsilon/2). 
	\end{align*}


	Since $v_{K, +}$ is USC and $E(\varepsilon)$ is compact, $v_{K, +}$ is bounded from above on $E(\varepsilon)$. For a small enough $\eta > 0$, we obtain
	\begin{equation*}
		\sup_{(t, x_{K:K+1}, y) \in E} v_{K, +}(t, x_{K:K+1}, y) - v_{K, +} (T_K, \bar{x}_{K:K+1}, \bar{y}) < \frac{\varepsilon^2}{4 \eta} - \varepsilon. 
	\end{equation*}
	As this inequality is strict, we can find another $v^{n_2}_K$, which corresponds to a stochastic supersolution $v^{n_2} = (v^{n_2}_1, \ldots, v^{n_2}_K, v^{n_2}_{K+1})$, and
	\begin{equation}\label{n2}
		\sup_{(t, x_{K:K+1}, y) \in E} v^{n_2}_{K}(t, x_{K:K+1}, y) - v_{K, +} (T_K, \bar{x}_{K:K+1}, \bar{y}) < \frac{\varepsilon^2}{4 \eta} - \varepsilon. 
	\end{equation}
	Finally, we take
	$$v^n := (v^{n}_1, \ldots, v^{n}_{K+1}) := (v^{n_1}_1 \wedge v^{n_2}_1, \ldots, v^{n_1}_{K+1} \wedge v^{n_2}_{K+1}),$$
	which is a stochastic supersolution by Lemma \ref{lem:two_stochsup}. The inequalities \eqref{n1} and \eqref{n2} also hold for $v^n_{K+1}$ and $v^n_K$, respectively.

	We introduce an operator
	\begin{equation}
		\begin{aligned}
			& [L^{\alpha_{k:K+1}}V_k] (x_{k:K+1}, y) \\
			& \quad := \sum^{K+1}_{i=k} r x_{i} \partial_i V_k + \mu_Y(y)^\top \partial_y V_k  \\
			& \qquad +  \sum^{K+1}_{i=k}  (\mu(y) - r \one )^\top \alpha_i x_i \partial_i V_k + \frac{1}{2} \tr\left[\Sigma(\alpha_{k:K+1}, x_{k:K+1}, y) \partial^2 V_k  \right] ,
		\end{aligned}
	\end{equation}
	such that the Hamiltonian can be expressed as
	\begin{equation}
		\begin{aligned}
			& H(x_{k:K+1}, y, \partial V_k, \partial^2 V_k) = \inf_{\alpha_{k:K+1} \in \cA^{K-k+2}} [L^{\alpha_{k:K+1}}V_k] (x_{k:K+1}, y).
		\end{aligned}
	\end{equation}

	For $p > 0$, define
	\begin{equation*}
		\psi^{\varepsilon, \eta, p}(t, x_{K:K+1}, y) := v_{K,+} (T_K, \bar{x}_{K:K+1}, \bar{y}) + \frac{|(x_{K:K+1}, y) -  (\bar{x}_{K:K+1}, \bar{y})|^2}{\eta} + p(T_K - t).
	\end{equation*}
	With a large enough $p$,
	\begin{equation*}
		\beta \psi^{\varepsilon, \eta, p} - \partial_t \psi^{\varepsilon, \eta, p} - \inf_{\alpha_{K:K+1} \in \cA^{2}} L^{\alpha_{K:K+1}} \psi^{\varepsilon, \eta, p} > 0 \quad \text{ on } \overline{D(T_K, \bar{x}_{K:K+1}, \bar{y},\varepsilon)}.
	\end{equation*}
	Moreover, there exist constant $\bar{\alpha}_{K:K+1}$ such that
	\begin{equation}
		\beta \psi^{\varepsilon, \eta, p} - \partial_t \psi^{\varepsilon, \eta, p} - L^{\bar{\alpha}_{K:K+1}} \psi^{\varepsilon, \eta, p} > 0 \quad \text{ on } \overline{D(T_K, \bar{x}_{K:K+1}, \bar{y},\varepsilon)}.
	\end{equation}

	By the definition of set $E(\varepsilon)$, the inequality \eqref{n2}, and a large enough $p$,
	\begin{align}
		\psi^{\varepsilon, \eta, p}(t, x_{K:K+1}, y) & \geq v_{K, +} (T_K, \bar{x}_{K:K+1}, \bar{y}) + \frac{\varepsilon^2}{4 \eta} \nonumber \\
		& > \varepsilon + \sup_{(t, x_{K:K+1}, y) \in E} v^{n}_{K}(t, x_{K:K+1}, y) \nonumber \\
		& \geq \varepsilon + v^n_K (t, x_{K:K+1}, y) \quad \text{ on } E(\varepsilon). \label{Eineq}
	\end{align}

	Besides, for any $t \leq T_K$ and $(x_{K:K+1}, y) \in \overline{B(\bar{x}_{K:K+1}, \bar{y},\varepsilon)}$, \eqref{n1} leads to
	\begin{align}
		\psi^{\varepsilon, \eta, p}(t, x_{K:K+1}, y) & \geq v_{K, +} (T_K, \bar{x}_{K:K+1}, \bar{y}) \nonumber \\
		& \geq w_K (G_K - x_K)^+ + v^{n}_{K+1}(T_K, x_{K+1}, y) + \frac{\varepsilon}{2}. \label{psi_bd}
	\end{align}

	Let $0 <\delta < \frac{\varepsilon}{2}$ be small enough such that
	\begin{equation}
		\beta (\psi^{\varepsilon, \eta, p} - \delta) - \partial_t (\psi^{\varepsilon, \eta, p} - \delta) - L^{\bar{\alpha}_{K:K+1}} (\psi^{\varepsilon, \eta, p} - \delta) > 0 \quad \text{ on } \overline{D(T_K, \bar{x}_{K:K+1}, \bar{y},\varepsilon)}.
	\end{equation}
	Set
	\begin{equation}
		v^{\varepsilon, \eta, p, \delta}_{K} (t, x_{K:K+1}, y) := \left\{ 
		\begin{array}{ c l }
			v^n_K (t, x_{K:K+1}, y) \wedge (\psi^{\varepsilon, \eta, p}(t, x_{K:K+1}, y) - \delta) & \text{on } \overline{D(T_K, \bar{x}_{K:K+1}, \bar{y},\varepsilon)}, \\
			v^n_K (t, x_{K:K+1}, y), & \text{otherwise}.
		\end{array}
		\right.
	\end{equation}

	Next, we show that $(v^n_1, \ldots, v^{\varepsilon, \eta, p, \delta}_{K}, v^n_{K+1})$ is a stochastic supersolution. Then it leads to the following contradiction:
	$$v^{\varepsilon, \eta, p, \delta}_{K} (T_K, \bar{x}_{K:K+1}, \bar{y}) = v_{K, +} (T_K, \bar{x}_{K:K+1}, \bar{y})  - \delta < v_{K, +} (T_K, \bar{x}_{K:K+1}, \bar{y}).$$

	Clearly, $(v^n_1, \ldots, v^{\varepsilon, \eta, p, \delta}_{K}, v^n_{K+1})$ satisfies the boundary/terminal conditions in Definition \ref{def:sto_super} (2). For the supermartingale property in Definition \ref{def:sto_super} (1), we first verify it when the random initial condition $(\tau, \xi_{K:K+1}, \xi_y)$ satisfies $\tau \in [T_{K-1}, T_K]$.

	Define $\psi^{p, \delta} := \psi^{\varepsilon, \eta, p} - \delta$ and the event
	\begin{equation*}
		A := \{ (\tau, \xi_{K:K+1}, \xi_y) \in D(T_K, \bar{x}_{K:K+1}, \bar{y},\varepsilon/2) \} \cap \{\psi^{p, \delta}(\tau, \xi_{K:K+1}, \xi_y) < v^n_K(\tau, \xi_{K:K+1}, \xi_y)\}.
	\end{equation*}
	Then $A \in \cF_\tau$. 

	Let $U^0 := (\alpha^0_{K:K+1}, L^0_K, M^0_K)$ be a suitable control for $v^n_{K}$ with the random initial condition $(\tau, \xi_{K:K+1}, \xi_y)$. Define a new control $U^1 := (\alpha^1_{K:K+1}, L^1_K, M^1_K)$ by
	\begin{equation}\label{U1}
		\begin{aligned}
			\alpha^1_{K:K+1}(t) & := \bar{\alpha}_{K:K+1} \one_{A \cap \{ \tau \leq t\}} + \alpha^0_{K:K+1}(t) \one_{A^c \cap \{ \tau \leq t\}}, \\
			(L^1_K(t), M^1_K(t)) & := \one_{A^c \cap \{ \tau \leq t\}} (L^0_K(t) - L^0_K(\tau-), M^0_K(t) - M^0_K(\tau-)).
		\end{aligned}
	\end{equation}
	By Lemma \ref{lem:glue}, we have $U^1 \in \cU (\tau, \xi_{K:K+1}, \xi_y)$. Denote $\{ (X_{K:K+1}, Y)(t; \tau, \xi_{K:K+1}, \xi_y, U^1) \}_{t \in [\tau, T]}$ as the solution of the state process with the random initial condition $(\tau, \xi_{K:K+1}, \xi_y)$ under the control $U^1$. Then $\p((X_{K:K+1}, Y)(t; \tau, \xi_{K:K+1}, \xi_y, U^1) \in \cS_{K}, \; \tau \leq t \leq T ) = 1$.


	Moreover, if $A^c$ happens, then $v^{\varepsilon, \eta, p, \delta}_{K} (\tau, \xi_{K:K+1}, \xi_y) = v^n_{K} (\tau, \xi_{K:K+1}, \xi_y)$. Hence, $U^1$ follows $U^0$ under $A^c$, which is a suitable control for $v^n_K$ starting from the time $\tau$.

	Let 
	\begin{align*}
		\tau^1 := \inf \{ t \in [\tau, T_K] \, | \,  (t,  (X_{K:K+1}, Y)(t; \tau, \xi_{K:K+1}, \xi_y, U^1)) \notin  D(T_K, \bar{x}_{K:K+1}, \bar{y}, \varepsilon/2) \}
	\end{align*}
	be the exit time of $D(T_K, \bar{x}_{K:K+1}, \bar{y},\varepsilon/2)$ and 
	\begin{align*}
		\xi^1 := (\xi^1_{K:K+1}, \xi^1_y) :=  ((X_{K:K+1}, Y)(\tau^1; \tau, \xi_{K:K+1}, \xi_y, U^1)) \in \cF_{\tau^1}
	\end{align*}
	be the exit position. 

%	If $\tau^1 < T_K$, then $|\xi^1 - (\bar{x}_{K:K+1}, \bar{y})| \geq \varepsilon/2$. However, if $\tau^1 = T_K$, it is still possible that we have $|\xi^1 - (\bar{x}_{K:K+1}, \bar{y})| < \varepsilon/2$. Hence, we consider the following two events separately:
%	\begin{align*}
%		G_a & := \{ \tau^1 = T_K \} \cap \{ | \xi^1 -  (\bar{x}_{K:K+1}, \bar{y}) | < \varepsilon/2 \text{ and } v^n_K(\tau^1, \xi^1) > \psi^{\varepsilon, \eta, p}(\tau^1, \xi^1) - \delta \}, \\
%		G_o & := \{ \tau^1 = T_K \} \cap \{ | \xi^1 -  (\bar{x}_{K:K+1}, \bar{y}) | \geq \varepsilon/2 \text{ or } v^n_K(\tau^1, \xi^1) \leq \psi^{\varepsilon, \eta, p}(\tau^1, \xi^1) - \delta \}.
%	\end{align*}
%	Then $G_a, G_o \in \cF_{T_K}$.

	Since $\tau^1 \leq T_K$ and $\xi^1 \in \cF_{\tau^1}$, then $(T_K, \xi^1_{K+1}, \xi^1_y)$ is a random initial condition. As $\p(\xi^1 \in \cS_{K}) = 1$, there exists a suitable control $U^2 := \{ \alpha^2_{K+1}(t) \}_{t \in [T_K, T]}$ for $v^n_{K+1}$ with the random initial condition $(T_K, \xi^1_{K+1}, \xi^1_y)$. $(\tau^1, \xi^1)$ is also a random initial condition. As $\p(\xi^1 \in \cS_{K}) = 1$, there is a suitable control $U^3 := ( \alpha^3_{K:K+1}, L^3_K, M^3_K)$ for $v^n_{K}$ with the random initial condition $(\tau^1, \xi^1)$. Finally, define a control $U := (\alpha_{K:K+1}, L_K, M_K)$ by
	\begin{align*}
		& (\alpha_{K:K+1}(t), L_K(t), M_K(t)) \\
		& \quad  = \one_{\{ \tau \leq t < \tau^1 \}} U^1(t) + \one_{ \{ \tau^1 = T_K\} \cap \{ \tau^1 \leq t \leq T\} } (L^1_K(\tau^1), M^1_K(\tau^1), U^2(t)) \\
		& \qquad + \one_{\{ \tau^1 < T_K\}  \cap \{ \tau^1 \leq t \leq T\} } (\alpha^3_{K:K+1}(t), L^3_K(t) - L^3_K(\tau^1-) + L^1_K(\tau^1), \\ 
		& \hspace{4.5cm} M^3_K(t) - M^3_K(\tau^1-) + M^1_K(\tau^1) ).
	\end{align*}
	By Lemma \ref{lem:glue}, the control $U \in \cU(\tau, \xi_{K:K+1}, \xi_y)$. Moreover, $\p((X_{K:K+1}, Y)(t; \tau, \xi_{K:K+1}, \xi_y, U) \in \cS_{K}, \; \tau \leq t \leq T ) = 1$. We verify that $U$ is suitable for $v^{\varepsilon, \eta, p, \delta}_{K}$ with $(\tau, \xi_{K:K+1}, \xi_y)$.

	 Consider a stopping time $\rho \in [\tau, T]$. Applying the It\^o's formula to $\psi^{p, \delta}$ from $\tau$ to $\rho \wedge \tau^1$ under the event $A$, we obtain
	\begin{align}
		& \one_A v^{\varepsilon, \eta, p, \delta}_{K} (\tau, \xi_{K:K+1}, \xi_y) \nonumber \\
		& = \one_A \psi^{p, \delta} (\tau, \xi_{K:K+1}, \xi_y) \nonumber \\
		& = \one_A \psi^{p, \delta} (\tau, (X_{K:K+1}, Y)(\tau; \tau, \xi_{K:K+1}, \xi_y, U^1)) \nonumber \\
		 & \geq \E\Big[ \one_{A \cap \{ \rho < \tau^1\}} e^{- \beta(\rho - \tau)}  \psi^{p, \delta} (\rho, (X_{K:K+1}, Y)(\rho; \tau, \xi_{K:K+1}, \xi_y, U^1)) \label{psiAineq1} \\
		& \qquad + \one_{A \cap \{ \rho \geq \tau^1\}}  e^{- \beta(\tau^1 - \tau)}  \psi^{p, \delta} (\tau^1, \xi^1) \Big| \cF_\tau \Big]. \nonumber
	\end{align} 
	Moreover, \eqref{Eineq} and \eqref{psi_bd} lead to
	\begin{align}
		\one_{A \cap \{ \rho \geq \tau^1\}} \psi^{p, \delta} (\tau^1, \xi^1) \geq & \one_{A \cap \{ \rho \geq \tau^1\} \cap \{ \tau^1 < T_K\}} v^n_K(\tau^1, \xi^1) \label{psiAineq2} \\
		& + \one_{A \cap \{ \rho \geq \tau^1\} \cap \{ \tau^1 = T_K\}} \big( w_K(G_K - \xi^1_K)^+ + v^n_{K+1}(T_K, \xi^1_{K+1}, \xi^1_y) \big). \nonumber
	\end{align}
	Combining \eqref{psiAineq1} and \eqref{psiAineq2}, since $v^{\varepsilon, \eta, p, \delta}_{K} \leq \psi^{p, \delta}$ on $\overline{D(T_K, \bar{x}_{K:K+1}, \bar{y},\varepsilon)}$, we obtain
		\begin{align}
		& \one_A v^{\varepsilon, \eta, p, \delta}_{K} (\tau, \xi_{K:K+1}, \xi_y) \nonumber \\
		& \geq \E\Big[ \one_{A \cap \{ \rho < \tau^1\}} e^{- \beta(\rho - \tau)}  v^{\varepsilon, \eta, p, \delta}_{K} (\rho, (X_{K:K+1}, Y)(\rho; \tau, \xi_{K:K+1}, \xi_y, U^1)) \label{psiAineq} \\
		& \qquad + \one_{A \cap \{ \rho \geq \tau^1\} \cap \{ \tau^1 < T_K\}}  e^{- \beta(\tau^1 - \tau)}  v^n_K(\tau^1, \xi^1) \nonumber \\
		& \qquad + \one_{A \cap \{ \rho \geq \tau^1\} \cap \{ \tau^1 = T_K\}}  e^{- \beta(T_K - \tau)}  \big( w_K(G_K - \xi^1_K)^+ + v^n_{K+1}(T_K, \xi^1_{K+1}, \xi^1_y) \big)  \Big| \cF_\tau \Big]. \nonumber
	\end{align} 

	Under the event $A^c$, because $U^1$ is a suitable control for $v^n_{K}$ with the random initial condition $(\tau, \xi_{K:K+1}, \xi_y)$, we have
	\begin{align}
		& \one_{A^c} v^{\varepsilon, \eta, p, \delta}_{K} (\tau, \xi_{K:K+1}, \xi_y) = \one_{A^c} v^{n}_{K} (\tau, \xi_{K:K+1}, \xi_y) \nonumber \\
		& \geq \E\Big[ \one_{A^c \cap \{ \rho < \tau^1\}} e^{- \beta(\rho - \tau)}  v^{n}_{K} (\rho, (X_{K:K+1}, Y)(\rho; \tau, \xi_{K:K+1}, \xi_y, U^1))  \label{Acvnineq} \\
		& \qquad + \one_{A^c \cap \{ \rho \geq \tau^1\} \cap \{ \tau^1 < T_K \}} e^{- \beta(\tau^1 - \tau)}  v^{n}_{K} (\tau^1, \xi^1) \nonumber \\
		& \qquad + \one_{A^c \cap \{ \rho \geq \tau^1\} \cap \{ \tau^1 = T_K \}} e^{- \beta(T_K - \tau)}  \big( w_K(G_K - \xi^1_K)^+ + v^n_{K+1}(T_K, \xi^1_{K+1}, \xi^1_y) \big)  \nonumber \\
		& \qquad + \lambda_{K} \int^{\rho \wedge \tau^1}_\tau e^{-\beta (s - \tau)} dL^1_K(s) + \theta_{K} \int^{\rho \wedge \tau^1}_\tau e^{-\beta (s - \tau)} dM^1_K(s) \Big| \cF_\tau \Big]. \nonumber
	\end{align} 
	As $v^n_K \geq v^{\varepsilon, \eta, p, \delta}_{K}$ everywhere and $U = U^1$ when $\rho < \tau^1$,  \eqref{psiAineq} and \eqref{Acvnineq} yield
		\begin{align}
		& v^{\varepsilon, \eta, p, \delta}_{K} (\tau, \xi_{K:K+1}, \xi_y) \nonumber \\
		& \geq \E\Big[ \one_{\{ \rho < \tau^1\}} e^{- \beta(\rho - \tau)}  v^{\varepsilon, \eta, p, \delta}_{K} (\rho, (X_{K:K+1}, Y)(\rho; \tau, \xi_{K:K+1}, \xi_y, U))  \label{ineq:tau1} \\
		& \qquad + \one_{ \{ \rho \geq \tau^1\} \cap \{ \tau^1 < T_K \}} e^{- \beta(\tau^1 - \tau)}  v^{n}_{K} (\tau^1, \xi^1) \nonumber \\
		& \qquad + \one_{\{ \rho \geq \tau^1\} \cap \{ \tau^1 = T_K \}} e^{- \beta(T_K - \tau)}  \big( w_K(G_K - \xi^1_K)^+ + v^n_{K+1}(T_K, \xi^1_{K+1}, \xi^1_y) \big)  \nonumber \\
		& \qquad +\lambda_{K} \int^{\rho \wedge \tau^1}_\tau e^{-\beta (s - \tau)} dL^1_K(s) + \theta_{K} \int^{\rho \wedge \tau^1}_\tau e^{-\beta (s - \tau)} dM^1_K(s) \Big| \cF_\tau \Big]. \nonumber
	\end{align} 

	Since $U^2$ is a suitable control for $v^n_{K+1}$ with the random initial condition $(T_K, \xi^1_{K+1}, \xi^1_y)$ and $U^3$ is a suitable control for $v^n_{K}$ with the random initial condition $(\tau^1, \xi^1)$, \eqref{ineq:tau1} and the definition of $U$ yield the desired result:
	\begin{align*}
		v^{\varepsilon, \eta, p, \delta}_{K} (\tau, \xi_{K:K+1}, \xi_y) \geq \E\Big[& \one_{\{ \tau \leq \rho < T_K \}} \Big\{ e^{- \beta(\rho - \tau)}  v^{\varepsilon, \eta, p, \delta}_{K} (\rho, (X_{K:K+1}, Y)(\rho; \tau, \xi_{K:K+1}, \xi_y, U))  \\
		& \quad \qquad \qquad + \lambda_{K} \int^\rho_\tau e^{-\beta (s - \tau)} dL_K(s) + \theta_{K} \int^\rho_\tau e^{-\beta (s - \tau)} dM_K(s) \Big\} \nonumber \\
		& + \one_{\{ T_K \leq \rho \leq T\}} \Big\{ w_K e^{-\beta(T_K - \tau)} (G_K - X_K(T_K; \tau, \xi_{K:K+1}, \xi_y, U))^+ \nonumber \\
		& \hspace{2.5cm} + e^{-\beta(\rho - \tau)}  v^n_{K+1}(\rho, (X_{K+1}, Y)(\rho; \tau, \xi_{K:K+1}, \xi_y, U)) \nonumber \\
		& \hspace{2.5cm} +  \lambda_K \int^{T_K}_{\tau} e^{-\beta(s - \tau)} dL_K(s) \nonumber \\
		& \hspace{2.5cm} + \theta_K \int^{T_K}_{\tau}  e^{-\beta(s - \tau)} dM_K(s) \Big\} \Big| \cF_\tau \Big].
	\end{align*}
	It is direct to verify the supermartingale property when $\tau \in [T_{k-1}, T_k]$, $k \neq K$. We omit it here.


	{\bf Step 3: Case (2)}. $- \lambda_{K} + \partial_{K+1} \varphi(\bar{x}_{K:K+1}, \bar{y}) - \partial_{K} \varphi(\bar{x}_{K:K+1}, \bar{y}) > 0$.

	Since $\varphi$ is $C^2$, there exists a small closed ball $\overline{B(\bar{x}_{K:K+1}, \bar{y},\varepsilon)} \subset \cS_K$, such that
	\begin{equation*}
		- \lambda_{K} + \partial_{K+1} \varphi(x_{K:K+1}, y) - \partial_{K} \varphi(x_{K:K+1}, y) > 0 \quad \text{ on } \quad \overline{B(\bar{x}_{K:K+1}, \bar{y},\varepsilon)}.
	\end{equation*} 
	Since the maximum at $(\bar{x}_{K:K+1}, \bar{y})$ is strict, we have
	\begin{equation*}
		v_{K, +}(T_K, x_{K:K+1}, y) < \varphi(x_{K:K+1}, y) \quad \text{ on }  \overline{B(\bar{x}_{K:K+1}, \bar{y},\varepsilon)} \backslash \{ (\bar{x}_{K:K+1}, \bar{y}) \}.
	\end{equation*}
	Define
	\begin{equation*}
		\varphi^p(t, x_{K:K+1}, y) := \varphi(x_{K:K+1}, y) + p(T_K - t).
	\end{equation*}
	We introduce a function
	\begin{equation*}
		h(\delta) := \sup_{\substack{ T_K - \delta \leq t \leq T_K, \\ \frac{\varepsilon}{2} \leq | (x_{K:K+1}, y) -  (\bar{x}_{K:K+1}, \bar{y})| \leq \varepsilon }} \Big( v_{K, +}(t, x_{K:K+1}, y) - \varphi(x_{K:K+1}, y) \Big), \quad 0 < \delta < \delta_0,
	\end{equation*}
	with some small $\delta_0 > 0$. Since $v_{K, +} - \varphi$ is USC as a function of $(t, x_{K:K+1}, y)$, then the maximum in $h(\delta)$ is attained. Let a maximizer be $(t^\delta, x^\delta_{K:K+1}, y^\delta)$. By compactness, there exists a subsequence, still denoted as $\delta \searrow 0$, such that 
	\begin{equation*}
		(t^\delta, x^\delta_{K:K+1}, y^\delta) \rightarrow (T_K, x^*_{K:K+1}, y^*) \quad \text{and} \quad \frac{\varepsilon}{2} \leq | (x^*_{K:K+1}, y^*) -  (\bar{x}_{K:K+1}, \bar{y})| \leq \varepsilon.
	\end{equation*}
	Thus,
	\begin{align}
		\limsup_{\delta \searrow 0} h(\delta) & = \limsup_{\delta \searrow 0} \Big( v_{K, +}(t^\delta, x^\delta_{K:K+1}, y^\delta) - \varphi(x^\delta_{K:K+1}, y^\delta) \Big) \nonumber \\
		& \leq v_{K, +} (T_K, x^*_{K:K+1}, y^*) - \varphi(x^*_{K:K+1}, y^*) \label{usc_in}\\
		& \leq \sup_{\frac{\varepsilon}{2} \leq | (x_{K:K+1}, y) -  (\bar{x}_{K:K+1}, \bar{y})| \leq \varepsilon} \Big( v_{K, +}(T_K, x_{K:K+1}, y) - \varphi(x_{K:K+1}, y) \Big) < 0. \label{strict}
	\end{align}
	\eqref{usc_in} follows from the USC property. \eqref{strict} holds since the local maximum at $(\bar{x}_{K:K+1}, \bar{y})$ is assumed to be strict. 

	\eqref{strict} implies that there exists $\delta$ small enough such that $h(\delta) < 0$. For this fixed $\delta$, we define $\delta_h := - h(\delta) > 0$. When $T_K - \delta \leq t \leq T_K$ and $\frac{\varepsilon}{2} \leq | (x_{K:K+1}, y) -  (\bar{x}_{K:K+1}, \bar{y})| \leq \varepsilon$, we have
	\begin{equation}\label{region1} 
		v_{K, +}(t, x_{K:K+1}, y) - \varphi(x_{K:K+1}, y) \leq \delta_h < 0.
	\end{equation}

	When $T_K - \delta \leq t \leq T_K - \delta/2$, $|(x_{K:K+1}, y) -  (\bar{x}_{K:K+1}, \bar{y})| \leq \varepsilon/2$ and $p$ is large enough, we have
	\begin{align}
		& v_{K, +}(t, x_{K:K+1}, y) - \varphi^p(t, x_{K:K+1}, y) \nonumber \\
		& \quad = v_{K, +}(t, x_{K:K+1}, y) - \varphi(x_{K:K+1}, y) - p(T_K - t) \nonumber \\
		& \quad \leq \sup_{\substack{T_K - \delta \leq t \leq T_K - \delta/2, \\  | (x_{K:K+1}, y) -  (\bar{x}_{K:K+1}, \bar{y})| \leq \frac{\varepsilon}{2} }} \Big( v_{K, +}(t, x_{K:K+1}, y) - \varphi(x_{K:K+1}, y) \Big) - p(T_K - t) \leq - \delta_h. \label{region2} 
	\end{align}
	Therefore, \eqref{region1} and \eqref{region2} indicate that
	\begin{equation}\label{deltah_ineq}
		v_{K, +}(t, x_{K:K+1}, y) - \varphi^p(t, x_{K:K+1}, y) \leq - \delta_h 
	\end{equation} 
	holds on 
	\begin{align*}
		E(\delta, \varepsilon) :=&  \big\{ (t, x_{K:K+1}, y) \big|\, t \in [T_K - \delta, T_K], \, | (x_{K:K+1}, y) -  (\bar{x}_{K:K+1}, \bar{y})| \leq \varepsilon \big\} \\
		& - \big\{ (t, x_{K:K+1}, y) \big|\, t \in (T_K - \delta/2, T_K], \, | (x_{K:K+1}, y) -  (\bar{x}_{K:K+1}, \bar{y})| < \varepsilon/2 \big\}.
	\end{align*}

	Moreover, by letting $p$ even larger, we have
	\begin{equation*}
		\beta \varphi^p - \partial_t \varphi^p - H(x_{K:K+1}, y, \partial \varphi^p, \partial^2 \varphi^p) > 0 \quad \text{ on } [T_K - \delta, T_K] \times \overline{B(\bar{x}_{K:K+1}, \bar{y},\varepsilon)}.
	\end{equation*}
	Hence, there exist constant $\bar{\alpha}_{K:K+1}$ such that
	\begin{equation}\label{phip}
		\beta \varphi^p - \partial_t \varphi^p - L^{\bar{\alpha}_{K:K+1}} \varphi^p > 0 \quad \text{ on } [T_K - \delta, T_K] \times \overline{B(\bar{x}_{K:K+1}, \bar{y},\varepsilon)}.
	\end{equation}
	With a Dini's argument, \eqref{deltah_ineq} implies that there exists $v^n_K$, which is the $K$-th component of a stochastic supersolution $v^n := (v^n_1, \ldots, v^n_{K+1})$, such that
	\begin{equation}\label{phi_E}
		v^n_K(t, x_{K:K+1}, y) - \varphi^p(t, x_{K:K+1}, y) \leq -\delta_h/2 \quad \text{ on } E(\delta, \varepsilon).
	\end{equation}

	Let $0 < \eta < \delta_h/2$ be small enough and define $\varphi^{p, \eta} := \varphi^p - \eta$. \eqref{phip} also holds for $\varphi^{p, \eta}$. Define
	\begin{equation}
		v^{p, \eta}_{K} (t, x_{K:K+1}, y) := \left\{ 
		\begin{array}{ c l }
			v^n_K (t, x_{K:K+1}, y) \wedge \varphi^{p, \eta}(t, x_{K:K+1}, y) & \text{on } [T_K - \delta, T_K] \times \overline{B(\bar{x}_{K:K+1}, \bar{y},\varepsilon)}, \\
			v^n_K (t, x_{K:K+1}, y), & \text{otherwise}.
		\end{array}
		\right.
	\end{equation}
	We use a similar argument as in the Case (1) to show $(v^n_1, \ldots, v^{p, \eta}_{K}, v^n_{K+1})$ is a stochastic supersolution. Only the supermartingale property is non-trivial. We first verify it when the random initial condition $(\tau, \xi_{K:K+1}, \xi_y)$ satisfies $\tau \in [T_{K-1}, T_K]$.

	Define the event 
	\begin{equation}\label{newA}
		\begin{aligned}
			A := & \{ (\tau, \xi_{K:K+1}, \xi_y) \in (T_K - \delta/2, T_K] \times B(\bar{x}_{K:K+1}, \bar{y},\varepsilon/2) \} \\
			& \cap \{\varphi^{p, \eta}(\tau, \xi_{K:K+1}, \xi_y) < v^n_K(\tau, \xi_{K:K+1}, \xi_y)\}.
		\end{aligned}
	\end{equation}
	Then $A \in \cF_\tau$. Define $U^1 := (\alpha^1_{K:K+1}, L^1_K, M^1_K)$ similarly as in \eqref{U1}, but with the event $A$ in \eqref{newA} instead. We have $U^1 \in \cU (\tau, \xi_{K:K+1}, \xi_y)$ and $$\p((X_{K:K+1}, Y)(t; \tau, \xi_{K:K+1}, \xi_y, U^1) \in \cS_{K}, \; \tau \leq t \leq T ) = 1.$$

	Let 
	\begin{align*}
		\tau^1 := \inf \big\{ t \in [\tau, T_K] \, \big| &  (t,  (X_{K:K+1}, Y)(t; \tau, \xi_{K:K+1}, \xi_y, U^1)) \\
		& \notin (T_K - \delta/2, T_K] \times B(\bar{x}_{K:K+1}, \bar{y},\varepsilon/2) \big\}.
	\end{align*}
	Denote 
	\begin{align*}
		\xi^1 := (\xi^1_{K:K+1}, \xi^1_y) :=  ((X_{K:K+1}, Y)(\tau^1; \tau, \xi_{K:K+1}, \xi_y, U^1)) \in \cF_{\tau^1}
	\end{align*}
	as the exit position. 

%	Define the event
%	\begin{align*}
%		G_a & := \{ \tau^1 = T_K \} \cap \{ | \xi^1 -  (\bar{x}_{K:K+1}, \bar{y}) | < \varepsilon/2 \text{ and } v^n_K(\tau^1, \xi^1) > \varphi^{p, \eta}(\tau^1, \xi^1) \}, \\
%		G_o & := \{ \tau^1 = T_K \} \cap \{ | \xi^1 -  (\bar{x}_{K:K+1}, \bar{y}) | \geq \varepsilon/2 \text{ or } v^n_K(\tau^1, \xi^1) \leq \varphi^{p, \eta}(\tau^1, \xi^1)\}.
%	\end{align*}
%	Then $G_a, G_o \in \cF_{T_K}$. Intuitively, when $G_a$ happens, we should rely on the property of $\varphi^{p, \eta}$ to verify the supermartingale property. 

	Note that 
	\begin{equation}\label{imp_ineq}
		- \lambda_{K} + \partial_{K+1} \varphi^{p, \eta} - \partial_{K} \varphi^{p, \eta} > 0 \quad  \text{ on } \overline{B(\bar{x}_{K:K+1}, \bar{y},\varepsilon)}.
	\end{equation}
	By the mean value theorem, for any $(x_{K:K+1}, y) \in B(\bar{x}_{K:K+1}, \bar{y},\varepsilon)$ and $(x_K + h, x_{K+1} - h, y) \in B(\bar{x}_{K:K+1}, \bar{y},\varepsilon)$ with a small enough $h>0$, we have
	\begin{align*}
		& \varphi^{p, \eta}(t, x_K + h, x_{K+1} - h, y) - \varphi^{p, \eta}(t, x_K, x_{K+1}, y) + \lambda_K h \\
		& \quad = [- \partial_{K+1} \varphi^{p, \eta} + \partial_K \varphi^{p, \eta}](t, \tilde{x}_K, \tilde{x}_{K+1}, y) h + \lambda_K h < 0,
	\end{align*}
	where $(\tilde{x}_K, \tilde{x}_{K+1})$ is on the line segment between $x_{K:K+1}$ and $(x_K + h, x_{K+1} - h)$. This suggests transferring from $x_{K+1}$ to $x_K$.


	Denote $(\cI_K(x_K), \cI_{K+1}(x_{K+1}), y)$ as the intersection of the ray $\{ (x_K + h, x_{K+1} - h, y): h \geq 0 \}$ and $\partial B(\bar{x}_{K:K+1}, \bar{y},\varepsilon/2)$. Then $x_{K+1} - \cI_{K+1}(x_{K+1}) = \cI_K(x_K) - x_K$ and either one can be used when defining $U$ below. Let $U^2 := \{ (\alpha^2_{K:K+1}(t), L^2_K(t), M^2_K(t)) \}_{t \in [T_K, T]}$ be a suitable control for $v^n_{K}$ with the random initial condition $(T_K, \cI_K(\xi^1_K), \cI_{K+1}(\xi^1_{K+1}), \xi^1_y)$. Let $$U^3 := \{ (\alpha^3_{K:K+1}(t), L^3_K(t), M^3_K(t)) \}_{t \in [\tau^1, T]}$$ be a suitable control for $v^n_{K}$ with the random initial condition $(\tau^1, \xi^1)$. Let  $U^4 := \{ \alpha^4_{K+1}(t) \}_{t \in [T_K, T]}$ be a suitable control for $v^n_{K+1}$ with the random initial condition $(T_K, \xi^1_{K+1}, \xi^1_y)$. Finally, define a control $U := (\alpha_{K:K+1}, L_K, M_K)$ by
	\begin{align*}
		& (\alpha_{K:K+1}(t), L_K(t), M_K(t)) \\
		& = \one_{\{ \tau \leq t < \tau^1 \}} U^1(t) \\
		& \quad + \one_{A \cap \{ \tau^1 = T_K\} \cap \{\tau^1 \leq t \leq T\}} (\alpha^2_{K:K+1}(t),  L^2_K(t) - L^2_K(\tau^1-) + \xi^1_{K+1} - \cI_{K+1}(\xi^1_{K+1}) + L^1_K(\tau^1), \\
		& \hspace{4.5cm}  M^2_K(t) - M^2_K(\tau^1 -) + M^1_K(\tau^1)) \\
		& \quad + \one_{\{ \tau^1 < T_K\} \cap \{ \tau^1 \leq t \leq T\}} (\alpha^3_{K:K+1}(t), L^3_K(t) - L^3_K(\tau^1 -) + L^1_K(\tau^1), M^3_K(t) - M^3_K(\tau^1 -) + M^1_K(\tau^1) ) \\
		& \quad + \one_{A^c \cap \{ \tau^1 = T_K\} \cap \{ \tau^1 \leq t \leq T\}} (\alpha^4_{K+1}(t), L^1_K(\tau^1), M^1_K(\tau^1) ).
	\end{align*}

	By Lemma \ref{lem:glue}, the control $U \in \cU(\tau, \xi_{K:K+1}, \xi_y)$. When $A \cap \{ \tau^1 = T_K\}$ happens, there can be ``triple transactions" at time $t = \tau^1 = T_K$, including $(\Delta L^1_K(T_K), \Delta M^1_K(T_K))$, $(\xi^1_{K+1} - \cI_{K+1}(\xi^1_{K+1}), 0)$, and $(\Delta L^2_K(T_K), \Delta M^2_K(T_K))$. In particular, $(\xi^1_{K+1} - \cI_{K+1}(\xi^1_{K+1}), 0)$ brings the state to the boundary $\partial B(\bar{x}_{K:K+1}, \bar{y},\varepsilon/2)$. But it is still possible to transfer immediately again with $(\Delta L^2_K(T_K), \Delta M^2_K(T_K))$. Besides, the investment proportion $\alpha^2_K(t)$ in $U^2$ for the portfolio $K$ is not really needed, since the goal $K$ expires right now.  

	We verify that $U$ is suitable for $v^{p, \eta}_{K}$ with $(\tau, \xi_{K:K+1}, \xi_y)$. Similar to the Case (1), the inequality \eqref{psiAineq1} holds with $\varphi^{p, \eta}$ instead. The proof uses \eqref{phip} with $\varphi^{p, \eta}$. \eqref{psiAineq2} is replaced by
	\begin{align*}
		& \one_{A \cap \{ \rho \geq \tau^1\}} \varphi^{p, \eta} (\tau^1, \xi^1)  \\
		& \geq \one_{A \cap \{ \rho \geq \tau^1\} \cap \{ \tau^1 < T_K\}} v^n_K (\tau^1, \xi^1)  \\
		& \quad + \one_{A \cap \{ \rho \geq \tau^1\} \cap \{ \tau^1 = T_K\}} \Big( \lambda_K (\xi^1_{K+1} - \cI_{K+1}(\xi^1_{K+1})) + \varphi^{p, \eta}(T_K, \cI_K(\xi^1_K), \cI_{K+1}(\xi^1_{K+1}), \xi^1_y) \Big)  \\
		& \geq \one_{A \cap \{ \rho \geq \tau^1\} \cap \{ \tau^1 < T_K\}} v^n_K (\tau^1, \xi^1) \\
		& \quad + \one_{A \cap \{ \rho \geq \tau^1\} \cap \{ \tau^1 = T_K\}} \Big( \lambda_K (\xi^1_{K+1} - \cI_{K+1}(\xi^1_{K+1})) + v^n_K(T_K, \cI_K(\xi^1_K), \cI_{K+1}(\xi^1_{K+1}), \xi^1_y) \Big).
	\end{align*} 
	Here, we use \eqref{phi_E}, \eqref{imp_ineq}, and $(\cI_K(\xi^1_K), \cI_{K+1}(\xi^1_{K+1}), \xi^1_y) \in \partial B(\bar{x}_{K:K+1}, \bar{y},\varepsilon/2)$.

	Similar to \eqref{Acvnineq} and \eqref{ineq:tau1}, the remaining proof of the supermartingale property when $\tau \in [T_{K-1}, T_K]$ follows from the definition of $U$. Other cases with $\tau \in [T_{k-1}, T_k]$, $k \neq K$ are direct to prove. Hence, $(v^n_1, \ldots, v^{p, \eta}_{K}, v^n_{K+1})$ is a stochastic supersolution, which leads to a contradiction.


	{\bf Step 3: Case (3)}. $- \theta_K - \partial_{K+1} \varphi(\bar{x}_{K:K+1}, \bar{y}) + \partial_{K} \varphi (\bar{x}_{K:K+1}, \bar{y}) > 0$. 

	This suggests transferring from $x_{K}$ to $x_{K+1}$. The proof is similar to the Case (2) with the counterpart inequality to \eqref{imp_ineq}. The control when $A \cap \{ \tau^1 = T_K\}$ happens should be modified as follows. Denote $(\cN_K(x_K), \cN_{K+1}(x_{K+1}), y)$ as the intersection of the ray $\{ (x_K - h, x_{K+1} + h, y): h \geq 0 \}$ and $\partial B(\bar{x}_{K:K+1}, \bar{y},\varepsilon/2)$. Let $U^2 := \{ (\alpha^2_{K:K+1}(t), L^2_K(t), M^2_K(t)) \}_{t \in [T_K, T]}$ be a suitable control for $v^n_{K}$ with the random initial condition $(T_K, \cN_K(\xi^1_K), \cN_{K+1}(\xi^1_{K+1}), \xi^1_y)$. The controls $U^3$ and $U^4$ are defined similarly as in Case (2). Finally, define a control $U := (\alpha_{K:K+1}, L_K, M_K)$ by
	\begin{align*}
		& (\alpha_{K:K+1}(t), L_K(t), M_K(t)) \\
		& = \one_{\{ \tau \leq t < \tau^1 \}} U^1(t) \\
		& \quad + \one_{A \cap \{ \tau^1 = T_K\} \cap \{\tau^1 \leq t \leq T\}} (\alpha^2_{K:K+1}(t),  L^2_K(t) - L^2_K(\tau^1-) + L^1_K(\tau^1), \\
		& \hspace{4.5cm}  M^2_K(t) - M^2_K(\tau^1 -) + \xi^1_{K} - \cN_{K}(\xi^1_{K}) + M^1_K(\tau^1)) \\
		& \quad + \one_{\{ \tau^1 < T_K\} \cap \{ \tau^1 \leq t \leq T\}} (\alpha^3_{K:K+1}(t), L^3_K(t) - L^3_K(\tau^1 -) + L^1_K(\tau^1), M^3_K(t) - M^3_K(\tau^1 -) + M^1_K(\tau^1) ) \\
		& \quad + \one_{A^c \cap \{ \tau^1 = T_K\} \cap \{ \tau^1 \leq t \leq T\}} (\alpha^4_{K+1}(t), L^1_K(\tau^1), M^1_K(\tau^1) ).
	\end{align*}


	Then the remaining proof is similar to the Case (2) above. 


	{\bf Step 4}. The viscosity subsolution property in Definition \ref{def:vis_sub} (1), when $t \in [T_{K-1}, T_K)$: The proof is similar to the previous Step 3 and \cite{bayraktar2013stochastic,bayraktar2015stochastic}. We mainly report the construction of the stochastic supersolutions and suitable controls here.

	Let $(\bar{t}, \bar{x}_{K:K+1}, \bar{y}) \in [T_{K-1}, T_K) \times \cS_K$ and $\varphi(t, x_{K:K+1}, y) \in C^{1, 2}([T_{K-1}, T_K) \times \cS_K)$ be a test function such that $v_{K, +} - \varphi$ attains a strict local maximum of zero at $(\bar{t}, \bar{x}_{K:K+1}, \bar{y})$. We want to prove
	\begin{equation}
		\begin{aligned}
			\max \Big\{ & \beta \varphi - \partial_t \varphi - H(\bar{x}_{K:K+1}, \bar{y}, \partial \varphi, \partial^2 \varphi), \\
			& - \lambda_{K} + \partial_{K+1} \varphi - \partial_{K} \varphi, - \theta_K - \partial_{K+1} \varphi + \partial_{K} \varphi \Big\} (\bar{t}, \bar{x}_{K:K+1}, \bar{y}) \leq 0.
		\end{aligned}
	\end{equation}
	Assume on the contrary that the left-hand side is strictly positive.

	{\bf Step 4: Case (1)}. $\beta \varphi(\bar{t}, \bar{x}_{K:K+1}, \bar{y}) - \partial_t \varphi(\bar{t}, \bar{x}_{K:K+1}, \bar{y}) - H(\bar{x}_{K:K+1}, \bar{y}, \partial \varphi, \partial^2 \varphi) > 0$.

	Similar to the Step 3, there exist $\varepsilon, \eta > 0$ and $v^n_K$, the $K$-th element of some $v^n := (v^n_1, \ldots, v^n_K, $ $v^n_{K+1}) \in \cV^+$, such that $\varphi^\eta := \varphi - \eta$ satisfies
	\begin{align*}
		& \beta \varphi^\eta - \partial_t \varphi^\eta - L^{\bar{\alpha}_{K:K+1}} \varphi^\eta > 0 \quad \text{ on } \overline{B(\bar{t}, \bar{x}_{K:K+1}, \bar{y}, \varepsilon)}, \\
		& \varphi^\eta \geq v^n_K \quad \text{ on } \overline{B(\bar{t}, \bar{x}_{K:K+1}, \bar{y}, \varepsilon)} \backslash B(\bar{t}, \bar{x}_{K:K+1}, \bar{y}, \varepsilon/2), \\
		& \varphi^\eta(\bar{t}, \bar{x}_{K:K+1}, \bar{y}) < v_{K, +}(\bar{t}, \bar{x}_{K:K+1}, \bar{y}).
	\end{align*}
	Here, the open ball $B(\bar{t}, \bar{x}_{K:K+1}, \bar{y}, \varepsilon) := (\bar{t}-\varepsilon, \bar{t}+\varepsilon) \times B(\bar{x}_{K:K+1}, \bar{y},\varepsilon)$.

	Define
	\begin{equation}\label{veta}
		v^{\eta}_{K} (t, x_{K:K+1}, y) := \left\{ 
		\begin{array}{ c l }
			v^n_K (t, x_{K:K+1}, y) \wedge \varphi^{\eta}(t, x_{K:K+1}, y), &\; \text{on } \overline{B(\bar{t}, \bar{x}_{K:K+1}, \bar{y}, \varepsilon)}, \\
			v^n_K (t, x_{K:K+1}, y), & \; \text{otherwise}.
		\end{array}
		\right.
	\end{equation}
	Consider the random initial condition $(\tau, \xi_{K:K+1}, \xi_y)$ with $\tau \in [T_{K-1}, T_K]$. Define the event 
	\begin{equation}\label{newA2}
		A := \{ (\tau, \xi_{K:K+1}, \xi_y) \in B(\bar{t}, \bar{x}_{K:K+1}, \bar{y}, \varepsilon/2) \} \cap \{\varphi^{\eta}(\tau, \xi_{K:K+1}, \xi_y) < v^n_K(\tau, \xi_{K:K+1}, \xi_y)\}.
	\end{equation}
	Define $U^1 := (\alpha^1_{K:K+1}, L^1_K, M^1_K)$ similarly as in \eqref{U1} with $A$ in \eqref{newA2} instead. Let 
	\begin{align*}
		\tau^1 := \inf \{ t \in [\tau, T_K) \, | \,  (t,  (X_{K:K+1}, Y)(t; \tau, \xi_{K:K+1}, \xi_y, U^1)) \notin B(\bar{t}, \bar{x}_{K:K+1}, \bar{y}, \varepsilon/2) \}.
	\end{align*}
	Denote $\xi^1 := (\xi^1_{K:K+1}, \xi^1_y)$ as the exit position. Let $U^2 := ( \alpha^2_{K:K+1}, L^2_K, M^2_K)$ be a suitable control for $v^n_{K}$ with the random initial condition $(\tau^1, \xi^1)$. Finally, define a control $U := (\alpha_{K:K+1}, L_K, M_K)$ by
	\begin{align}
		& (\alpha_{K:K+1}(t), L_K(t), M_K(t)) \nonumber \\
		& \quad  = \one_{\{ \tau \leq t < \tau^1 \}} U^1(t) \label{U_t} \\
		& \qquad + \one_{\{ \tau^1 \leq t \leq T\}} (\alpha^2_{K:K+1}(t), L^2_K(t) - L^2_K(\tau^1-) + L^1_K(\tau^1), M^2_K(t) - M^2_K(\tau^1-) + M^1_K(\tau^1)). \nonumber
	\end{align}
	Similar to the Case (1) in the Step 3, we can verify that $U$ is suitable for $v^{\eta}_{K}$ with $(\tau, \xi_{K:K+1}, \xi_y)$. Then the conclusion follows.



	{\bf Step 4: Case (2)}. $ - \lambda_{K} + \partial_{K+1} \varphi (\bar{t}, \bar{x}_{K:K+1}, \bar{y}) - \partial_{K} \varphi (\bar{t}, \bar{x}_{K:K+1}, \bar{y}) > 0$.

	There exist $\varepsilon, \eta > 0$ and $v^n_K$, the $K$-th element of some $v^n := (v^n_1, \ldots, v^n_K, v^n_{K+1}) \in \cV^+$, such that $\varphi^\eta := \varphi - \eta$ satisfies
	\begin{align*}
		& [- \lambda_{K} + \partial_{K+1} \varphi^\eta - \partial_{K} \varphi^\eta](t, x_{K:K+1}, y) > 0 \quad \text{ on } \overline{B(\bar{t}, \bar{x}_{K:K+1}, \bar{y}, \varepsilon)}, \\
		& \varphi^\eta \geq v^n_K \quad \text{ on } \overline{B(\bar{t}, \bar{x}_{K:K+1}, \bar{y}, \varepsilon)} \backslash B(\bar{t}, \bar{x}_{K:K+1}, \bar{y}, \varepsilon/2), \\
		& \varphi^\eta(\bar{t}, \bar{x}_{K:K+1}, \bar{y}) < v_{K, +}(\bar{t}, \bar{x}_{K:K+1}, \bar{y}).
	\end{align*}

	Define $v^{\eta}_{K} (t, x_{K:K+1}, y)$ as in \eqref{veta} and the event $A$ as in \eqref{newA2}. Consider the random initial condition $(\tau, \xi_{K:K+1}, \xi_y)$ with $\tau \in [T_{K-1}, T_K]$. Let $U^0 := (\alpha^0_{K:K+1}, L^0_K, M^0_K)$ be a suitable control for $v^n_{K}$ with the random initial condition $(\tau, \xi_{K:K+1}, \xi_y)$. Recall the function $\cI_{K+1}(x_{K+1})$ introduced in the Case (2) of the Step 3. Define a new control $U^1 := (\alpha^1_{K:K+1}, L^1_K, M^1_K)$ by
	\begin{equation}
		\begin{aligned}
			\alpha^1_{K:K+1}(t)  := & \alpha^0_{K:K+1}(t) \one_{\{ \tau \leq t\}}, \\
			(L^1_K(t), M^1_K(t)) := & \one_{A \cap \{ \tau \leq t\}}(\xi_{K+1} - \cI_{K+1}(\xi_{K+1}), 0) \\
			& + \one_{A^c \cap \{ \tau \leq t\}} (L^0_K(t) - L^0_K(\tau-), M^0_K(t) - M^0_K(\tau-)).
		\end{aligned}
	\end{equation}
	Then we define $U$ as in \eqref{U_t}. The remaining proof follows in the same way.

	{\bf Step 4: Case (3)}. $ - \theta_{K} - \partial_{K+1} \varphi (\bar{t}, \bar{x}_{K:K+1}, \bar{y}) + \partial_{K} \varphi (\bar{t}, \bar{x}_{K:K+1}, \bar{y}) > 0$.

	The proof is symmetric to the Case (2) above. The main difference is that $U_1$ uses
	\begin{equation}
		\begin{aligned}
			(L^1_K(t), M^1_K(t)) := & \one_{A \cap \{ \tau \leq t\}}(0, \xi_{K} - \cN_{K}(\xi_{K})) \\
			& + \one_{A^c \cap \{ \tau \leq t\}} (L^0_K(t) - L^0_K(\tau-), M^0_K(t) - M^0_K(\tau-)),
		\end{aligned}
	\end{equation} 
	where $\cN_K$ is defined in the Case (3) of the Step 3.

	{\bf Step 5}. With some modifications, the proof above also works when more than two goals are active. We omit the detail since it is almost the same.
\end{proof}


\begin{proof}[Proof of Lemma \ref{lem:boundary}.]
	Consider a given point $(x^o_{k:K+1}, y) \in \overline{\cS}^o_{k} \backslash \cS_k$. Let $i$ be the smallest index with $x^o_i > 0$. For a small $\zeta >0$, recall the definition of $Z_{k:K+1}(x^o_{k:K+1}, \zeta)$ in \eqref{z}. Note that $(Z_{k:K+1}(x^o_{k:K+1}, \zeta), y) \in \cS_k$ for small $\zeta > 0$.

	Given $\zeta >0$, we regard $(t, Z_{k:K+1}(x^o_{k:K+1}, \zeta), y) \in [T_{k-1}, T_k] \times \cS_k$ as the random initial condition. For every stochastic supersolution $v_k$, there exists a suitable control $U$ with respect this random initial condition. As the value function $V_k$ takes infimum over all admissible controls, we have
	\begin{align}
		V_k(t, x^o_{k:K+1}, y) \leq &  \sum_{i=k}^{K} \lambda_i \zeta \Delta L_i (x^o_{k:K+1}) +  \sum_{i=k}^{K} \theta_i \zeta \Delta M_i(x^o_{k:K+1}) \label{ineq:46} \\
		& + v_k (t, Z_{k:K+1}(x^o_{k:K+1}, \zeta), y), \nonumber
	\end{align}
	where $\Delta L_i(\cdot)$ and $\Delta M_i(\cdot)$ are defined in \eqref{transfer}. Taking infimum over $v_k$, we can replace $v_k$ with the upper stochastic envelope $v_{k, +}$ in this inequality \eqref{ineq:46}.

	Letting $\zeta \rightarrow 0$, since $(Z_{k:K+1}(x^o_{k:K+1}, \zeta), y) \in \cS_k$, we have
	\begin{align*}
		\limsup_{\zeta \rightarrow 0} v_{k, +}(t, Z_{k:K+1}(x^o_{k:K+1}, \zeta), y) \leq \limsup_{\substack{ x'_{k:K+1} \rightarrow x^o_{k:K+1} \\ x'_j > 0, \, j = k,\ldots,K+1}} v_{k, +}(t, x'_{k:K+1}, y).
	\end{align*}
	The first two terms in \eqref{ineq:46} converge to zero when $\zeta \rightarrow 0$. Then the claim \eqref{ineq:uscbd} follows.
\end{proof}


\subsection{Results of the stochastic subsolution}\label{sec:proof_stosub}


	\begin{proof}[Proof of Lemma \ref{lem:no_mental}]
		By definition of the value function $J$ without mental accounting, we have	
		\begin{align}
			\Gamma_k(t, 0, y) & \leq \sum^{K+1}_{i = k} w_i e^{-\beta (T_i-t)} G_i, \quad \forall\;  t \in [0, T], \; y \in \R^m, \; k = 1, \ldots, K+1, \\
			\Gamma_{K+1}(T, x_{K+1}, y) & \leq (G_{K+1} - x_{K+1})^+, \quad \forall \; (x_{K+1}, y) \in \cS_{K+1}.
		\end{align}

		Next, we prove that $(\Gamma_1, \ldots, \Gamma_k, \ldots, \Gamma_{K+1})$ satisfies the condition (1) in Definition \ref{def:sto_sub}:
		\begin{equation}\label{eq:sub_ex}
			\Gamma_k(\tau, \xi_{k:K+1}, \xi_y) \leq \E \big[ \cM \big([\tau, \rho], \Gamma_{k:K+1}, (X_{k:K+1}, Y)(\cdot; \tau, \xi_{k:K+1}, \xi_y, U) \big) \big|\cF_\tau \big],
		\end{equation}
        where $\tau \in [T_{k-1}, T_k]$. 

        Indeed, mental accounting terms in the objective function are non-negative:
        \begin{equation*}
        	\sum^K_{i=k} \lambda_i \int^{T_i}_{\tau} e^{-\beta t} d L_i(t) \geq 0 \; \text{ and } \; \sum^K_{i=k} \theta_i \int^{T_i}_{\tau} e^{-\beta t} d M_i(t) \geq 0
        \end{equation*}
        Then \eqref{eq:sub_ex} holds once we show that $\Gamma$ satisfies one direction of the DPP:
		\begin{align}
			& \Gamma_k(\tau, \xi_{k:K+1}, \xi_y) \label{ineq:Gam_k}\\
			& \leq \inf_{\substack{ U \in \cU(\tau, \xi_{k:K+1}, \xi_y) } } \E \Big[ e^{-\beta(\rho - \tau)} \Gamma_{k}(\rho, (X_{k:K+1}, Y)(\rho; \tau, \xi_{k:K+1}, \xi_y, U)) \one_{\{\tau \leq \rho < T_k\}} \nonumber \\		
			& \qquad \qquad \qquad \qquad \quad + \sum^{K-1}_{l=k} \Big\{ e^{-\beta(\rho - \tau)} \Gamma_{l+1}(\rho, (X_{l+1:K+1}, Y)(\rho; \tau, \xi_{k:K+1}, \xi_y, U)) \nonumber \\
			&\qquad \qquad \qquad \qquad \qquad \qquad \quad +  \sum^{l}_{i = k} w_i e^{-\beta (T_i - \tau)} (G_i - X_i(T_i; \tau, \xi_{k:K+1}, \xi_y, U))^+ \Big \} \one_{\{T_l \leq \rho < T_{l+1} \}} \nonumber \\
			&  \qquad \qquad \qquad \qquad \quad + \Big\{ e^{-\beta(\rho - \tau)} \Gamma_{K+1}(\rho, (X_{K+1}, Y)(\rho; \tau, \xi_{k:K+1}, \xi_y, U)) \nonumber \\
			&\qquad \qquad \qquad \qquad \qquad \quad +  \sum^{K}_{i = k} w_i e^{-\beta (T_i - \tau)} (G_i - X_i(T_i; \tau, \xi_{k:K+1}, \xi_y, U))^+ \Big \} \one_{\{T_K \leq \rho \leq T\}} \Big | \cF_{\tau} \Big]. \nonumber 
		\end{align}	 
		Since $\Gamma$ is defined by $J$, \eqref{ineq:Gam_k} follows from the fact that $J$ satisfies the DPP and is continuous when $t \in [T_{k-1}, T_k)$, as shown in \citet[Theorem 4.1 and Lemma E.2]{capponi2024}.
%		Since $\Gamma$ is defined by $J$, we only need to prove, for $\tau \in [T_{k-1}, T_k)$,
%		\begin{align}
%			J(\tau, \xi, \xi_y) & \leq \inf_{\substack{ (\alpha, C_{k:K+1} ) \\ \in \cU(\tau, \xi, \xi_y) } } \E \Big[ e^{-\beta(\rho - \tau)} J(\rho, (X, Y)(\rho; \tau, \xi, \xi_y, \alpha, C_{k:K+1})) \one_{\{\tau \leq \rho < T_k\}} \label{ineq:J} \\		
%			&\qquad \qquad \qquad \quad + \sum^{K-1}_{l=k} \Big\{ e^{-\beta(\rho - \tau)} J(\rho, (X, Y)(\rho; \tau, \xi, \xi_y, \alpha, C_{k:K+1})) \nonumber \\
%			&\qquad \qquad \qquad \qquad \qquad \quad +  \sum^{l}_{i = k} w_i e^{-\beta (T_i - \tau)} (G_i - C_i)^+ \Big \} \one_{\{T_l \leq \rho < T_{l+1} \}} \nonumber \\
%			& \qquad \qquad \qquad \quad + \Big\{ e^{-\beta(\rho - \tau)} J(\rho, (X, Y)(\rho; \tau, \xi, \xi_y, \alpha, C_{k:K+1})) \nonumber \\
%			& \qquad \qquad \qquad \qquad \quad +  \sum^{K}_{i = k} w_i e^{-\beta (T_i - \tau)} (G_i - C_i)^+ \Big \} \one_{\{T_K \leq \rho \leq T\}} \nonumber \Big],
%		\end{align}	 
%		where $\xi$ is an $\cF_\tau$-measurable random variable, interpreted as the random initial condition for $X$. Note that the difference between \eqref{ineq:Gam_k} and \eqref{ineq:J} at $\rho = T_l, l = k, \ldots, K$ above comes from the definition that $\Gamma_l(T_l, x_{l:K+1}, y) = J(T_l-, x_l + \ldots + x_{K+1}, y)$.
\end{proof}
Besides, one can also apply stochastic Perron's method to the problem \eqref{obj:no_acc} without mental accounting. To avoid the technical difficulty from the state constraint $X(t) \geq 0$ in \eqref{eq:no_account}, we can modify the wealth dynamic as in \citet[Equation (3.5)]{capponi2024} and allow negative initial wealth:
\begin{equation}\label{eq:extended}
	\begin{aligned}
		d X(u) &=  r X(u) du + (\mu(Y(u)) - r \mathbf{1})^\top \alpha(u) X^+(u) du + X^+(u) \alpha^\top(u) \sigma(Y(u)) dW(u), \\
		X(t) &= x \in \R.
	\end{aligned}
\end{equation}
It extends the spatial domain of the problem \eqref{obj:no_acc} to $\R \times \R^m$, while the value function in the original spatial domain $[0, \infty) \times \R^m$ is unchanged. Since there is no gradient constraint, the proof of viscosity supersolution and subsolution properties is standard and similar to \cite{bayraktar2013stochastic,bayraktar2015stochastic}. Moreover, Lemma \ref{lem:boundary} related to the state constraint  is no longer needed after the extension \eqref{eq:extended}. The proof of comparison principle is similar to \cite{capponi2024} and \citet[Theorem 4.4.5]{pham2009book}. We mention that the truncation $\rho(x)$ in \cite{capponi2024} is not needed, since the sequence $\{x_n\}$ is bounded. The unique viscosity solution in the enlarged domain $[T_{k-1}, T_k) \times \R \times \R^m$, agrees with the value function when restricting to the original domain $[T_{k-1}, T_k) \times [0, \infty) \times \R^m$.

As a side remark, if there are gradient constraints due to mental accounting and the state dynamic is extended to \eqref{eq:extended}, we could not find a strict classical subsolution as in Lemma \ref{lem:strict_l}. Therefore, this paper does not use this extension technique in the mental accounting case. 



\begin{proof}[Proof of Proposition \ref{prop:vissuper}]
	{\bf Step 1}. The boundary/terminal conditions in Definition \ref{def:vis_super} (4): By Lemma \ref{lem:no_mental}, the {\it value} function without mental accounting, i.e. $\lambda_{k} = \theta_k = 0$, $k=1, \ldots, K$, is a stochastic subsolution. Since $v_-$ is the supremum of stochastic subsolutions, $v_-$ satisfies the boundary condition \eqref{vissup_bd0} at $x_{k:K+1} = 0$. By a modification of the step 3 in \citet[Theorem 4.1]{bayraktar2013stochastic}, it follows that $v_{K+1, -}$ in $v_-$ satisfies the terminal condition \eqref{vissup_T} at $T$.

	{\bf Step 2}. The viscosity supersolution property in Definition \ref{def:vis_super} (3), when $t \in [T_k, T)$: Similarly, it follows from the proof of \citet[Theorem 4.1]{bayraktar2013stochastic}.

	{\bf Step 3}. The viscosity supersolution property in Definition \ref{def:vis_super} (2), when $t=T_K$: Let $(\bar{x}_{K:K+1}, \bar{y}) \in \overline{\cS}^o_K = \{ [0, \infty)^2 \backslash \{0\} \} \times \R^m$ and $\varphi(x_{K:K+1}, y) \in C^2(\overline{\cS}^o_K)$ be a test function such that $v_{K, -}(T_K, \cdot, \cdot) - \varphi(\cdot, \cdot)$ attains a strict local minimum of zero at $(\bar{x}_{K:K+1}, \bar{y})$. We want to prove
	\begin{equation}
		\begin{aligned}
			\max \Big\{ & \varphi(\bar{x}_{K:K+1}, \bar{y}) - w_K (G_K - \bar{x}_K)^+ - v_{K+1, -}(T_K, \bar{x}_{K+1}, \bar{y}), \\
			& - \lambda_{K} + \partial_{K+1} \varphi(\bar{x}_{K:K+1}, \bar{y}) - \partial_{K} \varphi(\bar{x}_{K:K+1}, \bar{y}), \\
			&- \theta_K - \partial_{K+1} \varphi(\bar{x}_{K:K+1}, \bar{y}) + \partial_{K} \varphi (\bar{x}_{K:K+1}, \bar{y}) \Big\} \geq 0.
		\end{aligned}
	\end{equation}
	Assume on the contrary that the left-hand side is strictly negative. Since $\varphi$ is $C^2$ and $v_{K+1, -}$ is LSC,
	\begin{equation}
		\begin{aligned}
			\max \Big\{ & \varphi(x_{K:K+1}, y) - w_K (G_K - x_K)^+ - v_{K+1, -}(T_K, x_{K+1}, y), \\
			& - \lambda_{K} + \partial_{K+1} \varphi(x_{K:K+1}, y) - \partial_{K} \varphi(x_{K:K+1}, y), \\
			&- \theta_K - \partial_{K+1} \varphi(x_{K:K+1}, y) + \partial_{K} \varphi (x_{K:K+1}, y) \Big\} < 0
		\end{aligned}
	\end{equation}
	on a small closed set $\overline{B_{\bar{\cS}}(\bar{x}_{K:K+1}, \bar{y}, \varepsilon)}$, which is the closure of  
	\begin{equation*}
		B_{\bar{\cS}}(\bar{x}_{K:K+1}, \bar{y}, \varepsilon) := B(\bar{x}_{K:K+1}, \bar{y}, \varepsilon) \cap \overline{\cS}_K.
	\end{equation*}
	Indeed, thanks to the LSC property of $v_{K+1, -}$ and the continuity of $\varphi$, the following set is open:
	\begin{equation*}
		\big\{ (x_{K:K+1}, y) \in \overline{\cS}_K | 0 < - \varphi(x_{K:K+1}, y) + w_K (G_K - x_K)^+ + v_{K+1, -}(T_K, x_{K+1}, y) \big\}.
	\end{equation*}
	Then, with a small enough $\varepsilon > 0$, we have
	\begin{equation*}
		\varepsilon \leq - \varphi(x_{K:K+1}, y) + w_K (G_K - x_K)^+ + v_{K+1, -}(T_K, x_{K+1}, y)
	\end{equation*}
	on $\overline{B_{\bar{\cS}}(\bar{x}_{K:K+1}, \bar{y}, \varepsilon)}$. Also, we can make $\varepsilon$ small such that $\overline{B_{\bar{\cS}}(\bar{x}_{K:K+1}, \bar{y}, \varepsilon)} \subset \overline{\cS}^o_K$. It is used to verify the boundary condition of $v^{p, \eta}_{K}$ in \eqref{vpeta} when $x_{K:K+1} = 0$.

	Similar to \citet[Theorem 4.1]{bayraktar2013stochastic} and the step 3 in Proposition \ref{prop:vissub}, we introduce a function
	\begin{equation*}
		h(\delta) := \inf_{\substack{ T_K - \delta \leq t \leq T_K, \; (x_{K:K+1}, y) \in \overline{\cS}_K \text{ and } \\ \frac{\varepsilon}{2} \leq | (x_{K:K+1}, y) -  (\bar{x}_{K:K+1}, \bar{y})| \leq \varepsilon}} \Big( v_{K, -}(t, x_{K:K+1}, y) - \varphi(x_{K:K+1}, y) \Big), \quad 0 < \delta < \delta_0,
	\end{equation*}
	with some small $\delta_0 > 0$. Since $v_{K, -} - \varphi$ is LSC as a function of $(t, x_{K:K+1}, y)$, the minimum in $h(\delta)$ is attained. Let a minimizer be $(t^\delta, x^\delta_{K:K+1}, y^\delta)$. By compactness, there exists a subsequence, still denoted as $\delta \searrow 0$, such that 
	\begin{align*}
		& (t^\delta, x^\delta_{K:K+1}, y^\delta) \rightarrow (T_K, x^*_{K:K+1}, y^*) \\ 
		& \text{and} \quad \frac{\varepsilon}{2} \leq | (x^*_{K:K+1}, y^*) -  (\bar{x}_{K:K+1}, \bar{y})| \leq \varepsilon, \; (x^*_{K:K+1}, y^*) \in \overline{\cS}_K.
	\end{align*}
	Thus,
	\begin{align*}
		\liminf_{\delta \searrow 0} h(\delta) & = \liminf_{\delta \searrow 0} \Big( v_{K, -}(t^\delta, x^\delta_{K:K+1}, y^\delta) - \varphi(x^\delta_{K:K+1}, y^\delta) \Big) \\
		& \geq v_{K, -} (T_K, x^*_{K:K+1}, y^*) - \varphi(x^*_{K:K+1}, y^*) \\
		& \geq \inf_{\substack{ (x_{K:K+1}, y) \in \overline{\cS}_K, \\ \frac{\varepsilon}{2} \leq | (x_{K:K+1}, y) -  (\bar{x}_{K:K+1}, \bar{y})| \leq \varepsilon}}  \Big( v_{K, -}(T_K, x_{K:K+1}, y) - \varphi(x_{K:K+1}, y) \Big) > 0. 
	\end{align*}
	It implies that there exists $\delta$ small enough such that $h(\delta) > 0$. For this fixed $\delta$, we define $\delta_h := h(\delta) > 0$. When $T_K - \delta \leq t \leq T_K$, $\frac{\varepsilon}{2} \leq | (x_{K:K+1}, y) -  (\bar{x}_{K:K+1}, \bar{y})| \leq \varepsilon$ and $(x_{K:K+1}, y) \in \overline{\cS}_K$, we have
	\begin{equation} 
		v_{K, -}(t, x_{K:K+1}, y) - \varphi(x_{K:K+1}, y) \geq \delta_h > 0.
	\end{equation}
	Define $\varphi^p(t, x_{K:K+1}, y) := \varphi(x_{K:K+1}, y) - p(T_K - t)$. When $T_K - \delta \leq t \leq T_K - \delta/2$, $|(x_{K:K+1}, y) -  (\bar{x}_{K:K+1}, \bar{y})| \leq \varepsilon/2$, $(x_{K:K+1}, y) \in \overline{\cS}_K$ and $p$ is large enough, we have
	\begin{align*}
		& v_{K, -}(t, x_{K:K+1}, y) - \varphi^p(t, x_{K:K+1}, y) \\
		& \quad = v_{K, -}(t, x_{K:K+1}, y) - \varphi(x_{K:K+1}, y) + p(T_K - t)  \\
		& \quad \geq \inf_{\substack{T_K - \delta \leq t \leq T_K - \delta/2, \\ (x_{K:K+1}, y) \in \overline{\cS}_K, \\  | (x_{K:K+1}, y) -  (\bar{x}_{K:K+1}, \bar{y})| \leq \frac{\varepsilon}{2} }} \Big( v_{K, -}(t, x_{K:K+1}, y) - \varphi(x_{K:K+1}, y) \Big) + p(T_K - t) \geq \delta_h.
	\end{align*}
	Combining these results, we derive that $v_{K, -}(t, x_{K:K+1}, y) - \varphi^p(t, x_{K:K+1}, y) \geq \delta_h$ on 
	\begin{align*}
		E_{\bar{\cS}}(\delta, \varepsilon) :=&  \big\{ (t, x_{K:K+1}, y) \big|\, t \in [T_K - \delta, T_K], \, (x_{K:K+1}, y) \in \overline{B_{\bar{\cS}}(\bar{x}_{K:K+1}, \bar{y}, \varepsilon)} \big\} \\
		& - \big\{ (t, x_{K:K+1}, y) \big|\, t \in (T_K - \delta/2, T_K], \, (x_{K:K+1}, y) \in B_{\bar{\cS}}(\bar{x}_{K:K+1}, \bar{y}, \varepsilon/2) \big\}.
	\end{align*}
	Moreover, by letting $p$ even larger, we have
	\begin{equation*}
		\beta \varphi^p - \partial_t \varphi^p - H(x_{K:K+1}, y, \partial \varphi^p, \partial^2 \varphi^p) < 0 \quad \text{ on } [T_K - \delta, T_K] \times \overline{B_{\bar{\cS}}(\bar{x}_{K:K+1}, \bar{y}, \varepsilon)}.
	\end{equation*}
	With a Dini's argument, there exists $v^{n_1}_K$, which is the $K$-th component of a stochastic subsolution $v^{n_1} := (v^{n_1}_1, \ldots,  v^{n_1}_{K}, v^{n_1}_{K+1})$, such that
	\begin{equation*}
		v^{n_1}_K(t, x_{K:K+1}, y) - \varphi^p(t, x_{K:K+1}, y) \geq \delta_h/2 \quad \text{ on } E_{\bar{\cS}}(\delta, \varepsilon).
	\end{equation*}
	There exists $v^{n_2}_{K+1}$, which is the last component of a stochastic subsolution $v^{n_2} := (v^{n_2}_1, \ldots,$ $ v^{n_2}_{K}, v^{n_2}_{K+1})$, such that
	\begin{equation*}
		\varepsilon/2 \leq - \varphi(x_{K:K+1}, y) + w_K (G_K - x_K)^+ + v^{n_2}_{K+1}(T_K, x_{K+1}, y)
	\end{equation*}
	on $\overline{B_{\bar{\cS}}(\bar{x}_{K:K+1}, \bar{y}, \varepsilon)}$.

	We take $v^n := (v^{n_1}_1 \vee v^{n_2}_1, \ldots,  v^{n_1}_{K} \vee v^{n_2}_{K}, v^{n_1}_{K+1} \vee v^{n_2}_{K+1})$, which is a stochastic subsolution by Lemma \ref{lem:two_sub}. Let $0 < \eta < \min\{ \delta_h/2, \varepsilon/2 \}$ be small enough and define $\varphi^{p, \eta} := \varphi^p + \eta$. In summary, the results above show that $\varphi^{p, \eta}$ and $v^n$ satisfy the following properties:
	\begin{enumerate}[label={(\arabic*)}]	
		\item On $[T_K - \delta, T_K] \times \overline{B_{\bar{\cS}}(\bar{x}_{K:K+1}, \bar{y}, \varepsilon)}$, we have
		\begin{align}
			& \beta \varphi^{p, \eta} - \partial_t \varphi^{p, \eta} - H(x_{K:K+1}, y, \partial \varphi^{p, \eta}, \partial^2 \varphi^{p, \eta}) < 0, \label{subsol} \\
			& - \lambda_{K} + \partial_{K+1} \varphi^{p, \eta} - \partial_{K} \varphi^{p, \eta} < 0, \quad - \theta_K - \partial_{K+1} \varphi^{p, \eta} + \partial_{K} \varphi^{p, \eta} < 0; \nonumber
		\end{align}
		\item On $\overline{B_{\bar{\cS}}(\bar{x}_{K:K+1}, \bar{y}, \varepsilon)}$ with $t = T_K$,   
		\begin{equation*}
			\varphi^{p, \eta}(T_K, x_{K:K+1}, y) \leq w_K (G_K - x_K)^+ + v^{n}_{K+1}(T_K, x_{K+1}, y); 
		\end{equation*}
		\item $v^n_K(t, x_{K:K+1}, y) \geq \varphi^{p, \eta}(t, x_{K:K+1}, y)$ on $E_{\bar{\cS}}(\delta, \varepsilon)$;
		\item $\varphi^{p, \eta}(T_K, \bar{x}_{K:K+1}, \bar{y}) > v_{K, -}(T_K, \bar{x}_{K:K+1}, \bar{y})$.
	\end{enumerate}

	Define
	\begin{equation}\label{vpeta}
		v^{p, \eta}_{K} (t, x_{K:K+1}, y) = \left\{ 
		\begin{array}{ c l }
			v^n_K (t, x_{K:K+1}, y) \vee \varphi^{p, \eta}(t, x_{K:K+1}, y) & \text{on } [T_K - \delta, T_K] \times \overline{B_{\bar{\cS}}(\bar{x}_{K:K+1}, \bar{y}, \varepsilon)}, \\
			v^n_K (t, x_{K:K+1}, y), & \text{otherwise}.
		\end{array}
		\right.
	\end{equation}
	We verify the submartingale property of $(v^n_1, \ldots, v^{p, \eta}_{K}, v^n_{K+1})$ as a stochastic subsolution. Consider a random initial condition $(\tau, \xi_{K:K+1}, \xi_y)$ with $\tau \in [T_{K-1}, T_K]$, $(\xi_{K:K+1}, \xi_y) \in \cF_\tau$ and $\p((\xi_{K:K+1}, \xi_y) \in \overline{\cS}^o_k) = 1$. Let $U:= (\alpha_{K:K+1}, L_K, M_K) \in \cU(\tau, \xi_{K:K+1}, \xi_y)$. Consider a stopping time $\rho \in [\tau, T]$.

	Define the event 
	\begin{align*}
		A := & \{ (\tau, \xi_{K:K+1}, \xi_y) \in (T_K - \delta/2, T_K] \times B_{\bar{\cS}}(\bar{x}_{K:K+1}, \bar{y}, \varepsilon/2) \} \\
		& \cap \{\varphi^{p, \eta}(\tau, \xi_{K:K+1}, \xi_y) > v^n_K(\tau, \xi_{K:K+1}, \xi_y)\}.
	\end{align*}
	Then $A \in \cF_\tau$. Let
	\begin{align*}
		\tau^1 := \inf \Big\{ t \in [\tau, T_K] \, \Big| \, &  (t,  (X_{K:K+1}, Y)(t; \tau, \xi_{K:K+1}, \xi_y, U)) \\
		& \notin (T_K - \delta/2, T_K] \times B_{\bar{\cS}}(\bar{x}_{K:K+1}, \bar{y}, \varepsilon/2) \Big\}.
	\end{align*}
	Denote 
	\begin{align*}
		\xi^1 := (\xi^1_{K:K+1}, \xi^1_y) :=  ((X_{K:K+1}, Y)(\tau^1; \tau, \xi_{K:K+1}, \xi_y, U)) \in \cF_{\tau^1}
	\end{align*}
	as the exit position.

	Under the event $A$ and at the exit time $\tau^1$, there may be a transfer such that the post-jump position $\xi^1$ is not on $\partial B_{\bar{\cS}}(\bar{x}_{K:K+1}, \bar{y}, \varepsilon/2)$. Since \eqref{subsol} only holds locally, we need the truncation method in \cite{bayraktar2015stochastic} to avoid this technical issue. However, our problem is more complicated as the exit may be only triggered by time expiration. If $\tau^1 = T_K$, the exit position $\xi^1$ could either be in $\overline{B_{\bar{\cS}}(\bar{x}_{K:K+1}, \bar{y}, \varepsilon/2)}$ or $\xi^1 \notin \overline{B_{\bar{\cS}}(\bar{x}_{K:K+1}, \bar{y}, \varepsilon/2)}$. Loosely speaking, we should use the intermediate position in \cite{bayraktar2015stochastic}, but also avoid overshooting.

	Let $(\xi^{1-}_{K:K+1}, \xi^{1-}_y) := (X_{K:K+1}, Y)(\tau^1-; \tau, \xi_{K:K+1}, \xi_y, U)$ be the left-limit position before the exit. We have $(\xi^{1-}_{K:K+1}, \xi^{1-}_y) \in \overline{B_{\bar{\cS}}(\bar{x}_{K:K+1}, \bar{y}, \varepsilon/2)}$ when $A$ happens. With a slight abuse of notations, denote $(\cI_K(x_K), \cI_{K+1}(x_{K+1}), y)$ as the intersection of the ray $\{ (x_K + h, x_{K+1} - h, y): h \geq 0 \}$ and $\partial B_{\bar{\cS}}(\bar{x}_{K:K+1}, \bar{y}, \varepsilon/2)$. Let $(\cN_K(x_K), \cN_{K+1}(x_{K+1}), y)$ be the intersection of the ray $\{ (x_K - h, x_{K+1} + h, y): h \geq 0 \}$ and $\partial B_{\bar{\cS}}(\bar{x}_{K:K+1}, \bar{y}, \varepsilon/2)$. We introduce the intermediate position as
	\begin{align*}
		(\tilde{\xi}^1_{K:K+1}, \tilde{\xi}^1_y) := & \one_{A \cap \{ \Delta L_K(\tau^1) > 0\}} \Big(\min\{\cI_K(\xi^{1-}_K), \xi^1_K \}, \max\{\cI_{K+1}(\xi^{1-}_{K+1}), \xi^1_{K+1}\}, \xi^{1-}_y \Big) \\
		& + \one_{A \cap \{ \Delta M_K(\tau^1) > 0\}} \Big(\max\{\cN_K(\xi^{1-}_K), \xi^1_K \}, \min \{\cN_{K+1}(\xi^{1-}_{K+1}), \xi^1_{K+1}\}, \xi^{1-}_y \Big) \\
		& + \one_{A^c} (\xi^1_{K:K+1}, \xi^1_y) \in \cF_{\tau^1}.
	\end{align*}
	Define 
	\begin{align*}
		(\Delta L^1_K(\tau^1), \Delta M^1_K(\tau^1)) := & \one_{A \cap \{ \Delta L_K(\tau^1) > 0\}} \Big( \xi^{1-}_{K+1} - \max\{\cI_{K+1}(\xi^{1-}_{K+1}), \xi^1_{K+1}\}, 0 \Big) \\
		& + \one_{A \cap \{ \Delta M_K(\tau^1) > 0\}} \Big(0, \xi^{1-}_K - \max\{\cN_K(\xi^{1-}_{K}), \xi^1_K \} \Big) \\
		& + \one_{A^c} (\Delta L_K (\tau^1), \Delta M_K (\tau^1)).
	\end{align*}
	To interpret the case under $A \cap \{ \Delta L_K(\tau^1) > 0 \}$, we note that
	\begin{align*}
		\xi^{1-}_{K+1} - \max\{\cI_{K+1}(\xi^{1-}_{K+1}), \xi^1_{K+1}\} = & \min \{ \xi^{1-}_{K+1} - \cI_{K+1}(\xi^{1-}_{K+1}), \xi^{1-}_{K+1} -  \xi^1_{K+1} \} \\
		= &  \min \{ \xi^{1-}_{K+1} - \cI_{K+1}(\xi^{1-}_{K+1}), \Delta L_K(\tau^1) \}.
	\end{align*}
	It means that we avoid overshooting by not transferring higher than $\Delta L_K(\tau^1)$. If the first term is binding, then $\tilde{\xi}^1_{K:K+1} = (\cI_K(\xi^{1-}_K), \cI_{K+1}(\xi^{1-}_{K+1}))$. Otherwise, $\tilde{\xi}^1_{K:K+1} = \xi^1_{K:K+1}$. Another case under $A \cap \{ \Delta M_K(\tau^1) > 0 \}$ can be interpreted similarly. Hence, $(\tilde{\xi}^1_{K:K+1}, \tilde{\xi}^1_y) \in \overline{B_{\bar{\cS}}(\bar{x}_{K:K+1}, \bar{y}, \varepsilon/2)}$.

	Define a control $U^1 := (\alpha^1_{K:K+1}, L^1_K, M^1_K)$ by
	\begin{equation}\label{def:U1_vissup}
		\begin{aligned}
			\alpha^1_{K:K+1}(t)  := & \alpha_{K:K+1}(t) \one_{\{ \tau \leq t\}}, \\
			(L^1_K(t), M^1_K(t)) := & \one_{\{ \tau \leq t < \tau^1\}}(L_K(t), M_K(t)) \\
			& + \one_{\{ t \geq \tau^1 \}} (L_K(\tau^1- ) + \Delta L^1_K(\tau^1), M_K(\tau^1- ) + \Delta M^1_K(\tau^1)).
		\end{aligned}
	\end{equation}
	When $t \geq \tau^1$, $(L^1_K(t), M^1_K(t))$ only transact at $\tau^1$ and are unchanged afterward.

	Under the event $A$, $(X_{K:K+1}, Y)(t; \tau, \xi_{K:K+1}, \xi_y, U^1) \in \overline{B_{\bar{\cS}}(\bar{x}_{K:K+1}, \bar{y}, \varepsilon/2)}$ for all $t \in [\tau, \tau^1]$. By the It\^o's formula for RCLL semimartingales, we have
	\begin{align}
		& e^{-\beta (\rho \wedge \tau^1 - \tau)} \varphi^{p, \eta} (\rho \wedge \tau^1 , (X_{K:K+1}, Y)(\rho \wedge \tau^1; \tau, \xi_{K:K+1}, \xi_y, U^1)) \nonumber \\
		& \qquad - \varphi^{p, \eta} (\tau, (X_{K:K+1}, Y)(\tau; \tau, \xi_{K:K+1}, \xi_y, U^1)) \nonumber \\
		& =  \int^{\rho \wedge \tau^1}_{\tau} e^{-\beta(s - \tau)}\big( - \beta \varphi^{p, \eta} + \partial_t \varphi^{p, \eta} + L^{\alpha^1_{K:K+1}} \varphi^{p, \eta} \big) ds \label{Ito} \\
		& \quad + \int^{\rho \wedge \tau^1}_{\tau} e^{-\beta(s - \tau)} \big( - \partial_{K+1} \varphi^{p, \eta} + \partial_K \varphi^{p, \eta} \big) dL^{1, c}_K(s) \nonumber \\
		& \quad + \int^{\rho \wedge \tau^1}_{\tau} e^{-\beta(s - \tau)} \big( \partial_{K+1} \varphi^{p, \eta} - \partial_K \varphi^{p, \eta} \big) dM^{1, c}_K(s) \nonumber \\
		& \quad + \int^{\rho \wedge \tau^1}_{\tau} e^{-\beta(s - \tau)} X_K(s) \partial_K \varphi^{p, \eta} \alpha^1_K(s)^\top \sigma(Y(s)) dW(s) \nonumber \\
		& \quad + \int^{\rho \wedge \tau^1}_{\tau} e^{-\beta(s - \tau)} X_{K+1}(s) \partial_{K+1} \varphi^{p, \eta} \alpha^1_{K+1}(s)^\top \sigma(Y(s)) dW(s) \nonumber\\
		& \quad  + \int^{\rho \wedge \tau^1}_{\tau} e^{-\beta(s - \tau)} \partial_y \varphi^{p, \eta} \sigma_Y(Y(s)) dW(s) \nonumber\\
		& \quad + \sum_{\tau < s \leq \rho \wedge \tau^1} e^{-\beta(s - \tau)} \big[ \varphi^{p, \eta} (s , (X_{K:K+1}, Y)(s; \tau, \xi_{K:K+1}, \xi_y, U^1)) \nonumber\\
		& \hspace{4cm} - \varphi^{p, \eta} (s-, (X_{K:K+1}, Y)(s-; \tau, \xi_{K:K+1}, \xi_y, U^1)) \big]. \nonumber
	\end{align} 
	$L^{1, c}_K$ and $M^{1, c}_K$ denote the continuous part of $L^1_K$ and $M^1_K$, respectively. \eqref{subsol} can be used to simplify the $ds$, $dL^{1, c}_K$ and $dM^{1, c}_K$ integrals. Since $X_{K:K+1}(\tau; \tau, \xi_{K:K+1}, \xi_y, U^1)$ is the post-jump position at $\tau$, the last term above does not include $s = \tau$. By \eqref{subsol} and the mean value theorem, if $\Delta L^1_K(s) > 0$ when $A$ happens and $s \in [\tau, \tau^1]$, then
	\begin{align*}
		& \varphi^{p, \eta} (s , (X_{K:K+1}, Y)(s; \tau, \xi_{K:K+1}, \xi_y, U^1)) - \varphi^{p, \eta} (s-, (X_{K:K+1}, Y)(s-; \tau, \xi_{K:K+1}, \xi_y, U^1)) \\
		& + \lambda_{K} \Delta L^1_K(s) \geq 0.
	\end{align*}
	If $\Delta M^1_K(s) > 0$ when $A$ happens and $s \in [\tau, \tau^1]$, then
	\begin{align*}
		& \varphi^{p, \eta} (s , (X_{K:K+1}, Y)(s; \tau, \xi_{K:K+1}, \xi_y, U^1)) - \varphi^{p, \eta} (s-, (X_{K:K+1}, Y)(s-; \tau, \xi_{K:K+1}, \xi_y, U^1)) \\
		& + \theta_{K} \Delta M^1_K(s) \geq 0.
	\end{align*}
	Moreover, $\Delta L^1_K(s)$ and $\Delta M^1_K(s)$ are not positive at the same time. Taking the $\cF_\tau$-conditional expectation on \eqref{Ito}, we obtain
	\begin{align}
		& \E \Big[ \one_A \Big\{ e^{-\beta (\rho \wedge \tau^1 - \tau)} \varphi^{p, \eta} (\rho \wedge \tau^1 , (X_{K:K+1}, Y)(\rho \wedge \tau^1; \tau, \xi_{K:K+1}, \xi_y, U^1))  \nonumber \\
		& \qquad \quad + \lambda_K \int^{\rho \wedge \tau^1}_{\tau+} e^{-\beta(s - \tau)} dL^1_K(s) + \theta_K \int^{\rho \wedge \tau^1}_{\tau+} e^{-\beta(s - \tau)} dM^1_K(s) \Big\} \Big| \cF_{\tau} \Big] \nonumber \\
		& \geq \one_A \varphi^{p, \eta} (\tau , (X_{K:K+1}, Y)(\tau; \tau, \xi_{K:K+1}, \xi_y, U^1)).    \label{tau1_vissup}
	\end{align}
	The $dL^1_K$ and $dM^1_K$ integrals do not include jumps at $\tau$. Instead, these jumps at $\tau$ are related to the right-hand side of \eqref{tau1_vissup}:
	\begin{align}
		& \one_A \varphi^{p, \eta} (\tau , (X_{K:K+1}, Y)(\tau; \tau, \xi_{K:K+1}, \xi_y, U^1)) \nonumber \\
		& \geq \one_A \big\{ - \lambda_K \Delta L^1_K(\tau) - \theta_K \Delta M^1_K(\tau) + \varphi^{p, \eta} (\tau, \xi_{K:K+1}, \xi_y) \big\} \nonumber \\
		& = \one_A \big\{ - \lambda_K \Delta L^1_K(\tau) - \theta_K \Delta M^1_K(\tau) + v^{p, \eta} (\tau, \xi_{K:K+1}, \xi_y) \big\}, \label{RHS}
	\end{align}
	where the last equality follows from the definition of $A$.

	Consider the left-hand side of \eqref{tau1_vissup}. If $\rho < \tau^1$, then $(X_{K:K+1}, Y)(\rho; \tau, \xi_{K:K+1}, \xi_y, U^1) \in \overline{B_{\bar{\cS}}(\bar{x}_{K:K+1}, \bar{y}, \varepsilon/2)}$. Moreover, $U=U^1$ when $t < \tau^1$. Thus,
	\begin{align}
		& \one_{A \cap \{ \rho < \tau^1 \}} \varphi^{p, \eta} (\rho , (X_{K:K+1}, Y)(\rho; \tau, \xi_{K:K+1}, \xi_y, U^1)) \nonumber \\
		& \quad \leq \one_{A \cap \{ \rho < \tau^1 \}} v^{p, \eta}_K (\rho , (X_{K:K+1}, Y)(\rho; \tau, \xi_{K:K+1}, \xi_y, U)). \label{lessrho}
	\end{align}


	To investigate the case with $\rho \geq \tau^1$, we consider three events:
		\begin{align*}
			Q_1 & := \{ \tau^1 < T_K\}, \\
			Q_2 & := \{ \tau^1 = T_K\} \cap \{ (\xi^1_{K:K+1}, \xi^1_y) \in B_{\bar{\cS}}(\bar{x}_{K:K+1}, \bar{y}, \varepsilon/2) \}, \\
			Q_3 & := \{ \tau^1 = T_K \} \cap \{ (\xi^1_{K:K+1}, \xi^1_y) \notin B_{\bar{\cS}}(\bar{x}_{K:K+1}, \bar{y}, \varepsilon/2) \}.
		\end{align*}
		Both $Q_1$ and $Q_3$ mean that $(\xi^1_{K:K+1}, \xi^1_y) \notin B_{\bar{\cS}}(\bar{x}_{K:K+1}, \bar{y}, \varepsilon/2)$. The event $Q_2$ indicates that the exit is triggered by the time only. 	Next, we introduce $U^2 := (\alpha^2_{K:K+1}, L^2_K, M^2_K)$ with
		\begin{equation}\label{def:U2_vissup}
			(\alpha^2_{K:K+1}(t), L^2_K(t), M^2_K(t)) = \left\{ 
			\begin{array}{ c l }
				(0, 0, 0), & \; t < \tau^1, \\
				(0, L_K(\tau^1)- L^1_K(\tau^1), M_K(\tau^1)- M^1_K(\tau^1)), &\; t \geq \tau^1.
			\end{array}
			\right.
		\end{equation}
		Under $Q_1$ and $Q_3$, $U^2$ brings $(\tilde{\xi}^1_{K:K+1}, \tilde{\xi}^1_y)$ to $(\xi^1_{K:K+1}, \xi^1_y)$ immediately at $\tau^1$ and stays inactive afterward. For $Q_2$, we have $U^2 = (0, 0, 0)$. 

		Since $(\tau^1, \tilde{\xi}^1_{K:K+1}, \tilde{\xi}^1_y) \in E_{\bar{\cS}}(\delta, \varepsilon)$ under $Q_1$, we have
		\begin{align}
			& \one_{A \cap \{ \rho \geq \tau^1 \} \cap Q_1} \varphi^{p, \eta}(\tau^1, \tilde{\xi}^1_{K:K+1}, \tilde{\xi}^1_y) \nonumber \\
			& \leq \one_{A \cap \{ \rho \geq \tau^1 \} \cap Q_1} v^n_K(\tau^1, \tilde{\xi}^1_{K:K+1}, \tilde{\xi}^1_y) \nonumber \\
			& \leq \one_{A \cap \{ \rho \geq \tau^1 \} \cap Q_1} \E \Big[ \lambda_K \Delta L^2_K(\tau^1) + \theta_K \Delta M^2_K (\tau^1) + v^n_K (\tau^1, (X_{K:K+1}, Y)(\tau^1; \tau^1, \tilde{\xi}^1_{K:K+1}, \tilde{\xi}^1_y, U^2)) \Big| \cF_{\tau^1} \Big] \nonumber \\
			& = \one_{A \cap \{ \rho \geq \tau^1 \} \cap Q_1} \big[ \lambda_K \Delta L^2_K(\tau^1) + \theta_K \Delta M^2_K (\tau^1) + v^n_K (\tau^1, \xi^1_{K:K+1}, \xi^1_y) \big].   \label{Q1}
		\end{align}
		The first inequality uses the property (3) above. The second inequality follows from the submartingale property of $v^n_K$ with the random initial condition $(\tau^1, \tilde{\xi}^1_{K:K+1}, \tilde{\xi}^1_y)$ and the control $U^2$. 

		With the property (2) and $(\tilde{\xi}^1_{K:K+1}, \tilde{\xi}^1_y) = (\xi^1_{K:K+1}, \xi^1_y)$ on $Q_2$ given $A$, we obtain
		\begin{align}
			& \one_{A \cap \{ \rho \geq \tau^1 \} \cap Q_2} \varphi^{p, \eta}(\tau^1, \tilde{\xi}^1_{K:K+1}, \tilde{\xi}^1_y) \nonumber \\
			& \leq \one_{A \cap \{ \rho \geq \tau^1 \} \cap Q_2} \big[ w_K(G_K - \tilde{\xi}^1_K)^+ + v^n_{K+1}(T_K, \tilde{\xi}^1_{K+1}, \tilde{\xi}^1_y) \big] \nonumber \\
			& = \one_{A \cap \{ \rho \geq \tau^1 \} \cap Q_2} \big[ w_K(G_K - \xi^1_K)^+ + v^n_{K+1}(T_K, \xi^1_{K+1}, \xi^1_y) \big]. \label{Q2}
		\end{align}


		Similarly,
		\begin{align}
			& \one_{A \cap \{ \rho \geq \tau^1 \} \cap Q_3} \varphi^{p, \eta}(\tau^1, \tilde{\xi}^1_{K:K+1}, \tilde{\xi}^1_y) \nonumber \\
			& \leq \one_{A \cap \{ \rho \geq \tau^1 \} \cap Q_3} v^n_K(\tau^1, \tilde{\xi}^1_{K:K+1}, \tilde{\xi}^1_y) \nonumber \\
			& \leq \one_{A \cap \{ \rho \geq \tau^1 \} \cap Q_3} \big[ \lambda_K \Delta L^2_K(\tau^1) + \theta_K \Delta M^2_K (\tau^1) + w_K(G_K - \xi^1_K)^+ + v^n_{K+1}(T_K, \xi^1_{K+1}, \xi^1_y) \big]. \label{Q3}	
		\end{align}
		The first inequality uses the property (3) and the fact that $(\tau^1, \tilde{\xi}^1_{K:K+1}, \tilde{\xi}^1_y) \in E_{\bar{\cS}}(\delta, \varepsilon)$ under $Q_3$. The second inequality applies the submartingale property of $v^n_K$ from $\tau_1$ to $\tau_1$ under the control $U^2$. 		

		Putting \eqref{tau1_vissup}, \eqref{RHS}, \eqref{lessrho}, \eqref{Q1}, \eqref{Q2}, and \eqref{Q3} together, we obtain
		\begin{align}
			\E \Big[ &  \one_{A \cap \{ \rho < \tau^1 \}} e^{-\beta (\rho - \tau)} v^{p, \eta}_K (\rho , (X_{K:K+1}, Y)(\rho; \tau, \xi_{K:K+1}, \xi_y, U)) \nonumber \\
			& + \one_{A \cap \{ \rho \geq \tau^1 \} \cap \{ \tau^1 < T_K \}} e^{-\beta (\tau^1 - \tau)} v^n_K (\tau^1, \xi^1_{K:K+1}, \xi^1_y) \nonumber \\
			& + \one_{A \cap \{ \rho \geq \tau^1 \} \cap \{ \tau^1 = T_K \}} e^{-\beta (T_K - \tau)} \big( w_K(G_K - \xi^1_K)^+ + v^n_{K+1}(T_K, \xi^1_{K+1}, \xi^1_y) \big)  \nonumber \\
			& + \one_A \Big(\lambda_K \int^{\rho \wedge \tau^1}_{\tau} e^{-\beta(s - \tau)} dL_K(s) + \theta_K \int^{\rho \wedge \tau^1}_{\tau} e^{-\beta(s - \tau)} dM_K(s) \Big) \Big| \cF_{\tau} \Big] \nonumber \\
			\geq & \one_A v^{p, \eta}_K (\tau, \xi_{K:K+1}, \xi_y). \label{Aineq}
		\end{align}
		Here, we use the fact that the sum of $(L^1_K, M^1_K)$ and $(L^2_K, M^2_K)$ equals to $(L_K, M_K)$ from $\tau$ to $\rho \wedge \tau^1$.

		Under $A^c$, the submartingale property of $v^n_K$ with the random initial condition $(\tau, \xi_{K:K+1}, \xi_y)$ and the control $U$ leads to
		\begin{align}
			\E \Big[ &  \one_{A^c \cap \{ \rho < \tau^1 \}} e^{-\beta (\rho - \tau)} v^{n}_K (\rho , (X_{K:K+1}, Y)(\rho; \tau, \xi_{K:K+1}, \xi_y, U)) \nonumber \\
			& + \one_{A^c \cap \{ \rho \geq \tau^1 \} \cap \{ \tau^1 < T_K \}} e^{-\beta (\tau^1 - \tau)} v^n_K (\tau^1, \xi^1_{K:K+1}, \xi^1_y) \nonumber \\
			& + \one_{A^c \cap \{ \rho \geq \tau^1 \} \cap \{ \tau^1 = T_K \}} e^{-\beta (T_K - \tau)} \big( w_K(G_K - \xi^1_K)^+ + v^n_{K+1}(T_K, \xi^1_{K+1}, \xi^1_y) \big)  \nonumber \\
			& + \one_{A^c} \Big(\lambda_K \int^{\rho \wedge \tau^1}_{\tau} e^{-\beta(s - \tau)} dL_K(s) + \theta_K \int^{\rho \wedge \tau^1}_{\tau} e^{-\beta(s - \tau)} dM_K(s) \Big) \Big| \cF_{\tau} \Big] \nonumber \\
			\geq & \one_{A^c} v^n_K (\tau, \xi_{K:K+1}, \xi_y) = \one_{A^c} v^{p, \eta}_K (\tau, \xi_{K:K+1}, \xi_y), \label{Acineq}
		\end{align}
		where the last equality follows from the definition of the event $A$ and the property (3). Noting that $v^{p, \eta}_K \geq v^n_K$ everywhere, \eqref{Aineq} and \eqref{Acineq} lead to
		\begin{align}
			\E \Big[ &  \one_{\{ \rho < \tau^1 \}} e^{-\beta (\rho - \tau)} v^{p, \eta}_K (\rho , (X_{K:K+1}, Y)(\rho; \tau, \xi_{K:K+1}, \xi_y, U)) \nonumber \\
			& + \one_{\{ \rho \geq \tau^1 \} \cap \{ \tau^1 < T_K \}} e^{-\beta (\tau^1 - \tau)} v^n_K (\tau^1, \xi^1_{K:K+1}, \xi^1_y) \nonumber \\
			& + \one_{\{ \rho \geq \tau^1 \} \cap \{ \tau^1 = T_K \}} e^{-\beta (T_K - \tau)} \big( w_K(G_K - \xi^1_K)^+ + v^n_{K+1}(T_K, \xi^1_{K+1}, \xi^1_y) \big)  \nonumber \\
			& + \lambda_K \int^{\rho \wedge \tau^1}_{\tau} e^{-\beta(s - \tau)} dL_K(s) + \theta_K \int^{\rho \wedge \tau^1}_{\tau} e^{-\beta(s - \tau)} dM_K(s) \Big| \cF_{\tau} \Big] \nonumber \\
			\geq & v^{p, \eta}_K (\tau, \xi_{K:K+1}, \xi_y). \label{AAc}
		\end{align}

		Similar to \citet[p.109]{bayraktar2015stochastic}, we introduce another control $U^3:=(\alpha^3_{K:K+1}, L^3_K,$ $ M^3_K)$ to avoid doing the same transaction of $U$ twice at $\tau^1$:
		\begin{equation}
			\begin{aligned}
				\alpha^3_{K:K+1}(t)  & := \alpha_{K:K+1}(t), \\
				(L^3_K(t), M^3_K(t)) & := (L_K(t) - \one_{\{\tau^1 \leq t \}} \Delta L_K(\tau^1), M_K(t) - \one_{\{\tau^1 \leq t \}} \Delta M_K(\tau^1)). 
			\end{aligned}
		\end{equation}
		The control $U^3$ makes
		\begin{align}
			(X_{K:K+1}, Y)(t; \tau^1, \xi^1_{K:K+1}, \xi^1_y, U^3) = (X_{K:K+1}, Y)(t; \tau, \xi_{K:K+1}, \xi_y, U), \quad t \geq \tau^1. \label{U3_U}
		\end{align}

		When $\tau^1 < T_K$, we have
		\begin{align}
			& \one_{\{ \rho \geq \tau^1 \} \cap \{\tau^1 < T_K\}} v^n_K (\tau^1, \xi^1_{K:K+1}, \xi^1_y) \nonumber \\
			& \leq \E \Big[\one_{\{ \rho \geq \tau^1 \} \cap \{\tau^1 < T_K\}} \cM \big([\tau^1, \rho], (v^n_K, v^n_{K+1}), (X_{K:K+1}, Y)(\cdot; \tau^1, \xi^1_{K:K+1}, \xi^1_y, U^3) \big) \Big|\cF_{\tau^1} \Big] \nonumber \\
			&  \leq \E \Big[\one_{\{ \rho \geq \tau^1 \} \cap \{\tau^1 < T_K\}} \cM \big([\tau^1, \rho], (v^{p, \eta}_K, v^n_{K+1}), (X_{K:K+1}, Y)(\cdot; \tau^1, \xi^1_{K:K+1}, \xi^1_y, U^3) \big) \Big|\cF_{\tau^1} \Big] \nonumber \\
			& = \E \Big[\one_{\{ \rho \geq \tau^1 \} \cap \{\tau^1 < T_K\}} \cM \big([\tau^1, \rho], (v^{p, \eta}_K, v^n_{K+1}), (X_{K:K+1}, Y)(\cdot; \tau, \xi_{K:K+1}, \xi_y, U) \big) \Big|\cF_{\tau^1} \Big]. \label{Q1M}
		\end{align}
		The first inequality comes from the submartingale property of $v^n_K$ with the admissible control $U^3$. The second inequality uses the fact that $v^{p, \eta}_K \geq v^n_K$. The last equality is due to \eqref{U3_U}.

		When $\tau^1 = T_K$, we have
		\begin{align*}
			& \one_{\{ \rho \geq \tau^1 \} \cap \{\tau^1 = T_K\}} \big( w_K(G_K - \xi^1_K)^+ + v^n_{K+1}(T_K, \xi^1_{K+1}, \xi^1_y) \big) \\
			& \leq \E \Big[ \one_{\{ \rho \geq \tau^1 \} \cap \{\tau^1 = T_K\}} \big\{ w_K(G_K - \xi^1_K)^+ \\
			& \hspace{3.8cm} + \cM \big([\tau^1, \rho], v^n_{K+1}, (X_{K+1}, Y)(\cdot; \tau^1, \xi^1_{K+1}, \xi^1_y, U^3) \big) \big\}  \Big| \cF_{\tau^1} \Big] \\
			& = \E \Big[ \one_{\{ \rho \geq \tau^1 \} \cap \{\tau^1 = T_K\}} \big\{ w_K(G_K - \xi^1_K)^+ \\
			& \hspace{3.8cm} + \cM \big([\tau^1, \rho], v^n_{K+1}, (X_{K+1}, Y)(\cdot; \tau, \xi_{K:K+1}, \xi_y, U) \big) \big\}  \Big| \cF_{\tau^1} \Big].
		\end{align*}
	The last equality comes from \eqref{U3_U}. Note that $X_{K+1}$ may also depend on $X_K$ and thus $\xi_K$, due to potential transactions between goals.

	Summing them up with \eqref{AAc}, we get the desired result.


	{\bf Step 4}. The viscosity supersolution property in Definition \ref{def:vis_super} (1), when $t \in [T_{K-1}, T_K)$: The main idea is similar to the Step 3 above. We give the detail about stochastic subsolutions and the decomposition of controls.

	Let $(\bar{t}, \bar{x}_{K:K+1}, \bar{y}) \in [T_{K-1}, T_K) \times \overline{\cS}^o_K$ and $\varphi(t, x_{K:K+1}, y) \in C^{1, 2}([T_{K-1}, T_K) \times \overline{\cS}^o_K)$ be a test function such that $v_{K, -} - \varphi$ attains a strict local minimum of zero at $(\bar{t}, \bar{x}_{K:K+1}, \bar{y})$. We want to prove
	\begin{equation}
		\begin{aligned}
			\max \Big\{ & \beta \varphi - \partial_t \varphi - H(\bar{x}_{K:K+1}, \bar{y}, \partial \varphi, \partial^2 \varphi), \\
			& - \lambda_{K} + \partial_{K+1} \varphi - \partial_{K} \varphi, - \theta_K - \partial_{K+1} \varphi + \partial_{K} \varphi \Big\} (\bar{t}, \bar{x}_{K:K+1}, \bar{y}) \geq 0.
		\end{aligned}
	\end{equation}
	Assume on the contrary that the left-hand side is strictly negative. By the continuity of SDE parameters and Berge's maximum theorem, the Hamiltonian $$H(x_{K:K+1}, y, \partial \varphi(t, x_{K:K+1}, y), \partial^2 \varphi(t, x_{K:K+1}, y))$$ is continuous in $(t, x_{K:K+1}, y)$. 

	Denote 
	\begin{equation*}
		B_{\bar{\cS}} (\bar{t}, \bar{x}_{K:K+1}, \bar{y}, \varepsilon) := (\bar{t}-\varepsilon, \bar{t}+\varepsilon) \times B_{\bar{\cS}}(\bar{x}_{K:K+1}, \bar{y}, \varepsilon).
	\end{equation*} 
	Similar to the Step 3, there exist $\varepsilon, \eta > 0$ and $v^n_K$, the $K$-th element of some $v^n := (v^n_1, \ldots, v^n_K, v^n_{K+1}) \in \cV^-$, such that $\varphi^\eta := \varphi + \eta$ satisfies

	\begin{enumerate}[label={(\arabic*)}]	
		\item on $\overline{B_{\bar{\cS}} (\bar{t}, \bar{x}_{K:K+1}, \bar{y}, \varepsilon)}$,
		\begin{equation}
			\begin{aligned}
				\max \Big\{ & \beta \varphi^\eta - \partial_t \varphi^\eta - H(x_{K:K+1}, y, \partial \varphi^\eta, \partial^2 \varphi^\eta), \\
				& - \lambda_{K} + \partial_{K+1} \varphi^\eta - \partial_{K} \varphi^\eta, - \theta_K - \partial_{K+1} \varphi^\eta + \partial_{K} \varphi^\eta \Big\} < 0;
			\end{aligned}
		\end{equation}
		\item $\varphi^\eta \leq v^n_K \quad \text{ on } \overline{B_{\bar{\cS}} (\bar{t}, \bar{x}_{K:K+1}, \bar{y}, \varepsilon)} \backslash B_{\bar{\cS}} (\bar{t}, \bar{x}_{K:K+1}, \bar{y}, \varepsilon/2)$;
		\item $\varphi^\eta(\bar{t}, \bar{x}_{K:K+1}, \bar{y}) > v_{K, -}(\bar{t}, \bar{x}_{K:K+1}, \bar{y})$.
	\end{enumerate}
	Also, we can make $\varepsilon$ small such that $\overline{B_{\bar{\cS}} (\bar{t}, \bar{x}_{K:K+1}, \bar{y}, \varepsilon)} \subset [T_{K-1}, T_K) \times \overline{\cS}^o_K$.

	Define
	\begin{equation}
		v^{\eta}_{K} (t, x_{K:K+1}, y) := \left\{ 
		\begin{array}{ c l }
			v^n_K (t, x_{K:K+1}, y) \vee \varphi^{\eta}(t, x_{K:K+1}, y) &\; \text{on } \overline{B_{\bar{\cS}} (\bar{t}, \bar{x}_{K:K+1}, \bar{y}, \varepsilon)}, \\
			v^n_K (t, x_{K:K+1}, y), & \; \text{otherwise}.
		\end{array}
		\right.
	\end{equation}
	Consider the random initial condition $(\tau, \xi_{K:K+1}, \xi_y)$ with $\tau \in [T_{K-1}, T_K]$. Define the event 
	\begin{equation*}
		A := \{ (\tau, \xi_{K:K+1}, \xi_y) \in B_{\bar{\cS}} (\bar{t}, \bar{x}_{K:K+1}, \bar{y}, \varepsilon/2) \} \cap \{\varphi^{\eta}(\tau, \xi_{K:K+1}, \xi_y) > v^n_K(\tau, \xi_{K:K+1}, \xi_y)\}.
	\end{equation*}
	Let 
	\begin{align*}
		\tau^1 := \inf \{ t \in [\tau, T_K) \, | \,  (t,  (X_{K:K+1}, Y)(t; \tau, \xi_{K:K+1}, \xi_y, U^1)) \notin B_{\bar{\cS}} (\bar{t}, \bar{x}_{K:K+1}, \bar{y}, \varepsilon/2) \}.
	\end{align*}
	Denote $\xi^1 := (\xi^1_{K:K+1}, \xi^1_y)$ as the exit position. $U^1$ and $U^2$ are defined as in \eqref{def:U1_vissup} and \eqref{def:U2_vissup}, respectively. There is no need to introduce events $Q_i, i=1,2,3$. The remaining proof is similar to but simpler than the Step 3.

	{\bf Step 5}. When more than two goals are active, the claim follows from a similar argument with some direct modifications. We omit the detail here.
\end{proof}


\subsection{Results of the comparison principle}\label{sec:proof_comp}

	\begin{proof}[Proof of Lemma \ref{lem:strict_l}]
		The derivatives of $l(\cdot)$ are
		\begin{align*}
			& \partial_t l = - \gamma l, \quad \partial_i l = - c_1 e^{\gamma(T_k - t)} \Big(1 + \sum^{K+1}_{i=k} a_i x_i \Big)^{q-1} a_i q, \quad \partial_y l = - 2 c_2 e^{\gamma (T_k - t)} y, \\
			& \partial^2_{ij} l = - c_1 e^{\gamma(T_k - t)} \Big(1 + \sum^{K+1}_{i=k} a_i x_i \Big)^{q-2} a_i a_j q(q-1), \quad \partial^2_{iy} l = 0, \quad \partial^2_{yy} l = - 2 c_2 e^{\gamma(T_k - t)} I_m. 
		\end{align*}
		% A key observation is, the first derivative $\partial_i l$ has a common term $ c_1 e^{\gamma(T_k - t)} \left(1 + \sum^{K+1}_{i=k} a_i x_i \right)^{q-1} q$ and the second derivative $\partial^2_{ij} l $ has a common term $c_1 e^{\gamma(T_k - t)} \Big(1 + \sum^{K+1}_{i=k} a_i x_i \Big)^{q-2} q(q-1)$. 

		First, we consider the infimum in the Hamiltonian. Since $\mu(y)$ and $\alpha_i$ are bounded, there exists a generic constant $C_\mu > 0$, such that
		\begin{align*}
			 &  \sum^{K+1}_{i=k}  (\mu(y) - r \one )^\top \alpha_i a_i x_i \leq  C_\mu \sum^{K+1}_{i=k} a_i x_i.
		\end{align*} 
		Then
		\begin{align*}
			&  \sum^{K+1}_{i=k}  (\mu(y) - r \one )^\top \alpha_i x_i \partial_i l \geq  - c_1 e^{\gamma(T_k - t)} \Big(1 + \sum^{K+1}_{i=k} a_i x_i \Big)^{q} C_\mu q.
		\end{align*} 
		 For the quadratic term, we introduce the following notations:
		 \begin{align*}
		 	A & := (\alpha_k, \ldots, \alpha_{K+1}) \in \R^{n \times (K-k+2)}, \\
		 	B & := (\mu(y) - r \one, \ldots, \mu(y) - r \one) \in \R^{n \times (K-k+2)}, \\
		 	X & := \text{diag}(x_{k:K+1}) \in \R^{(K-k+2) \times (K-k+2)}, \\
		 	\text{diag}(\partial_x l) & := \text{diag}((\partial_k l, \ldots, \partial_{K+1}l)) \in \R^{(K-k+2) \times (K-k+2)}.
		 \end{align*}
		 Since $\partial^2_{iy} l = 0$, we have 
		 \begin{align*}
		 	\tr[\Sigma(\alpha_{k:K+1}, x_{k:K+1}, y) \partial^2 l] = -2 c_2 e^{\gamma(T_k - t)} \tr[ \sigma_Y(y) \sigma_Y(y)^\top] + \tr[\Sigma_{xx} \partial^2_{xx} l],
		 \end{align*}
		 where $\partial^2_{xx} l$ is the Hessian matrix with the second derivative of $l$ on $x_{k:K+1}$ and 
		 \begin{align*}
		 	\Sigma_{xx} := (\alpha x)^\top_{k:K+1} \sigma(y) \sigma(y)^\top (\alpha x)_{k:K+1} = X A^\top \sigma(y) \sigma(y)^\top A X. 
		 \end{align*}
		 Since $\sigma_Y(y)$ is Lipschitz, there exists $C_{\sigma_Y} > 0$ such that
		 \begin{equation*}
		 	\tr[ \sigma_Y(y) \sigma_Y(y)^\top] \leq C_{\sigma_Y} (1 + |y|^2).
		 \end{equation*}
		 Entries of $X\partial^2_{xx}l X$ are given by
		 \begin{align*}
		 	 - c_1 e^{\gamma(T_k - t)} \Big(1 + \sum^{K+1}_{i=k} a_i x_i \Big)^{q-2} a_i a_j q(q-1) x_i x_j, \quad i, j \in \{k, \ldots, K+1\}.
		 \end{align*}
		  As $\alpha_i$ and $\sigma(y)$ are bounded, entries of $A^\top \sigma(y) \sigma(y)^\top A$ are bounded. There exists a constant $C_{\sigma} > 0$ such that
			\begin{align}
				\tr[\Sigma_{xx} \partial^2_{xx}l] \geq - C_\sigma q |q - 1| c_1 e^{\gamma(T_k - t)} \Big(1 + \sum^{K+1}_{i=k} a_i x_i \Big)^{q}.
			\end{align}
		 In summary, there exists a generic constant $C_{\sigma, \sigma_Y, \mu, q}$ depending on $q$, $\mu(y)$, $\sigma(y)$, and $\sigma_Y(y)$, such that
		\begin{align*}
			& \inf_{\alpha_{k:K+1} \in \cA^{K-k+2}}  \Big\{  \sum^{K+1}_{i=k}  (\mu(y) - r \one )^\top \alpha_i x_i \partial_i l + \frac{1}{2} \tr\left[\Sigma(\alpha_{k:K+1}, x_{k:K+1}, y) \partial^2 l  \right] \Big\} \\
			& \quad \geq - C_{\sigma, \sigma_Y, \mu, q} c_2  e^{\gamma(T_k - t)} (1 + |y|^2) - C_{\sigma, \sigma_Y, \mu, q} c_1 e^{\gamma(T_k - t)} \Big(1 + \sum^{K+1}_{i=k} a_i x_i \Big)^q,
		\end{align*} 
		Therefore, we obtain
		\begin{align*}
			& \beta l - \partial_t l - H(x_{k:K+1}, y, \partial l, \partial^2 l) \\
			& \leq (\beta + \gamma) l + r q c_1 e^{\gamma(T_k - t)} \Big(1 + \sum^{K+1}_{i=k} a_i x_i \Big)^q + C_{\mu_Y} c_2 e^{\gamma(T_k - t)} (1 + |y|^2) \\
			& \quad  + C_{\sigma, \sigma_Y, \mu, q} c_2  e^{\gamma(T_k - t)} (1 + |y|^2) + C_{\sigma, \sigma_Y, \mu, q} c_1 e^{\gamma(T_k - t)} \Big(1 + \sum^{K+1}_{i=k} a_i x_i \Big)^q \\
			& \leq \left[\beta + \gamma - rq - C_{\mu_Y} - C_{\sigma, \sigma_Y, \mu, q} \right]l,
		\end{align*}
		where $C_{\mu_Y}$ is a generic constant for the linear growth rate of $\mu_Y(y)$.

		We can choose $\gamma$ large enough, such that the right-hand side is strictly negative. Importantly, $\gamma$ only needs to be bigger than a constant independent of $c_1$ and $c_2$.

		For the gradient constraints in \eqref{F}, we have
		\begin{align*}
			\partial_{K+1} l - \partial_i l = (a_i - a_{K+1}) c_1 q e^{\gamma(T_k - t)} \Big(1 + \sum^{K+1}_{i=k} a_i x_i \Big)^{q-1}.
		\end{align*}
		Since $(1 + \sum^{K+1}_{i=k} a_i x_i )^{q-1} \leq 1$, we can set 
		$$ - \theta_i < (a_i - a_{K+1}) < \lambda_i, $$
		and choose $c_1 > 0$ small enough, such that $0 < c_1 q e^{\gamma(T_k - t)} < 1$. Then
		\begin{equation}\label{eq:grad}
			- \lambda_i + \partial_{K+1} l - \partial_i l < 0, \quad - \theta_i - \partial_{K+1} l + \partial_i l < 0.
		\end{equation}
	\end{proof}


\begin{proof}[Proof of Lemma \ref{lem:conti}]

	The claim \eqref{conti} is trivial for $(x_{k:K+1}, y) \in \cS_k$ since $g(x_{k:K+1})=0$. 

	Consider fixed $t \in [T_{k-1}, T_k]$ and $(x^o_{k:K+1}, y) \in \overline{\cS}^o_{k} \backslash \cS_k$. We define the corresponding transfer plan $(\zeta \Delta L_{k:K}(x^o_{k:K+1}), \zeta \Delta M_{k:K}(x^o_{k:K+1}))$ in \eqref{transfer} and the wealth state $Z_{k:K+1}(x^o_{k:K+1}, \zeta)$ in \eqref{z} after the transaction. First, it follows from the assumption that
	\begin{equation}
		u(t, x^o_{k:K+1}, y) = \limsup_{\substack{ x'_{k:K+1} \rightarrow x^o_{k:K+1} \\ x'_j > 0, \, j = k,\ldots,K+1}} u(t, x'_{k:K+1}, y).
	\end{equation}
	To provide an upper bound of the right-hand side, we note that the viscosity subsolution property \eqref{u_sub} of $u$ holds since $(t, x'_{k:K+1}, y) \in [T_{k-1}, T_k] \times \cS_k$. Moreover, elements of $x'_{k:K+1} - \zeta g(x^o_{k:K+1})$ are positive for any sufficiently small $\zeta > 0$. We obtain that
	\begin{align*}
		u(t, x'_{k:K+1}, y) \leq & u(t, x'_{k:K+1} - \zeta g(x^o_{k:K+1}), y) \\
		& + \sum^K_{j=k} \lambda_j \zeta \Delta L_j(x^o_{k:K+1}) + \sum^K_{j=k} \theta_j \zeta \Delta M_j(x^o_{k:K+1}),
	\end{align*}
	when $\zeta \in [0, \varepsilon)$ for some sufficiently small $\varepsilon>0$. Hence,
	\begin{align*}
		& u(t, x^o_{k:K+1}, y) \\
		&= \limsup_{\substack{ x'_{k:K+1} \rightarrow x^o_{k:K+1} \\ x'_j > 0, \, j = k,\ldots,K+1}} u(t, x'_{k:K+1}, y) \\
		& \leq \limsup_{\substack{ x'_{k:K+1} \rightarrow x^o_{k:K+1} \\ x'_j > 0, \, j = k,\ldots,K+1}} \Big\{ u(t, x'_{k:K+1} - \zeta g(x^o_{k:K+1}), y) + \sum^K_{j=k} \lambda_j \zeta \Delta L_j(x^o_{k:K+1}) + \sum^K_{j=k} \theta_j \zeta \Delta M_j(x^o_{k:K+1}) \Big\} \\
		& \leq u(t, x^o_{k:K+1} - \zeta g(x^o_{k:K+1}), y) + \sum^K_{j=k} \lambda_j \zeta \Delta L_j(x^o_{k:K+1}) + \sum^K_{j=k} \theta_j \zeta \Delta M_j(x^o_{k:K+1}),
	\end{align*}
	where the last inequality follows from the USC property of $u$. Next, we let $\zeta \downarrow 0$ and obtain
	\begin{align*}
		& u(t, x^o_{k:K+1}, y) \\
		& \leq \liminf_{\zeta \downarrow 0} \Big\{ u(t, x^o_{k:K+1} - \zeta g(x^o_{k:K+1}), y) + \sum^K_{j=k} \lambda_j \zeta \Delta L_j(x^o_{k:K+1}) + \sum^K_{j=k} \theta_j \zeta \Delta M_j(x^o_{k:K+1}) \Big\} \\
		& \leq \limsup_{\zeta \downarrow 0} \Big\{ u(t, x^o_{k:K+1} - \zeta g(x^o_{k:K+1}), y) + \sum^K_{j=k} \lambda_j \zeta \Delta L_j(x^o_{k:K+1}) + \sum^K_{j=k} \theta_j \zeta \Delta M_j(x^o_{k:K+1}) \Big\} \\
		& \leq \limsup_{\zeta \downarrow 0} u(t, x^o_{k:K+1} - \zeta g(x^o_{k:K+1}), y) \\
		& \quad + \limsup_{\zeta \downarrow 0}\Big\{ \sum^K_{j=k} \lambda_j \zeta \Delta L_j(x^o_{k:K+1}) + \sum^K_{j=k} \theta_j \zeta \Delta M_j(x^o_{k:K+1}) \Big\} \\
		& \leq u(t, x^o_{k:K+1}, y),
	\end{align*}
	where we apply the USC property of $u$ again in the last inequality. Then all inequalities should be equality and the claim follows.
\end{proof}

\begin{proof}[Proof of Proposition \ref{p:comp_btw}]
    For the ease of presentation, we consider $k = K$ only, since other cases are similar. 

    {\bf Step 1}. Denote $s := (t, x_{K:K+1}, y)$. Assume on the contrary that $ u_K(\bar{s}) - v_K(\bar{s}) > 0$ for some $\bar{s} = (\bar{t}, \bar{x}_{K:K+1}, \bar{y}) \in [T_{K-1}, T_K] \times \overline{\cS}_{K}$. Let $l(s)$ be the strict subsolution in Lemma \ref{lem:strict_l}. Consider a constant $\delta \in (0, 1)$ which is close enough to 1 and small positive constants $\varepsilon, \zeta > 0$, such that
	\begin{equation}
		\delta u_K(\bar{s}) - v_K(\bar{s})  + 2 \varepsilon l(\bar{s}) - 2 \zeta^2 > 0. 
	\end{equation}
	Hence,
	\begin{align}\label{shat}
		\sup_{s \in [T_{K-1}, T_K] \times \overline{\cS}_{K}} \Big\{ \delta u_K(s) - v_K(s) + 2 \varepsilon l(s) - 2 \zeta^2 \Big\} > 0.
	\end{align}
	Since $\delta u_K(s) - v_K(s)$ is USC and bounded, $l \rightarrow -\infty$ when $|(x_{K:K+1}, y) | \rightarrow \infty$ in $\overline{\cS}_K$, the maximum in \eqref{shat} is attained in a compact subset of $[T_{K-1}, T_K] \times \overline{\cS}_{K}$ at some $\hat{s} = (\hat{t}, \hat{x}_{K:K+1}, \hat{y})$. It follows from the boundary/terminal conditions that $\hat{t} < T_K$ and $\hat{x}_{K:K+1} \neq (0, 0)$. Moreover, \eqref{shat} indicates that $\hat{s}$ does not depend on $\zeta$.

	Define a map $g(\hat{s}): [T_{K-1}, T_K] \times\overline{\cS}^o_{K} \rightarrow \R^{3+m}$ as
	\begin{equation}\label{eq:ghats}
		g(\hat{s}) = g(\hat{t}, \hat{x}_{K:K+1}, \hat{y}) = \left\{ 
		\begin{array}{ c l }
			(0, 0, 0, 0_m), & \quad \hat{x}_{K} > 0 \text{ and } \hat{x}_{K+1} > 0, \\
			(0, -1, 1, 0_m), & \quad \hat{x}_{K} = 0 \text{ and } \hat{x}_{K+1} > 0, \\
			(0, 1, -1, 0_m), & \quad \hat{x}_{K} > 0 \text{ and } \hat{x}_{K+1} = 0.
		\end{array}
		\right.
	\end{equation}
	Then $\hat{s} - \zeta g(\hat{s}) \in [T_{K-1}, T_K) \times \cS_K$ for small $\zeta > 0$.

	Next, for each $n > 0$, define
	\begin{align}
		\Phi_n(s, s') & := \delta u_K(s) - v_K(s') + \varepsilon l(s) + \varepsilon l(s') - \psi_n(s, s'), \label{Phi} \\
		\psi_n(s, s') & := |n(s - s') + \zeta g(\hat{s})|^2 + \zeta | s' - \hat{s} |^2.
	\end{align}
	Similarly, thanks to the fact that $\delta u_K(s) - v_K(s')$ is USC and bounded, $l \rightarrow -\infty$ when $|(x_{K:K+1}, y) | \rightarrow \infty$ in $\overline{\cS}_K$, the maximum of $\Phi_n$ in \eqref{Phi} is attained at 
	$$(s_n, s'_n) = ((t_n, x_{K:K+1, n}, y_n), (t'_n, x'_{K:K+1, n}, y'_n))$$
	in some compact subset of $[T_{K-1}, T_K] \times \overline{\cS}_{K} \times [T_{K-1}, T_K] \times \overline{\cS}_{K}$. Moreover, in view of \eqref{shat},
	\begin{align}
		\Phi_n(s_n, s'_n) \geq \Phi_n(\hat{s}, \hat{s}) > 0.
	\end{align}
	If we set $s = \hat{s} - \zeta g(\hat{s})/n$ and $s' = \hat{s}$, the inequality $\Phi_n(s_n, s'_n) \geq \Phi_n(\hat{s} - \zeta g(\hat{s})/n, \hat{s})$ yields
	\begin{align}
		& \delta u_K(s_n) - v_K(s'_n) + \varepsilon l(s_n) + \varepsilon l(s'_n) - |n(s_n - s'_n) + \zeta g(\hat{s})|^2 - \zeta | s'_n - \hat{s} |^2 \nonumber \\
		& \quad \geq \delta u_K(\hat{s} - \zeta g(\hat{s})/n) - v_K(\hat{s})  + \varepsilon l(\hat{s} - \zeta g(\hat{s})/n) + \varepsilon l(\hat{s}).
	\end{align}
	It reduces to
	\begin{align}
		& |n(s_n - s'_n) + \zeta g(\hat{s})|^2 + \zeta | s'_n - \hat{s} |^2 \nonumber \\
		& \quad \leq \delta u_K(s_n) - v_K(s'_n) + \varepsilon l(s_n) + \varepsilon l(s'_n) - \delta u_K(\hat{s} - \zeta g(\hat{s})/n) + v_K(\hat{s}) \label{ubd} \\
		& \qquad  - \varepsilon l(\hat{s} - \zeta g(\hat{s})/n) - \varepsilon l(\hat{s}). \nonumber 
	\end{align}
	Since $u_K$ and $v_K$ are bounded and $l(\hat{s} - \zeta g(\hat{s})/n) \rightarrow l(\hat{s})$ when $n \rightarrow \infty$ by the continuity of $l$, the right-hand side of \eqref{ubd} is bounded for all $n \geq 1$. Then $\{s_n\}^\infty_{n=1}$ and $\{s'_n\}^\infty_{n=1}$ are bounded. Up to a subsequence, both $\{s_n\}^\infty_{n=1}$ and $\{s'_n\}^\infty_{n=1}$ are convergent. They must converge to the same limit, denoted as $s^*$, since $\{|n(s_n - s'_n) + \zeta g(\hat{s})|^2 \}^\infty_{n=1}$ is bounded. To show that $s^* = \hat{s}$, we use the upper semicontinuity to derive
	\begin{equation*}
		\limsup_{n \rightarrow \infty} \Big\{ \delta u_K(s_n) - v_K(s'_n) \Big\} \leq \delta u_K(s^*) - v_K(s^*).
	\end{equation*}
	By the condition \eqref{modi_bd_u} and Lemma \ref{lem:conti},
	\begin{equation*}
		\lim_{n \rightarrow \infty} u_K(\hat{s} - \zeta g(\hat{s})/n) = u_K(\hat{s}).
	\end{equation*}
	Putting together, \eqref{ubd} becomes
	\begin{align}
		& \limsup_{n \rightarrow \infty} |n(s_n - s'_n) + \zeta g(\hat{s})|^2 + \zeta | s'_n - \hat{s} |^2 \nonumber \\
		& \quad \leq \delta u_K(s^*) - v_K(s^*) + 2 \varepsilon l(s^*) - [\delta u_K(\hat{s}) - v_K(\hat{s}) + 2 \varepsilon l(\hat{s})] \\
		& \quad \leq 0, \nonumber
	\end{align}
	where the last inequality follows from the fact that $\hat{s}$ is a maximum point in \eqref{shat}. Therefore,
	\begin{equation}\label{s_limit} 
		\lim_{n \rightarrow \infty} s_n = \lim_{n \rightarrow \infty} s'_n = \hat{s} = s^*, \quad \lim_{n \rightarrow \infty} |n(s_n - s'_n) + \zeta g(\hat{s})|^2 = 0.
	\end{equation}
	It leads to 
	\begin{equation}
		s_n = s'_n - \frac{\zeta g(\hat{s}) + o(1)}{n}.
	\end{equation}
	For sufficiently large $n$, $\hat{s} \in [T_{K-1}, T_K) \times \overline{\cS}^o_K$ implies that $s'_n \in [T_{K-1}, T_K) \times \overline{\cS}^o_K$ and $s_n \in [T_{K-1}, T_K) \times \cS_K$. It ensures that the viscosity sub/supersolution properties of $u_k$ and $v_k$ can be applied at $s_n$ and $s'_n$, respectively.


	{\bf Step 2}. Since $(s_n, s'_n)$ is a maximum point of $\Phi_n(s, s')$, by applying Ishii's lemma to the USC function $\delta u_K(s) + \varepsilon l(s)$ and the LSC function $ v_K(s') - \varepsilon l(s')$, we derive that there exist $(m+2)\times(m+2)$ symmetric matrices $M_n$ and $N_n$ satisfying
	\begin{align}
		& \left( \frac{\partial \psi_n(s_n, s'_n)}{\partial s}, M_n \right) \in \bar{J}^{2, +}_{[T_{K-1}, T_K) \times \cS_K} \big[ \delta u_K(s_n) + \varepsilon l(s_n) \big], \\
		& \left( - \frac{\partial \psi_n(s_n, s'_n)}{\partial s'}, N_n \right) \in \bar{J}^{2, -}_{[T_{K-1}, T_K) \times \overline{\cS}^o_K} \big[ v_K(s'_n) - \varepsilon l(s'_n) \big],
	\end{align} 
	and 
	\begin{equation}
		\begin{pmatrix}
			M_n & 0\\
			0 & - N_n
		\end{pmatrix} 
		\leq \Xi_n + \frac{1}{n^2} (\Xi_n)^2,
	\end{equation}
	where 
	\begin{align}
		& \frac{\partial \psi_n(s_n, s'_n)}{\partial s} = \left( \frac{\partial \psi_n(s_n, s'_n)}{\partial t}, \frac{\partial \psi_n(s_n, s'_n)}{\partial x_{K:K+1}}, \frac{\partial \psi_n(s_n, s'_n)}{\partial y} \right), \\
		& \frac{\partial \psi_n(s_n, s'_n)}{\partial s'} = \left( \frac{\partial \psi_n(s_n, s'_n)}{\partial t'}, \frac{\partial \psi_n(s_n, s'_n)}{\partial x'_{K:K+1}}, \frac{\partial \psi_n(s_n, s'_n)}{\partial y'} \right).
	\end{align}
	The Hessian matrix $\Xi_n$ is given by
	\begin{align*}
		\Xi_n = 2n^2 \begin{pmatrix}
			I_{2+m} & - I_{2+m}\\
			-I_{2+m} & I_{2+m}
		\end{pmatrix} 
		+ 2 \zeta \begin{pmatrix}
			0 & 0\\
			0 & I_{2+m}
		\end{pmatrix}.
	\end{align*}

	Since $l$ is $C^{1, 2}$ smooth, we can define
	\begin{align*}
		p_{t, n} & := \frac{1}{\delta} \left( \frac{\partial \psi_n(s_n, s'_n)}{\partial t} -  \varepsilon \frac{\partial l(s_n)}{\partial t} \right), \quad p_{K, n} := \frac{1}{\delta} \left( \frac{\partial \psi_n(s_n, s'_n)}{\partial x_K} -  \varepsilon \frac{\partial l(s_n)}{\partial x_K} \right),  \\
		p_{K+1, n} & := \frac{1}{\delta} \left( \frac{\partial \psi_n(s_n, s'_n)}{\partial x_{K+1}} -  \varepsilon \frac{\partial l(s_n)}{\partial x_{K+1}} \right), \quad p_{y, n} := \frac{1}{\delta} \left( \frac{\partial \psi_n(s_n, s'_n)}{\partial y} -  \varepsilon \frac{\partial l(s_n)}{\partial y} \right), \\
		A_n & := \frac{1}{\delta} \left( M_n -  \varepsilon \frac{\partial^2 l(s_n)}{\partial (x_{K:K+1}, y)^2} \right), \\
		q_{t, n} & := - \frac{\partial \psi_n(s_n, s'_n)}{\partial t'} + \varepsilon \frac{\partial l(s'_n)}{\partial t'}, \quad q_{K, n} := - \frac{\partial \psi_n(s_n, s'_n)}{\partial x'_K} +  \varepsilon \frac{\partial l(s'_n)}{\partial x'_K}, \\
		q_{K+1, n} & := - \frac{\partial \psi_n(s_n, s'_n)}{\partial x'_{K+1}} + \varepsilon \frac{\partial l(s'_n)}{\partial x'_{K+1}}, \quad q_{y', n} := - \frac{\partial \psi_n(s_n, s'_n)}{\partial y'} + \varepsilon \frac{\partial l(s'_n)}{\partial y'}, \\
		B_n & := N_n +  \varepsilon \frac{\partial^2 l(s'_n)}{\partial (x'_{K:K+1}, y')^2}.
	\end{align*}
	Then 
	\begin{align*}
		& \left( p_{t, n}, (p_{K:K+1, n}, p_{y, n}),  A_n\right) \in \bar{J}^{2, +}_{[T_{K-1}, T_K) \times \cS_K} \big[ u_K(s_n) \big], \\
		& \left( q_{t, n}, (q_{K:K+1, n}, q_{y', n}),  B_n \right) \in \bar{J}^{2, -}_{[T_{K-1}, T_K) \times \overline{\cS}^o_K} \big[ v_K(s'_n) \big].
	\end{align*} 
	The semijets definition of viscosity solution yields
	\begin{equation}
		\begin{aligned}
			\max \Big\{ & \beta u_K(s_n) - p_{t, n} - H(x_{K:K+1, n}, y_n, (p_{K:K+1, n}, p_{y, n}), A_n), \\
			& - \lambda_{K} + p_{K+1, n} - p_{K, n}, - \theta_{K} - p_{K+1, n} + p_{K, n}\Big\} \leq 0
		\end{aligned}
	\end{equation}
	and 
	\begin{equation}
		\begin{aligned}
			\max \Big\{ & \beta v_K(s'_n) - q_{t, n} - H(x'_{K:K+1, n}, y'_n, (q_{K:K+1, n}, q_{y', n}), B_n), \\
			& - \lambda_{K} + q_{K+1, n} - q_{K, n}, - \theta_{K} - q_{K+1, n} + q_{K, n}\Big\} \geq 0.
		\end{aligned}
	\end{equation}

        {\bf Step 3}. We consider three scenarios.

	{\bf Case 1}. Suppose that $- \lambda_{K} + q_{K+1, n} - q_{K, n} \geq 0$ holds for infinitely many $n$'s. Then
	\begin{align*}
		0 \geq & \delta (- \lambda_{K} + p_{K+1, n} - p_{K, n}) - (- \lambda_{K} + q_{K+1, n} - q_{K, n}) \\
		= & (1 - \delta) \lambda_K + \frac{\partial \psi_n(s_n, s'_n)}{\partial x_{K+1}} + \frac{\partial \psi_n(s_n, s'_n)}{\partial x'_{K+1}} - \frac{\partial \psi_n(s_n, s'_n)}{\partial x_{K}} - \frac{\partial \psi_n(s_n, s'_n)}{\partial x'_{K}} \\
		& -  \varepsilon \frac{\partial l(s_n)}{\partial x_{K+1}} + \varepsilon \frac{\partial l(s_n)}{\partial x_{K}}  -  \varepsilon \frac{\partial l(s'_n)}{\partial x'_{K+1}} + \varepsilon \frac{\partial l(s'_n)}{\partial x'_{K}}.
	\end{align*}
	We note that
	\begin{align*}
		\frac{\partial \psi_n(s_n, s'_n)}{\partial x_{K:K+1}} + \frac{\partial \psi_n(s_n, s'_n)}{\partial x'_{K:K+1}} = 2 \zeta (x'_{K:K+1, n} - \hat{x}_{K:K+1}) \rightarrow 0 \text{ as } n \rightarrow \infty.
	\end{align*}
	Moreover,
	\begin{align*}
		- \frac{\partial l(s_n)}{\partial x_{K+1}} + \frac{\partial l(s_n)}{\partial x_{K}} > - \lambda_{K}, \quad - \frac{\partial l(s'_n)}{\partial x'_{K+1}} + \frac{\partial l(s'_n)}{\partial x'_{K}} > - \lambda_{K}
	\end{align*}
	by the strict subsolution property of $l$. Since the first-order derivative of $l$ is continuous, the inequality becomes
	\begin{equation}
		0  \geq  (1 - \delta) \lambda_K  -  2 \varepsilon \frac{\partial l(\hat{s})}{\partial x_{K+1}} + 2 \varepsilon \frac{\partial l(\hat{s})}{\partial x_{K}} > (1 - \delta - 2 \varepsilon) \lambda_{K}, \text{ as } n \rightarrow \infty.
	\end{equation}
	We apply the strict subsolution property of $l$ at $\hat{s}$ in the second inequality. It contradicts with the fact that $(1 - \delta - 2 \varepsilon) > 0$ and $\lambda_{K} \geq 0$.

	{\bf Case 2}. Suppose that $- \theta_{K} - q_{K+1, n} + q_{K, n} \geq 0$ holds for infinitely many $n$'s. Similarly, we can find a contradiction by $0 > (1 - \delta - 2 \varepsilon) \theta_{K}$.

	{\bf Case 3}. $\beta v_K(s'_n) - q_{t, n} - H(x'_{K:K+1, n}, y'_n, (q_{K:K+1,n}, q_{y', n}), B_n) \geq 0$ for infinitely many $n$'s. 

	For convenience, we define an operator 
	\begin{align*}
		& \cL^{\alpha_{k:K+1}} (x_{k:K+1}, y, \partial V_k, \partial^2 V_k) \\
		& := \sum^{K+1}_{i=k}  (\mu(y) - r \one )^\top \alpha_i x_i \partial_i V_k + \frac{1}{2} \tr\left[\Sigma(\alpha_{k:K+1}, x_{k:K+1}, y) \partial^2 V_k  \right].
	\end{align*} 
	By the continuity, the infimum in $H(x'_{K:K+1, n}, y'_n, (q_{K:K+1, n}, q_{y', n}), B_n)$ is attained by some $\alpha^*_{K:K+1}$.  Then
	\begin{align}
		0 \leq & \beta v_K(s'_n) - q_{t, n} - H(x'_{K:K+1, n}, y'_n, (q_{K:K+1, n}, q_{y', n}), B_n) \nonumber \\
		& - \left[ \beta u_K(s_n) - p_{t, n} - H(x_{K:K+1, n}, y_n, (p_{K:K+1, n}, p_{y, n}), A_n) \right] \delta \nonumber \\
		\leq & \beta [v_K(s'_n) - \delta u_K(s_n)] + \frac{\partial \psi_n(s_n, s'_n)}{\partial t} -  \varepsilon \frac{\partial l(s_n)}{\partial t} + \frac{\partial \psi_n(s_n, s'_n)}{\partial t'} - \varepsilon \frac{\partial l(s'_n)}{\partial t'} \nonumber \\
		& - \sum^{K+1}_{i=K} r x'_{i, n} \left(- \frac{\partial \psi_n(s_n, s'_n)}{\partial x'_i} + \varepsilon \frac{\partial l(s'_n)}{\partial x'_i} \right) - \mu_Y(y'_n)^\top \left(- \frac{\partial \psi_n(s_n, s'_n)}{\partial y'} + \varepsilon \frac{\partial l(s'_n)}{\partial y'} \right)  \nonumber \\
		& - \cL^{\alpha^*_{K:K+1}} \left[ x'_{K:K+1, n}, y'_n, - \frac{\partial \psi_n(s_n, s'_n)}{\partial (x'_{K:K+1}, y')} + \varepsilon \frac{\partial l(s'_n)}{\partial (x'_{K:K+1}, y')}, N_n +  \varepsilon \frac{\partial^2 l(s'_n)}{\partial (x'_{K:K+1}, y')^2} \right]  \nonumber \\
		& + \sum^{K+1}_{i=K} r x_{i,n} \left( \frac{\partial \psi_n(s_n, s'_n)}{\partial x_i} - \varepsilon \frac{\partial l(s_n)}{\partial x_i} \right) + \mu_Y(y_n)^\top \left( \frac{\partial \psi_n(s_n, s'_n)}{\partial y} - \varepsilon \frac{\partial l(s_n)}{\partial y} \right)  \nonumber \\
		& + \cL^{\alpha^*_{K:K+1}} \left[ x_{K:K+1, n}, y_n, \frac{\partial \psi_n(s_n, s'_n)}{\partial (x_{K:K+1}, y)} - \varepsilon \frac{\partial l(s_n)}{\partial (x_{K: K+1}, y)}, M_n -  \varepsilon \frac{\partial^2 l(s_n)}{\partial (x_{K:K+1}, y)^2} \right], \label{Ham1}
	\end{align}
	where we used the fact that $\delta$ is canceled with $1/\delta$ in $p_{K, K+1, n}$ and $A_n$, since $\cL^{\alpha_{K:K+1}}$ is linear in derivatives.

	%a direct calculation yields
	%\begin{align*}
	%	& \frac{\partial \psi_n(s_n, s'_n)}{\partial t} + \frac{\partial \psi_n(s_n, s'_n)}{\partial t'} = 2 \zeta (t_n - \hat{t}),	
	%\end{align*}

	A direct calculation simplifies the right-hand side of \eqref{Ham1} as
	\begin{align*}
		& \beta [v_K(s'_n) - \delta u_K(s_n)] + 2 \zeta (t'_n - \hat{t})  \\
		& + \sum^{K+1}_{i=K} r x'_{i,n} \frac{\partial \psi_n(s_n, s'_n)}{\partial x'_i} + \mu_Y(y'_n)^\top \frac{\partial \psi_n(s_n, s'_n)}{\partial y'} \\
		& + \cL^{\alpha^*_{K:K+1}} \left[ x'_{K:K+1, n}, y'_n, \frac{\partial \psi_n(s_n, s'_n)}{\partial (x'_{K:K+1}, y')}, -N_n \right]  \\
		& + \sum^{K+1}_{i=K} r x_{i,n}  \frac{\partial \psi_n(s_n, s'_n)}{\partial x_i} + \mu_Y(y_n)^\top \frac{\partial \psi_n(s_n, s'_n)}{\partial y} \\
		& + \cL^{\alpha^*_{K:K+1}} \left[ x_{K:K+1, n}, y_n, \frac{\partial \psi_n(s_n, s'_n)}{\partial (x_{K:K+1}, y)}, M_n \right] \\
		& - \varepsilon \frac{\partial l(s_n)}{\partial t} - \varepsilon \sum^{K+1}_{i=K} r x_{i, n} \frac{\partial l(s_n)}{\partial x_i}  - \varepsilon \mu_Y(y_n)^\top \frac{\partial l(s_n)}{\partial y} \\
		&  - \varepsilon \cL^{\alpha^*_{K:K+1}} \left[ x_{K:K+1, n}, y_n, \frac{\partial l(s_n)}{\partial (x_{K:K+1}, y)}, \frac{\partial^2 l(s_n)}{\partial (x_{K:K+1}, y)^2} \right] \\
		& - \varepsilon \frac{\partial l(s'_n)}{\partial t'} - \varepsilon \sum^{K+1}_{i=K} r x'_{i, n} \frac{\partial l(s'_n)}{\partial x'_i}  - \varepsilon \mu_Y(y'_n)^\top \frac{\partial l(s'_n)}{\partial y'} \\
		&  - \varepsilon \cL^{\alpha^*_{K:K+1}} \left[ x'_{K:K+1, n}, y'_n, \frac{\partial l(s'_n)}{\partial (x'_{K: K+1}, y')}, \frac{\partial^2 l(s'_n)}{\partial (x'_{K:K+1}, y')^2} \right].
	\end{align*}


	%Then the inequality \eqref{Ham1} reduces to 
	%\begin{align}
	%	0 < & \beta [v_K(s'_n) - \delta u_K(s_n)] - \varepsilon \beta l(s'_n) - \varepsilon \beta l(s_n) + 2 \zeta (t_n - \hat{t})  \label{Ham2} \\
	%	& + \sum^{K+1}_{i=K} r x'_{i,n} \frac{\partial \psi_n(s_n, s'_n)}{\partial x'_i} + \mu_Y(y'_n)^\top \frac{\partial \psi_n(s_n, s'_n)}{\partial y'} + \cL^{\alpha^*_{K:K+1}} \left[ x'_{K:K+1, n}, y'_n, \frac{\partial \psi_n(s_n, s'_n)}{\partial (x'_{K:K+1}, y')}, -N_n \right]  \nonumber \\
	%	& + \sum^{K+1}_{i=K} r x_{i,n}  \frac{\partial \psi_n(s_n, s'_n)}{\partial x_i} + \mu_Y(y_n)^\top \frac{\partial \psi_n(s_n, s'_n)}{\partial y} + \cL^{\alpha^*_{K:K+1}} \left[ x_{K:K+1, n}, y_n, \frac{\partial \psi_n(s_n, s'_n)}{\partial (x_{K:K+1}, y)}, M_n \right], \nonumber
	%\end{align}

	We discuss upper bounds for each term separately. Define matrices
	\begin{align}
		& C_n := \begin{pmatrix}
			(\alpha^* x_n)^\top_{K:K+1} \sigma(y_n)  \\
			\sigma_Y(y_n)
		\end{pmatrix} \in \R^{(2+m) \times d}, 
		\quad D_n := \begin{pmatrix}
			(\alpha^* x'_n)^\top_{K:K+1} \sigma(y'_n)  \\
			\sigma_Y(y'_n)
		\end{pmatrix} \in \R^{(2+m) \times d},
		\nonumber
	\end{align} 
	Then
	\begin{align}
		& \tr\left[\Sigma(\alpha^*_{K:K+1}, x_{K:K+1, n}, y_n) M_n \right] - \tr\left[\Sigma(\alpha^*_{K:K+1}, x'_{K:K+1, n}, y'_n) N_n \right] \nonumber \\
		& \leq 10 n^2 | C_n - D_n|^2 + \left(10 \zeta +  \frac{4\zeta^2}{n^2} \right)  \tr[D^\top_n D_n] - 8 \zeta \tr[C^\top_n D_n]. \label{Sigdiff} 
	\end{align}
	By first letting $n \rightarrow \infty$ and then $\zeta \rightarrow 0$, the right-hand side of \eqref{Sigdiff} converges to zero, thanks to the bounded Lipschitz $\sigma(\cdot)$, Lipschitz $\sigma_Y(\cdot)$, \eqref{s_limit}, and the boundedness of $\{s_n\}$ and $\{s'_n\}$ obtained from \eqref{s_limit}.

	We also have
	\begin{align*}
		& x'_{i,n} \frac{\partial \psi_n(s_n, s'_n)}{\partial x'_i} + x_{i,n}  \frac{\partial \psi_n(s_n, s'_n)}{\partial x_i} \\
		& \leq 2n|x_{i, n} - x'_{i, n}|\times|n(x_{i, n} - x'_{i, n}) + \zeta g(\hat{x}_{i})| + 2 \zeta x'_{i, n} |x'_{i, n} - \hat{x}_i| \\
		& \rightarrow 0, \text{ as } n \rightarrow \infty, \\
		& \mu_Y(y'_n)^\top \frac{\partial \psi_n(s_n, s'_n)}{\partial y'} + \mu_Y(y_n)^\top \frac{\partial \psi_n(s_n, s'_n)}{\partial y} \\
		& \leq c \left(  n^2|y_n - y'_n|^2 + \zeta | y'_n - \hat{y} | \right) \\
		& \rightarrow 0, \text{ as } n \rightarrow \infty,
	\end{align*}
	where $c$ is a generic constant, and
	\begin{align*}
		& (\mu(y_n) - r \one )^\top \alpha^*_i x_{i, n} \frac{\partial \psi_n(s_n, s'_n)}{\partial x_i} + (\mu(y'_n) - r \one )^\top \alpha^*_i x'_{i, n} \frac{\partial \psi_n(s_n, s'_n)}{\partial x'_i}   \\
		& \leq c (n |x_{i, n} - x'_{i, n}| + n |y_n - y'_n|) \times|n(x_{i, n} - x'_{i, n}) + \zeta g(\hat{x}_{i})| + c \zeta |x'_{i, n} - \hat{x}_i| \\
		& \rightarrow 0, \text{ as } n \rightarrow \infty.
	\end{align*}
        Here, $g(\hat{x}_i)$ denotes the entry of $g(\hat{s})$ in \eqref{eq:ghats} corresponding to $\hat{x}_i$. Hence, $g(\hat{x}_i)$ takes values in $\{1, -1, 0\}$.

	First, when $\beta > 0$, thanks to the estimates above and the fact that $l(s)$ is strict subsolution, \eqref{Ham1} reduces to
	\begin{align*}
		0 < & \beta [v_K(s'_n) - \delta u_K(s_n)] - \beta \varepsilon l(s_n) - \beta \varepsilon l(s'_n) + 2 \zeta |t'_n - \hat{t}|\\
		& + \sum^{K+1}_{i=K} \left( 2n|x_{i, n} - x'_{i, n}|\times|n(x_{i, n} - x'_{i, n}) + \zeta g(\hat{x}_{i})| + 2 \zeta x'_{i, n} |x'_{i, n} - \hat{x}_i| \right) \\
		& + c \left(  n^2|y_n - y'_n|^2 + \zeta | y'_n - \hat{y} | \right) \\
		& + \sum^{K+1}_{i=K} \Big\{ c (n |x_{i, n} - x'_{i, n}| + n |y_n - y'_n|) \times|n(x_{i, n} - x'_{i, n}) + \zeta g(\hat{x}_{i})| + c \zeta |x'_{i, n} - \hat{x}_i| \Big\} \\
		& + 10 n^2 | C_n - D_n|^2 + \left(10 \zeta +  \frac{4\zeta^2}{n^2} \right)  \tr[D^\top_n D_n] - 8 \zeta \tr[C^\top_n D_n] \\
		\leq & \beta [v_K(\hat{s}) - \delta u_K(\hat{s}) - 2 \varepsilon l(\hat{s}) + 2 \zeta^2 - \psi_n(s_n, s'_n)] + 2 \zeta |t'_n - \hat{t}|\\
		& + \sum^{K+1}_{i=K} \left( 2n|x_{i, n} - x'_{i, n}|\times|n(x_{i, n} - x'_{i, n}) + \zeta g(\hat{x}_{i})| + 2 \zeta x'_{i, n} |x'_{i, n} - \hat{x}_i| \right) \\
		& + c \left(  n^2|y_n - y'_n|^2 + \zeta | y'_n - \hat{y} | \right) \\
		& + \sum^{K+1}_{i=K} \Big\{ c (n |x_{i, n} - x'_{i, n}| + n |y_n - y'_n|) \times|n(x_{i, n} - x'_{i, n}) + \zeta g(\hat{x}_{i})| + c \zeta |x'_{i, n} - \hat{x}_i| \Big\} \\
		& + 10 n^2 | C_n - D_n|^2 + \left(10 \zeta +  \frac{4\zeta^2}{n^2} \right)  \tr[D^\top_n D_n] - 8 \zeta \tr[C^\top_n D_n].
	\end{align*}
	The second inequality is from
	\begin{align*}
		\Phi_n (s_n, s'_n) \geq \delta u_K(\hat{s}) - v_K(\hat{s}) + 2 \varepsilon l(\hat{s}) - 2 \zeta^2,
	\end{align*}
	since $(s_n, s'_n)$ is a maximum point of $\Phi_n$. By first letting $n \rightarrow \infty$ and then $\zeta \rightarrow 0$, it leads to
	\begin{align}\label{eq:contrad}
		0 \leq \beta [v_K(\hat{s}) - \delta u_K(\hat{s}) - 2 \varepsilon l(\hat{s})]. 
	\end{align}
	Since $\beta > 0$, \eqref{eq:contrad} contradicts with \eqref{shat}.

	When $\beta = 0$, we have
	\begin{align*}
		0 \leq 	& - \varepsilon \frac{\partial l(s_n)}{\partial t} - \varepsilon \sum^{K+1}_{i=K} r x_{i, n} \frac{\partial l(s_n)}{\partial x_i}  - \varepsilon \mu_Y(y_n)^\top \frac{\partial l(s_n)}{\partial y} \\
		&  - \varepsilon \cL^{\alpha^*_{K:K+1}} \left[ x_{K:K+1, n}, y_n, \frac{\partial l(s_n)}{\partial (x_{K:K+1}, y)}, \frac{\partial^2 l(s_n)}{\partial (x_{K:K+1}, y)^2} \right] \\
		& - \varepsilon \frac{\partial l(s'_n)}{\partial t'} - \varepsilon \sum^{K+1}_{i=K} r x'_{i, n} \frac{\partial l(s'_n)}{\partial x'_i}  - \varepsilon \mu_Y(y'_n)^\top \frac{\partial l(s'_n)}{\partial y'} \\
		&  - \varepsilon \cL^{\alpha^*_{K:K+1}} \left[ x'_{K:K+1, n}, y'_n, \frac{\partial l(s'_n)}{\partial (x'_{K: K+1}, y')}, \frac{\partial^2 l(s'_n)}{\partial (x'_{K:K+1}, y')^2} \right] \\
		& + 2 \zeta |t'_n - \hat{t}| + \sum^{K+1}_{i=K} \left( 2n|x_{i, n} - x'_{i, n}|\times|n(x_{i, n} - x'_{i, n}) + \zeta g(\hat{x}_{i})| + 2 \zeta x'_{i, n} |x'_{i, n} - \hat{x}_i| \right) \\
		& + c \left(  n^2|y_n - y'_n|^2 + \zeta | y'_n - \hat{y} | \right) \\
		& + \sum^{K+1}_{i=K} \Big\{ c (n |x_{i, n} - x'_{i, n}| + n |y_n - y'_n|) \times|n(x_{i, n} - x'_{i, n}) + \zeta g(\hat{x}_{i})| + c \zeta | x'_{i, n} - \hat{x}_i| \Big\}\\
		& + 10 n^2 | C_n - D_n|^2 + \left(10 \zeta +  \frac{4\zeta^2}{n^2} \right)  \tr[D^\top_n D_n] - 8 \zeta \tr[C^\top_n D_n].
	\end{align*}

	First letting $n \rightarrow \infty$ and then $\zeta \rightarrow 0$, by the continuity of derivatives of $l(s)$, we have
	\begin{align*}
		0 \leq 	& - 2 \varepsilon \frac{\partial l(\hat{s})}{\partial t} - 2 \varepsilon \sum^{K+1}_{i=K} r \hat{x}_{i} \frac{\partial l(\hat{s})}{\partial x_i}  - 2 \varepsilon \mu_Y(\hat{y})^\top \frac{\partial l(\hat{s})}{\partial y} \\
		&  - 2 \varepsilon \cL^{\alpha^*_{K:K+1}} \left[ \hat{x}_{K:K+1}, \hat{y}, \frac{\partial l(\hat{s})}{\partial (x_{K:K+1}, y)}, \frac{\partial^2 l(\hat{s})}{\partial (x_{K:K+1}, y)^2} \right].
	\end{align*}
	However, the strict subsolution property of $l$ at $\hat{s}$ indicates that the right-hand side is strictly smaller than zero, which is a contradiction.
\end{proof}


	\begin{proof}[Proof of Proposition \ref{prop:Tk}]
		Consider $k = K$ for the ease of presentation. 

		With a slight abuse of notations, denote $s := (x_{K:K+1}, y)$. Assume on the contrary that $ u_K(\bar{s}) - v_K(\bar{s}) > 0$ for some $\bar{s} = (\bar{x}_{K:K+1}, \bar{y}) \in \overline{\cS}_{K}$. A strict subsolution is
		\begin{equation}
			l(x_{K:K+1}, y) := - c_1 \Big(1 + \sum^{K+1}_{i=K} a_i x_i \Big)^q - c_2 (1+|y|^2),
		\end{equation}
		where 
		\begin{equation}
			\begin{aligned}
				c_1, c_2 >0, \; a_i >0, \; q \in (0, 1), \; - \theta_K < (a_K - a_{K+1}) < \lambda_K, \quad 0 < c_1 q < 1,
			\end{aligned} 
		\end{equation}
		and $c_2$ is large enough to guarantee $l(x_{K:K+1}, y) - w_K (G_K - x_K)^+ - f(x_{K+1}, y) < 0$, thanks to the boundedness of $f$.

		Since $f$ is bounded, there exists constant $C_f > 0$ such that $|f(x_{K+1}, y)| \leq C_f$. Consider a constant $\delta \in (0, 1)$ which is close enough to 1 and small positive constants $\varepsilon, \zeta > 0$, such that
		\begin{equation}
			\delta u_K(\bar{s}) - v_K(\bar{s})  + 2 \varepsilon l(\bar{s}) - 2 \zeta^2 - (1 - \delta) C_f > 0. 
		\end{equation}
		Hence,
		\begin{align}\label{shat_terminal}
			\sup_{s \in \overline{\cS}_{K}} \Big\{ \delta u_K(s) - v_K(s) + 2 \varepsilon l(s) - 2 \zeta^2 - (1 - \delta) C_f  \Big\} > 0,
		\end{align}
		and the maximum is attained in a compact subset of $\overline{\cS}_{K}$ at some $\hat{s} = (\hat{x}_{K:K+1}, \hat{y})$.

		Similar to the proof of Proposition \ref{p:comp_btw}, we can obtain a contradiction if $- \lambda_{K} + q_{K+1, n} - q_{K, n} \geq 0$ or $- \theta_{K} - q_{K+1, n} + q_{K, n} \geq 0$ holds for infinitely many $n$'s, where $q_{K+1, n}$ and $q_{K, n}$ are defined similarly as in the proof of Proposition \ref{p:comp_btw}. Hence, we only focus on the third case: $v_K(x'_{K:K+1, n}, y'_n) - w_K (G_K - x'_{K, n})^+ - f(x'_{K+1, n}, y'_n) \geq 0$ holds for infinitely many $n$'s. Then
		\begin{align}
			0 \leq & v_K(s'_n) - w_K (G_K - x'_{K, n})^+ - f(x'_{K+1, n}, y'_n)  \label{comTk1}\\
			& - \big( u_K(s_n) - w_K (G_K - x_{K, n})^+ - f(x_{K+1, n}, y_n)  \big) \delta. \nonumber
		\end{align}

		As in the proof of Proposition \ref{p:comp_btw}, $(s_n, s'_n)$ is a maximum point of $\Phi_n(s, s')$, defined in the same way as \eqref{Phi}, we have
		\begin{align}
			&\delta u_K(s_n) - v_K(s'_n) + \varepsilon l(s_n) + \varepsilon l(s'_n) - \psi_n(s_n, s'_n) \nonumber \\
			& \geq \delta u_K(\hat{s}) - v_K(\hat{s}) + 2 \varepsilon l(\hat{s}) - 2 \zeta^2. \label{comTk2}
		\end{align} 
		Therefore, \eqref{comTk1} and \eqref{comTk2} lead to
		\begin{align*}
			0 \leq & \delta w_K (G_K - x_{K, n})^+ - w_K (G_K - x'_{K, n})^+ - f(x'_{K+1, n}, y'_n) + \delta f(x_{K+1, n}, y_n) \\
			& + \varepsilon l(s_n) + \varepsilon l(s'_n) - \psi_n(s_n, s'_n) - \delta u_K(\hat{s}) + v_K(\hat{s}) - 2 \varepsilon l(\hat{s}) + 2 \zeta^2.
		\end{align*}
		When $n \rightarrow \infty$, by the continuity of $l$ and $f$, we have
		\begin{align*}
			0 & \leq v_K(\hat{s}) - \delta u_K(\hat{s}) + (\delta - 1) w_K (G_K - \hat{x}_K)^+ + (\delta - 1) f(\hat{x}_{K+1}, \hat{y}) + 2 \zeta^2\\
			& \leq v_K(\hat{s}) - \delta u_K(\hat{s}) + (1 - \delta) C_f + 2 \zeta^2,
		\end{align*}
		which contradicts with \eqref{shat_terminal}.
	\end{proof}



\begin{proof}[Proof of Proposition \ref{prop:comp_last}]
	Denote $s := (t, x_{K+1}, y)$. Assume on the contrary that $ u_{K+1}(\bar{s}) - v_{K+1}(\bar{s}) > 0$ for some $\bar{s} = (\bar{t}, \bar{x}_{K+1}, \bar{y}) \in [T_{K}, T] \times \overline{\cS}_{K+1}$. A strict subsolution $l(s)$ is given by
		\begin{equation}
			l(t, x_{K+1}, y) := - c_1 e^{\gamma(T - t)} \Big(1 + a_{K+1} x_{K+1} \Big)^q - c_2 e^{\gamma(T - t)} (1 + |y|^2),
		\end{equation}
		with $c_1, c_2, \gamma > 0$, $q \in (0, 1)$, and $\gamma$ large enough. Similar to Lemma \ref{lem:strict_l}, it is direct to verify that $l(s)$ is a strict subsolution of \eqref{Vlast} on $[T_{K}, T) \times \overline{\cS}_{K+1}$.


		Consider a small positive constant $\varepsilon > 0$, such that
		\begin{equation}
			u_{K+1}(\bar{s}) - v_{K+1}(\bar{s})  + 2 \varepsilon l(\bar{s}) > 0. 
		\end{equation}

		For each $n \geq 0$, define
		\begin{align}
			\Phi_n(s, s') & := u_{K+1}(s) - v_{K+1}(s') + \varepsilon l(s) + \varepsilon l(s') - \psi_n(s, s'), \label{Phi_K+1} \\
			\psi_n(s, s') & := \frac{n}{2} |s - s'|^2.
		\end{align}
		Since $u_{K+1}(s) - v_{K+1}(s')$ is USC and bounded, $l \rightarrow -\infty$ when $|(x_{K+1}, y) | \rightarrow \infty$ in $\overline{\cS}_{K+1}$, the maximum of $\Phi_n$ in \eqref{Phi_K+1} is attained at 
		$$(s_n, s'_n) = ((t_n, x_{K+1, n}, y_n), (t'_n, x'_{K+1, n}, y'_n))$$
		in some compact subset of $[T_{K}, T] \times \overline{\cS}_{K+1} \times [T_{K}, T] \times \overline{\cS}_{K+1}$. By the compactness, we can extract a subsequence, still denoted as $(s_n, s'_n)$, such that $(s_n, s'_n) \rightarrow (\hat{s}, \hat{s}')$. Moreover,
		\begin{align*}
			\Phi_n(s_n, s'_n) & \geq \sup_{s \in [T_K, T] \times \overline{\cS}_{K+1}} \Phi_0(s, s) \geq u_{K+1}(\bar{s}) - v_{K+1}(\bar{s}) + 2 \varepsilon l(\bar{s}) > 0.
		\end{align*}

		It reduces to
		\begin{align}
			& \frac{n}{2} | s_n - s'_n |^2 \leq u_{K+1}(s_n) - v_{K+1}(s'_n) + \varepsilon l(s_n) + \varepsilon l(s'_n) -  \sup_{s \in [T_K, T] \times \overline{\cS}_{K+1}} \Phi_0(s, s). \label{ubd_K+1}
		\end{align}
		Since $u_{K+1}$ and $v_{K+1}$ are bounded, $l(s_n)$ and $l(s'_n)$ converge to $l(\hat{s})$ by the continuity of $l$, and $\sup_{s \in [T_K, T] \times \overline{\cS}_{K+1}} \Phi_0(s, s) > 0$, the right-hand side of \eqref{ubd_K+1} is bounded for all $n \geq 1$. Then $| s_n - s'_n |^2 \rightarrow 0$. Hence $\hat{s} = \hat{s}'$. Putting it back to \eqref{ubd_K+1}, we obtain
		\begin{equation}\label{eq:limsup_K+1}
			\begin{aligned} 
				0 & \leq \limsup_{n \rightarrow \infty} \frac{n}{2}| s_n - s'_n|^2 \\
				& \leq \limsup_{n \rightarrow \infty} \left\{ u_{K+1}(s_n) - v_{K+1}(s'_n) + \varepsilon l(s_n) + \varepsilon l(s'_n) \right\} - \sup_{s \in [T_K, T] \times \overline{\cS}_{K+1}} \Phi_0(s, s) \\
				& \leq u_{K+1}(\hat{s}) - v_{K+1}(\hat{s}) + 2 \varepsilon l(\hat{s}) - \sup_{s \in [T_K, T] \times \overline{\cS}_{K+1}} \Phi_0(s, s) \leq 0, 
			\end{aligned}
		\end{equation} 
		where the third inequality holds since $u_{K+1} - v_{K+1}$ is USC and $l$ is continuous. Therefore,
		\begin{equation}\label{slim_K+1} 
			\lim_{n \rightarrow \infty} n|s_n - s'_n|^2 = 0.
		\end{equation}

		We note that $\Phi_n(s_n, s'_n)$ is monotone in $n$ since
		\begin{equation}
			\Phi_n(s_n, s'_n) \geq \Phi_n(s_{n+1}, s'_{n+1}) \geq \Phi_{n+1}(s_{n+1}, s'_{n+1}).
		\end{equation}
		Then the following limit exists and is given by
		\begin{equation}\label{shat_last}
			\begin{aligned}
				\lim_{n \rightarrow \infty} \Phi_n (s_n, s'_n) = & \lim_{n \rightarrow \infty} (u_{K+1}(s_n) - v_{K+1}(s'_n)) + \lim_{n \rightarrow \infty}  (\varepsilon l(s_n) + \varepsilon l(s'_n)) \\
				& - \lim_{n \rightarrow \infty} \frac{n}{2} |s_n - s'_n|^2 \\
				= &  u_{K+1}(\hat{s}) - v_{K+1}(\hat{s}) + 2 \varepsilon l(\hat{s})  = \sup_{s \in [T_K, T] \times \overline{\cS}_{K+1}} \Phi_0(s, s)  > 0,
			\end{aligned}
		\end{equation}
		where \eqref{eq:limsup_K+1} and \eqref{slim_K+1} are used.

		By the boundary/terminal conditions, we have $\hat{t} < T$ and $\hat{x}_{K+1} > 0$. Then for sufficiently large $n$, $s_n$ and $s'_n$ are also in $[T_K, T) \times \cS_{K+1}$. Hence, the viscosity sub/supersolution properties of $u_{K+1}$ and $v_{K+1}$ can be applied at $s_n$ and $s'_n$, respectively.


		Since $(s_n, s'_n)$ is a maximum point of $\Phi_n(s, s')$, by applying Ishii's lemma to the USC function $u_{K+1}(s) + \varepsilon l(s)$ and the LSC function $ v_{K+1}(s') - \varepsilon l(s')$, we derive that there exist $(m+1) \times (m + 1)$ symmetric matrices $M_n$ and $N_n$ satisfying
		\begin{align}
			& \left( \frac{\partial \psi_n(s_n, s'_n)}{\partial s}, M_n \right) \in \bar{J}^{2, +}_{[T_K, T) \times \cS_{K+1}} \big[ u_{K+1}(s_n) + \varepsilon l(s_n) \big], \\
			& \left( - \frac{\partial \psi_n(s_n, s'_n)}{\partial s'}, N_n \right) \in \bar{J}^{2, -}_{[T_K, T) \times \cS_{K+1}} \big[ v_{K+1}(s'_n) - \varepsilon l(s'_n) \big],
		\end{align} 
		and 
		\begin{equation}\label{eq:Ishii}
			\begin{pmatrix}
				M_n & 0\\
				0 & - N_n
			\end{pmatrix} 
			\leq \Xi_n + \frac{1}{n} (\Xi_n)^2,
		\end{equation}
		where the Hessian matrix $\Xi_n$ is given by
		\begin{align*}
			\Xi_n = n \begin{pmatrix}
				I_{1+m} & - I_{1+m}\\
				-I_{1+m} & I_{1+m}
			\end{pmatrix}.
		\end{align*}

		Since $l$ is $C^{1, 2}$ smooth, we can define
		\begin{align*}
			p_{t, n} & :=  \frac{\partial \psi_n(s_n, s'_n)}{\partial t} -  \varepsilon \frac{\partial l(s_n)}{\partial t} = n(t_n - t'_n) - \varepsilon \frac{\partial l(s_n)}{\partial t}, \\
			p_{K+1, n} & := \frac{\partial \psi_n(s_n, s'_n)}{\partial x_{K+1, n}}  -  \varepsilon \frac{\partial l(s_n)}{\partial y} = n (x_{K+1, n} - x'_{K+1, n}) -  \varepsilon \frac{\partial l(s_n)}{\partial x_{K+1}}, \\
			p_{y, n} & :=  \frac{\partial \psi_n(s_n, s'_n)}{\partial y} -  \varepsilon \frac{\partial l(s_n)}{\partial y} = n (y_n - y'_n) -  \varepsilon \frac{\partial l(s_n)}{\partial y}, \\
			q_{t, n} & := - \frac{\partial \psi_n(s_n, s'_n)}{\partial t'} + \varepsilon \frac{\partial l(s'_n)}{\partial t'} =  n(t_n - t'_n) + \varepsilon \frac{\partial l(s'_n)}{\partial t'}, \\
			q_{K+1, n} & := - \frac{\partial \psi_n(s_n, s'_n)}{\partial x'_{K+1}} + \varepsilon \frac{\partial l(s'_n)}{\partial x'_{K+1}} = n(x_{K+1, n} - x'_{K+1, n}) + \varepsilon \frac{\partial l(s'_n)}{\partial x'_{K+1}}, \\
			q_{y', n} &:= - \frac{\partial \psi_n(s_n, s'_n)}{\partial y'} + \varepsilon \frac{\partial l(s'_n)}{\partial y'} = n(y_n - y'_n) + \varepsilon \frac{\partial l(s'_n)}{\partial y'}, \\
			A_n & := M_n -  \varepsilon \frac{\partial^2 l(s_n)}{\partial (x_{K+1}, y)^2}, \quad B_n := N_n +  \varepsilon \frac{\partial^2 l(s'_n)}{\partial (x'_{K+1}, y')^2}.
		\end{align*}
		Then 
		\begin{align*}
			& \left( p_{t, n}, (p_{K+1, n}, p_{y, n}),  A_n\right) \in \bar{J}^{2, +}_{[T_K, T) \times \cS_{K+1}} \big[ u_{K+1}(s_n) \big], \\
			& \left( q_{t, n}, (q_{K+1, n}, q_{y', n}),  B_n \right) \in \bar{J}^{2, -}_{[T_K, T) \times \cS_{K+1}} \big[ v_{K+1}(s'_n) \big].
		\end{align*} 
		The semijets definition of viscosity solution yields
		\begin{equation}
			\begin{aligned} 
				& \beta u_{K+1}(s_n) - p_{t, n} - H(x_{K+1, n}, y_n, (p_{K+1, n}, p_{y, n}), A_n) \leq 0, \\
				& \beta v_{K+1}(s'_n) - q_{t, n} - H(x'_{K+1, n}, y'_n, (q_{K+1, n}, q_{y', n}), B_n) \geq 0.
			\end{aligned} 
		\end{equation}

		We argue by contradiction. Suppose $\beta v_{K+1}(s'_n) - q_{t, n} - H(x'_{K+1, n}, y'_n, (q_{K+1, n}, q_{y', n}), B_n) \geq 0$ for infinitely many $n$'s. By the continuity, the infimum in $H(x'_{K+1, n}, y'_n, (q_{K+1, n}, q_{y', n}), B_n)$ is attained at some $\alpha^*_{K+1}$.  Then
		\begin{align}
			0 \leq & \beta v_{K+1}(s'_n) - q_{t, n} - H(x'_{K+1, n}, y'_n, (q_{K+1, n}, q_{y', n}), B_n) \nonumber \\
			& - \left[ \beta u_{K+1}(s_n) - p_{t, n} - H(x_{K+1, n}, y_n, (p_{K+1, n}, p_{y, n}), A_n) \right] \nonumber \\
			\leq & \beta [v_{K+1}(s'_n) - u_{K+1}(s_n)] - \varepsilon \frac{\partial l(s_n)}{\partial t} - \varepsilon \frac{\partial l(s'_n)}{\partial t'}  \label{ineq:last} \\
			& - r \varepsilon x_{K+1, n} \frac{\partial l(s_n)}{\partial x_{K+1}} - r \varepsilon x'_{K+1, n} \frac{\partial l(s'_n)}{\partial x'_{K+1}}  - \varepsilon \mu_Y(y_n)^\top \frac{\partial l(s_n)}{\partial y_n}  - \varepsilon \mu_Y(y'_n)^\top \frac{\partial l(s'_n)}{\partial y'_n}  \nonumber \\
			& +  r n (x_{K+1, n} - x'_{K+1,n})^2 + n [ \mu_Y(y_n) - \mu_Y(y'_n)]^\top(y_n - y'_n) \nonumber \\
			& - (\mu(y'_n) - r\one)^\top \alpha^*_{K+1} x'_{K+1, n} \left( n (x_{K+1, n} - x'_{K+1, n}) + \varepsilon \frac{\partial l(s'_n)}{\partial x'_{K+1}} \right) \nonumber \\
			& - \frac{1}{2} \tr[\Sigma(\alpha^*_{K+1}, x'_{K+1, n}, y'_n) N_n] - \frac{\varepsilon}{2} \tr \left[\Sigma(\alpha^*_{K+1}, x'_{K+1, n}, y'_n) \frac{\partial^2 l(s'_n)}{\partial (x'_{K+1}, y')^2} \right] \nonumber \\
			& + (\mu(y_n) - r\one)^\top \alpha^*_{K+1} x_{K+1, n} \left( n (x_{K+1, n} - x'_{K+1, n}) - \varepsilon \frac{\partial l(s_n)}{\partial x_{K+1}} \right) \nonumber \\
			& + \frac{1}{2} \tr[\Sigma(\alpha^*_{K+1}, x_{K+1, n}, y_n) M_n] - \frac{\varepsilon}{2} \tr \left[\Sigma(\alpha^*_{K+1}, x_{K+1, n}, y_n) \frac{\partial^2 l(s_n)}{\partial (x_{K+1}, y)^2} \right].   \nonumber
		\end{align}


		By the Lipschitz property of $\mu_Y(y)$,
		\begin{align*}
			n [ \mu_Y(y_n) - \mu_Y(y'_n)]^\top(y_n - y'_n) \leq cn | y_n - y'_n|^2,
		\end{align*}
		where $c$ is the Lipschitz constant.

		Similarly, by the boundedness of $\{x_{K+1, n}\}$, $\{ x'_{K+1, n}\}$, $\mu(y)$, and the Lipschitz property of $\mu(y)$, we have
		\begin{equation}
			\begin{aligned}
				& (\mu(y_n) - r\one)^\top \alpha^*_{K+1} x_{K+1, n} n (x_{K+1, n} - x'_{K+1, n}) \\
				& \quad  - (\mu(y'_n) - r\one)^\top \alpha^*_{K+1} x'_{K+1, n} n (x_{K+1, n} - x'_{K+1, n}) \\
				& \leq c n |x_{K+1, n} - x'_{K+1, n} |^2 + c n | y_n - y'_n|^2.
			\end{aligned}
		\end{equation}

		%	We discuss upper bounds for each term separately. Define matrices
		%	\begin{align}
			%		& C_n := \begin{pmatrix}
				%			(\alpha^* x_n)^\top_{K:K+1} \sigma(y_n)  \\
				%			\sigma_Y(y_n)
				%		\end{pmatrix} \in \R^{(2+m) \times d}, 
			%		\quad D_n := \begin{pmatrix}
				%			(\alpha^* x'_n)^\top_{K:K+1} \sigma(y'_n)  \\
				%			\sigma_Y(y'_n)
				%		\end{pmatrix} \in \R^{(2+m) \times d},
			%		\nonumber
			%	\end{align} 
		With \eqref{eq:Ishii}, Lipschitz property of $\sigma_Y(y)$, and the bounded Lipschitz property of $\sigma_Y(y)$, we have
		\begin{align}
			& \tr\left[\Sigma(\alpha^*_{K+1}, x_{K+1, n}, y_n) M_n \right] - \tr\left[\Sigma(\alpha^*_{K+1}, x'_{K+1, n}, y'_n) N_n \right] \nonumber \\
			& \leq cn \left( |x_{K+1, n} - x'_{K+1, n}|^2 + |y_n - y'_n|^2 \right).
		\end{align}

		First, when $\beta > 0$, thanks to the estimates above and the fact that $l(s)$ is strict subsolution, \eqref{ineq:last} reduces to
		\begin{align}
			0 < & \beta [v_{K+1}(s'_n) - u_{K+1}(s_n)] - \beta \varepsilon l(s_n) - \beta \varepsilon l(s'_n) + c n |x_{K+1, n} - x'_{K+1, n} |^2 + c n | y_n - y'_n|^2 \nonumber \\
			\leq & \beta [v_{K+1}(\hat{s}) - u_{K+1}(\hat{s})] - 2 \beta \varepsilon l(\hat{s}) + c n | s_n - s'_n|^2. \label{ineq:beta1}
		\end{align}
		The second inequality is from
		\begin{align*}
			\Phi_n (s_n, s'_n) \geq u_{K+1}(\hat{s}) - v_{K+1}(\hat{s}) + 2 \varepsilon l(\hat{s}),
		\end{align*}
		since $(s_n, s'_n)$ is a maximum point of $\Phi_n$. When $n \rightarrow \infty$, \eqref{ineq:beta1} leads to
		\begin{align}\label{eq:con}
			0 \leq \beta [v_{K+1}(\hat{s}) - u_{K+1}(\hat{s}) - 2 \varepsilon l(\hat{s})]. 
		\end{align}
		Since $\beta > 0$, \eqref{eq:con} contradicts with \eqref{shat_last}.

		When $\beta = 0$, we have
		\begin{align*}
			0 \leq & - \varepsilon \frac{\partial l(s_n)}{\partial t} - \varepsilon \frac{\partial l(s'_n)}{\partial t'} \\
			& - \varepsilon r  x_{K+1, n} \frac{\partial l(s_n)}{\partial x_{K+1}} - \varepsilon r x'_{K+1, n} \frac{\partial l(s'_n)}{\partial x'_{K+1}} - \varepsilon \mu_Y(y_n)^\top \frac{\partial l(s_n)}{\partial y_n}  - \varepsilon \mu_Y(y'_n)^\top \frac{\partial l(s'_n)}{\partial y'_n}  \\
			&  - \varepsilon (\mu(y'_n) - r\one)^\top \alpha^*_{K+1} x'_{K+1, n}  \frac{\partial l(s'_n)}{\partial x'_{K+1}}  - \frac{\varepsilon}{2} \tr \left[\Sigma(\alpha^*_{K+1}, x'_{K+1, n}, y'_n) \frac{\partial^2 l(s'_n)}{\partial (x'_{K+1}, y')^2} \right]  \\
			&  - \varepsilon (\mu(y_n) - r\one)^\top \alpha^*_{K+1} x_{K+1, n}  \frac{\partial l(s_n)}{\partial x_{K+1}} - \frac{\varepsilon}{2} \tr \left[\Sigma(\alpha^*_{K+1}, x_{K+1, n}, y_n) \frac{\partial^2 l(s_n)}{\partial (x_{K+1}, y)^2} \right] \\
			& + c n | s_n - s'_n|^2.   
		\end{align*}

		Letting $n \rightarrow \infty$, by the continuity of derivatives of $l(s)$, we have
		\begin{align*}
			0 \leq 	& - 2 \varepsilon \frac{\partial l(\hat{s})}{\partial t} - 2 \varepsilon r \hat{x}_{K+1} \frac{\partial l(\hat{s})}{\partial x_{K+1}}  - 2 \varepsilon \mu_Y(\hat{y})^\top \frac{\partial l(\hat{s})}{\partial y} \\
			&  - 2 \varepsilon \cL^{\alpha^*_{K+1}} \left[ \hat{x}_{K+1}, \hat{y}, \frac{\partial l(\hat{s})}{\partial (x_{K+1}, y)}, \frac{\partial^2 l(\hat{s})}{\partial (x_{K+1}, y)^2} \right].
		\end{align*}
		However, the strict subsolution property of $l$ at $\hat{s}$ indicates that the right-hand side is strictly smaller than zero, which is a contradiction.
	\end{proof}

