\section{The scaling process of saddle point equation}
Based on Equation (\ref{eq:ps(t)}), Equation (\ref{eq:saddle point equationb}) can be rewritten in a more specific form as:
\begin{equation}
	\begin{aligned}
		\frac{A_0^2}{2} [\frac{\cos (t_r)-\cos (t_r-\tau )}{\tau }+\sin(t_r-\tau)]^2=-I_p.
	\end{aligned}
	\label{eq:saddle point equationb1}
\end{equation}
When scaled by $U_p$, the equation above can be simplified to the form related to the adiabatic parameter $\gamma$:
\begin{equation}
	\begin{aligned}
		{\frac{1}{\tau}[\cos(t_r)-\cos(t_r-\tau)]+\sin(t_r-\tau)}= \pm i\gamma.
	\end{aligned}
	\label{eq:saddle point equationb2}
\end{equation}
The following will use the positive sign as an example. Here, $t_r$ can be written as $(t_r - \tau/2) + \tau/2$ and $t_r - \tau$ can be written as $(t_r - \tau/2) - \tau/2$. Then, using trigonometric functions, one can obtain the following equation:
\begin{equation}
	\begin{aligned}
		\sin(t_r-\tau/2&)[\cos(\tau/2)-\frac{2\sin(\tau/2)}{\tau}]\\
		&-\cos(t_r-\tau/2)\sin(\tau/2)= i\gamma.
	\end{aligned}
	\label{eq:saddle point equationb3}
\end{equation}
Following the definitions $a(\tau)=\cos(\tau/2)-2\sin(\tau/2)/\tau$ and $s(\tau)= \sin(\tau/2)$, Eq. (\ref{eq:saddle point equationb3}) can be written in the form of Eq. (\ref{eq:saddleb reduced form}). 

\section{The derivation of the kinetic energy and return time of returned electron}
As indicated in Eq. (\ref{eq:saddle point equationb}), the first term on the left side of the equation represents the electron velocity at the moment of ionization $t_r$, while the second term represents the electron velocity at the moment $t_r-\tau$. Referring to Eq. (\ref{eq:ps(t)}), one can determine the electron velocity at the return moment $t_r$ as:
\begin{equation}
	\begin{aligned}
	v(t_r) = &p_s-A(t_r) \\=&A_0 [\frac{\cos (t_r)-\cos (t_r-\tau )}{\tau }+\sin (t_r)].
	\end{aligned}
	\label{eq:v(t_r)}
\end{equation}
By using the definition of $a(\tau)$ and $s(\tau)$, the kinetic energy of the returned electron can be expressed as
\begin{equation}
	E_{re}=2U_p
		[\sin\left( t_r-\frac {\tau}{2}\right) a\left( \tau \right) +\cos\left( t_r-\frac {\tau}{2}\right) s\left( \tau\right)]^2.
	\label{eq:return kinetic energy1}
\end{equation}
By utilizing the trigonometric identity $\sin\left( t_r-\tau/2\right)^2+\cos\left( t_r-\tau/2\right)^2=1$ in Eq. (\ref{eq:saddleb reduced form}), we can derive the formula as
\begin{equation}
	\sin(t_r-\frac{\tau}{2})=\frac{i\gamma a\left( \tau \right) + s\left( \tau \right) \sqrt{a^2\left( \tau \right) +s^2\left( \tau \right) +\gamma^2}}{ a^2\left( \tau \right) +s^2\left( \tau \right)}, 
	\label{eq:sin}
\end{equation} 
\begin{equation}
	\cos(t_r-\frac{\tau}{2})=\frac{-i\gamma s\left( \tau \right) + a\left( \tau \right) \sqrt{s^2\left( \tau \right) +a^2\left( \tau \right) +\gamma^2}}{ s^2\left( \tau \right) +a^2\left( \tau \right)}.
	\label{eq:cos}
\end{equation}
By substituting Eqs. (\ref{eq:sin}) and Eq. (\ref{eq:cos}) into Eq. (\ref{eq:return kinetic energy1}), one can derive the kinetic energy of the returned electron as a function of $\tau$, expressed as Eq. (\ref{eq:kinetic energy}).
Therefore, it appears that the return time can be expressed as
\begin{equation}
	t_r=\frac{\tau}{2}+\arctan \frac{\sin(t_r-\frac{\tau}{2})}{\cos(t_r-\frac{\tau}{2})} .
	\label{eq:arctan}
\end{equation}
Inserting Eq. (\ref{eq:sin}) and Eq. (\ref{eq:cos}) into Eq. (\ref{eq:arctan}) allows one to obtain the expression for the electron return time 
\begin{equation}
	\begin{aligned}
	&t_r=\frac{\tau }{2}+ \\ &\arctan(\frac{a \sqrt{a^2+\gamma ^2+s^2}-is \gamma }{a^2+s^2}, \frac{s \sqrt{a^2+\gamma ^2+s^2}+i a \gamma }{a^2+s^2}).
	\end{aligned}	
	\label{eq:return time}
\end{equation}

\section{The derivation of the $\theta_5$}
According to Equations (\ref{eq:theta}) and (\ref{eq:Theta}), $\theta$ is composed of two parts: the scaled quasiclassical action and the product of photon energy and return time. By scaling $S(p_{s}, t_r, \tau) = (U_p/\omega) \alpha$ and $\Omega t_{r} / \omega = (U_p/\omega) \beta$, $\theta$ can be expressed as
\begin{equation}
	\begin{aligned}
\theta&=\alpha+\beta. \\
	\end{aligned}
\end{equation}
Therefore, the FAE term of $\theta$ can be expressed as
\begin{equation}
	\begin{aligned}
\theta_5&=\alpha_5+\beta_5, \\
\label{eq:theta_5}
	\end{aligned}
\end{equation}
where $\alpha_5$ and $\beta_5$ are the fifth-order terms of $\alpha$ and $\beta$, respectively. Starting from $\beta$, due to the relationship $\Omega=E_{re}+I_p$, $\beta$ can be expressed as
\begin{equation}
	\begin{aligned}
	\beta&=\frac{(E_{re}+I_p)}{U_p}t_r \\
	\end{aligned}
	\label{eq:beta}
\end{equation}
Inserting Eqs.(\ref{eq: third order kinetic energy}) and (\ref{eq:tr}) to Eq.(\ref{eq:beta}), and keeping terms up to $\gamma^5$, one can obtain
\begin{equation}
	\begin{aligned}
	\beta_5&=(E_{re2}+2)t_{r3}. \\
	\end{aligned}
	\label{eq:beta_5}
\end{equation}
As for $\alpha$, using the definition $E(t)=E_0 \cos(t)$ then Eq. (\ref{eq:ps(t)}) can be used to replaced $\textbf{p}$ in Eq. (\ref{eq:quasiclassical action.}). Then $S(p_{st}, t_r, \tau)$ can be expressed as
\begin{equation}
	\begin{aligned}
	S=\frac{1}{\omega} \int_{t_i}^{t_r}{\left[\frac{A_0^2\left( \frac{\cos\left(t_r\right)-\cos\left(t_i\right)}{\tau}-\sin\left(t\right)    \right) ^2}{2}+I_p\right] dt }. 
	\end{aligned}
	\label{eq:SS}
\end{equation}
Then scaling $S(p_{st}, t_r, \tau)$ with $(U_p/\omega)$, one can obtain the expression of $\alpha$ as  
\begin{equation}
	\begin{aligned}
	\alpha= 2\int_{t_i}^{t_r}{\left[\left( \frac{\cos\left(t_r\right)-\cos\left(t_i\right)}{\tau}-\sin\left(t\right)    \right) ^2+\gamma^2\right] dt }. 
	\end{aligned}
	\label{eq:alpha1}
\end{equation}
Solving integral Eq. (\ref{eq:alpha1}), $\alpha$ can be rewrietten as
\begin{equation}
	\begin{aligned}
		\alpha=&2 \gamma ^2 \tau + \frac{-2+2 \cos \tau +\tau^2 }{\tau}+\\
		&\frac{-\cos 2t_i +(2-\tau \sin \tau ) \cos (t_r+t_i )-\cos 2 t_r}{\tau }.
	\label{eq:alpha2}
	\end{aligned}
\end{equation}
Based on the FAE method, $\alpha_5$ can be expressed as a function as 
\begin{equation}
	\begin{aligned}
		\alpha_5=\alpha_A+\alpha_B+\alpha_C+\alpha_D+\alpha_E+\alpha_F+\alpha_G.
	\label{eq:alpha_5}
	\end{aligned}
\end{equation}
Here $\alpha_{A-G}$ are
