	\title{Entropy Regularized Belief Reporting}

	\author{Elchin Suleymanov\thanks{Department of Economics, Purdue University. Email: \href{mailto:esuleyma@purdue.edu}{esuleyma@purdue.edu}.}}

	\date{\today}

