	\subsection*{Proof of Proposition \ref{prop:exponential}}

	The Lagrangian for the optimization problem is 
	$$\lambda \sum_{E_i \in \mathcal{P}}\pi'_{\mathcal{P}}(E_i) \ln\left(\frac{\pi'_{\mathcal{P}}(E_i)}{\pi_{\mathcal{P}}(E_i)}\right) + (1-\lambda)\sum_{E_i \in \mathcal{P}}\pi'_{\mathcal{P}}(E_i) \ln\left(\pi'_{\mathcal{P}}(E_i)\right)+ \eta_{\mathcal{P}} \left(\sum_{E_i\in \mathcal{P}} \pi'_{\mathcal{P}}(E_i)-1\right),$$
	where $\eta_{\mathcal{P}}$ is the multiplier corresponding to the constraint that reported beliefs add up to one. Simplifying, we get
	$$\sum_{E_i \in \mathcal{P}}\pi'_{\mathcal{P}}(E_i) \ln\left(\pi'_{\mathcal{P}}(E_i)\right) -\lambda\sum_{E_i \in \mathcal{P}}\pi'_{\mathcal{P}}(E_i) \ln\left(\pi_{\mathcal{P}}(E_i)\right)+ \eta_{\mathcal{P}} \left(\sum_{E_i\in \mathcal{P}} \pi'_{\mathcal{P}}(E_i)-1\right).$$
	The first order conditions require
	$$\ln(\pi'_{\mathcal{P}}(E_i)) +1  - \lambda\ln(\pi_{\mathcal{P}}(E_i)) + \eta_{\mathcal{P}} = 0 \quad \Rightarrow \quad 
	\pi'_{\mathcal{P}}(E_i)  = \frac{\pi_{\mathcal{P}}(E_i)^{\lambda}}{\exp(\eta_{\mathcal{P}}+1)} ,$$
	where $\eta_{\mathcal{P}}$ is chosen to satisfy the constraint. Adding over all $E_i\in \mathcal{P}$ and setting it equal to one, we get
	$$\pi'_\mathcal{P}(E_i) = \frac{\pi_\mathcal{P}(E_i)^{\lambda}}{\sum_{E_j\in \mathcal{P}} \pi_\mathcal{P}(E_j)^{\lambda}},$$
	as desired. Since the objective function is strictly convex and the constraint is linear, this uniquely pins down the reported beliefs. 

	\subsection*{Proof of Proposition \ref{prop:subadditive}}

	Let $p,q\in (0,1)$ be such that $p+q\leq 1$. We want to show that 
	\begin{itemize}
		\item if $\lambda\leq 1$, then $p^{\lambda} +q^{\lambda} \geq (p+q)^{\lambda}$, and
		\item if $\lambda\geq 1$, then $p^{\lambda} +q^{\lambda} \leq (p+q)^{\lambda}$.
	\end{itemize}
	First, consider the case $\lambda<0$. Since $f(x) = x^{\lambda}$ is a decreasing function for $\lambda<0$, $p<p+q$, and $q>0$, we have 
	$$p^{\lambda} +q^{\lambda} \geq p^{\lambda} \geq (p+q)^{\lambda}.$$

	Now, suppose $\lambda\geq 0$. If $\lambda=0$, then subadditivity is trivial. Hence, assume $\lambda>0$. Note that the function $f(x) = x^{\lambda}$ is concave for $\lambda \in (0,1]$ and convex for $\lambda\geq 1$. In addition, $f(0) = 0$ for all $\lambda>0$. To conclude the proof, note that since $f(0)=0$, a concave $f$ implies 
	\begin{align*}
		f(p) &= f\left(\frac{p}{p+q}(p+q)\right)\geq \frac{p}{p+q} f(p+q), \text{ and }\\
		f(q) &= f\left(\frac{q}{p+q}(p+q)\right)\geq \frac{q}{p+q} f(p+q).
	\end{align*}
	Hence, $f(p)+f(q)\geq f(p+q)$. Similarly, since $f(0)=0$, a convex $f$ implies superadditivity.

	\subsection*{Proof of Proposition \ref{prop:GST}}

	The necessity of Regularity follows from the representation in equation \ref{eq:GST} and the assumption that $s(E_i)>0$ for all nonempty $E_i\subseteq \Omega$. The necessity of Cyclical Independence follows from the exposition in the main text.

	For sufficiency, we first construct a support function $s(\cdot)$ and then show that it is well-defined. To this end, pick $\omega^*\in \Omega$ and let $s(\{\omega^*\})=1$. For a nonempty $A\subsetneq \Omega$, we can always find a collection of partitions $\mathcal{P}_1, \mathcal{P}_2, \ldots, \mathcal{P}_n$ and a collection of events $E_1,E_2,\ldots, E_{n+1}$ such that $E_1=\{\omega^*\}\in \mathcal{P}_1$, $E_{n+1}=A\in \mathcal{P}_n$, and $E_{i+1}\in \mathcal{P}_i\cap \mathcal{P}_{i+1}$ for $i< n$. We can then define $s(A)$ by
	$$s(A) = \frac{\mu_{\mathcal{P}_n}(E_{n+1})}{\mu_{\mathcal{P}_n}(E_{n})}\frac{\mu_{\mathcal{P}_{n-1}}(E_{n})}{\mu_{\mathcal{P}_{n-1}}(E_{n-1})}\cdots \frac{\mu_{\mathcal{P}_1}(E_2)}{\mu_{\mathcal{P}_1}(E_1)}.$$
	In fact, we can construct $s(A)$ with $n\leq 2$, as illustrated in the main text.

	We need to show that $s(A)$ is well-defined. Suppose there exists another collection of partitions $\mathcal{P}'_1, \mathcal{P}'_2, \ldots, \mathcal{P}'_m$ and events $E'_1,E'_2,\ldots, E'_{m+1}$ such that $E_1=\{\omega^*\}$, $E_{m+1}=A$, and $E'_{i+1}\in \mathcal{P}'_i\cap \mathcal{P}'_{i+1}$ for $i<m$. Construct a new collection of partitions $\mathcal{P}''_1, \mathcal{P}''_2, \ldots, \mathcal{P}''_n, \mathcal{P}''_{n+1},\ldots,  \mathcal{P}''_{n+m}$ and events $E''_1, E''_2, \ldots, E''_n, E''_{n+1},\ldots, E''_{n+m}$ by
	$$
	\begin{minipage}{.5\textwidth}
		\[
		\mathcal{P}''_i =
		\begin{cases}
			\mathcal{P}_{n-i+1}, & 1 \le i \le n,\\
			\mathcal{P}'_{i-n},  & n < i \le n+m,
		\end{cases}
		\]
	\end{minipage}%
	\begin{minipage}{.5\textwidth}
		\[
		E''_i =
		\begin{cases}
			E_{n-i+2}, & 1 \le i \le n,\\
			E'_{i-n},  & n< i \le n+m.
		\end{cases}
		\]
	\end{minipage}
	$$
	Notice that $E''_1=A=E_{n+1}=E'_{m+1}$ and $E''_{n+1}=\{\omega^*\}$. In addition, $E''_{j+1}\in \mathcal{P}''_j\cap  \mathcal{P}''_{j+1}$ for $j<n+m$ and $E''_1 \in \mathcal{P}''_{1}\cap \mathcal{P}''_{n+m}$. By Cyclical Independence,

	\begin{align*}
		1  & = \frac{\mu_{\mathcal{P}''_1}(E''_1)}{\mu_{\mathcal{P}''_1}(E''_2)}\frac{\mu_{\mathcal{P}''_2}(E''_2)}{\mu_{\mathcal{P}''_2}(E''_3)}\cdots \frac{\mu_{\mathcal{P}''_n}(E''_n)}{\mu_{\mathcal{P}''_n}(E''_{n+1})}\cdot  \frac{\mu_{\mathcal{P}''_{n+1}}(E''_{n+1})}{\mu_{\mathcal{P}''_{n+1}}(E''_{n+2})} \cdots \frac{\mu_{\mathcal{P}''_{n+m}}(E''_{n+m})}{\mu_{\mathcal{P}''_{n+m}}(E''_1)} \\
		& =	\frac{\mu_{\mathcal{P}_n}(E_{n+1})}{\mu_{\mathcal{P}_n}(E_n)}\frac{\mu_{\mathcal{P}_{n-1}}(E_{n})}{\mu_{\mathcal{P}_{n-1}}(E_{n-1})}\cdots \frac{\mu_{\mathcal{P}_1}(E_2)}{\mu_{\mathcal{P}_1}(E_1)}\cdot 
		\frac{\mu_{\mathcal{P}'_1}(E'_1)}{\mu_{\mathcal{P}'_1}(E'_2)}\frac{\mu_{\mathcal{P}'_2}(E'_2)}{\mu_{\mathcal{P}'_2}(E'_3)}\cdots \frac{\mu_{\mathcal{P}'_m}(E'_m)}{\mu_{\mathcal{P}'_m}(E'_{m+1})}\\
		& = s(A)\cdot  \frac{\mu_{\mathcal{P}'_1}(E'_1)}{\mu_{\mathcal{P}'_1}(E'_2)}\frac{\mu_{\mathcal{P}'_2}(E'_2)}{\mu_{\mathcal{P}'_2}(E'_3)}\cdots \frac{\mu_{\mathcal{P}'_m}(E'_m)}{\mu_{\mathcal{P}'_m}(E'_{m+1})},
	\end{align*}
	which implies 
		$$s(A) = \frac{\mu_{\mathcal{P}'_m}(E'_{m+1})}{\mu_{\mathcal{P}'_m}(E'_m)}\frac{\mu_{\mathcal{P}'_{m-1}}(E'_m)}{\mu_{\mathcal{P}'_{m-1}}(E'_{m-1})}\cdots \frac{\mu_{\mathcal{P}'_1}(E'_2)}{\mu_{\mathcal{P}'_1}(E'_1)}.$$
	Hence, $s(A)$ is well-defined for all nonempty $A\subseteq \Omega$, and, by Regularity, $s(A)>0$.

	To conclude the proof of the representation, we need to show that $\mu_{\mathcal{P}}(\cdot)$ is consistent with the GST model with this choice of support function. Let $\mathcal{P}\in \mathbb{P}$ and $A\in \mathcal{P}$ be given. If $A=\Omega$ and $\mathcal{P}=\{\Omega\}$, there is nothing to show. Alternatively, let $B\in \mathcal{P}$ be distinct from $A$. Then, we can construct a collection of partitions $\mathcal{P}_1, \mathcal{P}_2, \ldots, \mathcal{P}_n$ with $\mathcal{P}_n=\mathcal{P}$ and a collection of events $E_1,E_2,\ldots, E_n, E_{n+1}$ such that $E_1=\{\omega^*\}$, $E_n=A$, $E_{n+1}=B$,  and $E_{i+1}\in \mathcal{P}_i\cap \mathcal{P}_{i+1}$ for $i<n$. Using the definition of $s(\cdot)$,
	\begin{align*}
		s(B) = \frac{\mu_{\mathcal{P}_n}(E_{n+1})}{\mu_{\mathcal{P}_n}(E_n)}\frac{\mu_{\mathcal{P}_{n-1}}(E_n)}{\mu_{\mathcal{P}_{n-1}}(E_{n-1})}\cdots \frac{\mu_{\mathcal{P}_1}(E_2)}{\mu_{\mathcal{P}_1}(E_1)}
		= \frac{\mu_{\mathcal{P}}(B)}{\mu_{\mathcal{P}}(A)} s(A).
	\end{align*}
	Adding over $B\in \mathcal{P}$,
		\begin{align*}
		\sum_{B\in \mathcal{P}} s(B) = \frac{\sum_{B\in \mathcal{P}}\mu_{\mathcal{P}}(B)}{\mu_{\mathcal{P}}(A)} s(A) = \frac{s(A)}{\mu_{\mathcal{P}}(A)},
	\end{align*}
	where $\sum_{B\in \mathcal{P}}\mu_{\mathcal{P}}(B)=1$ due to Regularity. Hence,
	$$\mu_{\mathcal{P}}(A)= \frac{s(A)}{\sum_{B\in \mathcal{P}} s(B)}.$$
	Since this is true for any $\mathcal{P}\in \mathbb{P}$ and $A\in \mathcal{P}$, the representation follows. For uniqueness, note that once we fix $s(\{\omega^*\})$, $s(\cdot)$ is uniquely defined for all other proper events. 

	\subsection*{Proof of Proposition \ref{prop:ERBR}}

	The necessity of Power Additivity is described in the main text. For sufficiency, note that we already have the GST representation 
	$$\mu_{\mathcal{P}}(A)= \frac{s(A)}{\sum_{B\in \mathcal{P}} s(B)}.$$
	Since $s(\cdot)^{\alpha}$ is additive for some $\alpha\neq 0$, we can let 
	$$\pi(\omega) = \frac{s(\{\omega\})^{\alpha}}{\sum_{\omega'\in \Omega}s(\{\omega'\})^{\alpha}}.$$
	Note that $\pi(\omega)>0$ and $\sum_{\omega\in \Omega}\pi(\omega)=1$, and hence $\pi(\cdot)$ is a full support probability measure. In addition, for $A\subsetneq \Omega$,
	$$\pi(A) = \sum_{\omega\in A} \pi(\omega) 
	=  \frac{\sum_{\omega\in A} s(\{\omega\})^{\alpha}}{\sum_{\omega'\in \Omega}s(\{\omega'\})^{\alpha}} 
	= \frac{ s(A)^{\alpha}}{\sum_{\omega'\in \Omega}s(\{\omega'\})^{\alpha}},$$
	where the last equation is due to Power Additivity. Therefore, 
	$$\pi(A)^{1/\alpha} =  \frac{ s(A)}{\left(\sum_{\omega'\in \Omega}s(\{\omega'\})^{\alpha}\right)^{1/\alpha}} \quad \Rightarrow \quad s(A) = \pi(A)^{1/\alpha} \left(\sum_{\omega'\in \Omega}s(\{\omega'\})^{\alpha}\right)^{1/\alpha} $$
	Combining the previous expressions, 
	\begin{align*}
		\mu_{\mathcal{P}}(A)= \frac{s(A)}{\sum_{B\in \mathcal{P}} s(B)} 
		= \frac{\pi(A)^{1/\alpha} \left(\sum_{\omega'\in \Omega}s(\{\omega'\})^{\alpha}\right)^{1/\alpha}}{ \sum_{B\in \mathcal{P}}\pi(B)^{1/\alpha} \left(\sum_{\omega'\in \Omega}s(\{\omega'\})^{\alpha}\right)^{1/\alpha}} = \frac{\pi(A)^{1/\alpha}}{ \sum_{B\in \mathcal{P}}\pi(B)^{1/\alpha}}.
	\end{align*}
	Hence, letting $\lambda = 1/\alpha$ yields the ERBR representation. 

	For uniqueness, if $\{\mu_{\mathcal{P}}\}_{\mathcal{P}\in \mathbb{P}}$ is always uniform, we can reveal that $\lambda=0$ but the benchmark prior $\pi$ cannot be revealed. If $\{\mu_{\mathcal{P}}\}_{\mathcal{P}\in \mathbb{P}}$ is not always uniform, then the support function $s(\cdot)$ derived from $\{\mu_{\mathcal{P}}\}_{\mathcal{P}\in \mathbb{P}}$ will not be constant and there will be a unique $\alpha$ satisfying Axiom \ref{axiom:additivity}. Letting $\lambda=1/\alpha$ and defining $\pi$ as above uniquely reveals both in this case.

	\subsection*{Proof of Proposition \ref{prop:conjunction}}

	We have 
	$$\mu_{\mathcal{P}_B}(B)
	=\frac{\pi(B)^{\lambda_{\mathcal{P}_B}}}
	{\pi(B)^{\lambda_{\mathcal{P}_B}} + (1-\pi(B))^{\lambda_{\mathcal{P}_B}}}
	\quad \text{and} \quad 
	\mu_{\mathcal{P}_C}(C)
	=\frac{\pi(C)^{\lambda_{\mathcal{P}_C}}}
	{\pi(C)^{\lambda_{\mathcal{P}_C}} + (1-\pi(C))^{\lambda_{\mathcal{P}_C}}}.$$
	Hence,
	$$\mu_{\mathcal{P}_B}(B)>\mu_{\mathcal{P}_C}(C)
	\quad\Longleftrightarrow\quad
	\frac{\pi(B)^{\lambda_{\mathcal{P}_B}}}
	{\pi(B)^{\lambda_{\mathcal{P}_B}} + (1-\pi(B))^{\lambda_{\mathcal{P}_B}}}
	>
	\frac{\pi(C)^{\lambda_{\mathcal{P}_C}}}
	{\pi(C)^{\lambda_{\mathcal{P}_C}} + (1-\pi(C))^{\lambda_{\mathcal{P}_C}}}.$$
	Since the denominators are positive, cross-multiplying, we get
	$$\pi(B)^{\lambda_{\mathcal{P}_B}}
	\left(\pi(C)^{\lambda_{\mathcal{P}_C}} + (1-\pi(C))^{\lambda_{\mathcal{P}_C}}\right)
	>
	\pi(C)^{\lambda_{\mathcal{P}_C}}
	\left(\pi(B)^{\lambda_{\mathcal{P}_B}} + (1-\pi(B))^{\lambda_{\mathcal{P}_B}}\right).$$
	Expanding and canceling the common term $\pi(B)^{\lambda_{\mathcal{P}_B}}\pi(C)^{\lambda_{\mathcal{P}_C}}$ yields
	$$\pi(B)^{\lambda_{\mathcal{P}_B}} (1-\pi(C))^{\lambda_{\mathcal{P}_C}}
	>
	\pi(C)^{\lambda_{\mathcal{P}_C}} (1-\pi(B))^{\lambda_{\mathcal{P}_B}}.$$
	Dividing both sides by $(1-\pi(B))^{\lambda_{\mathcal{P}_B}}\,(1-\pi(C))^{\lambda_{\mathcal{P}_C}}$, we get
	$$\left(\frac{\pi(B)}{1-\pi(B)}\right)^{\lambda_{\mathcal{P}_B}}
	>
	\left(\frac{\pi(C)}{1-\pi(C)}\right)^{\lambda_{\mathcal{P}_C}}.$$
	Taking the natural logarithms on both sides, we get
	$$\lambda_{\mathcal{P}_B}\ln\left(\frac{\pi(B)}{1-\pi(B)}\right)
	>
	\lambda_{\mathcal{P}_C}\ln\left(\frac{\pi(C)}{1-\pi(C)}\right),$$
	as desired.


