\section{Supplemental Material}
 \subsection{Universality and comparison to other species}

 It has been demonstrated that the scattering property of microwave-linked identical bosonic dipolar molecules is universal in units of the chracteristic length $R_3=md^2/\hbar^2 4 \pi \epsilon_0$ and energy $E_3=\hbar^2/mR_3^2$ scales of the dipole-dipole interaction \cite{Dutta:2025}. The validity range of this universality is expected to extend to two-component fermionic molecules, since in both cases the collisions occur on the same $V^{++}(r,\theta,\phi)$ potential surface via the $s$-wave. We confirm the generalisation of this universality by comparing the scattering length of $^{23}$Na$^{40}$K in unlike spin states to that of $^{23}$Na$^{87}$Rb in identical spin states, scaled by $R_3$ and plotted against $\hbar\Omega/E_3$, as is shown in Fig.~\ref{fig:uni}. This establishes that the derived analytical expressions [Eqs.~\eqref{eq:flro} and \eqref{eq:flrd}] are generally applicable to other two-component fermionic as well as identical bosonic dipolar gases. Notably, they can serve as an easy tool for estimating the interaction strength and weakly bound state (when incorporated with Eq.~\ref{eq:Ebexpan}) in microwave field-dressed dipolar molecular gases. 

\subsection{Scaling formulas for $\Omega_{\rm{r}_i}$ and $\bar{\Delta}_i$}

Although multi-channel scattering induces appreciable shifts, the characteristic scales of field-linked resonances (FLRs) can be extracted by restricting the analysis to the $s$-wave channel of the incoming $|{++}\rangle$ state. The interaction is, to a good approximation, captured by the effective potential ~\cite{Deng:2023}:  
\begin{equation}
\begin{split}
    &V_{\rm eff}(\mathbf r)=\frac{\sqrt{4\pi}\,A}{r^{3}}Y_{2,0}(\theta,\phi) \\
    &~+\frac{\sqrt{4\pi}\,B}{r^{6}}\!\left[7Y_{0,0}(\theta,\phi)-\frac{Y_{2,0}(\theta,\phi)}{\sqrt5}-\frac{2Y_{4,0}(\theta,\phi)}{3}\right],
\end{split}
\end{equation}
with couplings
\begin{align}
    A&=\sqrt{\frac15}\,\frac{d^{2}}{24\pi\epsilon_{0}}\left[1+\left(\frac{|\delta|}{\Omega}\right)^{2}\right]^{-1}, \label{C4taoshi}\\
    B&=\frac{d^{4}}{1120\pi^{2}\epsilon_{0}^{2}\Omega}\left[1+\left(\frac{|\delta|}{\Omega}\right)^{2}\right]^{-3/2}.
    \label{eq:C6taoshi}
\end{align}

Projecting $V_{\rm eff}$ onto the $s$-wave subspace,
we found that only the $1/r^{6}$ term survives at the leading order $\langle 00|V_{\rm eff}|00\rangle$. However, the $1/r^{3}$ term can contribute at the second order via the coupling of $s$ and $d$ channels, $\langle 00|V_{\rm eff}|20\rangle\langle 20|V_{\rm eff}|00\rangle/V_{\rm cen}$, resulting in a $1/r^4$ interaction \cite{Karman:2018pra}. This leads to the effective $s$-wave potential
\begin{equation}
    V^{\rm eff}_{00}(r)\approx \frac{7B}{r^{6}}-\frac{C_4}{r^{4}},
    \label{eq:potential_tao_shi}
\end{equation}
with $C_4=mA^2/6\hbar^2=d^4m/[\hbar^2 1080(4\pi \epsilon_0)^2(1+(\delta/\Omega)^2)^2$, from which we define the long-range chracteristic length 
\begin{equation}
R_{4}=d^2m/[\hbar \sqrt{1080} (4\pi \epsilon_0) (1+(\delta/\Omega)^2)]
\end{equation}
and energy
\begin{equation}
E_{4}=1080(4\pi \epsilon_0)^2[1+(\delta/\Omega)^2]^2\hbar^{4}/(m^2d^4)
\end{equation}
scales. As the scattering properties of the molecules are largely determined by the long-range $-C_4/r^{4}$ interaction, one expects that $\Omega_{\rm r_i} \propto E_4$ and $\bar{\Delta}_i \propto R_4 E_4$ according to dimensional analysis, indicating $\Omega_{\rm r_i}\propto [1+(\delta/\Omega)^2]^2$ and $\bar{\Delta}_i \propto 1+(\delta/\Omega)^2$. At short and intermediate range, additional interactions such as the $7B/r^{6}$ term become significant, modifying the overall scaling of the dominant $-C_4/r^{4}$ potential. To describe such modification, we introduce a correction parameter $\lambda_{\Omega_{\rm r}}$  
\begin{equation}
\Omega_{\rm r_i}\propto [1+\lambda_{\Omega_{\rm r}}(\delta/\Omega)^2]^2
\end{equation}
for $\Omega_{\rm r_i}$, and $\lambda_{\Delta}$
\begin{equation}
\bar{\Delta}_i \propto 1+\lambda_{\Delta}(\delta/\Omega)^2
\end{equation}
for $\bar{\Delta}_i$. 

In the following, we derive the short-range correction parameters according to the effective $s$-wave interaction potential \ref{eq:potential_tao_shi}, using the first FLR as an example.
We render dimensionless with
$R_{4}$,
$E_{4}$ and
$\chi=7B/(R_{4}^{6}E_{4})$,
yielding the radial Schrödinger equation
\begin{equation}
    \left[-\frac{{\rm d}^{2}}{{\rm d}r^{2}}-\frac1{r^{4}}+\frac{\chi}{r^{6}}\right]\psi(r)=\epsilon\,\psi(r).
\end{equation}


  \begin{figure}
     \centering
     \includegraphics[width=1.0\linewidth]{Uni.pdf}
     \caption{Comparison of real $\alpha_s$ (a) and imaginary $\beta_s$ (b) part of the scattering length in two-component $^{23}$Na$^{40}$K and single-component $^{23}$Na$^{87}$Rb gases. The detuning $\delta$ is considered to be zero. }
     \label{fig:uni}
 \end{figure}


The log-derivative calculation show the first FLR occurs at
$\chi=\chi_{1}=0.11$, giving
\begin{eqnarray}\label{eq:resonance_tao_shi}
    \Omega_{\rm{r}_1}&=&\frac{1}{0.11}\,
    \frac{1866240\,\pi^{2}\epsilon_{0}^{2}\hbar^{6}}{5d^{4}m^{3}} \\ \notag
    &\times&\left\{1+\frac{5}{2}\left(\frac{|\delta|}{\Omega}\right)^{2}+\frac{15}{8}\left(\frac{|\delta|}{\Omega}\right)^{4}+O\left[\left(\frac{|\delta|}{\Omega}\right)^{6}\right]\right\}. \\ \notag
    &\approx&\frac{1}{0.11}\,
    \frac{1866240\,\pi^{2}\epsilon_{0}^{2}\hbar^{6}}{5d^{4}m^{3}}\left[1+\lambda_{\Omega_{\rm r}}\left(\frac{|\delta|}{\Omega}\right)^{2}\right]^2
\end{eqnarray}
with $\lambda_{\Omega_{\rm r}}=1.25$. The estimated $\lambda_{\Omega_{\rm r}}=1.25$ is in good agreement with our numerical result $\lambda_{\Omega_{\rm r}}=1.22$.
Near resonance the $s$-wave scattering length exhibits a simple pole,
\begin{equation}
    \frac{\alpha}{R_{4}}\simeq\frac{\alpha_{\mathrm{bg}}}{R_{4}}+
    \frac{\Delta\chi_{i}}{\chi-\chi_{i}},
\end{equation}
where $\Delta\chi_{i}$ is obtained numerically (e.g.\ via log-derivative analysis).
Re-expressing in terms of $\Omega$ gives
\begin{equation}
    \alpha
    =\left(\alpha_{\mathrm{bg}}-\frac{\Delta\chi_{1}}{0.11}\right)R_{4}
    -\frac{\overbrace{(\Delta\chi_{1}/0.11)\Omega_{\rm{r}_1}R_{4}}^{=\bar{\Delta}_1}}{\Omega-\Omega_{\rm{r}_1}}
\end{equation}
for the first FLR. The corresponding effective width reads
\begin{equation}
   \bar{\Delta}_{1}\approx\frac{\Delta\chi_{1}}{0.11}\,
    \frac{2592\sqrt{30}\,\pi\epsilon_{0}\hbar^{3}}{d^{2}m^{2}\Omega_{\rm{r}_i}}
    \left[1+\lambda_{\Delta}\left(\frac{|\delta|}{\Omega}\right)^{2}\right].
    \label{eq:width_tao_shi}
\end{equation}
with $\lambda_{\Delta}=1.5$, which also agree well with our numerical result $\lambda_{\Delta}=1.41$. For higher FLRs, the decrease of $B$ with increasing $\Omega$ in Eq. (\ref{eq:potential_tao_shi}) implies that the short-range correction will become less significant at higher $\Omega$. Consistently, our numerical result shows $\lambda_{\Omega_i} \approx \lambda_{\Delta_i} \approx 1$ for the second FLR.

Equations~\eqref{eq:resonance_tao_shi} and \eqref{eq:width_tao_shi} are valid only in the long-range regime
$r^{3}>d^{2}/(4\pi\epsilon_{0}\hbar\Omega)$ assumed in Ref.~\cite{Deng:2023} within our perturbative approach. In reality,  additional terms enter the effective potential, which may explain the small deviations of the numerical value of $\lambda_{\Omega_{\rm r}}$ and $\lambda_{\Delta}$ from our estimations. 

