% The decrease of $B$ with increasing $\Omega$ implies that the short-range correction will become less significant at higher $\Omega$.

% Table I of the main text demonstrates that, indeed, for the first FLR the pseudo-potential of Ref.~\cite{Deng:2023} is accurate, and values of $\lambda_{\Omega_i}$ and $\Delta_i$ are in very good agreement with Eq.~\eqref{eq:resonance_tao_shi} and \eqref{eq:width_tao_shi}. On the other side, when the system is tuned to the second FLR the scattering resonance obeys a pure $R_4$, $E_4$ scaling as $\lambda_{\Omega_i} \approx \lambda_{\Delta_i} \approx 1$.
\subsection{Derivation of the expansion formula for $E_b$}
 \begin{table*}[]
    \centering
     \caption{The fitting parameters of the first and second FLRs at $|\delta|/\Omega=0$.}
    \begin{tabular}{cccccccc}
    \hline
    \hline
       &scan range&$\alpha_{s\rm bg}$&$b$&$\Omega_{\rm r_1}/2\pi$&$\bar{\Delta}_1/2\pi$&$\Omega_{\rm r_2}/2\pi$&$\bar{\Delta}_2/2\pi$\\
       model&[$2\pi$MHz]&[$a_0$]&[$a_0$/MHz]&[MHz]&[$10^5a_0$MHz]&[MHz]&[$10^5a_0$MHz] \\
       (i)&[0,100]&2352&-35.37&20.97&1.027&-&-  \\
       (ii)&[0,800]&1584&-&20.97&1.028&383.5&10.03 \\
       (iii)&[0,800]&3686&-8.373&20.97&1.027&383.5&10.04 \\
    \hline
    \hline
    \end{tabular}
    \label{tab:fit}
\end{table*}
To get the expansion formula (\ref{eq:Ebexpan}) for $E_b$, we employ the quantization function $F_4(E)$ for $1/r^4$ potential \cite{Raab:2009}:
\begin{equation}
F_4(E)=A(E)F^{\rm low}_4(E)+[1-A(E)]F_4^{\rm high}(E)+F_4^{\rm sr}(E),
\end{equation}
where $F^{\rm low}_4(E)$ and $F_4^{\rm high}(E)$ are the low-$\kappa$ and high-$\kappa$ limit forms of the quantization function of the potential tail of $-C^4/r^4$, with $\kappa=\sqrt{-mE}/\hbar$. They read as
\begin{equation}
F^{\rm low}_4(E)=\frac{R_4 \kappa}{\pi}-\frac{(d_4 \kappa)^2}{2 \pi}
\end{equation}
and 
\begin{eqnarray}
F^{\rm high}_4(E)=-\frac{1}{4}+\frac{\Gamma(3/4)(\kappa R_4)^{1/2}}{\Gamma(5/4)2\sqrt{\pi}}+\frac{D_1/2\pi}{(\kappa R_4)^{1/2}} \\ \notag
+\frac{D_3/2\pi}{(\kappa R_4)^{3/2}} +\frac{D_5/2\pi}{(\kappa R_4)^{5/2}}+\frac{D_7/2\pi}{(\kappa R_4)^{7/2}},
\end{eqnarray}
where $d_4=\sqrt{2\pi/3}R_4$ are referred to as the threshold length and effective length, respectively. The $D_j$ denote the coefficients of the $j/2$-th order term of $(1/\kappa R_4)$ in the high-order WKB approach, which is documented in Ref.~\cite{Raab:2009}. The interpolation function $A(E)$ is selected as
\begin{equation}
A(E)=\frac{1}{1+(\kappa B_6)^6+(\kappa B_7)^7},
\end{equation}
with the fitted parameters $B_6=1.622576 R_4$ and $B_7=1.338059 R_4$. The short-range quantization function $F_4^{\rm sr}$ is a smooth analytic function that vanishes at threshold $E=0$
\begin{equation}
F_4^{\rm sr}(E)=\gamma_{\rm sr} E+\gamma_{\rm sr2} E^2+O(E^3).
\end{equation}
The scattering length is related to $F_4(E=E_b)$ via \cite{Raab:2009}
\begin{equation}
\alpha_s=\frac{R_4}{\tan[F_4(E_b)\pi]}.
\end{equation}
Next, we expand $R_4/\tan[F_4(E_b)\pi]$ in terms of $\kappa$
\begin{equation}
\frac{R_4}{\tan[F_4(E_b)\pi]}=1/\kappa+c_0+c_1 \kappa+c_2 \kappa^2+\cdots,
\end{equation}
where $c_0=(d_4^2+2 \pi \gamma_{\rm sr})/2R_4$, $c_1=(-4 R_4^4 + 3 d_4^4 + 12 d_4^2 \pi \gamma_{\rm sr} + 12 \pi^2 \gamma_{\rm sr}^2)/12 R_4^2$. The parameter $\gamma_{\rm sr 2}$ enters at the order of $c_2 \kappa^2$ in the expansion, whereas the contributions from the parameters in $F^{\rm high}_4(E)$ only arise beginning at the $c_5 \kappa^5$ order. By solving
\begin{equation}
\alpha_s=1/\kappa+c_0+c_1 \kappa+c_2 \kappa^2
\end{equation}
and expanding the solution in terms of $1/\alpha_s$, we get
% \begin{equation}
% E_b=-\frac{\hbar^2}{m}\left(\frac{1}{a^2}+\frac{2c_0}{a^3}+\frac{3c_0^2+2c_1}{a^4} \\
% +\frac{4 c_0^3+8c_0c_1+2c_2}{a^5}+\cdots \right).    
% \end{equation}
\begin{align}
E_b &=-\frac{\hbar^2 \kappa^2}{m} \\
&= -\frac{\hbar^2}{m} \left( 
\frac{1}{\alpha_s^2} + \frac{2c_0}{\alpha_s^3} + \frac{3c_0^2 + 2c_1}{\alpha_s^4} \right. \notag \\
&\left. + \frac{4c_0^3 + 8c_0 c_1 + 2c_2}{\alpha_s^5} + \cdots \right)
\end{align}
This result shows that $c_2$ first appears in the $E_b$ at the order of $1/\alpha_s^5$. In principle, one can truncate the expansion of $E_b$ at this order to exclude the contribution of $c_2$, thereby eliminating all terms involving $\gamma_{\rm sr 2}$. In practice, we truncate at the order of $1/\alpha_s^4$ and get
\begin{equation}
E_b=-\frac{\hbar^2}{m}\left[\frac{1}{\alpha_s^2}+\frac{b_2}{R_4}\frac{1}{\alpha_s^3}+\mathcal{O}\left(\frac{1}{\alpha_s^4}\right)\right]
\end{equation}
with $b_2=d_4^2+2\pi \gamma_{\rm sr}$, which is the Eq.~\eqref{eq:Ebexpan} in the main text. We note that the same expansion can be obtained in this order by applying the quantum defect theory to the analytical solution of the $-C_4/r^4$ potential \cite{Gao:2013}.
\subsection{Details of numerical simulation}
In our numerical simulation, we propagate the log-derivative matrix $\mathbf{Y}$ from an initial radius of $r_{\rm in}= 15$ $a_0$ to a final radius $r_{\rm out}= 2000$ $R_4$, where $R_4$ depends on microwave field parameters. Here, $a_0$ denotes the Bohr radius. At $r_{\rm in}$, the full absorbing boundary condition is applied by setting the diagonal element $Y_{\nu_{\rm s}lm_l,\nu_{\rm s}lm_l}(r_{\rm in})=-ik_{\nu_{\rm s}lm_l}(r_{\rm in})$ while the off-diagonal elements of $\mathbf{Y}$ are set to zero \cite{Wang:2015}. Here, $k_{\nu_{\rm s}lm_l}(r_{\rm in})=\sqrt{E-V_{lm}^{\nu_{\rm s}}(r_{\rm in})}$ denotes the local wave number associated with the adiabatic channel $|\nu_{\rm s}lm_l\rangle$. We note that the inclusion of van-der-Waals interaction leads to $V_{lm}^{\nu_{\rm s}}(r_{\rm in})<E$ for all $|\nu_{\rm s}lm_l\rangle$ when $r_{\rm in}<15$ $a_0$. We found the van-der-Waals interaction plays a negligible role in the scattering process initialized in the $|\nu_{\rm s}^{\rm in}={++}\rangle$ state. However, for molecules prepared in certain other $|\nu_{\rm s}\rangle$ or $|\nu_{\rm a}\rangle$ states, the inclusion of the van-der-Waals interaction can be crucial. In the case of circular polarization without ellipticity $\xi=0$, we truncate the partial wave basis at $l<10$, which is sufficient for numerical convergence. Nevertheless, we find that truncation is generally required at $l<20$ when $\xi \neq 0$. 
\subsection{The FLR fit}
To extract the FLR parameters at a given $|\delta|/\Omega$, we fit the numerical obtained $\alpha_s$ using the following model: (i) $\alpha_s=\alpha_{s\rm bg}+\bar{\Delta}_1/(\Omega-\Omega_{\rm r_1})+b\Omega$ applied over the scan range $\Omega \in 2\pi \times [0,100]$ MHz; (ii) $\alpha_s=\alpha_{s\rm bg}+\bar{\Delta}_1/(\Omega-\Omega_{\rm r_1})+\bar{\Delta}_2/(\Omega-\Omega_{\rm r_2})$ applied over the extended scan range $\Omega \in 2\pi \times [0,800]$ MHz; and (iii) $\alpha_s=\alpha_{s\rm bg}+\bar{\Delta}_1/(\Omega-\Omega_{\rm r_1})+\bar{\Delta}_2/(\Omega-\Omega_{\rm r_2})+b\Omega$ applied also over $\Omega \in 2\pi \times [0,800]$ MHz. The fitted parameters for $|\delta|/\Omega=0$ are listed in Table \ref{tab:fit}. We found that the background scattering length $\alpha_{s\rm bg}$ and linear coefficient $b$ depend strongly on the scan range and the model. However, the resonance positions ($\Omega_{\rm r_1}$ and $\Omega_{\rm r_2}$ ) and effective width ($\bar{\Delta}_1$ and $\bar{\Delta}_2$) remain nearly unchanged across different fittings.
\end{document}

