\subsection{Matter Bispectrum}
The expression of the tree-level matter bispectrum in Eulerian perturbation theory, for an Einstein de-Sitter Universe \citep{1984ApJ...279..499F}
\begin{equation}
    B_\mathrm{TL}(k_1,k_2,k_3) = 2F_2(k_1,k_2,k_3)P_{L}(k_1)P_{L}(k_2)+2\,\mathrm{cyc.}\label{eq:bt}
\end{equation}
where we did not write explicitly the permutations between modes and where the  $F_2$ kernel is given by \citep{1984ApJ...279..499F,Goroff:1986ep}\footnote{See Chapter 12 of \cite{dodelson2020modern} for a presentation of second-order cosmological perturbation theory and \cite{bernardeau2002} for further details.}
\begin{equation}
    F_2(k_1,k_2,k_3)=F_2(\mathbf{k}_1,\mathbf{k}_2)=\frac{5}{7}+\frac{1}{2}\cos\theta_{12}\left(\frac{k_1}{k_2}+\frac{k_2}{k_1}\right)+\frac{2}{7}(\cos\theta_{12})^2\quad\mathrm{with}\quad \cos\theta_{12}=\frac{\mathbf{k}_1\cdot\mathbf{k}_2}{k_1 k_2}=\frac{k_3^2-k_2^2-k_1^2}{2k_1 k_2}\label{eq:f2s}.
\end{equation}
(This is the expression as implemented in \verb|class_sz|, which takes the three wavenumber moduli as an input.) The \cite{Gil_Mar_n_2012} bispectrum fitting formula has the same form as Eq.~\eqref{eq:bt}, except that the linear matter power spectrum is replaced by its non-linear counterpart and that it includes extra scale- and redshift-dependent coefficients in front of the terms in the expression of the $F_2$ kernel. There are nine parameters that control the scale and redshift dependence of those coefficients, whose values are found by fitting the data from $N$-body simulations. Thus, the non-linear matter bispectrum is written as
 \begin{equation}
    B_{\mathrm{eff}}^{NL}(k_1,k_2,k_3) = 2F_2^\mathrm{eff}(k_1,k_2,k_3)P_{NL}(k_1)P_{NL}(k_2)+2\,\mathrm{cyc}.\label{eq:b_gilma}
\end{equation}
For $F_2^\mathrm{eff}$ we implemented the \cite{Scoccimarro:2000ee} and \cite{Gil_Mar_n_2012} formulas and fitting parameters.  The main difference between these formulas is that the \cite{Gil_Mar_n_2012} formula corrects the unphysical oscillations associated with the BAOs in the power spectrum which are visible in the \cite{Scoccimarro:2000ee} prediction \citep[see, e.g.,][for details]{Gil_Mar_n_2012}. On large scales, both formulas match with the tree-level bispectrum of Eq.~\eqref{eq:bt}. Note that the \cite{Gil_Mar_n_2012} formula is calibrated on a fairly restricted $k$- and $z$-range, namely:  $0.03\,h/\mathrm{Mpc}\leq k \leq 0.4 h/\mathrm{Mpc}$, and $0\leq z\leq 1.5$. Recent  matter bispectrum fitting formulas have been derived by \cite{Takahashi_2020} on a broader $k$- and $z$-range ($k\lesssim 3 h/\mathrm{Mpc}$ and $z<3$) but we do not discuss them here as they have not been used in the context of the kSZ effect. 


The \cite{Scoccimarro:2000ee} formula reads
\begin{eqnarray}
    F_2^\mathrm{eff}(\mathbf{k}_i,\mathbf{k}_j) & = &\frac{5}{7}a(n_i,k_i)a(n_j,k_j)\nonumber\\
                     & +&\frac{1}{2}\cos (\theta_{ij})\left(\frac{k_i}{k_j}+\frac{k_j}{k_i}\right)b(n_i,k_i)b(n_j,k_j)+\frac{2}{7}\cos^2 (\theta_{ij})c(n_i,k_i)c(n_j,k_j)\label{eq:socci}
\end{eqnarray}
where 
\begin{eqnarray}
 \nonumber \label{abc} a(n,k)&=&\frac{1+\sigma_8^{a_6}(z)[0.7Q_3(n)]^{1/2}(q a_1)^{n+a_2}}{1+(q a_1)^{n+a_2}}, \\
 b(n,k)&=&\frac{1+0.2a_3(n+3)q^{n+3}}{1+q^{n+3.5}}, \\
\nonumber c(n,k)&=&\frac{1+4.5a_4/[1.5+(n+3)^4](q a_5)^{n+3}}{1+(q a_5)^{n+3.5}}.
\end{eqnarray}
where 
\begin{equation}
n \equiv \frac{d\log P_L(k)}{d\log k}    
\end{equation}
is the slope of the linear matter power spectrum at $k$. To accelerate calculations, we pre-tabulate $n$ on a $(z,k)$-grid, which we then interpolate when necessary. 
Note that since BAO is present in $P_L(k)$ it creates oscillations in n(k). In the \cite{Scoccimarro:2000ee} approach, these oscillations are kept.

And 
\begin{equation}
    Q_3(n) = \frac{4-2^n}{1+2^{n+1}}
\end{equation}
and 
\begin{equation}
q = \frac{k}{k_{NL}}\quad\mathrm{with}\quad k_{NL}\quad
     \mathrm{such}\,\,\mathrm{that}\quad \frac{k_{NL}^3P_L(k_{NL})}{2\pi^2} = 1
\end{equation}
where the coefficients are
\begin{equation}
\nonumber a_1=0.25,\, a_2=3.5,\, a_3=2,\,  a_4=1,\, a_5=2,\, a_6=-0.2 \,.
\end{equation}

