\subsubsection{Cosmic Infrared Background}\label{sss:cib}

\begin{figure*}
    \includegraphics[width=1.\columnwidth]{CIB_monopole_Shang2012_and_Maniyar2021.pdf}
    \vspace{-0.2cm}
