    \label{fig:CIBmonopole}
\end{figure*}

{\bf{Shang et al. CIB model.}} We give the halo model description of the CIB emission, which is based on the model presented in \cite{Shang2012}, which was further used in many other analyses, including \cite{Viero_2013_hermes, websky_Stein_2020, McCarthy:2021lfp, Sabyr_2022}. Following \cite{Shang2012}, we can define the CIB in the halo model analogously to the galaxy HOD, but with additional prescriptions that describe the infrared emission of each galaxy.

First, we can write the specific intensity of the CIB $I_{\nu}$ at frequency $\nu$ as 
\begin{equation}
    I_{\nu} = \int \frac{\mathrm{d} \chi}{\mathrm{d}z} a(z) \bar{j}_\nu(z) \mathrm{d}z \,, 
\end{equation}
where $\bar{j}_\nu(z)$ is the average emissivity~(\textit{e.g.},~\cite{McCarthy:2021lfp}): 
\begin{equation}
    \bar{j}_\nu(z) = \int_{}^{} \mathrm{d}M \frac{\mathrm{d}n}{\mathrm{d}M} \frac{L_{(1+z)\nu}(M,z)}{4\pi} \,, 
    \label{eq:j_nu}
\end{equation}
where $L_{(1+z)\nu}(M,z)$ is the infrared luminosity of a halo of mass $M$ at redshift $z$ and the factor of $(1+z)$ in the frequency accounts for redshifting of the emitted radiation. 

The luminosity $L_{(1+z)\nu}(M,z)$ is the sum of the contributions from the central and satellite galaxies, defined by $L_{(1+z)\nu}^{c}(M,z)$ and $L_{(1+z)\nu}^{s}(M,z)$, respectively. In this work, we follow the assumption made in \cite{McCarthy:2021lfp} that both the central and satellite luminosity depend on the same galaxy luminosity model $L^{\rm{gal}}_{(1+z)\nu} (M,z)$ (which is only dependent on the mass of the host halo $M$ and redshift $z$), weighted by the number of centrals and satellites, respectively. Thus, the central luminosity, $L_{(1+z)\nu}^{c}(M,z)$ can be defined as
 \begin{equation}
     L_{(1+z)\nu}^{c}(M,z) = N_{c}^{\rm{CIB}} (M,z) L^{\rm{gal}}_{(1+z)\nu} (M,z) \,,
     \label{eq:L_cent}
 \end{equation}
where the number of CIB central galaxies in a halo, $N_{c}^{\rm{CIB}}$, similarly to the galaxy HOD, is either zero or one, depending on whether the halo mass $M$ is smaller or larger than the parameter $M_{\rm{min}}^{\rm{CIB}}$, the minimum mass to host a central galaxy that sources CIB emission. This requirement can be  written as
\begin{equation}
    N_{c}^{\rm{CIB}} (M,z) = 
    \begin{cases}
      0, & \text{if}\ M < M_{\rm{min}}^{\rm{CIB}} \\
      1, &  \text{if}\ M \geq M_{\rm{min}}^{\rm{CIB}} \,.
    \end{cases}
\end{equation}
The satellite luminosity, $L_{(1+z)\nu}^{s}(M,z)$, that is, the luminosity of a halo due to its satellite galaxies, is given by
\begin{equation}
    L_{(1+z)\nu}^{s}(M,z) = \int \mathrm{d} M_s \frac{\mathrm{d} N}{\mathrm{d} M_s}  L^{\rm{gal}}_{(1+z)\nu} (M,z) \,,
    \label{eq:L_sat}
\end{equation}
where $\mathrm{d} N/\mathrm{d} M_s$ is the subhalo mass function. For the subhalo mass function we have implemented several formulas (see Subsection \ref{ss:subhmf}). Note that \cite{McCarthy:2020qjf} uses the \cite{2010ApJ...719...88T} formula while \cite{websky_Stein_2020} uses the \cite{Jiang:2013kza} formula.

The luminosity of galaxies $L^{\rm{gal}}_{(1+z)\nu}$ is governed by the \emph{luminosity-mass relation} (or \emph{L--M relation}), that can be written as 
\begin{equation}
    L^{\rm{gal}}_{(1+z)\nu} = L_0 \Phi(z) \Sigma(M) \Theta((1+z)\nu) \,,
    \label{eq:LM_relation}
\end{equation}
where $L_0$ is a normalization factor, $\Phi(z)$ describes the redshift evolution, $\Sigma(M)$ the mass dependence, and $\Theta$ is the SED of the infrared emission. We describe parametrized functions for the \emph{L--M relation} below.

The redshift evolution of the \emph{L--M relation} is parametrized by a power law index $\delta^{\rm{CIB}}$ in the form of
\begin{equation}
    \Phi(z) = (1+z)^{\delta^{\rm{CIB}}} \,.
    \label{eq:Phi_cib}
\end{equation}
It is well-motivated by observations~\cite{Stark_2009, Gonzalez_2011}, however, to extend the redshift evolution of the \emph{L--M relation}, by including the so-called plateau redshift $z_p$, where $\delta^{\rm{CIB}} = 0$ at $z \geq z_p$:
\begin{equation}
    \Phi(z) = 
    \begin{cases}
      (1+z)^{\delta^{\rm{CIB}}}, & \text{if}\ z < z_p \,, \\
      1, &  \text{if}\ z \geq z_p \,.
    \end{cases}
    \label{eq:Phi_cib_zp}
\end{equation} 
This approach was taken in \cite{websky_Stein_2020} and \cite{Viero_2013_hermes}, where the authors assumed $z_p = 2$, motivated by observations \cite{Stark_2009, Gonzalez_2011}. We also follow this prescription and include $z_p$ as a parameter in our model, to be specified below. 


The mass dependence of the \emph{L--M relation} is written as 
\begin{equation}
\Sigma (M) = \frac{M}{\sqrt{2\pi \sigma^2_{L-M}}} e^{-(\mathrm{log}_{10} M - \mathrm{log}_{10} M_{\rm{eff}}^{\rm{CIB}})/2 \sigma^2_{L-M}} \,, 
\end{equation}
with two free parameters, $M_{\rm{eff}}^{\rm{CIB}}$ the peak of the specific IR emissivity, and $\sigma^2_{L-M}$ which controls
the range of halo masses that source the CIB emission. 

The CIB SED is the standard modified blackbody combined with a power law decline at high frequencies 
\begin{equation}
    \Theta = 
    \begin{cases}
       \nu^{\beta^{\rm{CIB}}}B_{\nu}(T_d(z))& \text{if}\ \nu < \nu_0, \\
      \nu^{—\gamma^{\rm{CIB}}} &  \text{if}\  \nu \geq \nu_0,
    \end{cases}
    \label{eq:theta_cib}
\end{equation}
where $B_{\nu}(T)$ is the Planck function at temperature $T$, $\nu_0$ is the break frequency that has to satisfy the continuous derivative requirement
\begin{equation} 
   \frac{\mathrm{d} \ln \Theta(\nu,z) }{\mathrm{d} \ln \nu} = -\gamma^{\rm{CIB}} \,, 
\end{equation}
 and $T_d(z)$ is the dust temperature at redshift $z$ that we parameterize as 
 \begin{equation}
      T_d(z) = T_0 (1+z)^{\alpha^{\rm{CIB}}}, 
 \end{equation}
 with $T_0$ and $\alpha^{\rm{CIB}}$ being free parameters.

To sum up, the \cite{Shang2012} CIB model presented in this work  has ten free parameters \{$L_0$, $\alpha^{\rm{CIB}}$, $\beta^{\mathrm{CIB}}$, $\gamma^{\mathrm{CIB}}$, $T_0$, $M_{\rm{eff}}$, $\sigma^2_{L-M}$, $\delta^{\rm{CIB}}$,  $M_{\rm{min}}^{\rm{CIB}}$, ($z_p$)\}. 

In CIB modeling and analysis, e.g., \cite{Shang2012, Planck:2013cib, McCarthy:2021lfp}, one usually implements a flux cut above which bright sources are detected and can be removed (thus suppressing the Poisson power associated with these objects). In our modeling, we follow this prescription and allow to remove all halos whose total luminosity is larger than the luminosity corresponding to a given flux cut value,  $ S_{\nu}$ defined as 
\begin{equation}
    S_{\nu} = \frac{L_{(1+z)\nu}(M,z)}{4\pi(1+z)\chi^2} \,.
    \label{eq:flux_cut}
\end{equation}
We present the flux cut values for selected \emph{Planck} and SO frequencies in Table~\ref{table:fluxcut}; for the \emph{Planck} frequencies the values are taken from Ref.~\cite{Planck:2013cib}, and for SO frequencies those in the SO forecast paper~\cite{Ade_2019}. 


