\section{Lower bound for the image multiset}

%\subsection{Lagarias generalization of Erd\"os upper bound theorem}

%\subsection{Proof of lower bound for the size of multiset}

In this section we will prove the following lower bound for the size of the multiset $\langle F : S\rangle^\#$, which complements the upper bound of Erd\"os and Lagarias. It will be used in Section \ref{ecc-section} for the lower bounds of the sets for a particular class of orbit sets.

\newcommand{\filterc}{x(\delta - 1) \geq \denominator}
\newcommand{\denominator}{s(\delta - 1) + \beta}

\begin{theorem}\label{lowerbound}
Let $F$ be a finite set of affine functions
\begin{equation*}
F = \{f_i(x) = a_i x + b_i \mid i = 1,\ldots,n\},
\end{equation*}
such that $a_i > 1, b_i \geq 0$. Suppose that $\sigma$ is a positive real number such that
\begin{equation*}
\sum_{i=1}^n \frac 1{a_i^{\sigma}} = 1.
\end{equation*}
Let $S \subset \mathbb R_+$~ be a discrete set. Then for any $x \geq 1$
\begin{equation*}
\prefix {\langle F : S \rangle} \geq \frac {(\delta - 1)^{\sigma}}{\gamma^{\sigma}}\left(\sum_ {\substack{s \in S \\ \filterc}} \frac 1{(\denominator)^{\sigma}}\right)x^{\sigma},
\end{equation*}
where $\delta = \min\limits_{i=1,\ldots,n} a_i, \beta = \max\limits_{i=1,\ldots,n} b_i, \gamma = \max\limits_{i=1,\ldots,n} a_i$.
\end{theorem}

First. we prove the following auxiliary result:

\begin{lemma}
Let $F$ be a finite set of affine functions $F = \{f_i(x) = a_i x + b_i \mid i=1,\ldots,n\}$,
such that $a_i > 1, b_i \geq 0$.
Then for any tuple $I=(i_1,\ldots,i_r)\in \{1,\ldots,n\}^r$ and any $s\in \mathbb R$
\begin{equation*}
f_I(s) 
%= a_{i_1}a_{i_2}\ldots a_{i_r}c + \sum_{j = 1}^r a_{i_1}a_{i_2}\ldots a_{i_{j - 1}}b_j 
\leq \frac{\denominator}{\delta - 1} a_{i_1}a_{i_2}\ldots a_{i_r},
\label{upper_est}
\end{equation*} 
where $\delta = \min\limits_{i=1,\ldots,n} a_i, \beta = \max\limits_{i=1,\ldots,n} b_i$.
\end{lemma}
\begin{proof}
First, a straightforward check shows that 
\begin{equation}
f_I(s) = a_{i_1}a_{i_2}\ldots a_{i_r}s + \sum_{j = 1}^r a_{i_1}a_{i_2}\ldots a_{i_{j - 1}}b_j.
\label{direct_computation}
\end{equation} 

In order to establish the desired inequality $f_I(s)\leq \dfrac{\denominator}{\delta - 1} a_{i_1}a_{i_2}\ldots a_{i_r}$ we prove the following auxiliary estimation:
\begin{equation}
\sum_{j = 1}^r a_{i_1}a_{i_2}\ldots a_{i_{j - 1}} < \frac{a_{i_1}a_{i_2}\ldots a_{i_r}}{\delta - 1}.
\label{inter_ineq}
\end{equation}
To check this, we consider the following equivalent inequality obtained by multiplication by $\delta-1$ and subsequent rearrangement of the terms.

\begin{equation*}
\sum_{j = 1}^{r - 1} (a_{i_1}a_{i_2}\ldots a_{i_{j - 1}}\delta - a_{i_1}a_{i_2}\ldots a_{i_{j - 1}}a_{i_j}) + a_{i_1}a_{i_2}\ldots a_{i_{r - 1}}\delta - 1 < a_{i_1}a_{i_2}\ldots a_{i_r}.
\end{equation*}
Since $\delta=\min a_i$, the sum consists of non-positive values, so this inequality and \eqref{inter_ineq} hold true. As, moreover, $\beta=\max b_j$, from \eqref{direct_computation} and \eqref{inter_ineq} we obtain the Lemma \ref{upper_est}.
\end{proof}

\begin{proof}[Proof of Theorem \ref{lowerbound}.]
For positive $x \geq 1$, we define
\begin{equation*}
N(x) = \{I = (i_1, \ldots, i_r) \mid r \geq 0, a_{i_1}\ldots a_{i_r} \leq x\}.
\end{equation*}
The size of this set is $|N(x)| \geq 1$ for $1 \leq x < \gamma$. First we will show that for any $x \geq 1$
\begin{equation}
|N(x)| \geq \frac {1}{\gamma^{\sigma}}x^{\sigma} 
\label{Nx_lower_bound}
\end{equation}

We will prove this claim for the half-interval $1 \leq x < \delta^k\gamma$ by induction on $k$. The base for $k = 0$ is:
\begin{equation*}
|N(x)| \geq 1 = \frac{\gamma^{\sigma}}{\gamma^{\sigma}} \geq \frac {1}{\gamma^{\sigma}}x^{\sigma}
\end{equation*}
Inductive step from $k$ to $k + 1$ is:
\begin{equation*}
|N(x)| = 1 + \sum_{i=1}^n\left|N\left(\frac{x}{a_i}\right)\right|.
\end{equation*}
Since $1 \leq \delta^k \leq \frac x{\gamma} \leq \frac x{a_i} \leq \frac x{\delta} < \delta^k\gamma$, we can apply the induction hypothesis:
\begin{eqnarray*}
|N(x)| &\geq& 1 + \frac {1}{\gamma^{\sigma}}\left(\sum_{i=1}^n \left(\frac x{a_i}\right)^{\sigma}\right)\\
&=& 1 + \frac {1}{\gamma^{\sigma}}\left(\sum_{i=1}^n \frac 1{a_i^{\sigma}}\right)x^{\sigma}\\
&=& 1 + \frac {1}{\gamma^{\sigma}}x^{\sigma} \geq \frac {1}{\gamma^{\sigma}}x^{\sigma}.
\end{eqnarray*}
%Finally, we count the elements for each $s \in S$ separately, using the fact that
%\begin{equation*}
%\langle F : S \rangle^{\#} = \bigcup_{s \in S} \langle F : \{s\} \rangle^{\#}.
%\end{equation*}

Now we will show that for any $x > 0$
\begin{equation}
\prefix {\langle F : \{s\} \rangle} \geq \left|N\left(\frac{x(\delta - 1)}{\denominator}\right)\right|.
\label{lower_estimation}
\end{equation}
Let us consider such tuples $I=(i_1,\ldots, i_r)$ such that 
\begin{equation}
\dfrac{\denominator}{\delta - 1} a_{i_1}a_{i_2}\ldots a_{i_r} \leq x.
\label{Ix-bound}
\end{equation}
Then, according to Lemma \ref{upper_est} we obtain that for any such tuple $I$ we have $f_I(s) \leq x$. The definition of the set $N$ shows that any tuple $I$ satisfying \eqref{Ix-bound} is in the set 
\[
N\left(\frac{x(\delta - 1)}{\denominator}\right),
\] so the estimation \eqref{lower_estimation} follows.

%This means,
%\begin{equation}
%\prefix {\langle F : \{s\} \rangle} \geq \left|N\left(\frac{x(\delta - 1)}%{\denominator}\right)\right|.
%\end{equation} 
%\qed

\medskip

For $\filterc$ the right hand side of \eqref{lower_estimation} can be estimated from below by $\frac{1}{\gamma^{\sigma}}\left(\frac{x(\delta - 1)}{\denominator}\right)^{\sigma}$ due to bound \eqref{Nx_lower_bound}. For others $\left|N\left(\frac{x(\delta - 1)}{\denominator}\right)\right| = 0$. This allows us to finally obtain the main claim of the Theorem:

\begin{eqnarray*}
\prefix {\langle F : S \rangle} &=& \sum_{\substack{s\in S}} \prefix {\langle F : \{s\} \rangle}\\
&\geq& \frac{1}{\gamma^{\sigma}}\left(\sum_{\substack{s \in S \\ \filterc}}\left(\frac{x(\delta - 1)}{\denominator}\right)^{\sigma}\right)\\
&=& \frac{(\delta - 1)^{\sigma}}{\gamma^{\sigma}}\left(\sum_{\substack{s \in S \\ \filterc}}\frac{1}{(\denominator)^{\sigma}}\right)x^{\sigma}.
\end{eqnarray*}
\end{proof}

