\section{Sublinear bound for Erd\"os-Graham question}

\begin{theorem}\label{subbound}
Let $F$ be a finite set of affine functions
\begin{equation*}
F = \{f_i(x) = a_i x + b_i \mid i=1,\ldots n\},
\end{equation*}
such that $a_i > 1, b_i \geq 0$. Suppose that $F$ is a basis of a free semigroup and $\sum\limits_{I}\frac1{a_i}=1$. Then for any $s\geq 0$
\begin{equation*}
\left|\langle F : s \rangle\cap [0, x]\right| = \Omega(x/\log^{\frac{n-1}2}(x)), \text{ when }x\to \infty.
%= 
\end{equation*}
\end{theorem}

The main estimate follows from the next Lemma, which shows that we can construct sufficiently many compositions having equal slope and distinct free coefficients.

%For the latter we save $k_i(t)=t\cdot a_1 \ldots a_{i-1} a_{i+1} \ldots a_n$.

\begin{lemma}
\label{density_estimation}
Let $F$ be a set of affine functions $F = \{f_i(x) = a_i x + b_i \mid i=1,\ldots,n\}$ such that $a_i > 1, b_i \geq 0$. Suppose that $F$ is a basis of a free semigroup. Then for any $k_1,\ldots,k_n\in \mathbb N$ there exists a set $\mathcal C$ consisting of compositions of functions from $F$ having equal slope $\prod\limits_{i=1}^n a_i^{k_i}$, such that 

a) $|\mathcal S|\geq\left(\sum\limits_{i=1}^n k_i\right)!/(\prod\limits_{i=1}^n k_i!)$

b) For any function $f\in C$ and any $s\geq 0$ the value $f(s)$ is bounded as
\[ 0\leq f(s)\leq M(k_1,k_2,\ldots, k_n;s)=\left(\dfrac{\max_{i=1}^n b_i}{\min_{i=1}^n a_i - 1}+s\right) \prod\limits_{i=1}^n a_i^{k_i}.\]
\end{lemma}
\begin{proof}
Let $\mathcal C$ be the set of compositions $f_{i_1}\circ f_{i_2} \circ \ldots \circ f_{i_L}$, where $L=k_1+k_2+\ldots + k_n$ and the tuple $(i_1,i_2,\ldots,i_L)$ contains each number $i\in \{1,\ldots, n\}$ exactly $k_i$ times. In this case, the slope of any function $f\in \mathcal C$ is equal to $\prod\limits_{i=1}^n a_i^{k_i}$, and all functions in $\mathcal  C$ are distinct because $F$ is a basis of a free semigroup. The number of tuples $(i_1,i_2,\ldots,i_d)$ with the property described above is then equal to the number of words in the alphabet $\{1,\ldots,n\}$ containing $k_1,k_2,\ldots,k_n$ letters of the respective type, which is $\left(\sum\limits_{i=1}^n k_i\right)!/(\prod\limits_{i=1}^n k_i!)$ due to the multinomial theorem.

In (b) the estimation for the value $f(s)$ is immediate with the use of Lemma \ref{upper_est}.
\end{proof}

