\end{proof}


\subsection{The simplified market setting}\label{sec:simplified}
For illustration we discuss throughout the paper also a {\em simplified market setting}, where  we assume in \eqref{e.4'} only one driving Brownian motion such that the stock GOP satisfies
	\begin{align}
		\label{e.4 1d}
	\frac{dS^{*}_t}{S^{*}_t}=\lambda^*_t \, dt + \theta_t\,  (  \theta_t \, dt+d B_t), \quad t \ge 0,
	\end{align}
with \begin{equation}
\label{thetasigma*}
\theta = ||\sigma^* ||,\end{equation}
where $B= ((\theta_t)^{-1} \sigma_t^*{}^\top W_t)_{t \ge 0}$ is a one-dimensional Brownian motion. %
  For illustration, in Section \ref{sec:MMM} the  stock GOP dynamics of this simplified  market setting will be specified.\\

We can extend this simplified market setting by adding the riskless savings account 
$S^0 \equiv 1$, which leads to the following conclusion: 
\begin{corollary}
	For the extended simplified market setting with the stock GOP $S^*$ satisfying \eqref{e.4 1d} with $\theta>0$ $dt \otimes dP$-a.s.~and the riskless savings account $S^0 \equiv 1$,   the unique  GOP $S^{**}$ satisfies
	\begin{align}\label{eq:GOP 1d}
		\frac{dS^{**}_t}{S^{**}_t} =  \sigma^{**}_t (\sigma_t^{**} dt +  dB_t) 
	\end{align}
	with
	\begin{align}\label{eq:sigma **2}
		\sigma_t^{**} =  \frac{\lambda_t^* }{\theta_t}+\theta_t.
	\end{align}
\end{corollary}
\begin{proof}
	In the case where $n=1$,
	 \eqref{e.4 1d} implies that $b_t = \theta_t=||\sigma^*_t||$ in Equation \eqref{eq: dS}.
	Then, the result follows by applying Proposition \ref{prop:2.2}.
\end{proof}




