In the following we  study in the given insurance-finance market  arbitrages of the first kind where the insurance company can dynamically reallocate or hedge securities by trading in the financial market. We follow  \cite{kardaras2012market} and refer to \cite{karatzas2021portfolio} for a detailed exposition on the topic. Note that arbitrages of the first kind (A${}_1$s) are a weaker concept in comparison to  free lunches with vanishing risk (FLVRs). The situation we consider here, with existing  GOP $S^{**}$ of the extended financial market, might not guarantee NFLVR but guarantees no unbounded profit with bounded risk (NUPBR), as shown in \cite{karatzas2021portfolio}. %


\begin{definition}
	An \emph{insurance-finance arbitrage of the first kind} (IFA${}_1$) is an $\ccF_T$-measurable random variable $\varepsilon$ satisfying $P(\varepsilon \geq 0) = 1$ and $P(\varepsilon > 0) > 0$, for which there exists, for every $x > 0$, an insurance allocation $\psi$ and  a permissible self-financing trading strategy $\zeta$ satisfying	$x=\zeta_0^\top X_0$ and
	$$ U_T^{\psi} + V_T^{(0,\zeta)}
	S^*_T 
	\ge \varepsilon. $$
%
%
%
	%
\end{definition}

\smallskip

If no such arbitrage exists, we shall say that NIFA${}_1$ holds. Note that this condition requires NA${}_1$, since $\psi\equiv {\bf {0}}$ is a permissible insurance strategy. It, however, does not require NFLVR. We now provide the simple direction of the fundamental theorem of asset pricing on the absence of IFA${}_1$ in our setting. 

\begin{proposition} \label{prop:FTIFA}
Assume that Assumption \ref{ass} and Assumption \ref{assum:ConditionalExpectations} hold. If the $i$-th insurance premium $p^i=p$ is bounded by the BN-price, i.e.~if 
\begin{align}\label{eq:QP BN}
	p \le E_P\bigg[ \frac{\beta^i}{S_T^{**}} \, \Big| \, \ccG_0\bigg] = 
 E^*\bigg[ \frac{\beta^i}{S_T^*} \, \Big| \, \ccG_0\bigg] 
\end{align}
for all $i\in\{1,...,m\}$, then NIFA${}_1$ holds.
\end{proposition}
\begin{proof}
To begin with, we note that by Equation \eqref{eq:H H*}
\begin{align}\label{temp598}
E^*\bigg[ \frac{\beta^i}{S_T^*} \, \Big|\, \ccG_0\bigg] = E^*\bigg[ \frac{\beta^i}{S_T^*} \, \Big| \, \ccF_0\bigg] =
E_P\bigg[ \frac{S^*_T}{S_T^{**}}\frac{\beta^i}{S_T^{*}}  \, \Big| \,  \ccF_0\bigg] =
E_P\bigg[ \frac{\beta^i}{S_T^{**}}  \, \Big| \,  \ccF_0\bigg]
\end{align}
for all $i\in\{1,...,m\}$ because $\ccG_0=\ccF_0$. 
%
%
Furthermore, 
	note that by our previous assumptions there exists a GOP $S^{**}$ in the financial market including the savings account $S^0$. By Proposition 2.41 in \cite{karatzas2021portfolio}, the inverse of the GOP $S^{**}$ is a supermartingale deflator, and by Proposition 2.4 therein, this is equivalent to being a local martingale deflator, i.e., primary security accounts denominated by $S^{**}$ are $\bbF$-$P$-local martingales. 

Now, we	 choose a sequence of permissible wealth processes $V^{(0,\zeta_k)}$ with $x_k=\zeta^\top_0 X_0$ and insurance allocations $\psi_k$ such that $x_k \to 0$ and 
	 \begin{align}\label{temp:607}
	U_T^{\psi_k} + V_T^{(0,\zeta_k)}S^*_T \ge \varepsilon
	 \end{align}
 for some  non-negative random variable $\varepsilon \ge 0$. Denote by $Z=(S^{**})^{-1}$ the local martingale deflator associated to $S^{**}$. 

 For the insurance part, note that for any allocation $\psi_k$ one has
 \begin{align}
 	E_P\Big[ Z_T  U^{\psi_k}_T  \Big] &=
 	E_P\Big[ Z_T  \sum_{i = 1 }^m \psi^i_k (p\, S_T^{*}-\beta^i) \Big] \notag \\
 	&= \sum_{i = 1 }^m p \psi^i_k E_P\Big[  \frac{S^*_T}{S^{**}_T}  \Big] - 
 	E_P\Big[ Z_T \sum_{i = 1}^m \psi^i_k \beta^i \Big].  \label{AES1}
 \end{align}
 For the following, we introduce $\gamma_k=\sum_{i=1}^{m} \psi^i_k$. Moreover, since $Z_T$ and $\psi^1_k,\dots,\psi^m_k $ are $\ccH$-measurable, we obtain by Assumption \ref{assum:ConditionalExpectations}
 \begin{align}
 	E_P\Big[ Z_T \sum_{i = 1}^m \psi^i_k \beta^i \Big] &= E_P\Big[ Z_T \sum_{i = 1}^m \psi^i_kE_P \big[\beta^i | \ccH \big] \Big] 
 	= E_P\Big[ Z_T \sum_{i = 1}^n  \psi_k^iE_P \big[\beta^1 | \ccH \big] \Big] \notag\\
 	&= E_P\big[ Z_T \, \gamma_k \, \beta^1  \big]. \label{AES2}
 \end{align}

 Then,
	 by Equations \eqref{AES1} and \eqref{AES2},
	 \begin{align}
	 	E_P\Big[ Z_T \big( U_T^{\psi_k} + V_T^{(0,\zeta_k)}S^*_T \big) \Big]
	 	= E_P\big[  \gamma_k (p -Z_T\beta^1)\big] + 
	 	E_P\big[ Z_TS^*_T V_T^{(0,\zeta_k)} \big].
	 \end{align}
	 By condition \eqref{eq:QP BN},
	 \begin{align}
	 	E_P\big[  \gamma_k (p -Z_T\beta^1)\big] &= E_P\Big[\gamma_k \Big(p -\frac{\beta^1}{S_T^{**}}\Big) \Big] \le 0,
	 \end{align}
	 where we used \eqref{temp598}. Moreover, since $ZS^* V^{(0,\zeta_k)}$ is a nonnegative local martingale, and hence a supermartingale,
	 \begin{align*}
	 	E_P\big[ Z_TS^*_T V_T^{(0,\zeta_k)} \big] & \le  V_0^{(0,\zeta_k)} = x_k  
	 \end{align*}
	 for all $k \ge 1$. Hence, 
	 \begin{align*}
	 	E_P\Big[ Z_T \big( U_T^{\psi_k} + V_T^{(0,\zeta_k)}S^*_T \big) \Big] \le 0
	 \end{align*}
	 and, therefore, by Equation \eqref{temp:607},
	 \begin{align*}
	 0 \ge 	E_P\Big[ Z_T \big(U_T^{\psi_k} + V_T^{(0,\zeta_k)} S^*_T\big) \Big] \ge E_P[Z_T \varepsilon].
	 \end{align*}
	 Since $\varepsilon \ge  0$ this implies $\varepsilon = 0$ and, therefore, $\varepsilon$ cannot be an arbitrage of the first kind, such that NIFA${}_1$ holds. 
\end{proof}	 


\begin{remark}In comparison to \cite{ArtznerEiseleSchmidt2024}, and in particular to \cite{OberprillerRitterSchmidt2024}, we consider here insurance strategies with only finitely many contracts. For the shown result in Proposition \ref{prop:FTIFA}, this is the easiest approach and suffices our purpose. Extending this to asymptotic insurance-finance arbitrages of the first kind requires substantial more work, since Proposition B.1 of \cite{OberprillerRitterSchmidt2024} is no longer applicable in the setting with local martingale deflators. 	
\end{remark}	


\subsection{The relation to the QP-rule}
\label{sec:QP}
The QP-rule, originally proposed in \cite{plachky1984conservation} and used in \cite{dybvig1992hedging} for the pricing of non-traded wealth, was applied to the insurance setting in \cite{ArtznerEiseleSchmidt2024}. It essentially combines the putative risk-neutral measure with the real-world probability measure in a way that does not allow asymptotic insurance-finance arbitrages. 

More precisely,  we consider the filtered probability space $(\Omega,\ccF_T,(\ccF_t)_{0 \le t \le T},P)$ for the financial market and the probability space $(\Omega,\ccG_T,P)$ for the insurance market where we recall that $\ccF_T \subset \ccG_T$. If we assume that NFLVR holds, then there exists an equivalent risk-neutral local martingale measure $Q$. The QP-rule specifies a unique measure $\QcirP$ which guarantees market consistency on the one side and valuation of insurance claims by conditional expectations on the other side. Indeed, it is the unique measure such that for a $\ccG_T$-measurable random variable $\beta \ge 0$, $E_{\QcirP}[\beta|\ccF_t] = E_Q[ E_P[\beta|\ccF_T] | \ccF_t]$. Asymptotic insurance-finance arbitrage-free pricing can now be performed by computing the $\QcirP$-conditional expectation of the discounted benefits. 

For the following conclusion, let us denote the density of $Q$ with respect to $P$, on $(\Omega,\ccF_T)$, by $Z_T=dQ / dP$.
\begin{proposition}
	If Assumption \ref{ass} and NFLVR hold with $S^0_0=S^{**}_0$, there exists an equivalent risk-neutral local martingale measure $Q$, such that the QP-rule coincides with the BN-price, i.e.
	\begin{align*}
		E^*\bigg[ \frac{\beta}{S_T^*} \,\Big|\, \ccG_0\bigg] =	E_P\bigg[ \frac{\beta}{S_T^{**}} \,\Big|\, \ccG_0\bigg] = E_{\QcirP} \bigg[ \frac{\beta}{S^0_T} \,\Big|\, \ccF_0 \bigg] = E_{\QcirP} \big[ \beta \,\Big|\, \ccF_0 \big]
	\end{align*}
	for any $\ccG_T$-measurable benefit $\beta \ge 0$. 
\end{proposition}

In reality, it seems unlikely that the assumptions of the above result are satisfied. However,
one can conclude the BNP-rule, which would hold under NUPBR. Most generally, one has  the $P$-rule of  the benchmark approach, which employs just the  real-world probability measure $P$, which  requests NUPBR. The latter is equivalent to the existence of the GOP $S^{**}$. Under Assumption \ref{ass}, however, the $P$-rule is equivalent to the BNP-rule.

