\section{Proof of Revenue Adequacy for the Pricing Scheme of Section 2.3}
\label{sect:proof1}

Let us rewrite the LD function in Equation \eqref{eq:SM_Lagrangian5} as follows:
\begin{equation}
    \begin{aligned}
        \label{eq:SM_Lagrangian6_app}
        \phi(\boldsymbol{\Pi}) = & \ CP(\boldsymbol{\Pi}) 
        - \sum\limits_{i \in \mathcal{I}} \max\limits_{\boldsymbol{x}_i \in \mathcal{X}_i} \Bigg\{ Profit^g_i(\boldsymbol{\Pi}, \boldsymbol{x_i}) \Bigg\}
    \end{aligned}
\end{equation}


\noindent
where $CP(\boldsymbol{\Pi})$ and $Profit^g_i(\boldsymbol{\Pi}, \boldsymbol{x_i})$ represent the consumer payment and the profit of generator $i$, respectively. Since $Profit^g_i(\boldsymbol{\Pi},\boldsymbol{x_i})$ is 
a linear objective function maximized over $\boldsymbol{x_i}$, with $\boldsymbol{x_i} \geq \boldsymbol{0}$, the optimal value of $Profit^g_i(\boldsymbol{\Pi}, \boldsymbol{x_i})$ is guaranteed to be non-negative. In other words, if $\pi_0$ and $\pi_k$ fail to cover generator $i$'s costs, the generator will not produce any output, resulting in $g^*_{i0} = r^{g,up*}_i = 0$. Likewise, at the optimal solution $\boldsymbol{x^*_i}$ and $\boldsymbol{\Pi^*}$:

\begin{equation}
    Profit^g_i(\boldsymbol{\Pi^*},\boldsymbol{x^*_i}) \geq 0, \ \forall i \in \mathcal{I}
\end{equation}


Therefore, the theorem holds.
\hfill $\qed$

\section{Proof of Revenue Neutrality for the Pricing Scheme of Section 2.3}
\label{sect:proof2}
By the strong duality theorem, the optimal value of the primal objective function in Equation \eqref{eq:SMobj} is equal to the optimal value of the LD function in Equation \eqref{eq:SM_Lagrangian6}. Thus, at the optimal solution $\boldsymbol{x}^*$ and $\boldsymbol{\Pi}^*$, we have:

\begin{equation}
\begin{aligned}
    \label{sect:app-LDP}
    \sum\limits_{i \in \mathcal{I}}c_ig_{i0}^* + \sum\limits_{i \in \mathcal{I}}q^{g,up}_ir_i^{g,up*} &= \left(\pi^*_0 + \sum\limits_{k \in \mathcal{K}} \pi^*_k \right) d \\
    &\quad - \sum\limits_{i \in \mathcal{I}} \Bigg[ 
        \left(\pi^*_{0} + \sum\limits_{k \in \mathcal{K}} \pi^*_k - c_i \right) g^*_{i0} \\
    &\quad + \left(\sum\limits_{k \in \mathcal{K}} \pi^*_k - q_i^{g,up} \right) r_i^{g,up*} \\
    &\quad - \sum\limits_{k \in \mathcal{K}^{OFF}_i} \pi^*_k \left(g_{i0}^* + r_i^{g,up*}\right) \Bigg]
\end{aligned}
\end{equation}

By canceling out identical terms in both sides of Equation \eqref{sect:app-LDP} and rearranging terms, we simplify the expression as follows:

\begin{equation}
\begin{aligned}
    \label{sect:app-LDP2}
    \left(\pi^*_0 + \sum\limits_{k \in \mathcal{K}} \pi^*_k \right) d &= 
     \sum\limits_{i \in \mathcal{I}} \Bigg[ 
        \left(\pi^*_{0} + \sum\limits_{k \in \mathcal{K}} \pi^*_k \right) g^*_{i0} \\
    &\quad + \sum\limits_{k \in \mathcal{K}} \pi^*_k  r_i^{g,up*} 
    - \sum\limits_{k \in \mathcal{K}^{OFF}_i} \pi^*_k \left(g_{i0}^* + r_i^{g,up*}\right) \Bigg]
\end{aligned}
\end{equation}

Therefore, at the optimal solution, the consumer payment equals the sum of all generator revenues.
\qed
\section{Proof of Revenue Adequacy for the Pricing Scheme of Section 3.3}
\label{sect:proof3}

Let us rewrite the LD function in Equation \eqref{eq:EM_Lagrangian6} as follows:

\begin{equation}
\begin{aligned}
    \label{eq:EM_Lagrangian5_app}
    \phi\left(\boldsymbol{\Pi}^*\right) =& - \sum\limits_{l \in \mathcal{L}} \left( \left|\pi_{l0}^{f*}\right| + \sum\limits_{k \in \mathcal{K}} \left|\pi_{lk}^{f*}\right| \right) F_l \\    
    & - \sum\limits_{i \in \mathcal{I}} \max\limits_{\boldsymbol{x_i} \in \mathcal{X}_i} \Bigg[ Profit^g_i\left(\boldsymbol{\Pi^*_{b(i)}}, \boldsymbol{x_i}\right) \Bigg] \\
    &-\sum\limits_{j \in \mathcal{J}}\max\limits_{\boldsymbol{y_j} \in \mathcal{Y}_j}\Bigg[Profit^d_j\left(\boldsymbol{\Pi^*_{b(j)}}, \boldsymbol{y_j}\right)  \Bigg]
\end{aligned}
\end{equation}


The terms $Profit^g_i\left(\boldsymbol{\Pi_{b(i)}^*}, \boldsymbol{x_i}\right)$ and $Profit^d_j\left(\boldsymbol{\Pi_{b(j)}^*}, \boldsymbol{y_j}\right)$ respectively represent the profits of generator $i$ and consumer $j$. It should be noted that $Profit^g_i\left(\boldsymbol{\Pi_{b(i)}^*}, \boldsymbol{x_i}\right)$ and $Profit^d_j\left(\boldsymbol{\Pi_{b(j)}^*}, \boldsymbol{y_j} \right)$ are linear objective functions respectively maximized over $\boldsymbol{x_i}$ and $\boldsymbol{y_j}$ with $\boldsymbol{x_i} \geq \boldsymbol{0}$ and $\boldsymbol{y_j} \geq \boldsymbol{0}$. Therefore, at the optimal solution, $Profit^g_i\left(\boldsymbol{\Pi_{b(i)}^*}, \boldsymbol{x^*_i}\right)$ and $Profit^d_j\left(\boldsymbol{\Pi_{b(j)}^*}, \boldsymbol{y^*_j}\right)$ are both non-negative. In other words, if $\pi^*_{b(i)0}$ and $\pi^*_{b(i)k}$ fail to cover generator $i$'s costs, the production and reserve contributions of this generator will be $0$, i.e., $g^*_{i0} = r^{g,up*}_i = r^{g,dn*}_i = 0$. Analogously, if $\pi^*_{b(j)0}$ and $\pi^*_{b(j)k}$ are not profitable for consumer $j$, the consumption and reserve contributions of this consumer will be $0$, i.e., $d^*_{j0} = r^{d,up*}_j = r^{d,dn*}_j = 0$. Therefore:

\begin{equation}
    Profit^g_i\left(\boldsymbol{\Pi_{b(i)}^*}, \boldsymbol{x^*_i}\right) \geq 0, \ \forall i \in \mathcal{I} 
\end{equation}
\vspace{-3ex}
\begin{equation}
    Profit^d_j\left(\boldsymbol{\Pi_{b(j)}^*}, \boldsymbol{y^*_j}\right)  \geq 0, \ \forall j \in \mathcal{J}
\end{equation}

Therefore, the theorem holds.
\hfill $\qed$

\section{Proof of Revenue Neutrality for the Pricing Scheme of Section 3.3}
\label{sect:proof4}

By the strong duality theorem, the optimal value of the primal objective function in Equation \eqref{eq:EMobj} is equal to the optimal value of the LD function in Equation \eqref{eq:EM_Lagrangian6}. Thus, at the optimal solution $\boldsymbol{x^*}$, $\boldsymbol{y^*}$, and $\boldsymbol{\Pi^*}$, we have:

\begin{equation}
\label{eq:app_lulu}
\begin{aligned}
    & \sum_{i \in \mathcal{I}} c_i g^*_{i0} 
    + \sum_{i \in \mathcal{I}} q_i^{g,up} r_i^{g,up*} 
    + \sum_{i \in \mathcal{I}} q_i^{g,dn} r_i^{g,dn*} \\
    &
    - \sum_{j \in \mathcal{J}} w_j d^*_{j0}
    + \sum_{j \in \mathcal{J}} q_j^{d,up} r_j^{d,up*} 
    + \sum_{j \in \mathcal{J}} q_j^{d,dn} r_j^{d,dn*} = \\
    & 
    -\sum_{l \in \mathcal{L}} \left( |\pi_{l0}^{f*}| + \sum_{k \in \mathcal{K}} |\pi_{lk}^{f*}| \right) F_l     
    -\sum_{i \in \mathcal{I}} 
    \Bigg[ 
        \left( 
            \pi^*_{b(i)0} + \sum_{k \in \mathcal{K}} \pi^*_{b(i)k} - c_i 
        \right) g^*_{i0} \\
    & \quad 
        + \left( 
            \sum_{k \in \mathcal{K}} \pi_{b(i)k}^{+*} - q_i^{g,up} 
        \right) r_i^{g,up*} 
        + \left( 
            \sum_{k \in \mathcal{K}} \pi_{b(i)k}^{-*} - q_i^{g,dn} 
        \right) r_i^{g,dn*} \\
    & \quad 
        - \sum_{k \in \mathcal{K}_{i}^{\text{OFF}}} 
        \Bigg( 
            \pi^*_{b(i)k} g^*_{i0} 
            + \pi_{b(i)k}^{+*} r_i^{g,up*} 
            + \pi_{b(i)k}^{-*} r_i^{g,dn*} 
        \Bigg) 
    \Bigg] \\
    &- \sum_{j \in \mathcal{J}} 
    \Bigg[ 
        \left( 
            w_j - \pi^*_{b(j)0} - \sum_{k \in \mathcal{K}} \pi^*_{b(j)k} 
        \right) d^*_{j0} \\
    & \quad 
        + \left( 
            \sum_{k \in \mathcal{K}} \pi_{b(j)k}^{+*} - q_j^{d,up} 
        \right) r_j^{d,up*} 
        + \left( 
            \sum_{k \in \mathcal{K}} \pi_{b(j)k}^{-*} - q_j^{d,dn} 
        \right) r_j^{d,dn*} 
    \Bigg]
\end{aligned}
\end{equation}


By canceling out identical terms in both sides of Equation \eqref{eq:app_lulu} and rearranging terms, we simplify the expression as follows:

\allowdisplaybreaks

\begin{equation}
\begin{aligned}
    &\sum_{j \in \mathcal{J}} 
        \Bigg[ 
            \left( 
                \pi^*_{b(j)0} + \sum_{k \in \mathcal{K}} \pi^*_{b(j)k} 
            \right) d^*_{j0}  
            - \sum_{k \in \mathcal{K}} \pi_{b(j)k}^{+*} r_j^{d,up*} 
            - \sum_{k \in \mathcal{K}} \pi_{b(j)k}^{-*} r_j^{d,dn*} 
        \Bigg] = \\
    &\sum_{l \in \mathcal{L}} \left( |\pi_{l0}^{f*}| + \sum_{k \in \mathcal{K}} |\pi_{lk}^{f*}| \right) F_l 
    + \sum_{i \in \mathcal{I}} \Bigg[ 
        \left( 
            \pi^*_{b(i)0} + \sum_{k \in \mathcal{K}} \pi^*_{b(i)k} 
        \right) g^*_{i0} 
        + \sum_{k \in \mathcal{K}} \pi_{b(i)k}^{+*} r_i^{g,up*} \\
        & \quad
        + \sum_{k \in \mathcal{K}} \pi_{b(i)k}^{-*} r_i^{g,dn*}  
        - \sum_{k \in \mathcal{K}_{i}^{\text{OFF}}} 
        \Bigg( 
            \pi^*_{b(i)k} g^*_{i0} 
            + \pi_{b(i)k}^{+*} r_i^{g,up*} 
            + \pi_{b(i)k}^{-*} r_i^{g,dn*} 
        \Bigg) 
    \Bigg] 
\end{aligned}
\end{equation}

Therefore, at the optimal solution, the sum of all consumer payments equals the sum of all generator and transmission line revenues.
\hfill $\qed$

