\section{Appendix: The Resistive MHD Equations}
\label{sec:appendix}

This appendix sketches the numerical methods in the evolution of the momentum equations with a focus on the algebraic form of the diagonal blocks of the Jacobian matrix in \textit{M3D-C1}, which is of the most relevance to algebraic solvers. Start from the resistive MHD equations:

\begin{eqnarray}
	\ddt{n} + \div{(n \v)} =0 & \mbox{continuity}
    \\
	\ddt{\B} = \curl{ \left[ \v \times \B -\eta \J \right] } & \mbox{Maxwell}
    \\
	nM_i \frac{d\v}{dt} + \grad{p} - \nu \nabla^2 \v = \J \times \B & \mbox{momentum} \label{eq:mom1}
	\\
	\E + \v \times \B = \eta \J + \frac{1}{ne} \left( \J \times \B - \grad{p}_e - \div{\P}_e \right) & \mbox{Ohm's}
	\\
	\ddt{p} + \v \cdot \grad{p} +\gamma p \div{\v}   = (\gamma -1) \left[ \eta\J^2 - \P:\grad{\v} \right]  & \mbox{energy}
\end{eqnarray}
%	-\frac{\eta_W}{\delta_W} \left(\uvec{n} \cdot \grad{\psi} - R \uvec{t} \cdot \B_v \right)
%	\frac{\eta_W}{\delta_W} \left(F - R \uvec{\tor} \cdot \B_v \right)
\noindent
$\eta$: resistivity\\
$\mu$: viscosity\\

\subsection{Dimensionless Scaling of The momentum equation}
\begin{eqnarray}
	nM_i \frac{d\v}{dt} + \grad{p} - \nu \nabla^2 \v = \J \times \B \\
	n_0\tilde{n}M_i \frac{v_0}{t_0}\frac{d\tilde{\v}}{d\tilde{t}} 
	+ \frac{p_0}{l_0} \tilde{\nabla}\tilde{p} 
	- \frac{\nu_0 v_0}{l_0^2}\tilde{\nu} \tilde{\nabla}^2 \tilde{\v} = J_0B_0 \tilde{\J} \times \tilde{\B} \\
	\frac{l_0^2}{t_0^2} \frac{\mu_0 n_0 M_i}{B_0^2} \tilde{n} \frac{d\tilde{\v}}{d\tilde{t}} 
	+ \frac{\mu_0 p_0}{B_0^2} \tilde{\nabla}\tilde{p} -\frac{\nu_0 v_0 \mu_0}{B_0^2 l_0}\tilde{\nu} \tilde{\nabla}^2 \tilde{\v} = \tilde{\J} \times \tilde{\B} \\
	\tilde{n} \frac{d\tilde{\v}}{d\tilde{t}} + \tilde{\nabla}\tilde{p} -\tilde{\nu} \tilde{\nabla}^2 \tilde{\v} = \tilde{\J} \times \tilde{\B} 
\end{eqnarray}
where 
$$
t_0 = l_0 \left[\frac{\mu_0 n_0 M_i}{B_0^2} \right]^{\frac{1}{2}} ,
p_0 = \frac{B_0^2}{\mu_0},
J_0 = \frac{B_0}{\mu_0 l_0},
\v_0 = \frac{l_0}{t_0},
\nu_0 = \frac{B_0^2 t_0}{\mu_0} = \frac{n_0 M_i}{t_0} l_0^2
$$


\subsection{Parabolization}
\label{sec:parb}

let $\dot{\v} \equiv \ddt{\v}$ and the ideal MHD momentum equation results:
\begin{equation}
n_0 \dot{\v} + \grad{p} = \left[ \left( \nabla \times \B \right) \times \B \right]
\end{equation}
take its time derivative 
\begin{equation}
	n_0 \ddot{\v} + \grad{\dot{p}} = \left[ \left( \nabla \times \dot{\B} \right) \times \B + 
								  \left( \nabla \times \B \right) \times \dot{\B}
	                                                  \right]
\end{equation}
Substitute the ideal MHD eqution for $\dot{\B}$ and $\dot{p}$
\begin{eqnarray}
	\dot{\B} = \nabla \times \left[ \v \times \B \right]\\
	\dot{p} = -\v \cdot \grad{p} - \gamma p \div{\v}
\end{eqnarray}
we get the parabolization operator
\begin{equation}
	\begin{array}{l}
\mathcal{L} (\v) = \left\{ \nabla \times \left[ \nabla \times \left( \v \times \B \right) \right] \right\} \times \B 
 +  \left\{ \left( \nabla \times \B \right) \times \nabla \times \left( \v \times \B \right) \right\} 
 + \grad{ ( \v \cdot \grad{p} + \gamma p \div{\v} ) }
\end{array}
\label{eq:L1}
\end{equation}

with the parabolozation, the momentum equation becomes:
\begin{eqnarray}
	\left\{ n - \theta^2 \dt^2 \mathcal{L} \right\} \pp{\v}{t} + n \v \cdot \grad{\v} + \grad{p} - \nu \nabla^2 \v 
	= \left[ \left( \nabla \times \B \right) \times \B \right] 
    \label{eq:L2}
\end{eqnarray}
Then we can advance the velocity as follow
\begin{equation}
	\begin{array}{l}
\left\{ n - \theta^2 \dt^2 \mathcal{L} \right\} \v^{n+1} + \theta \dt (n \v^{n+1} \cdot \grad{\v^n} + n \v^n \cdot \grad{\v^{n+1}}) -\nu \theta \dt \nabla^2 \v^{n+1} = \\
\qquad \qquad \qquad \qquad \qquad \qquad
\left\{ n - \theta^2 \dt^2 \mathcal{L} \right\} \v^{n} -(1-2\theta) \dt (n \v^n \cdot \grad{\v^n}) +
\dt \left\{ - \grad{p} + \left[ \left( \nabla \times \B \right) \times \B \right] \right\}^{n+\frac{1}{2}}
\end{array}
\label{eq:L3}
\end{equation}



\subsection{Decompose the Momentum Equation in \texorpdfstring{$(R,\phi,Z)$}{R,phi,Z} coordinate system}
\label{sec:momentum}

% C1Element-7.pdf

\begin{eqnarray}
	\v = R^2 \grad{U} \times \grad{\phi} + R^2 \omega \grad{\phi} + \frac{1}{R^2} \nabla_\perp \chi
  \label{eq:stream}  
\end{eqnarray}

\noindent
The operator $\nabla_\perp$ denotes the gradient in the $(R,Z)$ plane, 
$$
\nabla_\perp \chi \equiv \chi_R \hat{R} + \chi_Z \hat{Z},
$$
orthogonal to $\grad{\phi}$. $| \grad{\phi} | = \ff{1}{R}$.

$U$ - shear Alfven wave, does not compress the strong toroidal magnetic field.

$\omega$ - slow wave, does not compress the toroidal magnetic field.

$\chi$ - fave wave, does compress the toroidal field. %The magnitude of $\chi$ doesn't matter, only the $\div{\P}$ matters.

\noindent
To obtain the scalar time-advancement equations, apply 3 scalar projections: % by operating with 3 projection operators:

\begin{eqnarray}
	\grad{\phi} \cdot \nabla_\perp \times R^2 \\
	R^2 \grad{\phi} \cdot\\
	\nabla_\perp \cdot \ff{1}{R^2}
    \label{eq:projections}  
\end{eqnarray} 

\subsection{Strong Form of \texorpdfstring{$\cal{L}$}{L}}

Let's set $\Q=\nabla \times \left( \v \times \B \right)$, and rewrite the $\mathcal{L} (\v)$ as 
$$
		\mathcal{L} (\v) = (\nabla\times\Q ) \times \B + \J \times Q 
		+ \grad{ (\v\cdot\grad{p} + \gamma p \div{\v}) }
$$

The projections on (\ref{eq:projections}) are applied to $\mathcal{L}$, for example, applying the first projection operator $\grad{\phi} \cdot \nabla_\perp \times R^2$, we have
\begin{equation}
	\begin{array}{ll}
		\grad{\phi} \cdot \nabla_\perp \times R^2 \; \mathcal{L} (\v)
		&= \grad{\phi} \cdot \nabla_\perp \times R^2 \left[ (\nabla\times\Q ) \times \B + \J \times Q 
		   + \grad{ (\v\cdot\grad{p} + \gamma p \div{\v}) } \right]\\
		&= \grad{\phi} \cdot \nabla_\perp \times \left[ (\nabla\times\Q ) \times R^2 \B + R^2 \J \times Q 
		   + R^2 \grad{ (\v\cdot\grad{p} + \gamma p \div{\v}) } \right]\\
		&= \grad{\phi} \cdot \nabla_\perp \times \left[ (\nabla\times\Q ) \times R^2 \B \right] 
		   + \grad{\phi} \cdot \nabla_\perp \times \left[ R^2 \J \times Q \right] \\
		   &+ \grad{\phi} \cdot \nabla_\perp \times \left[ R^2 \grad{ (\v\cdot\grad{p} + \gamma p \div{\v}) } \right]\\
	\end{array}
\end{equation}

\begin{comment}
