\subsection{Applying the 2nd projection operator}
\begin{equation}
	\begin{array}{rl}
	R^2 \grad{\phi} \cdot \mathcal{L} (\v)
		&= R^2 \grad{\phi} \cdot
		\left[ (\nabla\times\Q ) \times \B + \J \times Q 
		   + \grad{ (\v\cdot\grad{p} + \gamma p \div{\v}) } \right]\\
		&= \grad{\phi} \cdot \left[ (\nabla\times\Q ) \times R^2 \B + R^2 \J \times Q 
		   + R^2 \grad{ (\v\cdot\grad{p} + \gamma p \div{\v}) } \right]\\
		&=   \grad{\phi} \cdot \left[ (\nabla\times\Q ) \times R^2 \B \right] 
		   + \grad{\phi} \cdot \left[ R^2 \J \times Q \right] 
		   + \grad{\phi} \cdot \left[ R^2 \grad{ (\v\cdot\grad{p} + \gamma p \div{\v}) } \right]\\
	\end{array}
\end{equation}


\subsection{Applying the 3rd projection operator}
\begin{equation}
	\begin{array}{rl}
	\nabla_\perp \cdot \ff{1}{R^2} \mathcal{L} (\v)
		&= \nabla_\perp \cdot \ff{1}{R^2}
		\left[ (\nabla\times\Q ) \times \B + \J \times Q 
		   + \grad{ (\v\cdot\grad{p} + \gamma p \div{\v}) } \right]\\
		&= \nabla_\perp \cdot \left[ (\nabla\times\Q ) \times R^{-2} \B + R^{-2} \J \times Q 
		   + R^{-2} \grad{ (\v\cdot\grad{p} + \gamma p \div{\v}) } \right]\\
		&=   \nabla_\perp \cdot \left[ (\nabla\times\Q ) \times R^{-2} \B \right] 
		   + \nabla_\perp \cdot \left[ R^{-2} \J \times Q \right] 
		   + \nabla_\perp \cdot \left[ R^{-2} \grad{ (\v\cdot\grad{p} + \gamma p \div{\v}) } \right]\\
	\end{array}
\end{equation}
