		\theta \dt (n \v^{n+1} \cdot \grad{\v^n} + n \v^n \cdot \grad{\v^{n+1}}) -
		\nu \theta \dt \nabla^2 \v^{n+1} 
		\right]
	\\
		= & - \ff{1}{R^2} \grad{\nu_i} \cdot n \v^{n+1} \\ 
	          & + \ff{1}{R^2} \grad{\nu_i} \cdot \theta^2 \dt^2 \mathcal{L}(\v^{n+1}) \\
	          & - \ff{1}{R^2} \grad{\nu_i} \cdot \theta \dt \left( n \v^{n+1} \cdot \grad{\v^n} + n \v^n \cdot \grad{\v^{n+1}} \right) \\
		  & + \ff{1}{R^2} \grad{\nu_i} \cdot \nu \theta \dt \nabla^2 \v^{n+1} \\
           \equiv & I_3^1 + \theta^2 \dt^2 \; I_3^2 + \theta \dt \; I_3^3 + \nu \theta \dt \; I_3^4 
