\section{Appendix}
\begin{lem}\label{problem}
    Let $A_0<A_1<\dots<A_N$ be real numbers. We define sequences by recursion as follows:
    \begin{align*}
        &A_i^0=A_i,\hspace{0.5cm}\text{ for all } 0\leq i\leq N,\\
        &A_0^k=A_0,\,A_N^k=A_N,\,A_i^k=\frac{A_{i-1}^{k-1}+A_{i+1}^{k-1}}{2},\hspace{0.5cm}\text{ for all }1\leq i\leq N-1, \, k \ge 1.
    \end{align*}
    Then $A_i^k\to \frac{iA_N+(N-i)A_0}{N}$ as $k \rightarrow \infty$.
\end{lem}

\begin{proof}
    Let $(X_i^k)_{k\in\mathbb N}$ be a Markov Chain on $(A_0,\ldots,A_N)$ given by the transition matrix 
    \[
    P =
    \begin{bmatrix}
    1 & 0 & 0 & 0 & \dots & 0 & 0 & 0  \\
    \frac{1}{2} & 0 & \frac{1}{2} & 0 & \dots & 0 & 0 & 0  \\
    0 & \frac{1}{2} & 0 & \frac{1}{2} & \dots & 0 & 0 & 0  \\
    \vdots & \vdots & \vdots & \vdots &  & \vdots & \vdots & \vdots \\
    0 & 0 & 0 & 0 & \dots & \frac{1}{2} & 0 & \frac{1}{2} \\
    0 & 0 & 0 & 0 & \dots & 0 & 0 &1
    \end{bmatrix}
    \]
    and the inital distribution $\delta_{A_i}$. This is essentially a symmetric random walk with absorbing barriers $A_0$ and $A_N$. We clearly have $A_i^k=\mathbb{E}(X_i^k)$ and the probability that the random walk hits one of the barriers is $1$. However, it is not immediately clear what the probability of it hitting $A_N$ before $A_0$ is. We call this probability $P_i$. Then $P_0=0$ and $P_N=1$, while for $2\leq i\leq N$ we have $P_i=\frac{P_{i-1}+P_{i+1}}{2}$. This final expression is equivalent to 
    \begin{equation*}
    P_{i+1}-P_i=P_i-P_{i-1}=:\Delta.
    \end{equation*}
    We can now write
    \begin{equation*}
        1=P_N=P_N-P_{N-1}+P_{N-1}-P_{N-2}\pm\dots-P_0+P_0=N\Delta
    \end{equation*}
    This implies that $\Delta=1/N$ and $P_i=i/N$. Consequently we get $\mathbb{P}(X_i^k=A_N)\to \frac{i}{N}$, $\mathbb{P}(X_i^k=A_0)\to\frac{N-i}{N}$ and for $2\leq j\leq N$, we have $\mathbb{P}(X_i^k=A_j)\to 0$. Hence, finally,
    \begin{equation*}
        \lim_{k\to\infty}A_i^k=\lim_{k\to\infty}\mathbb{E}(X_i^k)=\sum_{j=0}^N \lim_{k\to\infty}\mathbb{P}(X_i^k=A_j)A_j=\frac{iA_N+(N-i)A_0}{N}.\qedhere
    \end{equation*} 
\end{proof}

