\subsection{Terminology}

Every graph discussed in this note is finite, simple, and undirected. $\mathbb{N}$ denotes the set of natural numbers (including $0$). For any positive integer $n$, we denote the set $\{1,2, \dots, n\}$ as $[n]$. Any undefined terms and notations are in accordance with \citet{chartrand2010graphs}.


\section{Proof of Theorem \ref{r5}} \label{s2}
We use exponential notation to indicate repeated sequences in the vertex so that a vertex $110001$ in $Q_6$ will be written as $1^2 0^3 1$. The \textit{hamming weight} $\operatorname{wt}(u)$ of a vertex $u$ is the distance of $u$ from $0^{n}$ in $Q_n$. As a warm-up, first we determine $\mp(Q_{n})$ for $n \leqslant 6$. It is easy to observe that  $\mp(Q_{1})=1, \mp(Q_{2})=1, \mp(Q_{3})=2, \mp(Q_{4})=2$ and $\mp(Q_{5})=2$. 
\begin{proposition}\label{propQ6}
$\mp(Q_{6})=4$.
\end{proposition}
\begin{proof}
One can observe that, since the set $\{0^6, 0^31^3, 1^30^3, 1^6\}$ is a multipacking in $Q_{6}$, $\mp(Q_{6}) \geqslant 4$. Now, we show that no set of order $5$ can be a multipacking in $Q_{6}$. On the contrary, let $P$ be a multipacking in $Q_{n}$ of $5$ vertices. As $Q_{n}$ is vertex-transitive, without loss of generality, suppose $0^{6} \in P$. Then $P$ cannot contain any vertex of hamming weight $1$ or $2$. Then $P \setminus \{0^{6}\} \subseteq N_{3}[1^{6}]$. Hence, $|N_{3}[1^{6}] \cap P|=4 > 3$, a contradiction to the fact that $P$ is a multipacking. Therefore, $\mp(Q_{6})=4$. 
\end{proof}

Since $Q_{n+1}$ contains a copy of $Q_n$ as a distance preserving subgraph, it is easy to observe that the multipacking number of $Q_n$ is monotonic in $n$. % This monotonicity property is utilized in the subsequent parts of the paper.
\begin{observation}\label{r0}
For any positive integer $n$, $\mp(Q_{n}) \leqslant \mp(Q_{n+1})$.
\end{observation}

\subsection{Lower bound}
We begin with a couple of lemmas needed for the recursive construction. Given a vertex \( x \in Q_n \), and an integer \( m \geqslant 1 \), we define \( i^m \cdot x \) as the binary string obtained by concatenating $i^m$ to \( x \), where $i \in \{0,1\}$. For any set of vertices $S$, $$i^m \cdot S=\{i^m \cdot x: x \in S\}.$$

%\begin{lemma}
%Let $n_{0} \geqslant n_{1}$ be two natural numbers and $Q_{n_0}$ and $Q_{n_1}$ be two hypercubes equipped with multipackings $P_{0}$ and $P_{1}$, respectively. Further, let $$
%$n = n_{0} + \max\left(|P_0|+|P_1| -1, 3\right),
%$$
%and $P$ be the set $$(0^{n - n_{0}} \cdot P_{0}) \cup (1^{n - n_{1}} \cdot P_{1}).$$ Then $P$ is a multipacking in $Q_n$.
%\end{lemma}

\begin{lemma}\label{r10}
Let $n_{0} \geqslant n_{1}$ be two positive integers, and $Q_{n_0}$ and $Q_{n_1}$ be two hypercubes equipped with multipackings $P_{0}$ and $P_{1}$, respectively. Further, let 
$$
    n = n_{0} + \max(|P_0|,2) + \max(|P_1|,2) -1,
$$ 
and $P$ be the set $$
(0^{n - n_{0}} \cdot P_{0}) \cup (1^{n - n_{1}} \cdot P_{1}).
$$ Then $P$ is a multipacking in $Q_n$.
\end{lemma}

\begin{proof}
Let $p = |P| = |P_{0}|+|P_{1}|$. Pick any $x \in V(Q_n)$ and any $k \in [p-1]$. We will show that the number of vertices of $P$ in $N_{k}[x]$ is at most $k$ by counting separately the number of vertices of $0^{n - n_{0}} \cdot P_{0}$ and $1^{n - n_{1}} \cdot P_{1}$ in $N_{k}[x]$.

Let $x_0$ denote the $n_0$-length suffix of $x$ (the last $n_0$ bits) and $x_1$ denote the $n_1$-length suffix of $x$. Let $q_0$ and $q_1$ respectively denote the number of zeros and ones in the first $(n - n_0)$ bits of $x$. For any vertex $y \in P_{0}$,  $d_{Q_n}(x,0^{n - n_{0}} \cdot y) = q_1 + d_{Q_{n_0}}(x_0, y)$. For any vertex $y \in P_{1}$, $d_{Q_n}(x,1^{n - n_{1}} \cdot y) \geqslant q_0 + d_{Q_{n_1}}(x_1, y)$. Hence we have
\begin{align} 
    |N_k[x] \cap P|
        & = |N_k[x] \cap 0^{n-n_{0}} \cdot P_{0}| 
            + |N_k[x] \cap 1^{n-n_{1}} \cdot P_{1}| \notag \\
        &\leqslant |N_{k-q_1}[x_0] \cap P_{0}|
            + |N_{k-q_0}[x_1] \cap P_{1}|. \label{eq2}
\end{align}

If both $(k - q_1)$ and $(k-q_0)$ are positive, then the right hand side of (\ref{eq2}) is bounded above by $(k - q_1) + (k - q_0)$, since $P_i$ is a multipacking in $Q_{n_i}$ for each $i \in \{0,1\}$. Since $(q_0 + q_1) = (n - n_0) \geqslant (p - 1) \geqslant k$, this bound is at most $k$ and we are done. If $(k - q_1) < 0$, then the right hand side of (\ref{eq2}) is bounded above by $0 + (k - q_0) \leqslant k$. The case when $(k - q_0) < 0$ is similar.
If $(k - q_1) = 0$ but $q_0 > 0$, then the right hand side of (\ref{eq2}) is bounded above by $1 + (k - q_0) \leqslant k$. The case when $(k - q_0) = 0$ but $q_1 > 0$ is also similar.

We are only left with two boundary cases, viz., $k - q_1 = 0 = q_0$ and $k - q_0 = 0 = q_1$. Here we use the fact that $n - n_0 = \max(|P_0|,2) + \max(|P_1|,2) -1 \geqslant \max\{|P_0|, |P_1|\} + 1$. In the first boundary case, since $q_0 = 0$, we have $q_1 = (n - n_0) \geqslant |P_1| + 1$. Further since $k - q_1 = 0$ in this case, we have $k = q_1 \geqslant |P_1| + 1$. Hence, the right-hand side of (\ref{eq2}), which is at most $1 + |P_1|$, is bounded above by $k$. The second boundary case ($k - q_0 = 0 = q_1$) is similar.
\end{proof}

%It should be noted that if $n = n_{0} + |P_0|+|P_1| -1$ (rather than $n_{0} + \max(|P_0|,2) + \max(|P_1|,2) -1$), then for small values of $n_0$ (particularly $n_0=1$ or $2$), the resulting set $P$ does not form a valid multipacking. In such cases, to ensure that $P$ is indeed a multipacking, the order of $Q_n$ must be at least three more than $n_0$. Therefore, one must consider ``$\max (|P_i|,2)$".

\begin{corollary}\label{r13}
Let $n_{0} \geqslant n_{1}$ be two positive integers. Let $\mp(Q_{n_0}) \geqslant p_0$ and $\mp(Q_{n_1}) \geqslant p_1$. Then $\mp(Q_n) \geqslant p_0+p_1$, where 
$$n = n_{0} + \max(p_0,2) + \max(p_1,2) - 1.$$
\end{corollary}
This recursive approach leads to a general lower bound of the multipacking number on hypercubes, which we formalize in the subsequent results. 
\begin{lemma}\label{r11}
For any positive integer $k$, $\mp(Q_{2k}) \geqslant k$.
\end{lemma}
\begin{proof}
We use induction on $k$. The statement is easy to verify for $k \leqslant 2$ and holds for $k=3$ by Proposition~\ref{propQ6}. Suppose $k \geqslant 4$ and that the statement holds for all natural numbers less than $k$. Due to the induction hypothesis, we have
$$\mp\left(Q_{2\left\lceil\frac{k}{2}\right\rceil}\right) \geqslant \left\lceil\frac{k}{2}\right\rceil,~ \text{and} \mp\left(Q_{2\left\lfloor\frac{k}{2}\right\rfloor}\right) \geqslant \left\lfloor\frac{k}{2}\right\rfloor.$$

Since $\left\lfloor\frac{k}{2}\right\rfloor \geqslant 2$, by Corollary \ref{r13}, we have 
$$
    \mp(Q_n) 
        \geqslant  \left\lceil\frac{k}{2}\right\rceil
        +           \left\lfloor\frac{k}{2}\right\rfloor\\
        = k,
$$
where
$$
    n   =  2 \left\lceil\frac{k}{2}\right\rceil
        +   \left\lceil\frac{k}{2}\right\rceil
        +   \left\lfloor\frac{k}{2}\right\rfloor
        -   1 
        \leqslant 2k.
$$
Hence by Observation \ref{r0}, we have $\mp(Q_{2k}) \geqslant k$.
\end{proof}

\noindent\prf ~If $n=1$, then $\mp(Q_1) > 0$. When $n$ is an even positive integer, the proof follows from Lemma \ref{r11}. When $n=2k+1$ is odd for some positive integer $k$, by Lemma \ref{r11} and Observation \ref{r0} we have, 
$$\mp(Q_n) = \mp(Q_{2k+1}) \geqslant \mp(Q_{2k}) \geqslant k = \left\lfloor \frac{n}{2} \right\rfloor.$$ \qed

Though we cannot improve the lower bound of $\left\lfloor \frac{n}{2} \right\rfloor$ in general, we show that $\mp(Q_n) - \left\lfloor \frac{n}{2} \right\rfloor$ can be arbitrarily large.
\begin{proposition}
For every positive integer $i$, $\mp(Q_{n_i}) \geqslant \frac{n_i}{2} + \frac{\log_2 n_i - 1}{2}$, where $n_i = 2^{i+1} - i$.
\end{proposition}
\begin{proof}
We construct a specific sequence of hypercubes \( \{Q_{n_i}\} \) by repeatedly applying Corollary \ref{r13} starting from \( Q_3 \), for which the multipacking number is $2$. Hence, we consider \( n_1 = 3 \) and \( p_1 = 2 \). At each step, we consider two identical copies multipacking of the hypercube $Q_{n_{i}}$, and using Lemma $\ref{r10}$, we obtain a multipacking of $Q_{n_{i+1}}$. We continue this process indefinitely and obtain the recurrence relations
\[
n_i = n_{i-1} + 2p_{i-1} - 1, \quad p_i = 2p_{i-1}.  
\] 
On solving these recurrence relations with initial conditions \( n_1 = 3 \) and \( p_1 = 2 \), we obtain
\[
n_i = 2^{i+1} - i , \quad p_i = 2^i \quad\text{for all } i \geqslant 1.
\] From $n_i = 2^{i+1} - i$, we get $p_i = \frac{n_i}{2} + \frac{i}{2}$, and using $n_i \leqslant 2^{i+1}$, it follows that $i \geqslant \log_2 n_i - 1$. As \( \mp(Q_{n_i}) \geqslant p_i  \), we have $$\mp(Q_{n_i}) \geqslant \frac{n_i}{2} + \frac{\log_2 n_i - 1}{2}.$$
\end{proof}

\subsection{Upper bound}
Suppose we have a finite family of sets with finite elements, and we intend to color the underlying set with two colors such that each subset has roughly half of each color. The discrepancy quantifies how unbalanced any set in the family can be under the best possible two-coloring of the underlying set. Formally, let $\mathcal{A}$ be a family of subsets of $\Omega$, and consider the coloring as a mapping $$\chi: \Omega \rightarrow \{-1,+1\}.$$ Suppose for every $A \subseteq \Omega$, $\chi(A)=\sum_{a \in A} \chi(a)$. Then, the discrepancy of $\mathcal{A}$ with respect to $\chi$ is defined as $$\disc(\mathcal{A}, \chi) = \max_{A \in \mathcal{A}} |\chi(A)|.$$ The discrepancy of $\mathcal{A}$ is defined as $$\disc(\mathcal{A}) = \min_{\chi: \Omega \rightarrow\{-1,+1\}} \disc(\mathcal{A}, \chi).$$ \\[0.5em]
Let's recall a classic result due to \citet{spencer1985six} from the discrepancy theory. 
\begin{theorem}\emph{\cite{spencer1985six}} \label{disc}
	Let $\mathcal{A}$ be a family of $n$ subsets of an $n$-element set $\Omega$. Then $$\disc(\mathcal{A}) \leqslant 6\sqrt{n}.$$
\end{theorem}

The next lemma establishes an upper bound on $\mp(Q_n)$ using this bound. 

\begin{lemma}\label{lemUB}
For any positive integer $n$, we have
$$\mp(Q_n) 
    \leqslant \frac{n}{2} + 6\sqrt{2 \mp(Q_n)}
$$
\end{lemma}

\begin{proof}
Let $P=\{x_1, x_2, \dots, x_p\}$ be a maximum multipacking in $Q_n$ of size $p ~(\geqslant \frac{n}{2})$. For each $x_i \in P$, we construct a set $A_i \subseteq [n]$ comprising of the coordinates at which $x_i$ has $1$, and $\overline{A_i}= [n] \setminus A_i$. In particular, $\overline{A_i}$ contains the coordinate values at which $x_i$ has $0$. Now, consider the family of $2p$ sets $$\mathcal{A}=\{A_1, \overline{A_1}, A_2, \overline{A_2}, \dots, A_{p}, \overline{A_{p}}\},$$ with the underlying set $\Omega = [2p] \supseteq [n]$. Let $\chi$ be a mapping such that $\disc(\mathcal{A}, \chi) = \disc(\mathcal{A})$. For each $i \in [n]$, if $\chi(i) = -1$, then we flip the bit at the $i$-th coordinate for all the vertices of $Q_n$. All such flippings induce an automorphism $\varphi$ on the vertex set of $Q_n$. Hence, the set $P$ contains new vertices of $Q_n$. Further, a bit-flipping preserves the hamming distance, and therefore $P$ is still a multipacking in $Q_n$.

	%Such flipping does not alter the hamming distances and hence the set $P$, with a new collection of vertices, is still a multipacking of $Q_n$. Consequently, every element of $P'$ is replaced by a new element of $P$.\\[0.5em]
    Since, for each $i \in [n]$, $|\chi(A_i)|, |\chi(\overline{A_i})| \leqslant \disc(\mathcal{A})$, the number of ones in  $\varphi(x_i)$ is %at least $\left(\frac{|A_i|}{2} - \frac{\disc(\mathcal{A})}{2}\right) + \left(\frac{|\overline{A_i}|}{2} - \frac{\disc(\mathcal{A})}{2}\right)$ = $\frac{n}{2} - \disc(\mathcal{A})$ and 
    at most $\left(\frac{|A_i|}{2} + \frac{\disc(\mathcal{A})}{2}\right) + \left(\frac{|\overline{A_i}|}{2} + \frac{\disc(\mathcal{A})}{2}\right)$ = $\frac{n}{2} +
	\disc(\mathcal{A})$. Hence $\operatorname{wt}(x_i) \leqslant \frac{n}{2} + \disc(\mathcal{A})$ for every $x_i \in P$ after flipping. 
	%Without loss of generality, let's consider that at least half of the elements of $P\setminus P'$ have hamming weight less than $\frac{n}{2}$. Suppose $P'' \subset P\setminus P'$ is such a set. Hence, $|P' \cup P''| \geqslant \frac{n}{2} + \frac{k}{2}$. 
	This means that, after flipping, $P \subseteq N_{\frac{n}{2} + \disc(\mathcal{A})}[0^n]$. As $P$ is still a multipacking, we have $$|P| \leqslant \frac{n}{2} + \disc(\mathcal{A}) \leqslant \frac{n}{2} + 6\sqrt{2p},$$ where the last inequality is due to Theorem \ref{disc}. As $P$ is a maximum multipacking in $Q_n$, we have the desired upper bound. 
\end{proof}

\noindent \prff~ The upper bound $\mp(Q_n) \leqslant \frac{n}{2} + 6\sqrt{2n}$ in Theorem~\ref{r5} now follows from Lemma~\ref{lemUB} since  $\mp(Q_n) \leqslant n$. \qed

