    \label{eq:HadronicTensorDnbar}\bigl[\mathcal{W}^{\mu\nu}\bigr]_{D\nbar}^{(3,2)}
    &=
    \biggl(\frac{n^\mu}{q^+}-\frac{\nbar^\mu}{q^-}\biggr)
    \int\frac{\df^2 b}{(2\pi)^2}\,e^{+\img q_T \cdot b_T}\,
    \int\frac{\df b^+}{2\pi}\,e^{+\img q^- b^+}\,
    \int\frac{\df b^-}{2\pi}\,e^{+\img q^+ b^-}\,
    \\\nonumber
    &\quad\times
    (\gamma_T^\rho)_{\alpha\beta}
    (\gamma_T^\nu)_{\gamma\delta}
    \int\df y_1^-\,\df y_2^-\df y^+\,C_2(\{y_1^-,y_2^-\},y^+)\,
    \int\df z^-\,\df z^+\,C_1^*(z^-,z^+)\,
    \\\nonumber
    &\quad\times
    \grn{\bra{P}\bigl[\bar\chi(b_T + b^- n + y_1^- n)
    \mathcal{A}_T^\rho(b_T + b^- n + y_2^- n)\bigr]_{i,\alpha}\ket{X}}
    \grn{\bra{X}\chi_{l,\delta}(z^- n)\ket{P}}
    \\\nonumber
    &\quad\times
    \blu{\bra{0}\chi_{j,\beta}(b_T + b^+ \nbar + y^+ \nbar)\ket{p,X}}
    \blu{\bra{p,X}\bar\chi_{k,\gamma}(z^+ \nbar)\ket{0}}
    \\\nonumber
    &\quad\times
    \orn{\bra{0}\bigl[S_\nbar^\dagger S_n (b_T)\bigr]_{ij}\ket{X}}
    \orn{\bra{X}\bigl[S_n^\dagger S_\nbar (0)\bigr]_{kl}\ket{0}}\,,
\end{align}
After proper subtraction of rapidity divergences, these terms form the genuine twist-3 contribution at NLP.

\subsubsection*{NLP: soft gluon contribution}

We now consider the contribution of the soft gluon operators where the inverse derivative acts on a collinear or anti-collinear field. In this case the inverse derivative can be replaced by $q^\pm$ by virtue of eq.~\eqref{eq:InverseDerivativeIdentity}. We then find the following contributions
\begin{align}
