    \\\nonumber
    &\qquad\times
    \biggl\{
    \frac{\grn{\bra{P}\bigl[\bar\chi(b_T + b_1^- n)
    \fsl{\mathcal{A}}_T(b_T + b_2^- n)\bigr]_{i,\alpha}\ket{X}
