    \\\nonumber
    &\qquad\qquad\qquad\times
    \orn{\frac{1}{N_c}\tr\Bigl[\bra{0} S_\nbar^\dagger S_n (b_T)\,
    \mathcal{A}_{T,n}^\rho(b_T + b_2^+ \nbar)\ket{X}
    \bra{X} S_n^\dagger S_\nbar(0)\ket{0}\Bigr]}
    \biggr\}\,,
    \\[6ex]
    &\blu{\bigl[\mathcal{D}_{q,12}^\text{bare}(z,\xi,b_T,\zeta)\bigr]_{\delta\alpha}}
    \\\nonumber
    &=-\img q^-\int\frac{\df b_1^+}{2\pi}\,\frac{\df b_2^+}{2\pi}\,
