\begin{mdframed}
 \begin{analogy}
There is an analogy between the Wiener--Hopf equations for continuous and lattice problems: 
\[
\Psi^-_d(s) = K_d(s)\Psi^+_d(s) + F_d(s) \Longleftrightarrow \Psi^-_c(\xi) = K_c(\xi)\Psi^+_c(\xi) + F_c(\xi),
\]
 where
 \begin{itemize}
 \item the functions $\Psi^+_d(s)$ and $\Psi^-_d(s)$ are analytic inside and outside the unit circle, respectively and the Wiener--Hopf equation is valid on the unit circle.
     \item the functions ${\Psi}_c^-(\xi)$ and ${\Psi}_c^+(\xi)$ are analytical in the lower and the upper half-planes respectively and the Wiener--Hopf equation is valid on the line $(-\infty,\infty)$;
     \item  there is a function $\mathcal{K}\!$, called the \emph{generating kernel function}, such that
     \[
K_d(s) = \mathcal{K}\!\left[\Upsilon(\lx),\lx^M,\ly^N\right],\quad K_c(\xi) = \mathcal{K}\!\left[i\gamma(\xi),\exp\{i\xi a\},\exp\{i\gamma(\xi) b\}\right];
\]
     \item there is a function ${\mathcal{F}}\!$, called the \emph{generating forcing function}, such that
\begin{align*}
F_d(s) &=\mathcal{F}\!\left[1 - \lx\left(\lx^{\rm in}\right)^{-1},1 - \lx\lx^{\rm in},(\lx^{\rm in})^M,(\ly^{\rm in})^N,\Upsilon(s),\Upsilon(s^{\rm in})\right],\\
F_c(\xi) &=\mathcal{F}\!\left[i\kstar-i\xi,-i\kstar-i\xi,\exp\{i \xi^{\rm in} a\},\exp\{i\gamma(\xi^{\rm in}) b\},i\gamma(\xi),i\gamma(\xi^{\rm in})\right].
\end{align*}
 \end{itemize}
 \end{analogy}
 \end{mdframed}
