\subsection{Finite strip}
The geometry of the problem is shown in Figure~\ref{fig:strip_geometry}.
\begin{figure}[htbp!]
    \centering
    \includegraphics[width=0.8\linewidth]{figures/strip.pdf}
    \caption{Geometry of the continuous and lattice problems of diffraction by a finite strip}
    \label{fig:strip_geometry}
\end{figure}

Let the Dirichlet boundary conditions be satisfied on the strip:
\[
u(x,0)=0,\quad x\in(-a,a),\quad u(m,0) = 0,\quad  m \in[-M,M].
\]

Using Green's identity \cite{korolkov2024recycling,kisil2018aerodynamic}  one can derive \RED{a} $2 \times 2$ matrix Wiener--Hopf equation of the type (\ref{eq:WH_mat}) for the continuous problem and of the type (\ref{eq:WH_mat_lat}) for the lattice problem with
\[
\rmU^\pm_c=
\begin{pmatrix}
U^\pm_c \\
W^\pm_c
\end{pmatrix},
\quad
{\rmA}_c=
\begin{pmatrix}
-\exp\{2i\xi a\} &  (i\gamma)^{-1} \\
0 &\exp\{-2i\xi a\}
\end{pmatrix},\quad
{\rm F}_c = \frac{i \exp\{i\kstar a\}}{\xi-\kstar}
\begin{pmatrix}
1\\
0
\end{pmatrix},
\]
\begin{align*}
U^-_c(\xi)  &= \exp\{i\xi a\}\int_{-\infty}^{-a} \exp\{i\xi x\}u^{\rm sc}(x,0) dx,\\
W^-_c(\xi)  &= \exp\{-i\xi a\}\int_{-a}^{a} \exp\{i\xi x\}\frac{\ptl u^{\rm sc}}{\ptl y}(x,0) dx,\\
U^+_c(\xi) &= \exp\{-i\xi a\}\int_a^\infty \exp\{i\xi x\}u^{\rm sc}(x,0)dx + \frac{i\exp\{-i\kstar a\}}{\xi-\kstar},\\
W^+_c(\xi)  &= \exp\{i\xi a\}\int_{-a}^{a} \exp\{i\xi x\}\frac{\ptl u^{\rm sc}}{\ptl y}(x,0) dx,
\end{align*}
for the continuous problem, and 
\[
\rmU^\pm_d=
\begin{pmatrix}
U^\pm_d \\
W^\pm_d
\end{pmatrix},
\quad
{\rmA}_d=
\begin{pmatrix}
-\lx^{2M} &  \Upsilon^{-1} \\
0 &\lx^{-2M}
\end{pmatrix},\quad
{\rm F}_d =   \frac{(\lx^{\rm in})^{M}}{1 - \lx\left(\lx^{\rm in}\right)^{-1}}
\begin{pmatrix}
1\\
0
\end{pmatrix},
\]

\begin{alignat*}{2}
U_d^-(\lx) &= \lx^{M}\sum_{m=-\infty}^{-M-1}\lx^{m}u^{\rm sc}(m,0),
& \quad &
U_d^+(\lx) = \lx^{-M}\sum_{m=M+1}^{\infty}\lx^{m}u^{\rm sc}(m,0)+\frac{(s^{\rm in})^{-M}}{1 - \lx\left(\lx^{\rm in}\right)^{-1}},\\
W_d^-(\lx) &= \lx^{-M}\sum_{m=-M}^{M}\lx^{m}\ptl_{(m,0)}[u^{\rm sc}],&\quad& W_d^+(\lx) = \lx^{M}\sum_{m=-M}^{M}\lx^{m}\ptl_{(m,0)}[u^{\rm sc}],
\end{alignat*}
\RED{for the lattice problem}. 
For both problems $\rmA_{c,d}$ is an upper triangular matrix, but for the continuous problem it grows exponentially at infinity, while for the lattice problem, it has polynomial growth. It is worth mentioning that the lattice problem was studied in \cite{sharma2015near2,medvedeva2024diffraction}. Another interesting observation is that kernel $\rmA_d$ falls into a class of branch commutative matrices \cite{shanin2012criteria}, i.e.\ it can be factorised using ideas \RED{from} \cite{zverovich1971boundary, antipov2002factorization}, and the solution of the problem can be presented in terms of elliptic integrals. Such a solution can be of practical importance, as there is no analytical solution available for the continuous problem. For example, one can study how the lattice solution approaches the solution of the continuous problem in the limit $h\to0$. 

\RED{The analogy holds in this case also since
\begin{alignat*}{2}
\rmA_c(\xi) &= \gK\left[i\gamma,\exp\{2i\xi a\}\right], & \quad & \rmF_c(\xi)=\gF\left[i\kstar - i\xi,\exp\{i\kstar a\}\right], \\
\rmA_d(\lx) &= \gK\left[\Upsilon,\lx^{2M}\right], &\quad& \rmF_d(\lx)=\gF\left[1 - \lx\left(\lx^{\rm in}\right)^{-1},(\lx^{\rm in})^{M}\right],
\end{alignat*}
where the generating functions $\gK$ and $\gF$ are given by:}
\[
\gK\left[t_1,t_2\right] = 
\begin{pmatrix}
t_2 & t_1 \\
0 & (t_2)^{-1} 
\end{pmatrix},
\quad 
\gF\left[t_1,t_2\right] =
\frac{t_2}{t_1}
\begin{pmatrix}
1\\
0
\end{pmatrix}.
\]
