\section{The method of analogies in 3D}
\label{sec:3D}
\subsection{Green's identity}
Green's identity can be easily extended to three-dimensional problems. Indeed, in the continuous case
we have
\[
\int_{\ptl \Omega}\left[u\frac{\ptl w}{\ptl \bn}-w\frac{\ptl u}{\ptl \bn}\right] d\RED{S}= \int_\Omega(fw - gu)dV,
\]
where  $w,u$  are solutions of \RED{the} 3D Helmholtz equations
\[
\Delta u(x,y,z) + k^2 u(x,y,z) = f(x,y,z),\quad \Delta w(x,y,z) + k^2 w(x,y,z) = g(x,y,z),  
\]
$\Omega$ is a closed domain with boundary $\ptl \Omega$, and $\bn$ is the unit inward normal on $\ptl \Omega$.  

To introduce  3D Green's identity on lattices we need, as in \RED{the} 2D case, to introduce an analogue of the normal derivative.  Let us consider a cubic lattice and a pair of functions that satisfy the discrete Helmholtz equation:
\begin{equation}
\Delta_{(m,n,\ell)}[u] + \lk^2u(m,n,\ell) = f(m,n,\ell),\quad
\Delta_{(m,n,\ell)}[w] + \lk^2w(m,n,\ell) = g(m,n,\ell),
\end{equation}
where $\Delta_{(m,n,k)}[u]$ is the 3D discrete Laplace operator, which is a 7-point finite difference approximation of the continuous Laplace operator:
\begin{align*}
\Delta_{(m,n,\ell)}[u] &= u(m+1,n,\ell)+u(m-1,n,\ell)+ u(m,n+1,\ell)+u(m,n-1,\ell) \\
&+u(m,n,\ell+1)+u(m,n,\ell-1) - 6u(m,n,\ell).
\end{align*}

%\BLUE{NOTE to AK: I'm a bit worried about the use of $k$ as the third index as it is the wavenumber for the continuous case. Maybe $\ell$ if not already used?}

%\BLUE{NOTE to AK: Should we also introduce $\Delta_{m,n}[u]$ in the 2D case for consistency?}

\RED{As in the 2D case}, let $\Omega$ be a closed domain \RED{of a 3D lattice} with boundary $\ptl\Omega$, \RED{and introduce} the multi-index ${\bnu} = (m,n,\ell)$. We can \RED{then} re-write the Helmholtz equation\RED{s} in a \RED{condensed} form \RED{similar to (\ref{eq:disc_Helm})}: 
\begin{equation}
\label{eq:disc_Helm_3D}
\sum_{{\bmu}\in\Omega\cup\ptl\Omega}\beta_{{\bnu}{\bmu}}u_{{\bmu}} = f_{\bnu}, \quad \sum_{{\bmu}\in\Omega\cup\ptl\Omega}\beta_{{\bnu}{\bmu}}w_{{\bmu}} = g_{\bnu}, \quad {\bnu} \in \Omega,
\end{equation}
where the coefficients $\beta_{{\bnu}{\bmu}}$ are defined as follows:
\[
\beta_{{\bnu}{\bmu}}=\begin{cases}
1, & {\bnu}\neq {\bmu}, \text{ ${\bnu}$ is adjacent \RED{to} ${\bmu}$}\\
\lk^2 - 6, & {\bnu} = {\bmu},\\
0, & \text{otherwise}.
\end{cases}
\]

Finally, \RED{we} introduce the discrete normal derivative
\[
\ptl_{\bnu}[u] = \sum_{{\bmu} \in \ptl \Omega\cup\Omega_{\rm adj}} \alpha_{{\bnu}{\bmu}} u_{\bmu} ,\quad {\bnu}\in \ptl\Omega,
\]
where $\Omega_{\rm adj}$ is the set of all nodes of $\Omega$ adjacent to the boundary.
There are 7 possible boundary configurations,  $\alpha_{{\bnu}{\bmu}}$ having the following structure:
\[
\alpha_{{\bnu}{\bmu}}=\begin{cases}
p/4, & {\bnu}\neq {\bmu}, \text{ ${\bnu}$ is adjacent \RED{to} ${\bmu}$, ${\bmu} \in \ptl \Omega$  }\\
1, & {\bnu}\neq {\bmu}, \text{ ${\bnu}$ is adjacent \RED{to} ${\bmu}$, ${\bmu} \in \Omega_{\rm adj}$}\\
l(\lk^2 - 6)/8, & {\bnu} = {\bmu},\\
0, & \text{otherwise},
\end{cases}
\]
where $p$ is some natural number between $1$ and $4$, and $l$ is some natural number between $1$ and $8$. The exact expression can be deduced by expanding the FEM procedure described in Appendix~\ref{app:FEM} to \RED{3D}. Below we consider only the problem of diffraction by a quarter-plane where $\alpha_{{\bnu}{\bmu}}$ corresponding to the planar part of the boundary is used. In this particular case $p=2$, $l=4$, as \RED{can be shown} directly from the symmetry of the problem.

\RED{As in the 2D case,} using  the symmetry of coefficients, we obtain the \RED{3D discrete} Green's identity:
\begin{equation}
\label{Green's_lattice_3D}
\sum_{{\bnu} \in \ptl \Omega} \left(\ptl_{\bnu}[u] w_{\bnu}  - \ptl_{\bnu}[w] u_{\bnu}\right) =    \sum_{{\bnu} \in \Omega}\left(g_{\bnu} u_{\bnu}-f_{\bnu} w_{\bnu}\right).
\end{equation}

\subsection{Dispersion \RED{relation}}
Let us seek solutions to the homogeneous Helmholtz equation 
\begin{equation}
\label{eq:Helm3d}
(\Delta +k^2)u(x,y\RED{,z}) = 0,
\end{equation}
where $k$ is the wavenumber\RED{, of the form}
%Let the total field be expressed in the form
\[
u(x,y) = \exp\{i\xi_1 x  + i\xi_2y+  i\gamma z \},
\]
\RED{for some complex numbers} $\xi_1,\xi_2,\gamma$.  Substituting the latter into the Helmholtz equation \RED{and introducing $\bdxi\equiv(\xi_1,\xi_2)$,} we get \RED{the dispersion relation}: 
\[
\RED{D_c}(\bdxi,\gamma) = -\xi_1^2 - \xi_2^2 - \gamma^2 +k^2 = 0.
\]
 Solving the latter with respect to $\gamma$ we obtain:
\[
\gamma(\bdxi)  = \sqrt{k^2 - \xi_1^2-\xi_2^2}.
\]
