\subsection{Diffraction by a Dirichlet quarter-plane}
\RED{The important canonical} problem of diffraction by a quarter-plane is the simplest generalisation of Sommerfeld's half-plane problem into 3 dimensions. \RED{In the continuous case, as we will briefly recall below, it is known that it can be formulated as a scalar Wiener--Hopf problem in two complex variables. Despite the fact that no closed-form solution to this problem is yet known, recent progress have been made by exploiting this two-complex-variables functional equation  \cite{assier2019diffraction,AssierAbrahamsSIAP21,AssierShanin2021Vertex,assier2024contribution}. To the authors knowledge, however, the discrete counterpart of the quarter-plane problem has not yet been considered. We will show below that it can also be formulated as a two-complex-variables Wiener--Hopf problem, and that an analogy, akin to that presented in Section~\ref{sec:analogy}, also holds in this case.}

%however, we should note some recent progress \cite{assier2019diffraction,assier2024contribution}. 
\subsubsection{\RED{The} continuous problem}
\RED{We study the diffraction of an incident plane wave $u^{\rm in}$ by a quarter-plane $\rm QP$ subjected to Dirichlet boundary conditions.} The geometry of the problem is sketched in Figure~\ref{fig:quarterplane}. 
\begin{figure}[htbp!]
    \centering
    \includegraphics[width=0.8\linewidth]{figures/quarter_plane.pdf}
    \caption{Geometry of the problem of diffraction by a quarter-plane}
    \label{fig:quarterplane}
\end{figure}
The total field $u$ satisfies the Helmholtz equation 
\[
(\Delta + k^2)u(x,y,z) = 0
\]
everywhere except \RED{on} the quarter-plane, \RED{where a Dirichlet boundary condition is imposed:}
\[
\RED{u|_{\rm QP}=0, \quad {\rm QP}=\{x\geq 0,y\geq0,z=0\}}.
\]
% \[
% u(x,y,0) = 0, \quad (x,y) \in {\rm QP} = \{x\geq 0,y\geq0\}.
% \]
The total field $u$ can be written as the sum of the incident plane wave $u^{\rm in}$ and the \RED{scattered} field $u^{\rm sc}$:
\[
u = u^{\rm sc} + u^{\rm in}, 
\]
\[
u^{\rm in}\RED{(x,y,z)} = \exp\{-i\xi^{\rm in}_1x - i\xi^{\rm in}_2y-i\xi^{\rm in}_3z\},\quad \xi^{\rm in}_3 = \sqrt{k^2 - \left(\xi^{\rm in}_1\right)^2 - \left(\xi^{\rm in}_2\right)^2}.
\]
%\BLUE{AK: please check the signs inside the exponential for the incident wave, it looks different to \cite{assier2019diffraction} and \cite{AssierAbrahamsSIAP21}. Ok I've checked and I think it's ok: your $k_{1,2}$ are minus the $k_{1,2}$ of \cite{assier2019diffraction}, but they correspond to the $a_{1,2}$ of \cite{AssierAbrahamsSIAP21}. The obtained forcing is consistent.}
%\BLUE{NOTE: For consistency, I think it'd be best to use $\xi^{\rm in}_{1,2}$ instead of $k_{1,2}$ actually.}
\RED{For the problem to be well-posed,} the scattered field should satisfy the radiation condition as well as Meixner conditions at the edges and  at the vertex (see \cite{assier2019diffraction}). 

Using a symmetry argument, \RED{one} can show that $u^{\rm sc}$ satisfies Neumann boundary conditions on the rest of the plane $z=0$:
\[
\frac{\ptl u^{\rm sc}}{\ptl z}(x,y,0)=0, \quad \RED{(x,y,0)\notin {\rm QP}}.
\]
% \[
% \frac{\ptl u^{\rm sc}}{\ptl z}(x,y,0)=0, \quad (x,y)\in \mathbb{R}^2\setminus{\rm QP}.
% \]

\RED{Following \cite{assier2019diffraction}, } the Wiener--Hopf equation \RED{can be derived by applying} Green's identity in the upper half-space $z>0$ (\RED{through} a limiting procedure similar to the one considered in 2D, see~Figure~\ref{fig:Green_dom_cont}, right), with the auxiliary  function
\[
w(\bdxi) = \exp\{i\xi_1 x +i\xi_2 y + i\gamma(\bdxi)z\}.
\]
After some algebra, we obtain: 
\begin{equation}
\label{eq:WH_3D}
U_c(\bdxi)=K_c(\bdxi)W_c(\bdxi) + F_c(\bdxi),  
\end{equation}
where \RED{the kernel $K_c$ and forcing $F_c$ are given by}
\[
K_c(\bdxi)=\frac{1}{i\gamma(\bdxi)},\quad F_c(\bdxi)=-\frac{1}{(\xi_1 - \xi^{\rm in}_1)(\xi_2 - \xi^{\rm in}_2)}.
\]
\RED{The unknown spectral function}  $W_c(\bdxi)$ is defined as
\[
W_c(\bdxi) = \iint_{\RED{{\rm Q}_1}} \frac{\ptl u^{\rm sc}}{\ptl z}(x,y,0\RED{^+})\exp\{i\xi_1 x + i\xi_2 y\}\green{dx dy},
\]
% \[
% W_c(\bdxi) = \iint_{\rm QP} \frac{\ptl u^{\rm sc}}{\ptl z}(x,y,0)\exp\{i\xi_1 x + i\xi_2 y\}d\xi_1\wedge d\xi_2,
% \]
\RED{where ${\rm Q}_1=\{x\geq0,y\geq0\}$}, \RED{while} the unknown spectral function $U_c(\bdxi)$ \RED{is defined by}
\[
U_c(\bdxi) = \iint_{\mathbb{R}_2\RED{\setminus{\rm Q}_1}} u^{\rm sc}(x,y,0)\exp\{i\xi_1 x + i\xi_2 y\}\green{dx dy}.
\]
% \[
% U_c(\bdxi) = \iint_{\mathbb{R}_2/{\rm QP}} u^{\rm sc}(x,y,0)\exp\{i\xi_1 x + i\xi_2 y\}d\xi_1\wedge d\xi_2.
% \]
\RED{The} equation (\ref{eq:WH_3D}) is a two-complex-variables scalar Wiener--Hopf equation \RED{with kernel $K_c$, forcing $F_c$, and} unknowns $W_c$ and $U_c$. \RED{It is valid on the $(\xi_1,\xi_2)$ real plane}. To have a unique solution it should be supported with additional analyticity conditions, see \cite{assier2019diffraction}.

\subsubsection{\RED{The} lattice problem}
\RED{For the discrete quarter-plane problem, see Figure \ref{fig:quarterplane} (right),} the total field $u_{\bnu}$ satisfies the discrete Helmholtz equation
\[
\Delta_{\bnu}[u] + \lk^2 u_{\bnu} = \RED{0}%f_{\bnu}
\]
everywhere except \RED{on} the quarter-plane, where \RED{it} satisfies Dirichlet boundary conditions:
\[
u_{\bnu} = 0, \quad {\bnu} \in {\rm QP} = \{m\geq 0, n\geq0,\ell =0\}. 
\]
The total field \RED{is the sum of the incident wave and the scattered field}: 
\[
u_{\bnu} = u^{\rm sc}_{\bnu} + u^{\rm in}_\bnu, \quad  u^{\rm in}(m,n,\ell) = (\lx_1^{\rm in})^{-m}(\lx_2^{\rm in})^{-n}(\ly^{\rm in})^{-\ell},
\]
where $\lx_1^{\rm in},\lx_2^{\rm in}, \ly^{\rm in}$ satisfy the dispersion relation (\ref{eq:disp_rel3D_lat}). The scattered field should satisfy the radiation condition, which as we mentioned before might not be possible for some values of $\lk$, which we exclude from \RED{our} consideration. 

Using a symmetry argument we can introduce a lattice Neumann boundary condition on the rest of the plane $k=0$: 
\[
\ptl_{(m,n,0)}[u^{\rm sc}] = 0,  \quad \RED{(m,n,0) \notin {\rm QP}},
\]
\RED{where} $\ptl_{(m,n,0)}[\cdot]$ is the lattice normal derivative \RED{defined by}
\begin{align*}
\ptl_{(m,n,0)}[u] &= \frac{1}{2}\left[u(m+1,n,0)+u(m-1,n,0)+ u(m,n+1,0)+u(m,n-1,0)\right] \\
&+(3-\lk^2/2)u(m,n,0)+u(m,n,1).
\end{align*}
Then, analogously to the continuous case, applying Green's identity in the upper half-space with the outgoing wave
\[
w(m,n,\ell) = \lx_1^m\lx_2^n\ly^\ell,
\]
we obtain the following functional equation:
\begin{equation}
\label{eq:WH_eq3D_lat}
U_d(\blx) = K_d(\blx)W_d(\blx) +  F_d(\blx). 
\end{equation}
\RED{The kernel $K_d$ and the forcing $F_d$ are given by}
\[
K_d(\blx)=\frac{1}{\Upsilon(\blx)}, \quad F_d(\blx) =  \frac{1}{\left(1 - \lx_1\left(\lx_1^{\rm in}\right)^{-1}\right)\left(1 - \lx_2\left(\lx_2^{\rm in}\right)^{-1}\right)},
\]
\RED{while the unknown spectral functions $U_d$ and $W_d$ are defined by}
\[
W_d(\blx) = \sum_{(m,n) \in \RED{{\rm Q}_1}} \ptl_{(m,n,0)}[u]\lx_1^m\lx_2^n, \quad U_d(\blx) = \sum_{(m,n) \in \RED{\mathbb{Z}^2\setminus{\rm Q}_1}} u(m,n,0)\lx_1^m\lx_2^n,
\]
\RED{where ${\rm Q}_1=\{(m,n)\in\mathbb{Z}^2: m\geq0, n\geq0\}$}.

\RED{The} equation (\ref{eq:WH_eq3D_lat}) is a 2D Wiener---Hopf equation \RED{valid on the} direct product of two unit circles (a torus). 

Equations (\ref{eq:WH_3D}) and (\ref{eq:WH_eq3D_lat}) have a similar structure, and the analogy can be built in the same way as it was done in Section~\ref{sec:analogy}. That is we can find some kernel generating function $\mathcal{K}$ and forcing generating function $\mathcal{F}$ such that
\RED{
\begin{alignat*}{2}
  & K_c(\bdxi)=\mathcal{K}\!\left[ i\gamma(\bdxi)\right]  \quad && F_c(\bdxi)=\mathcal{F}\!\left[ (i\xi_1 -i \xi_1^{\rm in})(i\xi_2 - i\xi_2^{\rm in})\right]\\
  & K_d(\blx)=\mathcal{K}\!\left[ \Upsilon(\blx)\right], \quad &&    F_d(\blx)=\mathcal{F}\!\left[ \left(1 - \lx_1\left(\lx_1^{\rm in}\right)^{-1}\right)\left(1 - \lx_2\left(\lx_2^{\rm in}\right)^{-1}\right) \right].
\end{alignat*}
For the quarter-plane problem we therefore recover the same generating functions as for the half-plane problem, namely
\[
\mathcal{K}\!\left[t\right]=\frac{1}{t}, \quad \mathcal{F}\!\left[t\right]=\frac{1}{t}.
\]
}

