\title{Optimizing Cognitive Networks: Reinforcement Learning Meets Energy Harvesting over Cascaded Channels
}

  \author{Deemah H. Tashman,~\IEEEmembership{Member, IEEE}, Soumaya Cherkaoui,~\IEEEmembership{Senior Member, IEEE}, and Walaa Hamouda,~\IEEEmembership{Senior Member, IEEE}
\thanks{D. Tashman and S. Cherkaoui are with the Department of Computer  and Software Engineering, Polytechnique Montreal, Montreal, QC, Canada,  H3T 1J4 (e-mail: \{deemah.tashman, soumaya.cherkaoui\}@polymtl.ca).} 
