			\centering
			\includegraphics[width=\linewidth]{Figure_2a.eps}
			\caption{}
			\label{fig:Figure_2a}
		\end{subfigure}
		\hfill
		\begin{subfigure}[b]{0.48\textwidth}
			\centering
			\includegraphics[width=\linewidth]{Figure_2b.eps}
