\subsection{Upper bound for binary distributions}
\label{sec:UpperBoundForBinaryDistributions}

Recall the definitions of $\cH$ and $\cH_2$ in \eqref{eq:MomentSet}--\eqref{eq:MomentSetFinite}.
We denote the sub-Gaussian parameter of a probability measure $\mu \in \cH$ by
\[
 \sig_\mu
 \weq \inf\left\{\sig \in [0,\infty):
 \int e^{s x} \mu(dx) \le e^{\sig^2 s^2/2} \ \text{for all $s \in \R$}
 \right\}.
\]
%where $m_1(\mu) = \int x \, \mu(dx)$ is the first moment of $\mu$.

\begin{proposition}
\label{the:UpperBoundBinary}
$\sig_\mu \le \sqrt{\log 2}$ for all $\mu \in \cH_2$.
\end{proposition}

\begin{proof}
Fix a $\mu \in \cH_2$.
Being a probability measure supported on two points, we find that
$\mu = p \de_{x_1} + (1-p) \de_{x_2}$ with $p \in (0,1)$ and $x_1 \ne x_2$.
By swapping $x_1$ and $x_2$ if necessary, we may assume without loss of generality that
$p \in [1/2,1)$.
Because $\mu$ is centered, we find that $x_2 = - \frac{p}{1-p} x_1$.
For convenience, let us parametrise $p = \frac{u}{1+u}$ in terms of $u \in [1,\infty)$.
Then $\int e^{x^2} \mu(dx) = G(u,x_1^2)$ where
\[
 G(u,t)
 \weq \frac{u}{1+u} e^t + \frac{1}{1+u} e^{u^2 t}.
\]
In this case we know \cite[Theorem 3.1]{Buldygin_Moskvichova_2013}
that
\[
 \sig_\mu^2
 \weq
 \begin{cases}
  x_1^2 \frac{u^2-1}{2 \log u}, &\qquad u \ne 1, \\
  x_1^2, &\qquad u = 1.
 \end{cases}
\]

Assume first that $u=1$. Then
$\int e^{x^2} \mu(dx) = e^{x_1^2}$,
so that the condition $\int e^{x^2} \mu(dx) \le 2$
implies that
$\sig_\mu^2 = x_1^2 \le \log 2$.

Assume next that $u>1$.
Denote $\al(u) = 2 \log 2 \frac{\log u}{u^2-1}$.
Then our claim amounts to verifying that
$x_1^2 \le \al(u)$ for all $x_1 \in \R$ 
such that $G(u,x_1^2) \le 2$.
Because $G$ is strictly increasing in its second input,
this is equivalent to verifying that $F(u) = G(u,\al(u))$ satisfies $F(u) \ge 2$.
We note that $F$ is continuously differentiable on $(1,\infty)$, with $F(1+) = 2$.
Therefore, it is sufficient to show that $F'(u) \ge 0$ for all $u > 1$.

Observe that
\begin{equation}
 \label{eq:FPrimePre}
 F'(u)
 \weq \partial_1 G(u,\al(u)) + \al'(u) \partial_2 G(u,\al(u)),
\end{equation}
where
\begin{align*}
 \partial_1 G(u, t)
 %&\weq (1+u)^{-2} \bigg( ( e^t + 2ut e^{u^2 t} ) (1+u) - (u e^t + e^{u^2 t}) \bigg) \\
 &\weq (1+u)^{-2} \Big( e^t  + (2u(1+u)t-1) e^{u^2 t} \Big) \\
 \partial_2 G(u, t)
 &\weq u (1+u)^{-1} \Big( e^t + u e^{u^2 t} \Big), \\
 %&\weq (1+u)^{-1} \Big( u e^t + u^2 e^{u^2 t} \Big), \\
 \al'(u)
 %&\weq 2 \log 2 \, (u^2-1)^{-2} \bigg( u^{-1}(u^2-1) - 2 u \log u  \bigg), \\
 &\weq 2 \log 2 \, u^{-1} (u^2-1)^{-2} \Big( u^2 - 1 - 2 u^2  \log u  \Big).
\end{align*}
By substituting the above equations into \eqref{eq:FPrimePre}, and simplifying, we find that
\begin{equation}
 \label{eq:FPrime}
 F'(u) \weq \frac{h_1(u) e^{\al(u)}}{(1+u)(u^2 - 1)^2} + \frac{h_2(u) e^{u^2 \al(u)}}{(1+u)(u^2 - 1)^2},
 %F'(u) \weq H_1(u) e^{\al(u)} + H_2(u) e^{u^2 \al(u)},
\end{equation}
\begin{comment}
where
\begin{align*}
 H_1(u)
 &\weq (1+u)^{-2} + 2 \log 2 \, (1+u)^{-1} (u^2-1)^{-2} \Big( u^2 - 1 - 2 u^2  \log u \Big), \\
 H_2(u)
 &\weq (1+u)^{-2} (2u(1+u)\al(u)-1) \\
 &\qquad + 2 \log 2 \, (1+u)^{-1} (u^2-1)^{-2} \Big( u^2 - 1 - 2 u^2  \log u  \Big) u.
\end{align*}
After simplifying, we find that
\begin{align*}
 H_1(u)
 &\weq 2\log 2 \cdot \frac{u^2 - 1 - 2 u^2 \log u}{(1+u)(u^2 - 1)^2} + \frac{1}{(1+u)^2}, \\
 H_2(u)
 &\weq 2\log 2 \cdot \frac{u^3 - u - 2 u \log u}{(1+u)(u^2 - 1)^2} - \frac{1}{(1+u)^2}.
\end{align*}
After noting that $\frac{1}{(1+u)^2} = \frac{(1+u)(u-1)^2}{(1+u)(u^2-1)^2}$, 
we see that these can also be written as
$H_1(u) = \frac{h_1(u)}{(1+u)(u^2 - 1)^2}$
and 
$H_2(u) = \frac{h_2(u)}{(1+u)(u^2 - 1)^2}$,
\end{comment}
where
\begin{align*}
 h_1(u)
 &\weq 2\log 2 \cdot (u^2 - 1 - 2 u^2 \log u) + (1+u)(u-1)^2, \\
 h_2(u)
 &\weq 2\log 2 \cdot (u^3 - u - 2 u \log u) - (1+u)(u-1)^2.
\end{align*}
Differentiation shows that $h_2(1)=h_2'(1)=h_2''(1)=0$, and that
$h_2'''(u) = 2\log 2 \cdot (6 + 2/u^2) - 6 \ge 0$
for $u \ge 1$.  Therefore, $h_2(u) \ge 0$.
Because $e^{u^2 \al(u)} \ge e^{\al(u)}$,
we find by \eqref{eq:FPrime} that
\begin{equation}
 \label{eq:FPrimeLB}
 F'(u)
 \wge \frac{h(u) e^{\al(u)}}{(1+u)(u^2 - 1)^2},
\end{equation}
where $h(u) = h_1(u)+h_2(u)$.
Differentiation shows that
\[
 h(u)
 \weq 2\log 2 \cdot \Big( u^3 + u^2 - u - 1 - 2 u^2 \log u - 2 u \log u \Big) 
\]
satisfies $h(1)=h'(1)=h''(1)=0$,
together with $h'''(u) = 2\log 2 \cdot \big( 6 - \frac{2}{u^2} - \frac{4}{u} \big) \ge 0$.
Therefore, $h(u) \ge 0$ for $u > 1$.  It follows that $F'(u) \ge 0$ for all $u > 1$ due to \eqref{eq:FPrimeLB}.
\end{proof}

