 \nabla g_1(p,x) &\weq (1, 1, 0, 0), \\
 \nabla g_2(p,x) &\weq (x_1, x_2, p_1, p_2), \\
 \nabla g_3(p,x) &\weq (e^{x_1^2}, e^{x_2^2}, 2 p_1 x_1 e^{x_1^2}, 2 p_2 x_2 e^{x_2^2}).
\end{align*}
