 s p_1 e^{x_1} &\weq \la_2 p_1 + 2 \la_3 p_1 x_1 e^{x_1^2}, \\
 s p_2 e^{x_2} &\weq \la_2 p_2 + 2 \la_3 p_2 x_2 e^{x_2^2}.
\end{align*}
