\subsection{Concluding the proof of the upper bound}
\label{sec:ConclusionUB}

\begin{proof}[Proof of Theorem~\ref{the:Main}: Upper bound]
Let $X$ be a random variable such that $\E X = 0$ and $\sgnorm{X} < \infty$.
Choose a number $K > \sgnorm{X}$, and define $Y = X/K$.
Then $Y$ is a centered random variable such that
\[
 \E e^{Y^2}
 \weq \E e^{X^2/K^2}
 \wle 2.
\]
We conclude that the probability distribution $\mu$ of $Y$ belongs to $\cH$.

Fix $s \in \R$, and denote by $M_\mu(s) = \E e^{sY}$ the moment generating function of $Y$.
By Proposition~\ref{the:ReductionToBinary}, we know that
for some $\mu_* \in \cH_2$,
\[
 M_{\mu_*}(s)
 \wge
 M_\mu(s).
\]
By Proposition~\ref{the:UpperBoundBinary},
the sub-Gaussian parameter of $\mu_*$ is bounded by
$\sig_{\mu_*} \le \sqrt{\log 2}$,
so that $M_{\mu_*}(s) \le e^{\log 2 \cdot s^2/2}$.
We conclude that the moment generating function of $Y$
is bounded by 
\begin{equation}
 \label{eq:MGFBoundY}
 \E e^{sY}
 \wle e^{\log 2 \cdot s^2/2}
 \qquad \text{for all $s \in \R$}.
\end{equation}

By applying \eqref{eq:MGFBoundY} with input $sK$, 
it follows that for all $s \in \R$,
\[
 \E e^{sX}
 \weq \E e^{(sK)Y}
 \wle e^{\log 2 \cdot (sK)^2/2}
 \weq e^{(\sqrt{\log 2} \, K)^2 s^2/2}
\]
Because the above bound holds for all $K > \sgnorm{X}$, we conclude that
$\sig_X \le \sqrt{\log 2} \, \sgnorm{X}$.
\end{proof}




\section{Proof of lower bound}
\label{sec:LowerBound}

For completeness, we include a short proof of the lower bound in Theorem~\ref{the:Main}, even though the result is implicit in earlier works \cite{Buldygin_Kozachenko_2000, Li_2024+, Wainwright_2019} and can be obtained, e.g., by evaluating \cite[Lemma~1.6]{Buldygin_Kozachenko_2000} or by tracking constants in the proof of \cite[Theorem~2.6]{Wainwright_2019}.

\begin{proof}[Proof of Theorem~\ref{the:Main}: Lower bound]
Fix a number $K > \sqrt{2} \sig_X$,
and recall that
the moment generating function
of the standard Gaussian distribution with
the probability density function
$\phi(x) = \frac{1}{\sqrt{2\pi}} e^{-x^2/2}$
is given by
\(
 e^{t^2/2}
 = \int_{-\infty}^\infty e^{t u} \phi(u) du.
\)
By substituting $t = \sqrt{2} X/K$, taking expectations, and
applying Fubini's theorem,
we find that
\begin{align*}
 \E e^{X^2/K^2}
 \weq \int_{-\infty}^\infty \E e^{(u \sqrt{2}/K) X} \phi(u) \, du.
\end{align*}
The definition of the sub-Gaussian parameter implies that
\(
 \E e^{(u \sqrt{2}/K) X}
 \le e^{\sig_X^2 u^2 / K^2}.
\)
Observe also that
\(
 e^{\sig_X^2 u^2 / K^2} \phi(u)
 = \phi(u/\tau)
\)
where $\tau = (1 - 2 \sig_X^2/K^2)^{-1/2}$.
It follows that
\(
 \int_{-\infty}^\infty \E e^{(u \sqrt{2}/K) X} \phi(u) \, du
 \le \int_{-\infty}^\infty \phi(u/\tau) \, du
 = \tau,
\)
so that
\[
 \E e^{X^2/K^2}
 \wle (1 - 2 \sig_X^2/K^2)^{-1/2}.
\]
This above inequality reveals that
$\E e^{X^2/K^2} \le 2$
whenever $K > \sqrt{8/3} \, \sig_X$.
Therefore,
$\sgnorm{X} \le \sqrt{8/3} \, \sig_X$,
or equivalently, $\sig_X \ge \sqrt{3/8} \, \sgnorm{X}$.
\end{proof}





