\section{Old proof of the lower bound}

We will utilise the following well-known result
whose proof is included here for completeness.

\begin{lemma}[{\cite[Lemma 1.6]{Buldygin_Kozachenko_2000}}]
\label{the:SGParameterUB}
If $\E X = 0$ and $0 < \sigma_X < \infty$, then 
\begin{equation}
 \label{eq:SGParameterUB}
 \E \exp \bigg( \frac{s X^2}{2 \sigma_X^2} \bigg)
 \wle \frac{1}{\sqrt{1-s}}
 \qquad \text{for all $0 < s < 1$}.
\end{equation}

\begin{comment}
Compare with the MGF of $\chi^2$-distribution
with one degree of freedom.
The MGF of $X^2$ for $X$ standard normal is given by $\E e^{sX^2} = \frac{1}{\sqrt{1-2s}}$ for $\abs{s} < \frac12$,
\[
 \E e^{s (X/\sig_X)^2}
 \wle \frac{1}{\sqrt{1-2s}}
 \qquad \text{for all $0 < s < 1/2$}.
\]
\end{comment}

\end{lemma}
\begin{proof}
We will start by transforming the left side of \eqref{eq:SGParameterUB}
into a form involving $X$ instead of $X^2$ in the exponent.
\rnote{This is well written in an earlier version, but we no longer need this.}
By substituting
$t = \frac{\sqrt{s}}{\sig_X} x$
and performing a change of variables $v = \frac{\sqrt{s}}{\sig_X} u$,
we see that
\[
 \exp\bigg( \frac{sx^2}{2 \sig_X^2} \bigg)
 \weq \int_{-\infty}^\infty e^{\frac{\sqrt{s}}{\sig_X} u x} \frac{1}{\sqrt{2\pi}} e^{-u^2/2} \, du
 \weq \frac{\sig_X}{\sqrt{2\pi s}} \int_{-\infty}^\infty e^{v x} e^{-\sig_X^2 v^2/(2s)} \, dv.
\]
Let us now plug in the random variable $X$ in place of $x$ in the above equation,
and take expectations on both sides.  By Fubini's theorem, it follows that
\begin{equation}
 \label{eq:SGParameterUB1}
 \E \exp\bigg( \frac{sX^2}{2 \sig_X^2} \bigg)
 \weq \frac{\sig_X}{\sqrt{2\pi s}} \int_{-\infty}^\infty \E e^{v X} e^{-\sig_X^2 v^2/(2s)} \, dv.
\end{equation}

Because $\sig_X$ is the sub-Gaussian parameter of $X$, we find that
$\E e^{v X} \le e^{\sig_X^2 v^2/2}$ for all $v \in \R$.
Therefore, the integral on the right side of \eqref{eq:SGParameterUB1}
bounded by
\begin{equation}
 \label{eq:SGParameterUB2}
 \int_{-\infty}^\infty \E e^{v X} e^{-\sig_X^2 v^2/(2s)} \, dv
 \wle \int_{-\infty}^\infty e^{-(1/s -1) \sig_X^2 v^2/2} \, dv
 \weq \sqrt{\frac{2\pi}{(1/s -1) \sig_X^2}},
\end{equation}
where the equality follows by recognising that the integrand in the middle equals
a non-normalised probability density function of a centered Gaussian
distribution with variance $\frac{1}{(1/s -1) \sig_X^2}$.
%we see that
%\begin{equation}
% \label{eq:SGParameterUB3}
% \int_{-\infty}^\infty e^{-(1/s -1) \sig_X^2 v^2/2} \, dv
% \weq \sqrt{\frac{2\pi}{(1/s -1) \sig_X^2}}.
%\end{equation}
Now the claim follows by combining \eqref{eq:SGParameterUB1}--\eqref{eq:SGParameterUB2}.
\end{proof}

\begin{proof}[Proof of Theorem~\ref{the:Main}: Lower bound]
Assume first that $\sig_X=0$.  Then $\E e^{sX} \le 1$ for all $s \in \R$.
Because $e^{s\abs{X}} \le e^{s X} + e^{-s X}$, we see by taking expectations
that $\E e^{s\abs{X}} \le 2 $.
Markov's inequality then implies that for any $s,\eps > 0$,
\[
 \pr( \abs{X} \ge \eps)
 \weq \pr( e^{s \abs{X}} \ge e^{s \eps})
 \wle e^{-s\eps}. 
\]
By taking $s \uparrow \infty$, we see that $\pr( \abs{X} \ge \eps) = 0$ for all $\eps > 0$.
Therefore $X = 0$ almost surely.  Then $\E e^{X^2/K^2} \le 2$ for all $K > 0$,
and we conclude that $\sgnorm{X} = 0$.

Assume next that $0 < \sigma_X < \infty$.
By applying Lemma~\ref{the:SGParameterUB}, we then find that
\[
 \E \exp \bigg( \frac{s X^2}{2 \sigma_X^2} \bigg)
 \wle \frac{1}{\sqrt{1-s}}
 \qquad \text{for all $0 < s < 1$}.
\]
By plugging $s = \frac{3}{4}$ and $K = \sqrt{\frac{8}{3}}\sig_X$, we find that
\[
 \E e^{X^2/K^2}
 \weq \E \exp \bigg( \frac{s X^2}{2 \sigma_X^2} \bigg)
 \wle \frac{1}{\sqrt{1-s}}
 \weq 2.
\]
Hence $\sgnorm{X} \le K$ and we conclude that $\sig_X \ge \sqrt{3/8} \, \sgnorm{X}$.
\end{proof}



\section{Preliminaries}

\subsection{Rolle's theorem (no need to prove, this is \cite[Theorem 5.10]{Rudin_1976})}

\begin{lemma}
\label{the:DerivativeVanishes}
Let \( f \colon [a,b] \to \mathbb{R} \) be continuous on \( [a,b] \) and continuously differentiable on \( (a,b) \), and suppose that \( f(a) = f(b) \) for some \( a < b \). Then there exists a number
\( t \in (a,b) \) such that \( f'(t) = 0 \).
\end{lemma}
\begin{proof}
Let us write $f' = f'_+ - f'_-$ with $f'_+ = \max\{f',0\}$ and $f'_- = \max\{-f',0\}$.
Because $f(a) = f(b)$, we see that $\int_a^b f'(t) \, dt = 0$, which implies that
\begin{equation}
 \label{eq:DerivativeVanishes1}
 \int_a^b f_+'(t) \, dt
 \weq \int_a^b f_-'(t) \, dt,
\end{equation}
where we note that $f_+'$ and $f_-'$ are continuous and nonnegative. We consider two cases:
\begin{enumerate}[(i)]
\item If both integrals in \eqref{eq:DerivativeVanishes1} are zero,
then $f_+'$ and $f_-'$ are identically zero on $(a,b)$, and so is $f'$.
\item If the integrals in \eqref{eq:DerivativeVanishes1} are nonzero,
then there exist points $t_1$ and $t_2$ in $(a,b)$ at which
$f'_-(t_1) > 0$ and $f'_+(t_2) > 0$.
Then $f'(t_1) < 0 < f'(t_2)$,
and the claim follows by the continuity of $f'$ and the intermediate value theorem.
\end{enumerate}
\end{proof}


\subsection{Orlicz norms}

Orlicz spaces\footnote{Named after \Wladyslaw Orlicz (1903--1990), PhD 1928 @ Lviv.}
are generalisations of $L^p$ spaces and allow to characterise random variables and
probability distributions with different rates of tail decay.

An \new{Orlicz  function} is a nondecreasing convex function
$\psi \colon [0,\infty) \to [0,\infty)$
such that $\psi(0)=0$ and $\lim_{x \to \infty} \psi(x) = \infty$.
The associated \new{Orlicz norm}%
\footnote{This is sometimes called the \new{Luxemburg norm} after
the author of a PhD thesis \cite{Luxemburg_1955} where
this norm was apparently first introduced.}
of a real-valued random variable $X$ is an extended real number defined by
\begin{equation}
 \label{eq:ONorm}
 \onorm{X}
 \weq \inf \big\{ K \in (0,\infty) \colon \E \psi(\abs{X}/K) \le 1 \big\},
\end{equation}
with the convention $\inf\emptyset = \infty$.
The \new{Orlicz space} $L_\psi(\pr)$ is the set of real-valued random variables
on a probability space $(\Omega, \cA, \pr)$ such that $\onorm{X} < \infty$.


\begin{lemma}
\label{the:OInf}
For all $K, L \in (0,\infty)$ such that $K < \onorm{X} \le L$,
\begin{equation}
 \label{eq:OInf}
 \E \psi(\abs{X}/L) \wle 1 
 \ < \
 \E \psi(\abs{X}/K).
\end{equation}
\end{lemma}

\begin{proof}
We will first verify the implications
\begin{align}
 \label{eq:OInf1}
 \E \psi(\abs{X}/K) > 1 &\quad \implies \quad K \le \onorm{X}, \\
 \label{eq:OInf2}
 \E \psi(\abs{X}/K) \le 1 &\quad \implies \quad K \ge \onorm{X}.
\end{align}
To do this, denote by $\cK_X$ the set on the right side of \eqref{eq:ONorm}.

(i) Let us verify \eqref{eq:OInf1}.
Assume that $K \in (0,\infty)$ satisfies $\E \psi(\abs{X}/K) > 1$.
In this case 
$\E \psi( \abs{X}/J ) \ge \E \psi( \abs{X}/K)  > 1$ for all $0 < J \le K$,
from which we conclude that $K$ is a lower bound of $\cK_X$.
Because $\onorm{X} = \inf \cK_X$
is the greatest lower bound of $\cK_X$, we conclude that $K \le \onorm{X}$.

(ii) Let us verify \eqref{eq:OInf2}.
Assume that $K \in (0,\infty)$ satisfies $\E \psi(\abs{X}/K) \le 1$.  Then $K \in \cK_X$.
Because 
$\onorm{X}$
is a lower bound of $\cK_X$,
it follows that $K \ge \onorm{X}$.

(iii) 
Let us verify the first inequality in \eqref{eq:OInf}.
Assume that $L > \onorm{X}$. Then $\E \psi(\abs{X}/L) \le 1$
because otherwise \eqref{eq:OInf1} would lead to a contradiction.
Hence the first inequality in \eqref{eq:OInf} is valid.
Assume next that $L = \onorm{X}$, and consider a sequence $L_n \downarrow L$.
Then
$\psi(\abs{X}/L_n) \uparrow \psi(\abs{X}/L)$.
The monotone continuity of expectation then implies that
$\E \psi(\abs{X}/L) = \lim_{n \to \infty} \E \psi(\abs{X}/L_n) \le 1$.
Hence the first inequality in \eqref{eq:OInf} is valid also for $L = \onorm{X}$.

(iv)
Let us verify the second inequality in \eqref{eq:OInf}.
If $K < \onorm{X}$, then evidently $\E \psi(\abs{X}/K) > 1$,
because else \eqref{eq:OInf2} would lead to a contradiction.
\end{proof}


\begin{proposition}
\label{the:OrliczNorm}
The Orlicz norm is a norm on the vector space $L_\psi(\pr)$.
\end{proposition}
\begin{proof}
(i) Positive definiteness. 
Let us verify that $\onorm{X} = 0$ if and only if $X=0$ almost surely.
The `only if' implication follows immediately by noting that if $X=0$ a.s., then
$\E \psi( \abs{X}/K) = \psi(0) = 0$ for all $K > 0$.
Assume next that $\onorm{X} = 0$.
Lemma~\ref{the:OInf} then implies that
$\E \psi( \abs{X}/K) \le 1$ for all $K > 0$.
Fix a number $t > 0$.
The monotonicity of $\psi$ and Markov's inequality then imply that
\[
 \pr(\abs{X} \ge t)
 \wle \pr(\psi(\abs{X}/K) \ge \psi(t/K))
 \wle \frac{1}{\psi(t/K)} \E \psi(\abs{X}/K)
 \wle \frac{1}{\psi(t/K)}
\]
for all large enough $K > 0$ such that $\psi(t/K) > 0$.
By letting $K \to \infty$, it follows that $\pr(\abs{X} \ge t) = 0$.
Because this is true for all $t > 0$, we find by
the union bound that
\[
 \pr( \abs{X} > 0 )
 \weq \pr \bigg( \bigcup_{n=1}^\infty \{ \abs{X} \ge 1/n \} \bigg)
 \wle \sum_{n=1}^\infty \pr\{ \abs{X} \ge 1/n\}
 \weq 0.
\]
Therefore, $X = 0$ a.s.

(ii) Homogeneity.  Let us verify that $\onorm{c X} = \abs{c} \onorm{X}$ for all $c \in \R$.
By (i), the claim is true for $c=0$. Let us now fix $c \ne 0$.
Lemma~\ref{the:OInf} tells us that 
\[
 \E \psi \bigg( \frac{\abs{c X}}{\abs{c} L} \bigg) 
 \wle 1 
 \ < \
 \E \psi \bigg( \frac{\abs{c X}}{\abs{c} K} \bigg)
\]
for all $K, L \in (0,\infty)$ such that $K < \onorm{X} \le L$.
Equivalently,
\[
 \E \psi \bigg( \frac{\abs{c X}}{L} \bigg) 
 \wle 1 
 \ < \
 \E \psi \bigg( \frac{\abs{c X}}{K} \bigg) 
\]
for all $K, L \in (0,\infty)$ such that $K < c \onorm{X} \le L$.
From this we conclude that $\onorm{cX} = c \onorm{X}$.

(iii) Triangle inequality.
Let us prove $\onorm{X+Y} \le \onorm{X} + \onorm{Y}$.
Assume that $\onorm{X}, \onorm{Y} < \infty$ (otherwise the claim is trivial).
Fix a number $u > \onorm{X} + \onorm{Y}$, and select some numbers $s > \onorm{X}$ and $t >  \onorm{Y}$
such that $u = s+t$. Note that
\[
 \frac{\abs{X+Y}}{u}
 \weq \frac{\abs{X+Y}}{s+t}
 \wle \frac{\abs{X}}{s+t} + \frac{\abs{Y}}{s+t}
 \wle \frac{s}{s+t} \frac{\abs{X}}{s} +\frac{t}{s+t} \frac{\abs{Y}}{t}.
\]
Because $\psi$ is nondecreasing and convex, it follows that
\[
 \psi \left( \frac{\abs{X+Y}}{u} \right)
 \wle \frac{s}{s+t} \psi
 \left( \frac{\abs{X}}{s} \right) +\frac{t}{s+t} \psi \left( \frac{\abs{Y}}{t} \right).
\]
Because $s > \onorm{X}$ and $t > \onorm{Y}$, we see (Lemma~\ref{the:OInf}) that
$\E \psi ( \abs{X}/s ) \le 1$ and $\E \psi ( \abs{Y}/t ) \le 1$.
By taking expectations in the above inequality, we now find that
\[
 \E \psi \left( \frac{\abs{X+Y}}{u} \right)
 \wle 1.
\]
Therefore, $\onorm{X+Y} \le u$. Because this is true for every $u > \onorm{X} + \onorm{Y}$, we conclude by letting $u \downarrow \onorm{X} + \onorm{Y}$ that
$\onorm{X+Y} \le \onorm{X} + \onorm{Y}$.

(iv) The triangle inequality (iii) implies that $L_\psi(\pr)$ is a vector space.
The parts (i)--(iii) confirm that $\onorm{X}$ is a norm on $L_\psi(\pr)$.
\end{proof}





\subsection{sub-Gaussian parameter}

These simple results are more or less well known.

\begin{proposition}
\label{the:SGParameterEquality}
If $\sig_X < \infty$, then $\E e^{sX} \le e^{\sig_X^2 s^2/2}$ for all $s \in \R$.
\end{proposition}
\begin{proof}
Note that $\sig_X = \inf S$ where
\[
 S
 \weq \{ \sig \in [0,\infty) \colon \E e^{sX} \le e^{\sig^2 s^2/2} \text{ for all $s \in \R$} \}.
\]
Because $\sig_X < \infty$, we see that $S$ is nonempty, and there exists a decreasing sequence
$\sig_n \downarrow \sig_X$ with $\sig_n \in S$.
Fix a number $s \in \R$. Then $\E e^{sX} \le e^{\sig_n^2 s^2/2}$ for all $n$.
By continuity, it follows that $\E e^{sX} \le e^{\sig_X^2 s^2/2}$.

\end{proof}

\begin{proposition}
\label{the:SGParameterScale}
%The sub-Gaussian parameter satisfies
$\sigma_{a X + b} = a \sigma_X$ for all $a \ge 0$ and $b \in \R$.
\end{proposition}
\begin{proof}
Let $X$ have a finite mean.
Because $(aX+b) - \E (aX+b) = a X - \E (aX)$,
we see that from \eqref{eq:SGParameter} that $\sigma_{a X + b} = \sigma_{a X}$.
Next we note that $\sigma_{aX} = \inf \Sigma_{aX}$, where
\[
 \Sigma_{aX}
 \weq \Big\{ \sigma \in [0,\infty): \E e^{a s (X - \E(X)} \le e^{\sigma^2 s^2/2} \ \text{for all $s \in \R$} \Big\}.
\]

(i) Assume that $a > 0$. Then we see that $\sigma \in \Sigma_{aX}$ if and only if $\sigma/a \in \Sigma_X$.
Hence
\begin{align*}
 \sigma_{a X}
 \weq \inf \Sigma_{aX}
 \weq \inf\left\{ \sigma \colon \sigma/a \in \Sigma_X \right\}
 \weq \inf (a \Sigma_X).
\end{align*}
Because $\sigma \mapsto a \sigma$ is an increasing bijection,
we see that $\inf (a \Sigma_X) = a \inf \Sigma_X = a \sigma_X$.

(ii) Assume that $a=0$.  Then $\sigma_{a X} = \sigma_0$ for the degenerate random variable $X=0$.
In this case $\E e^{s (X - \E X)} = 1$ for all $s \in \R$. We conclude that $\sigma_{a X} = 0 = 0 \sigma_X$.
\end{proof}

\begin{proposition}
\label{the:SGParameterZero}
$\sigma_X = 0$ if and only if $X = \E X$ almost surely.
\end{proposition}
\begin{proof}
Assume that $\sigma_X = 0$. Let $Y = X - \E X$.  Then $\sigma_Y = \sigma_X = 0$ by
Proposition~\ref{the:SGParameterScale}.
Fix $\lambda \in \R$.
Then $\E e^{\lambda Y} \le e^{\sigma^2 \lambda^2/2}$ for all $\sigma>0$. By letting $\sigma \downarrow 0$, we see that $\E e^{\lambda Y} \le 1$ for all $\lambda \in \R$.  Hence
\[
 \E e^{\lambda \abs{Y}}
 \weq \E e^{\lambda Y} 1(Y \ge 0) + \E e^{- \lambda Y} 1(Y < 0)
 \wle 2
\]
for all $\lambda$. Then for all $\lambda, t > 0$,
\[
 \pr( \abs{Y} > t )
 \weq \pr( e^{\lambda \abs{Y}} > e^{\lambda t})
 \wle e^{-\lambda t} \E e^{\lambda \abs{Y}}
 \wle 2 e^{-\lambda t}.
\]
By letting $\lambda \uparrow \infty$, we conclude that $\pr( \abs{Y} > t ) = 0$ for all $t > 0$. 
Hence $\pr(Y \ne 0) = \lim_{n \to \infty} \pr(\abs{Y} > 1/n) = 0$, and we conclude that $Y=0$ almost surely.

Conversely, if $X = \E X$ almost surely, the we immediately see from \eqref{eq:SGParameter}
that $\sigma_X = 0$.
\end{proof}



\subsection{sub-Gaussian norm}

\begin{lemma}
\label{the:SGBall}
For any number $K > 0$, $\sgnorm{X} \le K$ if and only if $\E e^{X^2/K^2} \le 2$.
\end{lemma}
\begin{proof}
Fix a number $K > 0$.
(i) Assume that $\sgnorm{X} \le K$.
Then by Lemma~\ref{the:OInf}, it follows that $\E e^{X^2/K^2} \le 2$.
(ii) Assume next that $\sgnorm{X} > K$.
Then by Lemma~\ref{the:OInf}, $\E e^{X^2/K^2} > 2$.
\end{proof}


